    fn unalias_all_clears_every_alias() {
        let (o, _) = run("alias a='1'; alias b='2'; unalias -a; alias");
        assert_eq!(o, "");
    }

    #[test]
    fn echo_and_status() {
        let (o, s) = run("echo hello");
        assert_eq!(o, "hello\n");
        assert_eq!(s, 0);
    }

    #[test]
    fn variables_and_expansion() {
        let (o, _) = run("x=world; echo hi $x");
        assert_eq!(o, "hi world\n");
    }

    #[test]
    fn param_default() {
        let (o, _) = run("echo ${undefined:-fallback}");
        assert_eq!(o, "fallback\n");
    }

    #[test]
    fn param_default_colon_vs_plain() {
        // Colon form: empty-but-set uses the default.
        let (o, _) = run("x=; echo [${x:-D}]");
        assert_eq!(o, "[D]\n");
        // Plain form: empty-but-set is "set", so no default is applied.
        let (o, _) = run("x=; echo [${x-D}]");
        assert_eq!(o, "[]\n");
        // Both forms use the default when genuinely unset.
        let (o, _) = run("unset x; echo [${x:-D}][${x-D}]");
        assert_eq!(o, "[D][D]\n");
        // Set and non-empty: neither form applies the default.
        let (o, _) = run("x=v; echo [${x:-D}][${x-D}]");
        assert_eq!(o, "[v][v]\n");
    }

    #[test]
    fn param_alternate_colon_vs_plain() {
        // Colon form (`:+`): active only when set AND non-empty.
        let (o, _) = run("x=; echo [${x:+A}]");
        assert_eq!(o, "[]\n");
        // Plain form (`+`): active whenever set, even if empty.
        let (o, _) = run("x=; echo [${x+A}]");
        assert_eq!(o, "[A]\n");
        // Unset: neither form is active.
        let (o, _) = run("unset x; echo [${x:+A}][${x+A}]");
        assert_eq!(o, "[][]\n");
        // Set non-empty: both active.
        let (o, _) = run("x=v; echo [${x:+A}][${x+A}]");
        assert_eq!(o, "[A][A]\n");
    }

    #[test]
    fn param_assign_default_plain() {
        // Plain `=`: empty-but-set is left as-is (empty), not reassigned.
        let (o, _) = run("x=; echo [${x=D}][$x]");
        assert_eq!(o, "[][]\n");
        // Unset: assigns the default.
        let (o, _) = run("unset x; echo [${x=D}][$x]");
        assert_eq!(o, "[D][D]\n");
        // Colon `:=`: empty-but-set gets reassigned to the default.
        let (o, _) = run("x=; echo [${x:=D}][$x]");
        assert_eq!(o, "[D][D]\n");
    }

    #[test]
    fn arithmetic() {
        let (o, _) = run("echo $((6 * 7))");
        assert_eq!(o, "42\n");
    }

    #[test]
    fn echo_e_interprets_escapes() {
        // `-e` interprets backslash escapes; `-E`/default do not.
        assert_eq!(run("echo -e 'a\\nb'").0, "a\nb\n");
        assert_eq!(run("echo -e 'a\\tb'").0, "a\tb\n");
        assert_eq!(run("echo 'a\\nb'").0, "a\\nb\n");
        assert_eq!(run("echo -E 'a\\nb'").0, "a\\nb\n");
        // Clustered flags: `-ne` = no newline + interpret.
        assert_eq!(run("echo -ne 'x\\ty'").0, "x\ty");
        // `\c` stops output and suppresses the trailing newline.
        assert_eq!(run("echo -e 'keep\\cdrop'").0, "keep");
        // `\xHH` hex; `\0nnn` octal (needs the leading 0, else literal).
        assert_eq!(run("echo -e '\\x41\\0101'").0, "AA\n");
        assert_eq!(run("echo -e '\\101'").0, "\\101\n");
        // `\uHHHH` / `\UHHHHHHHH` Unicode code points, emitted as UTF-8
        // (matching osh's `$'…'` decoder). A missing hex digit stays literal.
        assert_eq!(run("echo -ne '\\u00e9'").0, "\u{e9}");
        assert_eq!(run("echo -ne '\\U0001F600'").0, "\u{1F600}");
        assert_eq!(run("echo -ne '\\u41'").0, "A");
        assert_eq!(run("echo -ne '\\uZ'").0, "\\uZ");
    }

    #[test]
    fn arithmetic_with_nested_command_sub() {
        // Command substitutions and nested arithmetic embedded in a `$(( ))`
        // expression must be expanded before evaluation.
        assert_eq!(run("f() { echo 5; }; echo $(( $(f) + 1 ))").0, "6\n");
        assert_eq!(run("f() { echo 5; }; echo $(( $(f) + $(f) ))").0, "10\n");
        assert_eq!(run("n=3; echo $(( $((n-1)) + 1 ))").0, "3\n");
        assert_eq!(run("echo $(( `echo 4` * 2 ))").0, "8\n");
        // Recursion through arithmetic command substitution (fibonacci).
        let fib = "fib() { local n=$1; if ((n<2)); then echo $n; \
                   else echo $(( $(fib $((n-1))) + $(fib $((n-2))) )); fi; }; fib 7";
        assert_eq!(run(fib).0, "13\n");
    }

    #[test]
    fn arithmetic_with_braced_param_expansion() {
        // A `${…}` inside `$(( ))` is a full parameter expansion, not just a
        // bare-name lookup: length (`${#x}`, `${#a[@]}`), operators (`${x:-N}`),
        // and subscripts must all evaluate. (Regression: these previously
        // yielded 0 because only bare names were handled.)
        assert_eq!(run("x=5; echo $(( ${#x} ))").0, "1\n");
        assert_eq!(run("x=hello; echo $(( ${#x} * 2 ))").0, "10\n");
        assert_eq!(run("a=(x y z); echo $(( ${#a[@]} ))").0, "3\n");
        assert_eq!(run("a=(x y z); echo $(( ${#a[@]} + 1 ))").0, "4\n");
        assert_eq!(run("echo $(( ${#BASH_VERSINFO[@]} ))").0, "6\n");
        // Operator forms and nested braces.
        assert_eq!(run("echo $(( ${x:-3} + 1 ))").0, "4\n");
        assert_eq!(run("x=10; echo $(( ${x:-3} + 1 ))").0, "11\n");
        assert_eq!(run("a=(5 6 7); echo $(( a[1] + ${a[2]} ))").0, "13\n");
        // Unset length is 0.
        assert_eq!(run("echo $(( ${#nonexist} ))").0, "0\n");
    }

    #[test]
    fn command_substitution() {
        let (o, _) = run("echo [$(echo inner)]");
        assert_eq!(o, "[inner]\n");
    }

    #[test]
    fn command_sub_read_file() {
        // `$(< file)` reads the file's contents (bash fast path), stripping the
        // trailing newline like any command substitution.
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("clock")
            .as_nanos();
        let path = std::env::temp_dir().join(format!("osh_readf_{}_{}.txt", std::process::id(), nanos));
        let p = path.to_string_lossy().replace('\\', "/");
        std::fs::write(&path, b"hello world\nsecond line\n").expect("write");
        let (o, st) = run(&format!("x=$(< {p}); echo \"[$x]\""));
        assert_eq!(st, 0);
        assert_eq!(o, "[hello world\nsecond line]\n");
        // Also works with the `< file` form embedded directly in a comsub arg.
        let (o2, _) = run(&format!("echo \"<$(<{p})>\""));
        assert_eq!(o2, "<hello world\nsecond line>\n");
        std::fs::remove_file(&path).ok();
    }

    #[test]
    fn a_builtin_writing_in_pieces_keeps_its_whole_output_in_a_file() {
        // A builtin whose output is interrupted by a diagnostic writes it in
        // pieces so the two interleave as bash's do. Its `> file` target is
        // therefore opened once for the builtin and written through, not
        // re-opened per write — which would truncate away everything but the
        // last piece. See `BuiltinStdout`.
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("clock")
            .as_nanos();
        let path =
            std::env::temp_dir().join(format!("osh_piecewise_{}_{}.txt", std::process::id(), nanos));
        let p = path.to_string_lossy().replace('\\', "/");
        run(&format!("kill -l 9 -x 15 > {p} 2>/dev/null"));
        assert_eq!(std::fs::read_to_string(&path).expect("read"), "KILL\nTERM\n");
        // `>>` reaches the same file without the first piece being lost either.
        run(&format!("kill -l 1 2 >> {p}"));
        assert_eq!(std::fs::read_to_string(&path).expect("read"), "KILL\nTERM\nHUP\nINT\n");
        std::fs::remove_file(&path).ok();
    }

    #[test]
    fn command_sub_read_file_missing_reports_error() {
        // `$(< missing)` must mirror bash: the failed open sets $? = 1 and the
        // substitution is the empty string (previously osh silently yielded ""
        // with status 0). The diagnostic goes to the shell's real stderr during
        // expansion, so it is not part of the captured stdout.
        let (o, _) = run("v=$(< /no_such_osh_file_xyz); echo \"[$v] e=$?\"");
        assert_eq!(o, "[] e=1\n");
    }

    #[test]
    fn command_sub_read_file_directory_is_empty_success() {
        // bash opens a directory read-only successfully: `$(< dir)` yields the
        // empty string with status 0. Use the OS temp dir (guaranteed to exist).
        let dir = std::env::temp_dir();
        let p = dir.to_string_lossy().replace('\\', "/");
        let (o, _) = run(&format!("v=$(< '{p}'); echo \"[$v] e=$?\""));
        assert_eq!(o, "[] e=0\n");
    }

    #[test]
    fn error_if_unset_aborts_shell() {
        // `${var:?msg}` on an unset parameter writes the message and aborts the
        // (sub)shell before the command runs — the `echo` never executes.
        let (o, _) = run("unset zz; (echo \"${zz:?is unset}\") 2>/dev/null; echo \"after=$?\"");
        assert_eq!(o, "after=1\n");
        // A set, non-empty parameter is unaffected.
        let (o2, _) = run("y=set; echo \"${y:?msg}\"");
        assert_eq!(o2, "set\n");
        // At top level the error aborts the whole run; the status is mode
        // dependent — 1 for the interactive/stdin/script-like `run` harness, 127
        // only under `-c` (see fatal_expansion_abort_status_by_context).
        let (o3, st3) = run("unset q; echo \"${q:?gone}\" 2>/dev/null; echo unreached");
        assert_eq!(o3, "");
        assert_eq!(st3, 1);
        let (_, st3c) = run_cmd_mode("unset q; echo \"${q:?gone}\" 2>/dev/null; echo unreached");
        assert_eq!(st3c, 127);
    }

    #[test]
    fn fatal_expansion_abort_status_by_context() {
        // A nounset / `${var:?}` error aborts the current shell environment. Its
        // exit status is *invocation-mode dependent* (verified against bash 5.2):
        // `bash -c` yields 127, while a script file / stdin / interactive shell
        // yields 1. The default `run` harness is interactive/stdin-like, so it
        // sees 1; `run_cmd_mode` models `-c` and sees 127. Inside a subshell /
        // command substitution the status is always 1 and the parent survives.
        // Bad indirect / subscript expansions are always 1.

        // Top level, interactive/stdin/script-like (`run`): nounset and `:?` -> 1.
        assert_eq!(run("set -u; echo $undef; echo after").1, 1);
        assert_eq!(run("unset q; echo ${q:?} 2>/dev/null; echo after").1, 1);
        assert_eq!(run("set -u; { echo $undef; }").1, 1);
        assert_eq!(run("f(){ echo $undef; }; set -u; f; echo after").1, 1);
        assert_eq!(run("set -u; x=$undef").1, 1);
        assert_eq!(run("set -u; a=($undef)").1, 1);

        // The same top-level cases under `-c` command mode -> 127.
        assert_eq!(run_cmd_mode("set -u; echo $undef; echo after").1, 127);
        assert_eq!(run_cmd_mode("unset q; echo ${q:?} 2>/dev/null; echo after").1, 127);
        assert_eq!(run_cmd_mode("set -u; { echo $undef; }").1, 127);
        assert_eq!(run_cmd_mode("f(){ echo $undef; }; set -u; f; echo after").1, 127);
        assert_eq!(run_cmd_mode("set -u; x=$undef").1, 127);
        assert_eq!(run_cmd_mode("set -u; a=($undef)").1, 127);

        // A subshell aborts with 1 and does NOT abort the parent (which goes on
        // to run `echo done` and exit 0) — regardless of the outer mode.
        assert_eq!(run("(set -u; echo $undef)").1, 1);
        assert_eq!(run("(set -u; echo $undef); echo done").1, 0);
        assert_eq!(run_cmd_mode("(set -u; echo $undef)").1, 1);
        assert_eq!(run_cmd_mode("(set -u; echo $undef); echo done").1, 0);
        // Command substitution is a subshell: it fails with 1, parent survives.
        assert_eq!(run("x=$(set -u; echo $undef); echo $?").0, "1\n");

        // Bad indirect / subscript expansions are always 1, in every mode.
        assert_eq!(run("echo ${!badref}").1, 1);
        assert_eq!(run_cmd_mode("echo ${!badref}").1, 1);
    }

    #[test]
    fn integer_assignment_arith_error_is_fatal() {
        // A bad arithmetic expression bound to an *integer-attribute* variable is
        // fatal in bash (status 1, the shell aborts) — unlike `let`/`(( ))`,
        // which merely return non-zero. Covers `declare -i NAME=EXPR`, a plain
        // assignment to an already-`-i` variable, `declare -ia` array elements,
        // and `name[i]=EXPR`. Both syntax errors and division by zero abort.
        assert_eq!(run("declare -i k=\"3 apples\"; echo after"), (String::new(), 1));
        assert_eq!(run("declare -i k=\"1/0\"; echo after"), (String::new(), 1));
        assert_eq!(run("declare -i k; k=\"3 apples\"; echo after"), (String::new(), 1));
        assert_eq!(run("declare -ia arr=(1 \"2 x\" 3); echo after"), (String::new(), 1));
        assert_eq!(run("declare -i a[0]=\"2 x\"; echo after"), (String::new(), 1));
        // A valid integer initializer still works and is non-fatal.
        assert_eq!(run("declare -i k=\"5+3\"; echo $k").0, "8\n");
        // A bare word that is a (bare) identifier is a variable reference -> 0,
        // not an error.
        assert_eq!(run("declare -i k=abc; echo $k").0, "0\n");

        // In a subshell / command substitution the abort is status 1 and does
        // NOT abort the parent.
        assert_eq!(run("(declare -i k=\"3 apples\"); echo done").1, 0);
        assert_eq!(run("x=$(declare -i k=\"3 apples\"; echo in); echo $?").0, "1\n");

        // `let` / `(( ))` remain non-fatal (the following command still runs).
        assert_eq!(run("let \"3 apples\" 2>/dev/null; echo after").0, "after\n");
        assert_eq!(run("(( 3 apples )) 2>/dev/null; echo after").0, "after\n");
    }

    #[test]
    fn subscript_and_substring_arith_error_is_fatal() {
        // Arithmetic errors that occur while *expanding a word* — an array
        // subscript, a substring/slice offset or length — are fatal in bash
        // (status 1, the shell aborts) at the main-shell level, but only fail
        // the subshell (status 1, parent survives) inside `( )`/`$( )`. This is
        // distinct from `[[ x -eq y ]]` / `[ x -eq y ]`, whose arithmetic
        // comparisons are non-fatal.

        // Array subscript read with a bad arithmetic expression -> fatal.
        assert_eq!(run("a=(1 2 3); echo ${a[3 x]}; echo after"), (String::new(), 1));
        // Substring offset with a bad arithmetic expression -> fatal.
        assert_eq!(run("x=abcdef; echo ${x:1 z}; echo after"), (String::new(), 1));
        // Substring length with a bad arithmetic expression -> fatal.
        assert_eq!(run("x=abcdef; echo ${x:1:2 z}; echo after"), (String::new(), 1));

        // In a subshell the abort is status 1 and does NOT abort the parent.
        assert_eq!(run("a=(1 2 3); (echo ${a[3 x]}); echo done").1, 0);
        assert_eq!(run("x=$(a=(1 2 3); echo ${a[3 x]}); echo $?").0, "1\n");

        // `[[ … -eq … ]]` / `[ … -eq … ]` arithmetic errors are NOT fatal: the
        // conditional reports non-zero but the following command still runs.
        assert_eq!(run("[[ \"3 x\" -eq 5 ]] 2>/dev/null; echo after").0, "after\n");
        assert_eq!(run("[ \"3 x\" -eq 5 ] 2>/dev/null; echo after").0, "after\n");
    }

    #[test]
    fn a_failed_expansion_abandons_the_assignment() {
        // A failing arithmetic expansion still has to return something, and that
        // something is `0`. Storing it would leave the variable reading as a
        // plausible wrong value instead of its old one, so the assignment is
        // abandoned entirely — bash parity. (The failure discards the rest of the
        // parse unit, so every read-back here is on a line of its own.)
        assert_eq!(run("x=old\nx=$(( a + ))\necho \"[$x]\"").0, "[old]\n");
        assert_eq!(run("x=old\nx=$(( 1/0 ))\necho \"[$x]\"").0, "[old]\n");
        // The fabricated value would otherwise show up mid-word, glued onto an
        // append, or evaluated under the integer attribute.
        assert_eq!(run("y=old\ny=p$(( a + ))q\necho \"[$y]\"").0, "[old]\n");
        assert_eq!(run("z=old\nz+=$(( a + ))\necho \"[$z]\"").0, "[old]\n");
        assert_eq!(run("declare -i n=7\nn=$(( a + ))\necho \"[$n]\"").0, "[7]\n");
        // Element assignments, both array kinds.
        assert_eq!(
            run("a=(o1 o2)\na[0]=$(( a + ))\necho \"[${a[*]}]\"").0,
            "[o1 o2]\n"
        );
        assert_eq!(
            run("declare -A m=([k]=o)\nm[k]=$(( a + ))\necho \"[${m[k]}]\"").0,
            "[o]\n"
        );
        // An indexed literal is expanded whole, so nothing binds — not even the
        // clearing a non-append literal would do first.
        assert_eq!(
            run("b=(o1 o2)\nb=( p$(( a + ))q z )\necho \"[${b[*]}]\"").0,
            "[o1 o2]\n"
        );
        assert_eq!(
            run("c=(o1)\nc+=( good x$(( a + )) )\necho \"[${c[*]}]\"").0,
            "[o1]\n"
        );
        // An associative literal binds element by element, so an append keeps
        // the pairs before the failing one — the one place a partial result
        // survives. A non-append one swaps at the end, so nothing survives.
        assert_eq!(
            run("declare -A p=([k]=o)\np+=( [i]=good [j]=$(( a + )) )\necho \"${#p[@]} [${p[i]}]\"").0,
            "2 [good]\n"
        );
        assert_eq!(
            run("declare -A q=([k]=o)\nq+=( pk pv j$(( a + )) x )\necho \"${#q[@]} [${q[pk]}]\"").0,
            "2 [pv]\n"
        );
        assert_eq!(
            run("declare -A r=([k]=o)\nr=( [i]=good [j]=$(( a + )) )\necho \"${#r[@]} [${r[k]}]\"").0,
            "1 [o]\n"
        );
        // A name that did not exist is not created, and an array that had no
        // value yet does not acquire an empty one.
        assert_eq!(
            run("NEW=$(( a + ))\ndeclare -p NEW 2>/dev/null\necho \"rc=$?\"").0,
            "rc=1\n"
        );
        assert_eq!(
            run("declare -a ea\nea=( x$(( a + )) )\ndeclare -p ea").0,
            "declare -a ea\n"
        );
        assert_eq!(
            run("declare -A em\nem=( [k]=$(( a + )) )\ndeclare -p em").0,
            "declare -A em\n"
        );
        // `declare`/`export` and a command prefix agree.
        assert_eq!(run("d=old\ndeclare d=$(( a + ))\necho \"[$d]\"").0, "[old]\n");
        assert_eq!(run("export e=old\nexport e=$(( a + ))\necho \"[$e]\"").0, "[old]\n");
        assert_eq!(run("p=old\np=$(( a + )) true\necho \"[$p]\"").0, "[old]\n");
        // An assignment that is not made is not traced, either.
        assert_eq!(
            run("t=old\nset -x\nt=$(( a + ))\nset +x\necho \"[$t]\"").0,
            "[old]\n"
        );
    }

    #[test]
    fn array_slice_negative_length_is_fatal() {
        // An array / positional-parameter slice rejects a *negative length* as a
        // fatal expansion error ("N: substring expression < 0"), unlike a string
        // substring where a negative length counts back from the end. Fatal at
        // the main shell (status 1, aborts), status 1 without aborting the parent
        // inside a subshell.
        assert_eq!(run("a=(1 2 3 4 5); echo ${a[@]:1:-1}; echo after"), (String::new(), 1));
        assert_eq!(run("a=(1 2 3); echo ${a[*]:0:-5}; echo after"), (String::new(), 1));
        assert_eq!(run("set -- a b c d e; echo ${@:1:-1}; echo after"), (String::new(), 1));
        // Subshell: fails with 1 but the parent survives to run `echo done`.
        assert_eq!(run("(a=(1 2 3); echo ${a[@]:0:-1}); echo done").1, 0);
        assert_eq!(run("x=$(a=(1 2 3); echo ${a[@]:0:-1}); echo $?").0, "1\n");
        // A string substring keeps its from-the-end negative-length semantics.
        assert_eq!(run("s=abcdef; echo ${s:1:-1}").0, "bcde\n");
        // A zero or positive length still slices normally.
        assert_eq!(run("a=(1 2 3 4 5); echo \"[${a[@]:1:0}]\"").0, "[]\n");
        assert_eq!(run("a=(1 2 3 4 5); echo ${a[@]:1:2}").0, "2 3\n");
    }

    #[test]
    fn arith_error_diagnostic_honors_stderr_redirect() {
        // Arithmetic-error diagnostics go through the shell's stderr routing, so
        // a command-scoped `2>/dev/null` silences them (bash parity) — regression
        // for a prior `eprintln!` that bypassed the redirect.
        assert_eq!(run("let \"3 apples\" 2>/dev/null; echo after"), ("after\n".into(), 0));
        assert_eq!(
            run("declare -i k=\"3 apples\" 2>/dev/null; echo after"),
            (String::new(), 1)
        );
        assert_eq!(
            run("for ((i=0;i<\"a b\";i++)); do :; done 2>/dev/null; echo after").0,
            "after\n"
        );
    }

    #[test]
    fn arith_error_in_word_aborts_command() {
        // Division by zero in a `$(( … ))` word is fatal in a non-interactive
        // shell (bash): the shell exits with status 1 without fabricating a "0",
        // so the following command never runs.
        let (o, st) = run("echo $((10/0)) 2>/dev/null; echo \"next=$?\"");
        assert_eq!(o, "");
        assert_eq!(st, 1);
        // An arithmetic error in an assignment value is likewise fatal.
        let (o2, st2) = run("x=$((1/0)) 2>/dev/null; echo \"st=$?\"");
        assert_eq!(o2, "");
        assert_eq!(st2, 1);
        // A `(( … ))` command reports its own error/status and does NOT leak the
        // abort flag onto the following command — it is not fatal.
        let (o3, _) = run("(( 1/0 )) 2>/dev/null; echo ok");
        assert_eq!(o3, "ok\n");
    }

    #[test]
    fn arith_error_discards_only_current_parse_unit() {
        // A `$(( … ))` word-expansion error is DISCARD-class (bash's
        // `jump_to_top_level(DISCARD)`): it aborts the *current* newline-delimited
        // parse unit but the shell keeps reading. In a script/stdin the *next
        // line* still runs (unlike the same-line `;` follow-on, which is dropped
        // with the aborted unit). Final `$?` reflects the surviving line.
        let (o, st) = run("echo $((1/0)) 2>/dev/null\necho after");
        assert_eq!(o, "after\n");
        assert_eq!(st, 0);
        // Same line, `;`-joined: the follow-on is discarded together with the
        // failed command, and the status is 1.
        let (o2, st2) = run("echo $((1/0)) 2>/dev/null; echo after");
        assert_eq!(o2, "");
        assert_eq!(st2, 1);
        // A subshell is a DISCARD-catch boundary: the child aborts (status 1) but
        // the parent survives and continues.
        let (o3, _st3) = run("( echo $((1/0)) ) 2>/dev/null; echo parent");
        assert_eq!(o3, "parent\n");
    }

    #[test]
    fn command_sub_runs_in_isolated_subshell() {
        // Variable assignments inside `$(...)` must not leak into the parent
        // shell (command substitution runs in a subshell, like bash).
        let (o, _) = run("count=0; r=$(count=5; echo $count); echo \"$r $count\"");
        assert_eq!(o, "5 0\n");
        // The command substitution still sees the parent's variables.
        let (o2, _) = run("x=hi; r=$(echo $x); echo $r");
        assert_eq!(o2, "hi\n");
        // Exit status of the command substitution propagates to $?.
        let (o3, _) = run("r=$(false); echo $?");
        assert_eq!(o3, "1\n");
        // A function defined inside `$(...)` does not persist afterwards.
        let (o4, _) = run("r=$(f(){ echo in; }; f); type -t f 2>/dev/null; echo \"[$r]\"");
        assert_eq!(o4, "[in]\n");
    }

    #[test]
    fn if_true() {
        let (o, _) = run("if true; then echo yes; else echo no; fi");
        assert_eq!(o, "yes\n");
    }

    #[test]
    fn for_loop() {
        let (o, _) = run("for x in a b c; do echo $x; done");
        assert_eq!(o, "a\nb\nc\n");
    }

    #[test]
    fn for_in_list_takes_reserved_words_as_plain_words() {
        // The `in …` list is not command position, so nothing in it is a
        // reserved word — not even `do`/`done`. Measured against bash 5.2.
        let (o, _) = run("for x in if then elif else fi while until do done; do printf '[%s]' \"$x\"; done");
        assert_eq!(o, "[if][then][elif][else][fi][while][until][do][done]");
        let (o, _) = run("for x in case esac in function time coproc select; do printf '[%s]' \"$x\"; done");
        assert_eq!(o, "[case][esac][in][function][time][coproc][select]");
        // Only the *first* word after the loop variable is the `in` keyword.
        let (o, _) = run("for x in in in; do printf '[%s]' \"$x\"; done");
        assert_eq!(o, "[in][in]");
        // …which is exactly why a missing separator before `do` is a syntax
        // error: `do` was swallowed by the list, so `done` is unexpected.
        // (through `eval`, so the diagnostic is redirectable — a parse error in
        // the outer source would abort before any redirect could apply).
        let (o, rc) = run("eval 'for x in a b do echo hi; done' 2>&1; echo \"rc=$?\"");
        assert!(o.contains("syntax error near unexpected token `done'"), "{o:?}");
        assert!(o.ends_with("rc=2\n"), "{o:?}");
        assert_eq!(rc, 0);
        // No `in` at all iterates `"$@"`; an empty `in` iterates nothing.
        let (o, _) = run("set -- p q; for x; do printf '[%s]' \"$x\"; done; echo; for x in; do echo NOT-REACHED; done");
        assert_eq!(o, "[p][q]\n");
    }

    #[test]
    fn select_in_list_takes_reserved_words_as_plain_words() {
        let (o, _) = run("select o in a fi b; do echo \"got=$o\"; break; done <<< '2'");
        assert_eq!(o, "got=fi\n");
    }

    #[test]
    fn while_with_break() {
        let (o, _) = run("x=0; while true; do echo $x; x=$((x+1)); if [ $x -ge 3 ]; then break; fi; done");
        assert_eq!(o, "0\n1\n2\n");
    }

    #[test]
    fn and_or() {
        let (o, _) = run("true && echo a; false || echo b; false && echo c");
        assert_eq!(o, "a\nb\n");
    }

    #[test]
    fn function_call() {
        let (o, _) = run("greet() { echo hi $1; }; greet there");
        assert_eq!(o, "hi there\n");
    }

    #[test]
    fn test_builtin() {
        let (_, s) = run("[ 3 -gt 2 ]");
        assert_eq!(s, 0);
        let (_, s2) = run("[ 1 -gt 2 ]");
        assert_eq!(s2, 1);
    }

    /// `test`/`[` compares the bytes it was given. Its operands are most often
    /// filenames, so a comparison that first approximated them would answer
    /// about a *different* name than the one it was asked about.
    #[test]
    fn test_builtin_compares_bytes_that_are_not_text() {
        // Equal bytes are equal; two values that differ only in a byte that
        // decodes to nothing are not — approximating both to U+FFFD would have
        // made them compare equal.
        assert_eq!(run("v=$(printf 'a\\xffb'); [ \"$v\" = \"$v\" ]").1, 0);
        assert_eq!(
            run("v=$(printf 'a\\xffb'); w=$(printf 'a\\xfeb'); [ \"$v\" = \"$w\" ]").1,
            1
        );
        assert_eq!(
            run("v=$(printf 'a\\xffb'); w=$(printf 'a\\xfeb'); [ \"$v\" != \"$w\" ]").1,
            0
        );
        // Ordering is byte-wise, which is what bash's C-locale `strcmp` does.
        assert_eq!(
            run("v=$(printf 'a\\xfeb'); w=$(printf 'a\\xffb'); [ \"$v\" \\< \"$w\" ]").1,
            0
        );
        // `-n`/`-z` see a non-empty value, not an undecodable one.
        assert_eq!(run("v=$(printf '\\xff'); [ -n \"$v\" ]").1, 0);
        assert_eq!(run("v=$(printf '\\xff'); [ -z \"$v\" ]").1, 1);
        // The operand is quoted back into the diagnostic as its own bytes.
        assert_eq!(
            run_raw("[ \"$(printf 'a\\xffb')\" -eq 1 ] 2>&1").0,
            b"osh: [: a\xffb: integer expression expected\n"
        );
        // A namespace primary answers false for a name that is not text —
        // nothing that is not text can be a set variable or a nameref, since
        // both namespaces are text.
        assert_eq!(run("[ -v \"$(printf 'a\\xffb')\" ]").1, 1);
        assert_eq!(run("[ -R \"$(printf 'a\\xffb')\" ]").1, 1);
    }

    #[test]
    fn test_builtin_integer_expression_error() {
        // A non-integer operand to an arithmetic comparison is an *error*
        // (exit 2), not a false result (exit 1) — matching bash. Base-10 only:
        // `0x10` is rejected here even though `[[ … ]]` would evaluate it.
        assert_eq!(run("[ 12 -eq 12.0 ]").1, 2);
        assert_eq!(run("[ 12.0 -eq 12 ]").1, 2);
        assert_eq!(run("[ 12 -eq abc ]").1, 2);
        assert_eq!(run("[ \"\" -eq 5 ]").1, 2);
        assert_eq!(run("[ 0x10 -eq 16 ]").1, 2);
        assert_eq!(run("test 12 -eq 12.0").1, 2);
        // Surrounding whitespace and a leading sign are still valid integers.
        assert_eq!(run("[ \" 5\" -eq 5 ]").1, 0);
        assert_eq!(run("[ +5 -eq 5 ]").1, 0);
        assert_eq!(run("[ -5 -lt 0 ]").1, 0);
        assert_eq!(run("[ 007 -eq 7 ]").1, 0);
    }

    #[test]
    fn test_v_variable_set() {
        // `[ -v name ]` and `[[ -v name ]]` test whether a variable is set.
        assert_eq!(run("x=1; [ -v x ]").1, 0);
        assert_eq!(run("[ -v x ]").1, 1);
        assert_eq!(run("x=1; [[ -v x ]] && echo yes").0, "yes\n");
        assert_eq!(run("[[ -v missing ]] || echo no").0, "no\n");
        // An empty-but-set variable still counts as set.
        assert_eq!(run("x=; [ -v x ]").1, 0);
    }

    #[test]
    fn test_v_array_element() {
        // Whole array is set; specific element presence honored.
        assert_eq!(run("a=(x y z); [[ -v a ]] && echo arr").0, "arr\n");
        assert_eq!(run("a=(x y z); [[ -v a[1] ]] && echo e1").0, "e1\n");
        assert_eq!(run("a=([5]=x); [[ -v a[2] ]] || echo gap").0, "gap\n");
        assert_eq!(run("declare -A m; m[k]=v; [[ -v m[k] ]] && echo key").0, "key\n");
        assert_eq!(run("declare -A m; [[ -v m[nope] ]] || echo nokey").0, "nokey\n");
    }

    #[test]
    fn length_expansion() {
        let (o, _) = run("x=hello; echo ${#x}");
        assert_eq!(o, "5\n");
    }

    #[test]
    fn negated_pipeline_status() {
        let (_, s) = run("! true");
        assert_eq!(s, 1);
    }

    #[test]
    fn quoted_no_split() {
        let (o, _) = run(r#"x="a b c"; for w in "$x"; do echo $w; done"#);
        assert_eq!(o, "a b c\n");
    }

    #[test]
    fn case_literal_and_glob() {
        let (o, _) = run("case hello in h*) echo star;; *) echo other;; esac");
        assert_eq!(o, "star\n");
        let (o2, _) = run("case foo in a|foo|b) echo alt;; esac");
        assert_eq!(o2, "alt\n");
        let (o3, _) = run("case xyz in a*) echo a;; esac; echo done");
        assert_eq!(o3, "done\n");
    }

    #[test]
    fn case_uses_variable() {
        let (o, _) = run("x=cat.txt; case $x in *.txt) echo text;; *.md) echo md;; esac");
        assert_eq!(o, "text\n");
    }

    #[test]
    fn case_char_class() {
        let (o, _) = run("case 5 in [0-9]) echo digit;; *) echo no;; esac");
        assert_eq!(o, "digit\n");
    }

    #[test]
    fn case_fallthrough_semi_amp() {
        // `;&` runs the next arm's body unconditionally.
        let (o, _) = run("case x in x) echo a ;& y) echo b ;; z) echo c ;; esac");
        assert_eq!(o, "a\nb\n");
    }

    #[test]
    fn case_fallthrough_stops_at_break() {
        // Fall through a chain of `;&` until a `;;` breaks.
        let (o, _) = run("case a in a) echo 1 ;& b) echo 2 ;& c) echo 3 ;; d) echo 4 ;; esac");
        assert_eq!(o, "1\n2\n3\n");
    }

    #[test]
    fn case_continue_match_dsemi_amp() {
        // `;;&` resumes pattern testing; both matching arms run.
        let (o, _) = run("case abc in a*) echo one ;;& *c) echo two ;; *) echo three ;; esac");
        assert_eq!(o, "one\ntwo\n");
    }

    #[test]
    fn case_continue_match_no_second() {
        // `;;&` resumes matching but no later arm matches.
        let (o, _) = run("case abc in a*) echo one ;;& z*) echo two ;; esac; echo done");
        assert_eq!(o, "one\ndone\n");
    }

    #[test]
    fn select_picks_by_number() {
        let (o, _) = run("select x in a b c; do echo \"picked $x\"; break; done <<< \"2\"");
        assert_eq!(o, "picked b\n");
    }

    #[test]
    fn select_invalid_gives_empty() {
        let (o, _) = run("select x in a b; do echo \"got=$x\"; break; done <<< \"9\"");
        assert_eq!(o, "got=\n");
    }

    #[test]
    fn select_sets_reply() {
        let (o, _) = run("select x in a b; do echo \"r=$REPLY x=$x\"; break; done <<< \"1\"");
        assert_eq!(o, "r=1 x=a\n");
    }

    #[test]
    fn select_eof_terminates() {
        // The here-string provides one line; the next read hits EOF and ends
        // the loop (no infinite spin, no `break` needed). EOF's own closing
        // newline goes to *stdout* — hence the second `\n` — even though the
        // menu and PS3 prompt went to stderr. Verified against bash 5 with the
        // two streams separated.
        let (o, _) = run("select x in a b; do echo \"$x\"; done <<< \"1\"");
        assert_eq!(o, "a\n\n");
    }

    #[test]
    fn select_menu_layout_matches_bash() {
        let items = |s: &str| -> Vec<Str> { s.split(' ').map(|w| w.as_bytes().to_vec()).collect() };
        // The menu is bytes (an item is a *value*); every item here is ASCII.
        let select_menu = |items: &[Str], width: usize| -> String {
            String::from_utf8(super::select_menu(items, width)).expect("menu is not text")
        };
        // A list that fits on one row is transposed into one *column* — the
        // familiar `select` look.
        assert_eq!(select_menu(&items("aaaa bbbb cccc"), 80), "1) aaaa\n2) bbbb\n3) cccc\n");
        // Twelve one-character items at 80 columns: stride 1+2+2+2 = 7, so
        // 80/7 = 11 columns, 2 rows, then 6 columns. Column-major, and the
        // first column's indices are one digit wide while the rest are two.
        assert_eq!(
            select_menu(&items("a b c d e f g h i j k l"), 80),
            "1) a    3) c   5) e   7) g   9) i  11) k\n\
             2) b    4) d   6) f   8) h  10) j  12) l\n"
        );
        // Narrower screens repack the same list; at width 1 it degenerates to
        // one column, where *every* index is two digits wide because the row
        // count is 12.
        assert_eq!(
            select_menu(&items("a b c d e f g h i j k l"), 40),
            "1) a    4) d   7) g  10) j\n\
             2) b    5) e   8) h  11) k\n\
             3) c    6) f   9) i  12) l\n"
        );
        assert!(select_menu(&items("a b c d e f g h i j k l"), 1).starts_with(" 1) a\n 2) b\n"));
        // Gutters are padded with tabs wherever a tab stop can be reached.
        assert_eq!(
            select_menu(&items("i1 i2 i3 i4 i5 i6 i7 i8 i9 i10 i11"), 80),
            "1) i1\t  3) i3\t   5) i5    7) i7    9) i9   11) i11\n\
             2) i2\t  4) i4\t   6) i6    8) i8   10) i10\n"
        );
        // A short final column just ends its row — no trailing padding.
        assert_eq!(
            select_menu(&items("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaa bbbbbbbbbbbbbbbbbbbbbbbbbbbbbb cccccccccccccccccccccccccccccc"), 80),
            "1) aaaaaaaaaaaaaaaaaaaaaaaaaaaaaa  3) cccccccccccccccccccccccccccccc\n\
             2) bbbbbbbbbbbbbbbbbbbbbbbbbbbbbb\n"
        );
        // bash prints a bare newline for an empty list (unreachable from
        // `select`, which returns before printing, but part of the function).
        assert_eq!(select_menu(&[], 80), "\n");
    }

    /// [`single_quote_bytes`] for a text value, so a test can build shell
    /// source with `format!`. Quoting only ever inserts ASCII, so quoting text
    /// yields text and the round trip cannot fail.
    fn single_quote(s: &str) -> String {
        String::from_utf8(single_quote_bytes(s.as_bytes())).unwrap_or_default()
    }

    #[test]
    fn select_menu_columns_read_like_atoi() {
        // `$COLUMNS` is read with `atoi`: leading whitespace and a sign are
        // skipped and the first non-digit ends the number, so `40x` is 40 while
        // `abc`, `0`, a negative and an unset variable all fall back to 80.
        let wide = "select o in aaaa bbbb cccc dddd eeee ffff gggg hhhh; do break; done </dev/null 2>&1 | head -1";
        for v in ["40x", " 40", "+40", "0040", "40 "] {
            assert_eq!(
                run(&format!("COLUMNS={}; {wide}", single_quote(v))).0,
                "1) aaaa\t 3) cccc  5) eeee  7) gggg\n",
                "COLUMNS={v:?}"
            );
        }
        for v in ["-5", "0", "abc", "", "999999999999999999999999"] {
            assert_eq!(
                run(&format!("COLUMNS={}; {wide}", single_quote(v))).0,
                "1) aaaa\n",
                "COLUMNS={v:?}"
            );
        }
    }

    #[test]
    fn select_eof_sets_status_and_reply() {
        // An EOF-terminated `select` reports status 1 and clears REPLY,
        // overwriting whatever was there before — the signal that the user ran
        // out of input rather than leaving via `break`.
        let (o, _) = run("REPLY=preset; select x in a b; do break; done < /dev/null; echo \"s=$? r=[$REPLY] x=${x-unset}\"");
        assert_eq!(o, "\ns=1 r=[] x=unset\n");
    }

    #[test]
    fn here_string_read() {
        let (o, _) = run("read x <<< hello; echo got $x");
        assert_eq!(o, "got hello\n");
    }

    #[test]
    fn read_last_var_keeps_internal_spacing() {
        // The final variable receives the raw remainder (internal runs of IFS
        // whitespace preserved), unlike a naive re-join.
        let (o, _) = run("read a b <<< '1   2   3'; echo \"[$a][$b]\"");
        assert_eq!(o, "[1][2   3]\n");
    }

    #[test]
    fn read_into_array() {
        let (o, _) = run("read -a arr <<< 'x y z'; echo \"${#arr[@]}:${arr[1]}\"");
        assert_eq!(o, "3:y\n");
    }

    #[test]
    fn read_raw_vs_escape() {
        // Without -r, a backslash escapes the next char; with -r it is literal.
        assert_eq!(run("read x <<< 'a\\tb'; echo \"$x\"").0, "atb\n");
        assert_eq!(run("read -r x <<< 'a\\tb'; echo \"$x\"").0, "a\\tb\n");
    }

    #[test]
    fn read_partial_final_line_status_one() {
        // A final line ending at EOF without a newline still assigns the value
        // but reports status 1 (matching bash). Here: two reads of "a\nb" — the
        // first line is newline-terminated (rc 0), the second hits EOF (rc 1).
        let (o, _) = run(
            "printf 'a\\nb' | { read x; echo \"rc1=$? x=$x\"; read y; echo \"rc2=$? y=$y\"; }",
        );
        assert_eq!(o, "rc1=0 x=a\nrc2=1 y=b\n");
        // A newline-terminated single line reports success.
        let (o2, _) = run("printf 'a\\n' | { read x; echo \"rc=$? x=$x\"; }");
        assert_eq!(o2, "rc=0 x=a\n");
    }

    #[test]
    fn read_custom_ifs() {
        let (o, _) = run("IFS=: read a b c <<< '1:2:3'; echo \"$a-$b-$c\"");
        assert_eq!(o, "1-2-3\n");
    }

    /// A delimiter is `ws* nonws? ws*`, so IFS whitespace next to a
    /// non-whitespace IFS character is part of the *same* delimiter — `a : b`
    /// with `IFS=': '` is two fields, not four — and a delimiter that runs to
    /// the end of the line ends it rather than opening a final empty field.
    #[test]
    fn read_coalesces_a_delimiter_run_and_drops_a_trailing_one() {
        let nf = |ifs: &str, input: &str| {
            run(&format!(
                "IFS='{ifs}' read -r -a A <<< '{input}'; printf '%d' \"${{#A[@]}}\"; \
                 for e in \"${{A[@]}}\"; do printf '[%s]' \"$e\"; done"
            ))
            .0
        };
        // A trailing non-whitespace delimiter closes the last field; it does not
        // add an empty one. Two of them do add one, between them.
        assert_eq!(nf(":", "a:b:"), "2[a][b]");
        assert_eq!(nf(":", "a:b::"), "3[a][b][]");
        assert_eq!(nf(":", "a:"), "1[a]");
        // A line that is nothing but delimiters has one field fewer than it has
        // delimiters, by the same rule.
        assert_eq!(nf(":", ":"), "1[]");
        assert_eq!(nf(":", "::"), "2[][]");
        assert_eq!(nf(":", ":::"), "3[][][]");
        // Mixed IFS: whitespace either side of the `:` joins that delimiter.
        assert_eq!(nf(": ", "a : b"), "2[a][b]");
        assert_eq!(nf(": ", "a  :"), "1[a]");
        assert_eq!(nf(": ", "a:  "), "1[a]");
        assert_eq!(nf(": ", " :a: "), "2[][a]");
        // …but only *one* non-whitespace character per delimiter, so a second
        // one still opens an empty field.
        assert_eq!(nf(": ", "a: :b"), "3[a][][b]");
        assert_eq!(nf(": ", "a: : "), "2[a][]");
        // Whitespace-only IFS is unchanged: runs collapse, ends are trimmed.
        assert_eq!(nf(" ", "  a  b  "), "2[a][b]");
    }

    /// The last name soaks up "the remaining words and their intervening
    /// separators" — but only when there are more fields than names. With no
    /// more fields than names each name takes its own field, which is the whole
    /// of the difference between `a:b:` (two fields, `y=b`) and `a:b:c:`
    /// (three, so `y` keeps the separators *and* the trailing delimiter).
    #[test]
    fn read_last_name_soaks_only_when_fields_outnumber_names() {
        let r = |ifs: &str, input: &str, names: &str| {
            let show =
                names.split(' ').map(|n| format!("printf '[%s]' \"${n}\";")).collect::<String>();
            run(&format!("IFS='{ifs}' read -r {names} <<< '{input}'; {show}")).0
        };
        // Two fields, two names: no soaking, so the trailing `:` is simply gone.
        assert_eq!(r(":", "a:b:", "x y"), "[a][b]");
        // Three fields, two names: the second soaks the rest of the line
        // verbatim — separators and trailing delimiter included.
        assert_eq!(r(":", "a:b:c:", "x y"), "[a][b:c:]");
        assert_eq!(r(":", "a:b::", "x y"), "[a][b::]");
        assert_eq!(r(":", "a::b:", "x y"), "[a][:b:]");
        // …and with a third name there is nothing left to soak.
        assert_eq!(r(":", "a:b::", "x y z"), "[a][b][]");
        assert_eq!(r(":", "a:b:", "x y z"), "[a][b][]");
        // One name and more than one field: the whole line, unsplit.
        assert_eq!(r(":", "a:b:", "x"), "[a:b:]");
        assert_eq!(r(":", ":a:", "x"), "[:a:]");
        assert_eq!(r(":", "::", "x"), "[::]");
        // One name and one field: the field, delimiter dropped.
        assert_eq!(r(":", "a:", "x"), "[a]");
        assert_eq!(r(":", ":", "x"), "[]");
        assert_eq!(r(": ", "a:  ", "x"), "[a]");
        assert_eq!(r(": ", "a  :", "x"), "[a]");
        // Soaking still strips trailing IFS whitespace from the remainder.
        assert_eq!(r(" ", "a b ", "x"), "[a b]");
        assert_eq!(r(":", "a:b: ", "x y"), "[a][b: ]");
        assert_eq!(r(": ", "a:b: ", "x y"), "[a][b]");
        // Fewer fields than names leaves the extras empty, as before.
        assert_eq!(r(":", "a", "x y"), "[a][]");
    }

    /// `read` strips its *delimiter* and nothing else. A `\r` before the newline
    /// is ordinary data that bash keeps, so CRLF-framed input (an HTTP header, a
    /// Windows-written `.csv`) arrives intact; stripping it also disagreed with
    /// the `-d`/`-n`/`-N` record path, which never stripped it.
    #[test]
    fn read_keeps_a_carriage_return_before_the_newline() {
        assert_eq!(run(r#"printf 'a\r\n' | { IFS= read -r l; printf '[%s]' "$l"; }"#).0, "[a\r]");
        // Default IFS does not list `\r`, so splitting does not remove it either.
        assert_eq!(run(r#"printf 'a\r\n' | { read -r l; printf '[%s]' "$l"; }"#).0, "[a\r]");
        // Interior and repeated CRs are data too.
        assert_eq!(
            run(r#"printf 'p\r\rq\n' | { IFS= read -r l; printf '[%s]' "$l"; }"#).0,
            "[p\r\rq]"
        );
        // A CR at EOF with no newline: still a partial read (status 1), CR kept.
        assert_eq!(
            run(r#"printf 'x\r' | { IFS= read -r l; printf '%d[%s]' "$?" "$l"; }"#).0,
            "1[x\r]"
        );
        // The record path agrees, as it always did.
        assert_eq!(
            run(r#"printf 'a\r\n' | { read -r -n 3 l; printf '[%s]' "$l"; }"#).0,
            "[a\r]"
        );
        // A `\r` *chosen* as the delimiter is consumed, like any delimiter.
        assert_eq!(
            run("printf 'a\\r\\n' | { read -r -d $'\\r' l; printf '[%s]' \"$l\"; }").0,
            "[a]"
        );
    }

    /// A line that is not valid UTF-8 must not read as end-of-input. `read` went
    /// through `BufRead::read_line`, which consumes the line and *then* reports
    /// `InvalidData` — indistinguishable from EOF once the error was dropped — so
    /// a `while read` loop stopped at the first such line and reported success,
    /// silently processing a prefix of its input. The byte itself still cannot be
    /// carried (it becomes U+FFFD): see TD-OILS-BYTE-STRINGS.
    #[test]
    fn read_does_not_mistake_a_non_utf8_line_for_eof() {
        // Three lines, the first holding a lone high byte: all three are read.
        assert_eq!(
            run(r#"printf 'a\xa9b\ncr\nlast\n' | { n=0; while IFS= read -r l; do n=$((n+1)); done; echo "$n"; }"#).0,
            "3\n"
        );
        // The line is assigned, and reports success rather than a partial read.
        assert_eq!(
            run(r#"printf 'a\xa9b\n' | { IFS= read -r l; printf '%d %d' "$?" "${#l}"; }"#).0,
            "0 3"
        );
        // The bytes after the offending one are not lost with it.
        assert_eq!(
            run(r#"printf 'a\xa9b\n' | { IFS= read -r l; printf '%s' "${l%?b}${l#a?}"; }"#).0,
            "ab"
        );
    }

    #[test]
    fn unquoted_word_split_honors_ifs() {
        // Unquoted expansion splits on a custom IFS, not just whitespace.
        assert_eq!(
            run(r#"IFS=:; x="a:b:c"; for w in $x; do echo "<$w>"; done"#).0,
            "<a>\n<b>\n<c>\n"
        );
        // Adjacent non-whitespace delimiters preserve an empty field.
        assert_eq!(
            run(r#"IFS=:; x="a::c"; for w in $x; do echo "<$w>"; done"#).0,
            "<a>\n<>\n<c>\n"
        );
        // A leading non-whitespace delimiter yields a leading empty field; a
        // trailing one does not add a trailing empty field.
        assert_eq!(
            run(r#"IFS=:; x=":a:"; for w in $x; do echo "<$w>"; done"#).0,
            "<>\n<a>\n"
        );
        // IFS whitespace runs still collapse and trim.
        assert_eq!(
            run(r#"x="  a   b  "; for w in $x; do echo "<$w>"; done"#).0,
            "<a>\n<b>\n"
        );
        // Mixed whitespace + non-whitespace IFS: whitespace around the delimiter
        // is absorbed.
        assert_eq!(
            run(r#"IFS=' :'; x="a : b"; for w in $x; do echo "<$w>"; done"#).0,
            "<a>\n<b>\n"
        );
    }

    #[test]
    fn ifs_defaults_to_space_tab_newline() {
        // bash seeds IFS to the literal default at startup; it is a real,
        // readable variable, not merely an implicit splitting rule. `declare -p`
        // renders it via ANSI-C quoting (bash: `declare -- IFS=$' \t\n'`).
        assert_eq!(run("declare -p IFS").0, "declare -- IFS=$' \\t\\n'\n");
        assert_eq!(run(r#"printf '%s' "${#IFS}""#).0, "3");
        // The ubiquitous save/restore idiom must round-trip: saving `$IFS`,
        // narrowing it, then restoring must bring back whitespace splitting —
        // if IFS were unset, `old=$IFS` would save "" and the restore would
        // silently disable field splitting.
        assert_eq!(
            run(r#"old=$IFS; IFS=:; IFS=$old; x="a b c"; for w in $x; do echo "<$w>"; done"#).0,
            "<a>\n<b>\n<c>\n"
        );
    }

    #[test]
    fn declare_p_names_scalar_dynamic_specials() {
        // `declare -p NAME` for a scalar dynamic special variable prints its
        // live value with the fixed bash attributes, rather than "not found" —
        // the value counters (`BASHPID`/`RANDOM`/`SECONDS`) carry `-i`, the rest
        // print `--`. Previously osh errored here even though `$NAME` expanded.
        assert_eq!(run("declare -p BASH_SUBSHELL").0, "declare -- BASH_SUBSHELL=\"0\"\n");
        assert_eq!(run("declare -p LINENO").0, "declare -- LINENO=\"1\"\n");
        assert_eq!(run("declare -p SECONDS").0, "declare -i SECONDS=\"0\"\n");
        // BASHPID / EPOCHSECONDS have runtime-dependent values, so just assert
        // the flag+name shape and a non-error status.
        let (out, st) = run("declare -p BASHPID");
        assert_eq!(st, 0);
        assert!(out.starts_with("declare -i BASHPID=\""), "got {out:?}");
        let (out, st) = run("declare -p EPOCHSECONDS");
        assert_eq!(st, 0);
        assert!(out.starts_with("declare -- EPOCHSECONDS=\""), "got {out:?}");
        // A genuinely-unset name still errors with status 1.
        assert_eq!(run("declare -p NoSuchVar_xyz").1, 1);
    }

    /// bash binds `OPTIND` and `OPTERR` from startup, before anything has
    /// parsed an option, and the value matters beyond the listing: the standard
    /// option-parsing preamble ends `shift $((OPTIND - 1))`, so a script that
    /// gets there without calling `getopts` (no options passed) must shift 0 —
    /// with `OPTIND` unset the arithmetic is `-1` and the shift fails.
    #[test]
    fn optind_and_opterr_are_bound_from_startup() {
        assert_eq!(run(r#"echo "[$OPTIND][$OPTERR]""#).0, "[1][1]\n");
        assert_eq!(
            run("declare -p OPTIND OPTERR").0,
            "declare -i OPTIND=\"1\"\ndeclare -- OPTERR=\"1\"\n"
        );
        // The preamble shape that needs the seed.
        assert_eq!(run(r#"set -- a b; shift $((OPTIND - 1)); echo "$*""#).0, "a b\n");
        // `OPTIND` carries the integer attribute, so an assignment to it is
        // evaluated as arithmetic; `OPTERR` does not. That asymmetry is bash's.
        assert_eq!(run("OPTIND=3+4; declare -p OPTIND").0, "declare -i OPTIND=\"7\"\n");
        assert_eq!(run("OPTERR=3+4; declare -p OPTERR").0, "declare -- OPTERR=\"3+4\"\n");
        // A scan still starts at 1 and leaves the index past the last option.
        assert_eq!(run("set -- -a -b x; while getopts ab o; do :; done; echo $OPTIND").0, "3\n");
    }

    #[test]
    fn comp_wordbreaks_is_bound_from_startup() {
        // bash's own default, byte for byte — the set readline breaks a
        // completion word on, which a completion function expects to find bound
        // (and often edits around a call).
        assert_eq!(
            run("declare -p COMP_WORDBREAKS").0,
            "declare -- COMP_WORDBREAKS=$' \\t\\n\"\\'@><=;|&(:'\n"
        );
        assert_eq!(run("echo ${#COMP_WORDBREAKS}").0, "14\n");
        // It is an ordinary variable: a completion function may change it, and
        // the change stands (that is how `_get_comp_words_by_ref` works).
        assert_eq!(
            run("f() { COMP_WORDBREAKS=x; }; compgen -F f q 2>/dev/null; echo \"<$COMP_WORDBREAKS>\"").0,
            "<x>\n"
        );
    }

    /// `$SRANDOM` (bash 5.1+) is 32 bits from the system entropy source — a
    /// different generator from `$RANDOM`, with a full 32-bit range and no
    /// seed, which is why bash documents assignments to it as having no effect.
    #[test]
    fn srandom_is_a_seedless_32_bit_random() {
        // Two reads differ (a frozen value would be the obvious bug) and both
        // fit in 32 bits.
        let (o, st) = run(r#"a=$SRANDOM; b=$SRANDOM; echo "$a $b""#);
        assert_eq!(st, 0);
        let (a, b) = o.trim().split_once(' ').expect("two values");
        let (a, b) = (a.parse::<u64>().expect("numeric"), b.parse::<u64>().expect("numeric"));
        assert_ne!(a, b, "two reads returned the same value: {o:?}");
        assert!(a <= u64::from(u32::MAX) && b <= u64::from(u32::MAX), "not 32-bit: {o:?}");
        // An assignment is swallowed: it neither takes effect nor leaves a
        // stored variable behind that would shadow the dynamic read.
        assert_ne!(run("SRANDOM=5; echo $SRANDOM").0.trim(), "5");
        assert_eq!(
            run(r#"SRANDOM=5; a=$SRANDOM; b=$SRANDOM; [ "$a" != "$b" ] && echo differ"#).0,
            "differ\n"
        );
        // Reseeding `$RANDOM` does not make `$SRANDOM` reproducible — the two
        // generators are separate, as in bash.
        assert_eq!(
            run(r#"RANDOM=1; a=$SRANDOM; RANDOM=1; b=$SRANDOM; [ "$a" != "$b" ] && echo apart"#).0,
            "apart\n"
        );
        // A subshell does not repeat its parent's stream.
        assert_eq!(
            run(r#"a=$(echo $SRANDOM); b=$(echo $SRANDOM); [ "$a" != "$b" ] && echo apart"#).0,
            "apart\n"
        );
        // `declare -p` prints a live value with the integer attribute; the
        // listing form is the bare name (see the dynamic-specials table).
        let named = run("declare -p SRANDOM").0;
        assert!(named.starts_with("declare -i SRANDOM=\""), "got {named:?}");
    }

    /// The *listing* forms — bare `declare -p`, the flag-filtered `declare -i`
    /// and `declare -a`, and `readonly -p` — report the dynamic special
    /// variables too. Their listing shape is not the named one: bash's listing
    /// prints the value it has *stored*, and a computed variable has none, so
    /// the name lists with its attributes and nothing else. osh used to omit
    /// these names from every listing, so `declare -p` was missing 21 of the
    /// names bash prints.
    #[test]
    fn listings_report_dynamic_special_variables() {
        let lines = |src: &str| run(src).0.lines().map(str::to_string).collect::<Vec<String>>();
        let has = |v: &[String], s: &str| v.iter().any(|l| l == s);

        let all = lines("declare -p");
        assert!(has(&all, "declare -i RANDOM"), "got {all:?}");
        assert!(has(&all, "declare -i BASHPID"), "got {all:?}");
        assert!(has(&all, "declare -- LINENO"), "got {all:?}");
        assert!(has(&all, "declare -- BASH_SUBSHELL"), "got {all:?}");
        assert!(has(&all, "declare -a BASH_SOURCE=()"), "got {all:?}");
        // `SECONDS` keeps its `-i` for `declare -p SECONDS` but loses it in a
        // listing — measured against bash 5.2, not a guess.
        assert!(has(&all, "declare -- SECONDS"), "got {all:?}");
        // `PPID` is a real binding rather than a computed one, so it is the one
        // entry that lists *with* a value; only its shape is fixed.
        assert!(all.iter().any(|l| l.starts_with("declare -ir PPID=\"")), "got {all:?}");

        // The flag-filtered listings select on the same attributes.
        let ints = lines("declare -i");
        assert!(has(&ints, "declare -i BASHPID"), "got {ints:?}");
        assert!(has(&ints, "declare -i RANDOM"), "got {ints:?}");
        assert!(!ints.iter().any(|l| l.contains("SECONDS")), "got {ints:?}");
        let arrays = lines("declare -a");
        assert!(has(&arrays, "declare -a BASH_SOURCE=()"), "got {arrays:?}");
        assert!(has(&arrays, "declare -a BASH_LINENO=()"), "got {arrays:?}");
        let ro = lines("readonly -p");
        assert!(ro.iter().any(|l| l.starts_with("declare -ir PPID=\"")), "got {ro:?}");
        // …and a dynamic special without the letter stays out of that listing.
        assert!(!ro.iter().any(|l| l.contains("RANDOM")), "got {ro:?}");

        // A real binding shadows the table rather than doubling it: inside a
        // function `BASH_SOURCE` has a live entry, and the listing prints that.
        let inner = lines("f(){ declare -p; }; f");
        assert_eq!(inner.iter().filter(|l| l.contains(" BASH_SOURCE")).count(), 1, "got {inner:?}");
        assert!(!has(&inner, "declare -a BASH_SOURCE=()"), "got {inner:?}");
    }

    #[test]
    fn bash_argv0_sets_dollar_zero() {
        // `BASH_ARGV0=name` sets `$0`; reading `$BASH_ARGV0` reflects the
        // current `$0`. It is dynamic (not stored in `vars`).
        assert_eq!(run("BASH_ARGV0=prog; echo \"$0\"").0, "prog\n");
        assert_eq!(run("BASH_ARGV0=prog; echo \"[$BASH_ARGV0]\"").0, "[prog]\n");
        // Assigning empty clears `$0`, matching bash.
        assert_eq!(run("BASH_ARGV0=; echo \"[$0]\"").0, "[]\n");
        // `$0` inside a function is still the shell name (BASH_ARGV0), not the
        // function name — bash parity.
        assert_eq!(run("f(){ echo \"$0\"; }; BASH_ARGV0=zz; f").0, "zz\n");
        // `declare -p` prints it as a plain string variable.
        assert_eq!(
            run("BASH_ARGV0=nm; declare -p BASH_ARGV0").0,
            "declare -- BASH_ARGV0=\"nm\"\n"
        );
        // It is enumerated by the `${!BASH*}` name-prefix expansion.
        assert!(run("echo ${!BASH*}").0.contains("BASH_ARGV0"));
        // `+=` appends to the current `$0` (osh uses a predictable append; see
        // the note in `apply_assignment` about bash's obscure `+=` quirk).
        assert_eq!(run("BASH_ARGV0=ab; BASH_ARGV0+=cd; echo \"$0\"").0, "abcd\n");
    }

    #[test]
    fn unquoted_word_split_boundary_delims() {
        // IFS whitespace at an expansion boundary must break against adjacent
        // literal text (the classic bug: `[$x]` gluing `[` to the first field).
        // Values here match real bash's field splitting exactly.
        assert_eq!(
            run(r#"x="  a b  "; printf "<%s>" [$x]; echo"#).0,
            "<[><a><b><]>\n"
        );
        // Leading boundary whitespace splits `pre` from the first field.
        assert_eq!(run(r#"x="  a  "; printf "<%s>" pre$x; echo"#).0, "<pre><a>\n");
        // Trailing boundary whitespace splits the last field from `suf`.
        assert_eq!(
            run(r#"x="  a  "; printf "<%s>" ${x}suf; echo"#).0,
            "<a><suf>\n"
        );
        // An all-whitespace expansion between two literals still forces a split.
        assert_eq!(
            run(r#"x="  "; printf "<%s>" pre${x}suf; echo"#).0,
            "<pre><suf>\n"
        );
        // An empty (unset) expansion does NOT split — the literals glue.
        assert_eq!(
            run(r#"x=""; printf "<%s>" pre${x}suf; echo"#).0,
            "<presuf>\n"
        );
        // Non-whitespace IFS boundary: a trailing delimiter splits against the
        // following literal without producing a spurious empty field.
        assert_eq!(
            run(r#"IFS=:; x="a:"; printf "<%s>" ${x}suf; echo"#).0,
            "<a><suf>\n"
        );
        // A bare non-whitespace delimiter after literal content closes that
        // field (no empty field appears).
        assert_eq!(
            run(r#"IFS=:; x=":"; printf "<%s>" a$x; echo"#).0,
            "<a>\n"
        );
        // Mixed IFS `ws* nonws ws*` between two literals collapses to a single
        // delimiter (the non-whitespace char is absorbed into the whitespace
        // run), so no empty field appears between `pre` and `suf`.
        assert_eq!(
            run(r#"IFS=" :"; x=" : "; printf "<%s>" pre${x}suf; echo"#).0,
            "<pre><suf>\n"
        );
    }

    #[test]
    fn read_nchars_limit() {
        // `-n N` stops after N characters (here-string adds a trailing \n, so
        // there are plenty of characters available).
        assert_eq!(run("read -n 3 x <<< 'abcdef'; echo \"$x\"").0, "abc\n");
        // Status 0 because the character count was reached.
        assert_eq!(run("read -n 3 x <<< 'abcdef'; echo $?").0, "0\n");
    }

    #[test]
    fn read_attached_and_clustered_options() {
        // Attached option-argument: `-d:` glues the delimiter to the flag.
        assert_eq!(
            run("{ read -d: x; read -d: y; } <<< 'a:b:c'; echo \"$x-$y\"").0,
            "a-b\n"
        );
        // Attached numeric argument: `-n3`.
        assert_eq!(run("read -n3 x <<< 'abcdef'; echo \"$x\"").0, "abc\n");
        // Clustered flags with a trailing attached argument: `-rn3`.
        assert_eq!(run("read -rn3 x <<< 'ab\\cd'; echo \"$x\"").0, "ab\\\n");
        // Separated form still works.
        assert_eq!(run("read -d ':' p <<< 'a:b'; echo \"$p\"").0, "a\n");
    }

    #[test]
    fn read_option_argument_validation() {
        // `-t` requires a non-negative decimal timeout; bash rejects a
        // non-numeric or negative value with `invalid timeout specification`
        // (exit 1) and accepts a fractional one.
        let (out, st) = run("read -t abc x <<< hi 2>&1");
        assert_eq!(out, "osh: read: abc: invalid timeout specification\n");
        assert_eq!(st, 1);
        assert_eq!(run("read -t -5 x <<< hi 2>&1").1, 1);
        assert_eq!(run("read -t 1.5 x <<< hi; echo $?").0, "0\n");
        // `-n`/`-N` require a non-negative integer.
        assert_eq!(
            run("read -n abc x <<< hi 2>&1").0,
            "osh: read: abc: invalid number\n"
        );
        assert_eq!(run("read -N -3 x <<< hi 2>&1").1, 1);
        // `-u` requires a valid file-descriptor specification.
        assert_eq!(
            run("read -u abc x <<< hi 2>&1").0,
            "osh: read: abc: invalid file descriptor specification\n"
        );
        // A missing argument to an option prints the usage synopsis and exits 2.
        let (out, st) = run("read -t 2>&1 </dev/null");
        assert!(out.starts_with("osh: read: -t: option requires an argument\n"));
        assert!(out.contains("read: usage: read [-ers]"));
        assert_eq!(st, 2);
    }

    #[test]
    fn read_prompt_suppressed_for_non_tty_input() {
        // `-p PROMPT` is written to stderr *only* when the input is a real
        // terminal. Under a pipeline, here-string, or redirect the read is
        // silent. We fold stderr into stdout via a command substitution
        // (`2>&1`) so that a wrongly-emitted prompt would show up in the
        // captured text; the fix keeps it empty.
        assert_eq!(
            run("out=$(echo x | { read -p 'P: ' y; echo \"$y\"; } 2>&1); echo \"[$out]\"").0,
            "[x]\n"
        );
        assert_eq!(
            run("out=$({ read -p 'P: ' y; echo \"$y\"; } 2>&1 <<< 'hi'); echo \"[$out]\"").0,
            "[hi]\n"
        );
        // The value is still read correctly regardless of the prompt.
        assert_eq!(
            run("printf 'a b\\n' | { read -p '> ' x z; echo \"$x-$z\"; }").0,
            "a-b\n"
        );
    }

    #[test]
    fn scalar_assign_to_array_updates_element_zero() {
        // bash: a plain scalar assignment (or `read`) to an existing indexed
        // array updates element 0, leaving the other elements intact.
        assert_eq!(run("a=(1 2 3); a=x; echo \"$a ${a[@]}\"").0, "x x 2 3\n");
        assert_eq!(run("a=(1 2 3); read a <<< 'q'; echo \"$a ${a[@]}\"").0, "q q 2 3\n");
        // Integer attribute still evaluates the RHS and lands in element 0.
        assert_eq!(run("declare -ia a=(1 2 3); a=4+5; echo \"$a ${a[@]}\"").0, "9 9 2 3\n");
    }

    #[test]
    fn declare_array_literal_applies_value_attributes() {
        // `declare -ia`/`-ai` sets the integer attribute on the array, so later
        // element assignments evaluate arithmetically.
        assert_eq!(run("declare -ai b=(1 2 3); b[1]=6+6; echo \"${b[@]}\"").0, "1 12 3\n");
        // `declare -ua` uppercases values stored into the array.
        assert_eq!(run("declare -ua u=(ab cd); u[0]=xy; echo \"${u[@]}\"").0, "XY CD\n");
        // `declare -ra` makes the array readonly: a later element assignment is
        // fatal in a non-interactive shell (bash) — the shell exits with status
        // 1, so the following `echo` lines never run.
        let (o, s) = run("declare -ra r=(1 2); r[0]=9; echo status=$?; echo \"${r[@]}\"");
        assert_eq!(o, "");
        assert_eq!(s, 1);
    }

    #[test]
    fn command_not_found_handle_invoked_with_args() {
        // A defined `command_not_found_handle` receives the command word as `$1`
        // and its arguments as `$2`…, and its exit status becomes `$?`.
        let src = "command_not_found_handle() { echo \"caught: $1 $2\"; return 42; }; \
                   no_such_cmd_xyz123 abc; echo status=$?";
        assert_eq!(run(src).0, "caught: no_such_cmd_xyz123 abc\nstatus=42\n");
    }

    #[test]
    fn command_not_found_handle_absent_reports_127() {
        // Without the handler, a missing command still reports 127.
        assert_eq!(run("no_such_cmd_xyz123; echo $?").0, "127\n");
    }

    #[test]
    fn command_not_found_handle_skipped_for_path_names() {
        // A name containing a slash bypasses the handler (bash: a slash path that
        // does not exist is a spawn error, not a "command not found" lookup).
        // Use an *absolute* non-existent path: a `./`-relative path would resolve
        // against the process cwd, which a parallel test's `cd` can retarget to a
        // directory holding a non-executable entry (yielding 126 instead of 127)
        // — a test-isolation flake, since `cd` mutates the process-global cwd.
        let src = "command_not_found_handle() { echo caught; }; \
                   /no_such_dir_osh_xyz123/no_such_cmd; echo $?";
        assert_eq!(run(src).0, "127\n");
    }

    #[test]
    fn command_not_found_honors_stderr_redirect() {
        // The "command not found" diagnostic must follow the command's own fd 2,
        // not the shell's real stderr (bash: a redirected `2>` on the missing
        // command captures/silences the message). Without a redirect the message
        // goes to the shell's real stderr, so the stdout capture holds only the
        // trailing `done`.
        let (o, _) = run("no_such_cmd_xyz123; echo done");
        assert_eq!(o, "done\n");
        // `2>&1` routes fd 2 into fd 1: the diagnostic now lands in the stdout
        // capture, matching bash.
        let (o2, s2) = run("no_such_cmd_xyz123 2>&1; echo done");
        assert_eq!(o2, "osh: no_such_cmd_xyz123: command not found\ndone\n");
        assert_eq!(s2, 0);
    }

    #[test]
    fn error_if_unset_message_and_subscript() {
        // Colon-less `?` tests only unset ("parameter not set"); colon `:?` tests
        // null-or-unset ("parameter null or not set"). A custom message overrides
        // the default text. bash renders an array subscript exactly as written in
        // source (unexpanded) in the diagnostic name. The `${var?}` error aborts
        // the shell, so we fold the diagnostic into the captured stdout with a
        // group `{ …; } 2>&1` (the group's stderr redirect covers the abort path).
        let (o, _) = run("{ echo \"${y?}\"; } 2>&1");
        assert_eq!(o, "osh: y: parameter not set\n");
        let (o2, _) = run("x=; { echo \"${x:?}\"; } 2>&1");
        assert_eq!(o2, "osh: x: parameter null or not set\n");
        let (o3, _) = run("{ echo \"${z:?custom}\"; } 2>&1");
        assert_eq!(o3, "osh: z: custom\n");
        // Associative-array element: the key appears in the name.
        let (o4, _) = run("declare -A m; { echo \"${m[k]?}\"; } 2>&1");
        assert_eq!(o4, "osh: m[k]: parameter not set\n");
        // Indexed-array element: the subscript is rendered as written, not the
        // evaluated index (`a[$i]`, not `a[5]`).
        let (o5, _) = run("i=5; declare -a a; { echo \"${a[$i]?}\"; } 2>&1");
        assert_eq!(o5, "osh: a[$i]: parameter not set\n");
    }

    #[test]
    fn getopts_error_uses_dollar_zero_prefix() {
        // bash prefixes the getopts diagnostic with `$0` (the shell/script name),
        // not a `getopts:` command label. In the test harness `$0` is "osh".
        // `2>&1` routes the message into the stdout capture so we can inspect it.
        let (o, _) = run("set -- -x; getopts ab o 2>&1; echo done");
        assert_eq!(o, "osh: illegal option -- x\ndone\n");
        // Missing option-argument diagnostic uses the same `$0` prefix.
        let (o2, _) = run("set -- -a; getopts 'a:' o 2>&1; echo done");
        assert_eq!(o2, "osh: option requires an argument -- a\ndone\n");
    }

    #[test]
    fn getopts_opterr_zero_suppresses_message() {
        // bash: OPTERR=0 mutes getopts' own diagnostics even when the optstring
        // does not start with `:`, but keeps the non-silent reported value
        // (`?`, OPTARG unset) — unlike the leading-colon silent mode.
        let (o, _) = run("OPTERR=0; set -- -q; getopts ab o 2>&1; echo \"[$o]\"");
        assert_eq!(o, "[?]\n");
        // A missing required argument is likewise silent under OPTERR=0, still
        // reporting `?` (not the silent-mode `:`).
        let (o2, _) = run("OPTERR=0; set -- -a; getopts 'a:' o 2>&1; echo \"[$o]\"");
        assert_eq!(o2, "[?]\n");
        // OPTERR back at its default (1) restores the diagnostic.
        let (o3, _) = run("OPTERR=1; set -- -q; getopts ab o 2>&1; echo done");
        assert_eq!(o3, "osh: illegal option -- q\ndone\n");
    }

    #[test]
    fn builtin_diagnostics_honor_stderr_redirect() {
        // A builtin's own diagnostic must follow the command's fd 2 (bash), so
        // `2>&1` folds it into the stdout capture and it is silenced when it
        // would otherwise reach the shell's real stderr.
        // `cd` failure:
        let (o, _) = run("cd /no_such_dir_xyz123 2>&1 | sed 's/^/E:/'; echo done");
        assert!(o.contains("E:osh: cd: /no_such_dir_xyz123:"), "got: {o:?}");
        assert!(o.ends_with("done\n"));
        // `test`/`[` operand error:
        let (o2, _) = run("[ 5 -eq x ] 2>&1; echo done");
        assert_eq!(o2, "osh: [: x: integer expression expected\ndone\n");
        // The `builtin` wrapper's own "not a shell builtin" diagnostic:
        let (o3, _) = run("builtin no_such_builtin_xyz 2>&1; echo done");
        assert_eq!(o3, "osh: builtin: no_such_builtin_xyz: not a shell builtin\ndone\n");
    }

    #[test]
    fn test_malformed_two_arg_reports_unary_operator_expected() {
        // `[ 1 -eq ]` collapses to a two-word test where the first word `1` is
        // neither `!` nor a unary operator, so bash reports "unary operator
        // expected" (naming the first word) and exits 2 — it must not silently
        // succeed. Verified against bash: `[: 1: unary operator expected`.
        let (o, rc) = run("[ 1 -eq ] 2>&1; echo rc=$?");
        assert_eq!(o, "osh: [: 1: unary operator expected\nrc=2\n");
        assert_eq!(rc, 0); // rc is from the final `echo`
        // A genuine unary operator with one argument still works.
        assert_eq!(run("[ -n x ]; echo $?").0, "0\n");
        assert_eq!(run("[ -z x ]; echo $?").0, "1\n");
    }

    #[test]
    fn read_exact_nchars() {
        // `-N N` reads exactly N characters, ignoring delimiters/spaces.
        assert_eq!(run("read -N 5 x <<< 'a b c d'; echo \"[$x]\"").0, "[a b c]\n");
        // A short read (fewer than N available) yields status 1.
        assert_eq!(run("read -N 20 x <<< 'abc'; echo $?").0, "1\n");
    }

    #[test]
    fn read_custom_delim() {
        // `-d :` reads up to the first ':' delimiter.
        assert_eq!(run("read -d : x <<< 'foo:bar'; echo \"$x\"").0, "foo\n");
        // Delimiter found ⇒ status 0.
        assert_eq!(run("read -d : x <<< 'foo:bar'; echo $?").0, "0\n");
    }

    #[test]
    fn type_word_classification() {
        assert_eq!(run("type -t echo").0, "builtin\n");
        assert_eq!(run("type -t if").0, "keyword\n");
        assert_eq!(run("f() { :; }; type -t f").0, "function\n");
        // Unknown name: -t prints nothing and reports status 1.
        assert_eq!(run("type -t osh_no_such_cmd_xyz; echo $?").0, "1\n");
    }

    #[test]
    fn type_default_descriptions() {
        assert_eq!(run("type echo").0, "echo is a shell builtin\n");
        assert_eq!(run("type while").0, "while is a shell keyword\n");
        // `type g` now prints the reconstructed function body after the header.
        assert_eq!(run("g() { :; }; type g").0, "g is a function\ng () \n{ \n    :\n}\n");
    }

    #[test]
    fn nocasematch_case_and_test() {
        // Default: case is case-sensitive.
        assert_eq!(
            run("case ABC in abc) echo y;; *) echo n;; esac").0,
            "n\n"
        );
        // With nocasematch, `case` folds case.
        assert_eq!(
            run("shopt -s nocasematch; case ABC in abc) echo y;; *) echo n;; esac").0,
            "y\n"
        );
        // `[[ == ]]` glob and literal both fold case under nocasematch.
        assert_eq!(run("shopt -s nocasematch; [[ Hello == h* ]] && echo y").0, "y\n");
        assert_eq!(run("shopt -s nocasematch; [[ Hello == hello ]] && echo y").0, "y\n");
        // Sanity: without it, the literal comparison is case-sensitive.
        assert_eq!(run("[[ Hello == hello ]] && echo y || echo n").0, "n\n");
    }

    #[test]
    fn dbracket_match_always_uses_extglob() {
        // bash matches the RHS of `==`/`!=` in `[[ ]]` "as if extglob were
        // enabled", regardless of the shopt setting — unlike `case`/glob, which
        // gate on it. Extended patterns must match even with extglob OFF.
        assert_eq!(
            run("shopt -u extglob; [[ foo == +(f|o) ]] && echo y || echo n").0,
            "y\n"
        );
        assert_eq!(
            run("shopt -u extglob; [[ foo == @(foo|bar) ]] && echo y || echo n").0,
            "y\n"
        );
        // `!(...)` negation and `*.@(...)` alternation, still with extglob off.
        // `run_script`, not `run`: with extglob off, `!(` is an *event
        // designator* to history expansion (`(` is not one of bash's
        // `history_no_expand_chars`), so an interactive bash rejects this very
        // line with `!: event not found` before the parser ever sees it. The
        // pattern behaviour under test is a script's.
        assert_eq!(
            run_script("shopt -u extglob; [[ hello == !(foo) ]] && echo y || echo n").0,
            "y\n"
        );
        assert_eq!(
            run("shopt -u extglob; [[ file.txt == *.@(txt|md) ]] && echo y || echo n").0,
            "y\n"
        );
        // The pattern really is a pattern, not a literal: `+(x)` doesn't match
        // the literal string "+(x)".
        assert_eq!(
            run("shopt -u extglob; [[ '+(x)' == +(x) ]] && echo y || echo n").0,
            "n\n"
        );
        // `!=` composes with the always-on extglob matching.
        assert_eq!(
            run("shopt -u extglob; [[ foo != +(f|o) ]] && echo y || echo n").0,
            "n\n"
        );
    }

    #[test]
    fn dbracket_numeric_bad_operand_prints_and_is_false() {
        // A malformed arithmetic operand to `[[ -eq ]]` (`10.0`) is an
        // arithmetic error: bash prints the diagnostic tagged `[[` and the
        // comparison is false (status 1), but the shell does not abort.
        let (out, _) = run("[[ 10 -eq 10.0 ]] && echo y || echo n; echo done");
        assert_eq!(out, "n\ndone\n");
        // The diagnostic body matches bash's arithmetic error, tagged `[[`.
        let (msg, _) = run("[[ 10 -eq 10.0 ]] 2>&1");
        assert!(
            msg.contains("[[: 10.0: syntax error: invalid arithmetic operator (error token is \".0\")"),
            "got: {msg:?}"
        );
        // Left operand is evaluated first and short-circuits: only its error is
        // reported when both are malformed.
        let (msg2, _) = run("[[ 10.0 -eq 20.0 ]] 2>&1");
        assert!(msg2.contains("10.0:"), "got: {msg2:?}");
        assert!(!msg2.contains("20.0:"), "should short-circuit: {msg2:?}");
        // A redirect silences it, like any other arithmetic diagnostic.
        assert_eq!(run("[[ 10 -eq 10.0 ]] 2>/dev/null; echo $?").0, "1\n");
        // A bare identifier is still a normal reference (0), not an error.
        assert_eq!(run("[[ 10 -eq abc ]] 2>&1; echo $?").0, "1\n");
    }

    #[test]
    fn nocasematch_regex() {
        // `=~` is case-sensitive by default, case-insensitive under nocasematch.
        assert_eq!(run("[[ Hello =~ ^hello$ ]] && echo y || echo n").0, "n\n");
        assert_eq!(
            run("shopt -s nocasematch; [[ Hello =~ ^hello$ ]] && echo y || echo n").0,
            "y\n"
        );
        // Character-class ranges fold too.
        assert_eq!(
            run("shopt -s nocasematch; [[ ABC =~ ^[a-z]+$ ]] && echo y || echo n").0,
            "y\n"
        );
    }

    #[test]
    fn extglob_in_test_and_case() {
        // Without extglob, `@(...)` is not special: the `@` and `(` are literal,
        // so `abc` does not match the pattern `@(a|b)c` textually.
        assert_eq!(run("[[ abc == @(a|b)c ]] && echo y || echo n").0, "n\n");
        // @(a|b) — exactly one alternative.
        assert_eq!(
            run("shopt -s extglob; [[ ac == @(a|b)c ]] && echo y || echo n").0,
            "y\n"
        );
        assert_eq!(
            run("shopt -s extglob; [[ xc == @(a|b)c ]] && echo y || echo n").0,
            "n\n"
        );
        // ?(...) zero or one.
        assert_eq!(
            run("shopt -s extglob; [[ color == colo?(u)r ]] && echo y || echo n").0,
            "y\n"
        );
        assert_eq!(
            run("shopt -s extglob; [[ colour == colo?(u)r ]] && echo y || echo n").0,
            "y\n"
        );
        assert_eq!(
            run("shopt -s extglob; [[ colouur == colo?(u)r ]] && echo y || echo n").0,
            "n\n"
        );
        // *(...) zero or more, +(...) one or more.
        assert_eq!(
            run("shopt -s extglob; [[ aaa == +(a) ]] && echo y || echo n").0,
            "y\n"
        );
        assert_eq!(
            run("shopt -s extglob; [[ '' == +(a) ]] && echo y || echo n").0,
            "n\n"
        );
        assert_eq!(
            run("shopt -s extglob; [[ '' == *(a) ]] && echo y || echo n").0,
            "y\n"
        );
        assert_eq!(
            run("shopt -s extglob; [[ ababab == *(ab) ]] && echo y || echo n").0,
            "y\n"
        );
        // !(...) negation. `run_script`, not `run`: history expansion runs on the
        // whole physical line *before* the `shopt` on it has run, so to an
        // interactive shell this line's `!(` is still an event designator and
        // fails with `!: event not found` (measured in bash). Keeping the `shopt`
        // on the same line is the point of the assertion — `[[ ]]` matching picks
        // the setting up immediately, unlike `case`, whose lexing does not — so
        // the script shell is the right one to ask.
        assert_eq!(
            run_script("shopt -s extglob; [[ foo == !(bar) ]] && echo y || echo n").0,
            "y\n"
        );
        assert_eq!(
            run_script("shopt -s extglob; [[ bar == !(bar) ]] && echo y || echo n").0,
            "n\n"
        );
        // In `case` — but only from the *next* unit, since `extglob` decides how
        // `@(` is lexed and bash has already read this line by the time the
        // `shopt` runs. Written on one line it is a syntax error, as in bash.
        assert_eq!(
            run("shopt -s extglob\ncase abc in @(a|x)bc) echo m;; *) echo no;; esac").0,
            "m\n"
        );
        assert_eq!(
            run("shopt -s extglob; case abc in @(a|x)bc) echo m;; *) echo no;; esac").0,
            ""
        );
    }

    #[test]
    fn extglob_in_param_and_glob() {
        // Parameter-trim with an extglob pattern.
        assert_eq!(
            run("shopt -s extglob; v=foobar; echo ${v##+(o|f)}").0,
            "bar\n"
        );
        // Replacement using an extglob alternation.
        assert_eq!(
            run("shopt -s extglob; v=cat; echo ${v/@(c|d)/b}").0,
            "bat\n"
        );
        // Nested extglob groups.
        assert_eq!(
            run("shopt -s extglob; [[ abab == *(@(a|b)) ]] && echo y || echo n").0,
            "y\n"
        );
    }

    #[test]
    fn here_doc_read_and_expand() {
        let (o, _) = run("name=world\nread line <<EOF\nhi $name\nEOF\necho $line");
        assert_eq!(o, "hi world\n");
    }

    #[test]
    fn here_doc_quoted_delim_no_expand() {
        let (o, _) = run("name=world\nread line <<'EOF'\nhi $name\nEOF\necho $line");
        assert_eq!(o, "hi $name\n");
    }

    #[test]
    fn param_trim_prefix_suffix() {
        assert_eq!(run("x=foo.tar.gz; echo ${x#*.}").0, "tar.gz\n");
        assert_eq!(run("x=foo.tar.gz; echo ${x##*.}").0, "gz\n");
        assert_eq!(run("x=foo.tar.gz; echo ${x%.*}").0, "foo.tar\n");
        assert_eq!(run("x=foo.tar.gz; echo ${x%%.*}").0, "foo\n");
    }

    #[test]
    fn param_case_modification() {
        // Doubled `^^`/`,,` convert every character.
        assert_eq!(run("x=hello; echo ${x^^}").0, "HELLO\n");
        assert_eq!(run("x=HELLO; echo ${x,,}").0, "hello\n");
        // Single `^`/`,` convert only the first character.
        assert_eq!(run("x=hello; echo ${x^}").0, "Hello\n");
        assert_eq!(run("x=HELLO; echo ${x,}").0, "hELLO\n");
        // A pattern selects which characters convert.
        assert_eq!(run("x=hello; echo ${x^^[aeiou]}").0, "hEllO\n");
        assert_eq!(run("x=HELLO; echo ${x,,[AEIOU]}").0, "HeLLo\n");
        // Single form only converts the first char if it matches the pattern.
        assert_eq!(run("x=hello; echo ${x^[b]}").0, "hello\n");
        assert_eq!(run("x=hello; echo ${x^[h]}").0, "Hello\n");
        // Mixed already-cased input is normalized.
        assert_eq!(run("x=\"Hello World\"; echo \"${x^^}\"").0, "HELLO WORLD\n");
        // Works on array elements.
        assert_eq!(run("a=(foo bar); echo ${a[1]^^}").0, "BAR\n");
        // Empty/unset value yields empty.
        assert_eq!(run("echo [${nope^^}]").0, "[]\n");
        // `~`/`~~` toggle case: `~` on the first char, `~~` on all matching.
        assert_eq!(run("x=hello; echo ${x~}").0, "Hello\n");
        assert_eq!(run("x=Hello; echo ${x~}").0, "hello\n");
        assert_eq!(run("x=aBcDeF; echo ${x~~}").0, "AbCdEf\n");
        assert_eq!(run("x=abcABC; echo ${x~~[a-c]}").0, "ABCABC\n");
        // Non-letters are left unchanged by a toggle.
        assert_eq!(run("x=123abc; echo ${x~~}").0, "123ABC\n");
        // Toggle over a whole array (per element).
        assert_eq!(run("a=(foo Bar BAZ); echo ${a[@]~~}").0, "FOO bAR baz\n");
    }

    #[test]
    fn param_indirect_expansion() {
        // `${!ref}` reads the variable named by `ref`.
        assert_eq!(run("x=hello; ref=x; echo ${!ref}").0, "hello\n");
        // Chained/renamed references.
        assert_eq!(run("a=b; b=c; c=done; echo ${!a} ${!b}").0, "c done\n");
        // A pointer that names an unset *target* yields empty (the target
        // `missing` is a valid name that is simply unset).
        assert_eq!(run("ref=missing; echo [${!ref}]").0, "[]\n");
        // An unset *pointer* itself is a fatal "invalid indirect expansion" in a
        // non-interactive shell (bash): the shell exits, so nothing is printed.
        let (o, s) = run("echo [${!nope}]; echo after");
        assert_eq!(o, "");
        assert_eq!(s, 1);
        // A pointer holding a malformed name is a fatal "invalid variable name".
        assert_eq!(run("ref='a-b'; echo [${!ref}]; echo after").0, "");
        // Referent naming an array element.
        assert_eq!(run("a=(x y z); ref='a[1]'; echo ${!ref}").0, "y\n");
        assert_eq!(
            run("declare -A m; m[k]=v; ref='m[k]'; echo ${!ref}").0,
            "v\n"
        );
        // Nameref special case: `${!ref}` yields the target NAME (not a second
        // indirection). `$ref` still yields the target value.
        assert_eq!(
            run("target=hi; declare -n ref=target; echo ${!ref} $ref").0,
            "target hi\n"
        );
        // Referent naming a whole array `a[@]`/`a[*]` expands like `${a[@]}`.
        assert_eq!(run("a=(1 2 3); ref='a[@]'; echo ${!ref}").0, "1 2 3\n");
        assert_eq!(run("a=(1 2 3); ref='a[*]'; echo ${!ref}").0, "1 2 3\n");
        // Quoted `"${!ref}"` preserves one field per element.
        assert_eq!(
            run(r#"a=("a b" c); ref='a[@]'; for x in "${!ref}"; do echo "<$x>"; done"#).0,
            "<a b>\n<c>\n"
        );
    }

    #[test]
    fn an_indirect_expansion_complains_under_the_name_it_was_written_as() {
        // `${!ref:?}` reads whatever `ref` points at, but the writer named the
        // reference — so that, and not the resolved target, is what the message
        // quotes. The subscript comes back as written, like everywhere else.
        assert_eq!(
            run("p=nosuch; { echo \"${!p:?msg}\"; } 2>&1").0,
            "osh: !p: msg\n"
        );
        assert_eq!(
            run("p=e; e=; { echo \"${!p:?}\"; } 2>&1").0,
            "osh: !p: parameter null or not set\n"
        );
        assert_eq!(
            run("ref='a[1]'; a=(x); { echo \"${!ref?msg}\"; } 2>&1").0,
            "osh: !ref: msg\n"
        );
        assert_eq!(
            run("a=(x); n=9; { echo \"${!a[$n]:?msg}\"; } 2>&1").0,
            "osh: !a[$n]: msg\n"
        );
        // Written directly, there is no second name to confuse it with.
        assert_eq!(run("x=; { echo \"${x:?msg}\"; } 2>&1").0, "osh: x: msg\n");
        assert_eq!(
            run("i=2; a=(); { echo \"${a[$i]:?}\"; } 2>&1").0,
            "osh: a[$i]: parameter null or not set\n"
        );
        // Only the complaint is renamed: an assignment still reaches the target.
        assert_eq!(run("p=t; echo \"[${!p:=v}]\"; echo \"t=[$t]\"").0, "[v]\nt=[v]\n");
    }

    #[test]
    fn the_pointer_of_an_indirect_expansion_may_be_an_element() {
        // `${!a[i]}` reads the *element's* value and uses that as the name, so
        // both ends of the indirection may carry a subscript, independently.
        assert_eq!(run("a=(xv yv); xv=HIT; echo ${!a[0]}").0, "HIT\n");
        assert_eq!(run("a=(xv yv); n=1; yv=H2; echo ${!a[n]}").0, "H2\n");
        assert_eq!(run("declare -A m=([k]=vv); vv=HIT; echo ${!m[k]}").0, "HIT\n");
        assert_eq!(run("a=(b); b=(p q r); echo ${!a[0]}").0, "p\n");
        assert_eq!(run("a=('b[1]'); b=(p q r); echo ${!a[0]}").0, "q\n");
        assert_eq!(run("a=('b[@]'); b=(p q r); echo ${!a[0]}").0, "p q r\n");
        assert_eq!(
            run(r#"a=("b[@]"); b=("p q" r); for w in "${!a[0]}"; do echo "<$w>"; done"#).0,
            "<p q>\n<r>\n"
        );
        // A nameref is followed like any other name here — the "expand to the
        // target's name" rule is only for a *bare* `${!ref}`.
        assert_eq!(run("a=(xv); xv=HIT; declare -n r=a; echo ${!r[0]} ${!r}").0, "HIT a\n");
        // The name pointed at is validated the same way: empty or malformed is
        // a fatal "invalid variable name", merely unset expands to nothing.
        assert_eq!(run("a=(nosuch); echo \"[${!a[0]}]\"; echo AFTER").0, "[]\nAFTER\n");
        assert_eq!(
            run("a=(1bad); { echo \"[${!a[0]}]\"; } 2>&1; echo AFTER").0,
            "osh: 1bad: invalid variable name\n"
        );
        // An element that is not there is not a pointer that is not there: the
        // reference simply points nowhere, and the command carries on…
        assert_eq!(run("a=(x); echo \"[${!a[9]}]\"; echo AFTER").0, "[]\nAFTER\n");
        assert_eq!(run("declare -A m; echo \"[${!m[k]}]\"; echo AFTER").0, "[]\nAFTER\n");
        // …whereas a reference whose *variable* does not exist had nothing to
        // point with at all, and is the fatal case — quoting the subscript as it
        // was written rather than as it evaluated.
        assert_eq!(
            run("unset a; n=3; { echo \"[${!a[$n]}]\"; } 2>&1; echo AFTER").0,
            "osh: a[$n]: invalid indirect expansion\n"
        );
        // Pointing nowhere is exactly what an unset parameter does, so the
        // modifiers answer accordingly — and name the reference itself, there
        // being no target name to give.
        assert_eq!(run("a=(x); echo \"[${!a[9]:-D}]\"").0, "[D]\n");
        assert_eq!(run("a=(x); echo \"[${!a[9]+S}]\"").0, "[]\n");
        assert_eq!(run("a=(x); echo \"[${!a[9]#z}]\"").0, "[]\n");
        assert_eq!(
            run("a=(x); { echo \"[${!a[9]:?msg}]\"; } 2>&1; echo AFTER").0,
            "osh: !a[9]: msg\n"
        );
        // A subscript that names nowhere is reported once, not once per attempt
        // to resolve it, and leaves the reference pointing nowhere.
        assert_eq!(
            run("a=(x y); { echo \"${!a[-5]}\"; } 2>&1; echo AFTER").0,
            "osh: a: bad array subscript\n\nAFTER\n"
        );
        // Only a *specific* subscript can point: `[@]`/`[*]` are the key listing,
        // and a second subscript is no reference at all.
        assert_eq!(run("a=(xv yv); echo ${!a[@]}").0, "0 1\n");
        assert_eq!(
            run("a=(xv); xv=(p q); { echo \"[${!a[0][1]}]\"; } 2>&1").0,
            "osh: [${!a[0][1]}]: bad substitution\n"
        );
        assert_eq!(
            run("set -- z; { echo \"[${!1[0]}]\"; } 2>&1").0,
            "osh: [${!1[0]}]: bad substitution\n"
        );
    }

    #[test]
    fn indirect_special_and_positional_referents() {
        // `${!#}` — indirect through `$#` (the count) selects the LAST
        // positional parameter (bash). With three args, that is the third.
        assert_eq!(run("set -- a b c; echo ${!#}").0, "c\n");
        assert_eq!(run("set -- x y z w; echo ${!#}").0, "w\n");
        // `${!N}` — indirect through a positional: the value of `$N` names the
        // variable to expand.
        assert_eq!(run("V=hi; set -- V; echo ${!1}").0, "hi\n");
        assert_eq!(run("b=BB; set -- a b c; echo ${!2}").0, "BB\n");
        // `${!?}` — indirect through `$?`. After a `true`, `$?` is 0, so this
        // resolves `${!0}` = `$0` (the shell name); just check it is non-empty
        // and does not error.
        assert_eq!(run("true; echo [${!?}]").1, 0);
        // `${!-}` — indirect through `$-` (option flags); those flag letters are
        // not a set variable, so it expands empty without error.
        assert_eq!(run("echo [${!-}]").0, "[]\n");
        // `$` and `!` are NOT valid indirect referents. Like bash, osh parses
        // the form and reports a *runtime* "bad substitution" (DISCARD-class,
        // status 1) at expansion time rather than a parse error.
        //
        // `run_script`, not `run`: history expansion inhibits only the `!` that
        // directly follows the `${`, so in `${!!}` the *second* `!` is still an
        // event designator and an interactive bash rewrites the line before
        // parsing it (measured: it substitutes the previous history entry).
        assert!(parse("echo ${!$}".as_bytes()).is_ok());
        assert!(parse("echo ${!!}".as_bytes()).is_ok());
        let (o1, s1) = run_script("echo ${!$} 2>/dev/null; echo after");
        assert_eq!((o1.as_str(), s1), ("", 1));
        assert_eq!(
            run_script("{ echo ${!!}; } 2>&1").0,
            "osh: line 1: ${!!}: bad substitution\n"
        );
    }

    #[test]
    fn indirect_at_star_positional() {
        // `${!@}` / `${!*}` (empty prefix) indirect through the positional list
        // `$@`/`$*`, NOT the "list all variable names" form (which requires a
        // non-empty prefix like `${!PATH@}`). With `set -- a b c`, `$@` joins to
        // "a b c", an invalid single variable name → fatal "invalid variable
        // name" (status 1), matching bash.
        let (o, s) = run("set -- a b c; echo \"${!@}\"; echo after");
        assert_eq!((o.as_str(), s), ("", 1));
        let (o2, s2) = run("set -- a b c; echo \"${!*}\"; echo after");
        assert_eq!((o2.as_str(), s2), ("", 1));
        // No positionals → nothing to indirect through → empty, status 0 (bash
        // distinguishes "nothing to indirect" from "indirect through a bad name").
        assert_eq!(run("foo=1; echo \"[${!@}]\"; echo done").0, "[]\ndone\n");
        assert_eq!(run("foo=1; echo \"[${!*}]\"; echo done").0, "[]\ndone\n");
        assert_eq!(run("foo=1; echo \"[${!@}]\"").1, 0);
        // A single positional whose value is a valid set variable name resolves
        // like `${!name}` — one level of indirection through that name.
        assert_eq!(run("V=hi; set -- V; echo \"${!@}\"").0, "hi\n");
        assert_eq!(run("V=hi; set -- V; echo \"${!*}\"").0, "hi\n");
        // A NON-empty prefix still lists variable names (unchanged behavior).
        assert_eq!(run("aa1=1; aa2=2; echo ${!aa@}").0, "aa1 aa2\n");
    }

    #[test]
    fn indirect_expansion_with_modifier() {
        // `${!ref<op>}` resolves the target NAME via `ref`, then applies the
        // modifier to that variable (bash). Covers the use/default, case,
        // trim, substring, replace and transform modifiers.
        assert_eq!(run("foo=bar; x=foo; echo ${!x:-def}").0, "bar\n");
        assert_eq!(run("x=foo; echo ${!x:-def}").0, "def\n"); // foo unset
        assert_eq!(run("foo=bar; x=foo; echo ${!x^^}").0, "BAR\n");
        assert_eq!(run("foo=Hello; x=foo; echo ${!x,,}").0, "hello\n");
        assert_eq!(run("foo=barbaz; x=foo; echo ${!x#bar}").0, "baz\n");
        assert_eq!(run("foo=barbaz; x=foo; echo ${!x##*a}").0, "z\n");
        assert_eq!(run("foo=abcdef; x=foo; echo ${!x:2:3}").0, "cde\n");
        assert_eq!(run("foo=banana; x=foo; echo ${!x//a/X}").0, "bXnXnX\n");
        assert_eq!(run("foo=bar; x=foo; echo ${!x:+SET}").0, "SET\n");
        // `:=` assigns to the *resolved target*, not the pointer.
        assert_eq!(
            run("x=foo; echo ${!x:=assigned}; echo post=$foo").0,
            "assigned\npost=assigned\n"
        );
        // Unset pointer with a modifier is still a fatal invalid indirection.
        let (o, s) = run("echo ${!nope:-x}; echo after");
        assert_eq!((o.as_str(), s), ("", 1));
        // Round-trips through the unparser (`${!ref<op>}`).
        assert_eq!(
            crate::bytes::trim(&crate::unparse::program_inline(
                &parse("echo ${!x:-def}".as_bytes()).unwrap()
            )),
            b"echo ${!x:-def}".as_slice()
        );
    }

    #[test]
    fn indirect_expansion_bad_pointer_is_fatal() {
        // An indirect expansion whose pointer is unset (or holds a malformed
        // name) is a fatal word-expansion error in a non-interactive shell
        // (bash): the shell exits with status 1 and the following command never
        // runs, in every expansion context.
        // Command word:
        let (o, s) = run("echo ${!nope}; echo after");
        assert_eq!((o.as_str(), s), ("", 1));
        // Bare assignment value:
        let (o, s) = run("x=${!nope}; echo after");
        assert_eq!((o.as_str(), s), ("", 1));
        // Temporary-prefix value (the command must NOT run):
        let (o, s) = run("x=${!nope} echo mid; echo after");
        assert_eq!((o.as_str(), s), ("", 1));
        // A valid-but-unset target is fine (empty, non-fatal):
        let (o, _) = run("p=missing; echo [${!p}]; echo after");
        assert_eq!(o, "[]\nafter\n");
        // Arithmetic *command* context (TD-OILS-INDIRECT-ARITH): a bad pointer
        // inside `(( … ))` is likewise fatal — the arith command aborts, `after`
        // never runs, status 1. Matches bash 5.2.
        let (o, s) = run("(( ${!nope} )); echo after");
        assert_eq!((o.as_str(), s), ("", 1));
    }

    #[test]
    fn nameref_to_array_element() {
        // A nameref may point at an array element: read and write route to it.
        assert_eq!(
            run("a=(x y z); declare -n ref=a[1]; echo $ref; ref=Y; echo \"${a[@]}\"").0,
            "y\nx Y z\n"
        );
        // Associative-array element target (string key).
        assert_eq!(
            run("declare -A m; m[k]=v; declare -n r=m[k]; echo $r; r=w; echo ${m[k]}").0,
            "v\nw\n"
        );
    }

    #[test]
    fn an_arithmetic_assignment_lands_where_an_ordinary_one_would() {
        // Arithmetic used to write straight into the scalar table, so it saw
        // none of what an ordinary `x=…` sees.
        // A nameref is followed — to a variable, and to an element.
        assert_eq!(run("x=1; declare -n r=x; ((r=5)); echo \"$x\"").0, "5\n");
        assert_eq!(
            run("declare -n r=q[0]; ((r=5)); declare -p q").0,
            "declare -a q=([0]=\"5\")\n"
        );
        // A subscript-less write to an existing array is element 0, and to an
        // existing associative array is key "0".
        assert_eq!(run("a=(1 2 3); ((a=9)); echo \"${a[@]}\"").0, "9 2 3\n");
        assert_eq!(
            run("declare -A m=([k]=1); ((m=9)); echo \"${m[0]}\"").0,
            "9\n"
        );
        // `set -a` gives the assigned name the export attribute.
        assert_eq!(run("set -a; ((x=5)); declare -p x").0, "declare -x x=\"5\"\n");
        // An element reference through a nameref reaches the referent's
        // elements, on both sides of the `=` and for both kinds of subscript.
        assert_eq!(run("a=(1 2 3); declare -n r=a; echo $((r[1]))").0, "2\n");
        assert_eq!(
            run("declare -n r=a; ((r[1]=5)); echo \"${a[1]}\"").0,
            "5\n"
        );
        assert_eq!(
            run("declare -A m=([k]=7); declare -n r=m; echo $((r[k])); ((r[j]=8)); echo \"${m[j]}\"").0,
            "7\n8\n"
        );
    }

    #[test]
    fn nameref_to_array_element_is_followed_by_every_writer() {
        // Where a nameref designates an element rather than a variable, it is
        // the *assignment* that has to notice — so every path that assigns a
        // scalar has to, not just the `name=value` command. `read` used to
        // create a variable literally called `q[0]` instead.
        assert_eq!(
            run("declare -n r=q[0]; read r <<< hi; declare -p q").0,
            "declare -a q=([0]=\"hi\")\n"
        );
        assert_eq!(
            run("declare -A m; declare -n r=m[k]; read r <<< hi; echo \"${m[k]}\"").0,
            "hi\n"
        );
        // The array is what carries the readonly attribute, so it is the array
        // the refusal names.
        let err = run("readonly -a q=(1); declare -n r=q[0]; { read r <<< hi; } 2>&1; declare -p q").0;
        assert_eq!(err, "osh: q: readonly variable\ndeclare -ar q=([0]=\"1\")\n");
    }

    #[test]
    fn param_prefix_names() {
        // `${!prefix*}` lists set variable names beginning with the prefix.
        assert_eq!(run("aa=1; ab=2; ba=3; echo ${!a*}").0, "aa ab\n");
        // `@` form behaves the same unquoted.
        assert_eq!(run("foo1=x; foo2=y; echo ${!foo@}").0, "foo1 foo2\n");
        // Names are sorted.
        assert_eq!(run("v_c=1; v_a=2; v_b=3; echo ${!v_*}").0, "v_a v_b v_c\n");
        // Quoted `@` form yields one field per name.
        assert_eq!(
            run("p1=x; p2=y; for n in \"${!p@}\"; do echo $n; done").0,
            "p1\np2\n"
        );
        // Arrays and assoc arrays are included by name.
        assert_eq!(
            run("arr=(1 2); declare -A amap; amap[k]=v; ascore=9; echo ${!a*}").0,
            "amap arr ascore\n"
        );
        // No match → empty.
        assert_eq!(run("echo [${!zzz*}]").0, "[]\n");
        // Dynamically-computed special variables (values produced on demand in
        // param_value, not stored in `vars`) are still listed, like bash.
        assert_eq!(run("echo ${!RAND*}").0, "RANDOM\n");
        assert_eq!(run("echo ${!SEC*}").0, "SECONDS\n");
        assert_eq!(run("echo ${!LINE*}").0, "LINENO\n");
        assert_eq!(run("echo ${!EPOCH*}").0, "EPOCHREALTIME EPOCHSECONDS\n");
        assert_eq!(run("echo ${!BASHP*}").0, "BASHPID\n");
        // BASH_SOURCE is a call-stack array bash keeps present at every level;
        // osh lists it (and BASH_SUBSHELL) to match, sorted.
        assert_eq!(run("echo ${!BASH_S*}").0, "BASH_SOURCE BASH_SUBSHELL\n");
        // A user variable and a dynamic special sharing a prefix are merged and
        // sorted together.
        assert_eq!(run("SECRET=1; echo ${!SEC*}").0, "SECONDS SECRET\n");
    }

    #[test]
    fn ansi_c_quoting() {
        // Common C escapes.
        assert_eq!(run("printf '%s' $'a\\tb'").0, "a\tb");
        assert_eq!(run("printf '%s' $'line1\\nline2'").0, "line1\nline2");
        // A literal backslash and a single quote inside.
        assert_eq!(run("printf '%s' $'a\\\\b'").0, "a\\b");
        assert_eq!(run("printf '%s' $'it\\'s'").0, "it's");
        // Hex and octal escapes.
        assert_eq!(run("printf '%s' $'\\x41\\x42'").0, "AB"); // 0x41=A 0x42=B
        assert_eq!(run("printf '%s' $'\\101\\102'").0, "AB"); // octal 101=A 102=B
        // Unicode escape.
        assert_eq!(run("printf '%s' $'\\u00e9'").0, "\u{e9}"); // é
        // No expansion inside $'…' (a `$var` stays literal).
        assert_eq!(run("x=hi; printf '%s' $'$x'").0, "$x");
        // Unknown escape keeps the backslash.
        assert_eq!(run("printf '%s' $'\\q'").0, "\\q");
        // Concatenation with adjacent text.
        assert_eq!(run("echo pre$'\\t'post").0, "pre\tpost\n");
        // A NUL byte terminates the ANSI-C string: bytes decoded after the
        // first NUL are dropped (a shell word cannot hold a NUL), matching
        // bash. `$'a\0b'` is just `a`. The scan still finds the closing quote
        // (escape-aware), so an escaped quote after the NUL does not close it.
        assert_eq!(run("printf '%s' $'a\\0b' | wc -c").0.trim(), "1");
        assert_eq!(run("printf '%s' $'\\x00tail' | wc -c").0.trim(), "0");
        assert_eq!(run("printf '%s' $'\\c@after' | wc -c").0.trim(), "0");
        assert_eq!(run("printf '%s' $'keep\\0\\'q\\'' | wc -c").0.trim(), "4");
    }

    #[test]
    fn getopts_basic() {
        // Flags, an option with an argument, and the OPTIND/remaining split.
        let src = "set -- -a -b val -c foo bar\n\
                   out=\n\
                   while getopts \"ab:c\" opt; do\n\
                     case $opt in\n\
                       a) out=\"$out a\" ;;\n\
                       b) out=\"$out b=$OPTARG\" ;;\n\
                       c) out=\"$out c\" ;;\n\
                     esac\n\
                   done\n\
                   shift $((OPTIND - 1))\n\
                   echo \"opts:$out rest:$*\"";
        assert_eq!(run(src).0, "opts: a b=val c rest:foo bar\n");
    }

    #[test]
    fn getopts_bundled_flags() {
        // Bundled short flags like -abc are parsed one per call.
        let src = "set -- -abc\n\
                   out=\n\
                   while getopts \"abc\" opt; do out=\"$out$opt\"; done\n\
                   echo \"$out\"";
        assert_eq!(run(src).0, "abc\n");
    }

    #[test]
    fn getopts_unknown_option() {
        // Unknown option sets opt to '?'; silent mode (leading ':') puts the
        // bad char in OPTARG instead of printing to stderr.
        let src = "set -- -x\n\
                   getopts \":ab\" opt\n\
                   echo \"$opt $OPTARG\"";
        assert_eq!(run(src).0, "? x\n");
    }

    #[test]
    fn getopts_binds_its_name_like_an_assignment() {
        // Running out of options is an answer too, and it is written into the
        // name: the variable reads `?`, not the previous call's option.
        assert_eq!(
            run("q=zz; set -- -a; getopts ab q; getopts ab q; echo \"rc=$? q=$q\"").0,
            "rc=1 q=?\n"
        );
        // …including when the scan stops at a non-option word or a `--`.
        assert_eq!(
            run("q=zz; set -- plain; getopts ab q; echo \"rc=$? q=$q\"").0,
            "rc=1 q=?\n"
        );
        // The write is an ordinary assignment, so it follows a nameref and
        // obeys the name's case-folding attribute.
        assert_eq!(
            run("t=orig; declare -n nr=t; set -- -a; getopts ab nr; echo \"t=$t\"").0,
            "t=a\n"
        );
        assert_eq!(
            run("declare -u U; set -- -a; getopts ab U; echo \"U=$U\"").0,
            "U=A\n"
        );
        // And it can be refused. A refusal costs an option result its status —
        // 2 rather than 0 — but leaves the out-of-options 1 alone, since there
        // the 1 is the answer rather than the write.
        assert_eq!(
            run("readonly r=1; set -- -a; getopts ab r 2>&1; echo \"rc=$? r=$r\"").0,
            "osh: r: readonly variable\nrc=2 r=1\n"
        );
        assert_eq!(
            run("readonly r=1; set --; getopts ab r 2>&1; echo \"rc=$? r=$r\"").0,
            "osh: r: readonly variable\nrc=1 r=1\n"
        );
    }

    #[test]
    fn getopts_missing_argument_silent() {
        // Missing required argument in silent mode: opt=':' and OPTARG=optchar.
        let src = "set -- -b\n\
                   getopts \":ab:\" opt\n\
                   echo \"$opt $OPTARG\"";
        assert_eq!(run(src).0, ": b\n");
    }

    #[test]
    fn mapfile_reads_lines() {
        // -t strips the trailing newline from each element.
        let src = "mapfile -t arr <<< $'a\\nb\\nc'\n\
                   echo \"${#arr[@]}\"\n\
                   echo \"${arr[0]}-${arr[1]}-${arr[2]}\"";
        assert_eq!(run(src).0, "3\na-b-c\n");
    }

    #[test]
    fn mapfile_refuses_a_name_it_cannot_fill() {
        // The three ways a target can be unusable, each worded its own way: the
        // readonly one names the variable alone, the other two are the
        // builtin's own objections.
        assert_eq!(
            run("readonly x=1; mapfile x <<< hi 2>&1; echo \"rc=$? x=$x\"").0,
            "osh: x: readonly variable\nrc=1 x=1\n"
        );
        assert_eq!(
            run("mapfile 'a b' <<< hi 2>&1; echo rc=$?").0,
            "osh: mapfile: `a b': not a valid identifier\nrc=1\n"
        );
        assert_eq!(
            run("declare -A m; mapfile m <<< hi 2>&1; echo rc=$?; declare -p m").0,
            "osh: mapfile: m: not an indexed array\nrc=1\ndeclare -A m\n"
        );
        // A refusal reads nothing, so input shared with the refused call is
        // still there for the next reader.
        assert_eq!(
            run("readonly x=1; { mapfile x; read y; } <<< $'p\\nq' 2>/dev/null; echo \"y=$y\"").0,
            "y=p\n"
        );
        // A nameref is followed first, so what is judged is the target.
        assert_eq!(
            run("declare -n r=zz; mapfile -t r <<< hi; declare -p zz").0,
            "declare -a zz=([0]=\"hi\")\n"
        );
        // Only the first operand is the array; the rest are ignored outright,
        // so a bad name after a good one costs nothing.
        assert_eq!(
            run("mapfile -t a 'b c' <<< hi 2>&1; echo rc=$?; declare -p a").0,
            "rc=0\ndeclare -a a=([0]=\"hi\")\n"
        );
    }

    #[test]
    fn mapfile_keeps_delimiter_by_default() {
        // Without -t, each element retains its trailing newline.
        let src = "mapfile arr <<< $'x\\ny'\n\
                   printf '[%s]' \"${arr[@]}\"";
        assert_eq!(run(src).0, "[x\n][y\n]");
    }

    #[test]
    fn mapfile_callback_quantum() {
        // -C callback fires every -c quantum lines. bash appends the target
        // index and the line as command *arguments* (not $1/$2 of the caller).
        // Here a helper function receives them as $1/$2 and observes that the
        // element is not yet assigned (${arr[$1]} empty). With -t the line arg is
        // the stripped value. Quantum 1 fires per line.
        let src = "cb() { printf 'cb %s [%s] cur=[%s]\\n' \"$1\" \"$2\" \"${arr[$1]}\"; }\n\
                   mapfile -t -C cb -c 1 arr <<< $'p\\nq'\n\
                   printf 'final=%s\\n' \"${arr[*]}\"";
        assert_eq!(
            run(src).0,
            "cb 0 [p] cur=[]\ncb 1 [q] cur=[]\nfinal=p q\n"
        );
    }

    #[test]
    fn mapfile_callback_line_keeps_delim_without_t() {
        // Without -t the line argument to the callback keeps its delimiter.
        let src = "cb() { printf '[%s|%s]' \"$1\" \"$2\"; }\n\
                   mapfile -C cb -c 1 arr <<< $'x\\ny'";
        assert_eq!(run(src).0, "[0|x\n][1|y\n]");
    }

    #[test]
    fn mapfile_callback_quantum_two() {
        // Quantum 2 fires at the 2nd and 4th assigned lines, with the index of
        // the element about to be stored (1, then 3). `echo CB:` receives the
        // index and line as appended arguments.
        let src = "mapfile -t -C 'echo CB:' -c 2 arr <<< $'1\\n2\\n3\\n4\\n5'\n\
                   echo done";
        assert_eq!(run(src).0, "CB: 1 2\nCB: 3 4\ndone\n");
    }

    #[test]
    fn mapfile_no_callback_without_dash_c_uppercase() {
        // A large default quantum (5000) means no callback fires for a few lines
        // when -C is given without -c.
        let src = "mapfile -t -C 'echo NOPE' arr <<< $'a\\nb\\nc'\n\
                   echo \"${#arr[@]}\"";
        assert_eq!(run(src).0, "3\n");
    }

    #[test]
    fn mapfile_dash_n_still_counts() {
        // -n (count) is now distinct from -c (quantum): -n limits how many lines
        // are read.
        let src = "mapfile -t -n 2 arr <<< $'a\\nb\\nc\\nd'\n\
                   echo \"${#arr[@]}\"; echo \"${arr[*]}\"";
        assert_eq!(run(src).0, "2\na b\n");
    }

    #[test]
    fn mapfile_reads_its_options_the_way_bash_does() {
        let feed = "<<< $'l1\\nl2\\nl3'";
        // A letter that takes an argument swallows the rest of its cluster, and
        // a letter that takes none can share the cluster with it.
        assert_eq!(run(&format!("mapfile -n2 a {feed}; echo ${{#a[@]}}")).0, "2\n");
        assert_eq!(run(&format!("mapfile -tn 2 a {feed}; echo [${{a[*]}}]")).0, "[l1 l2]\n");
        assert_eq!(run(&format!("mapfile -td, a {feed}; echo ${{#a[@]}}")).0, "1\n");
        // `--` ends the options, and what follows is the name — even one that
        // looks like an option, which is then rejected as the name it is.
        assert_eq!(run(&format!("mapfile -t -- a {feed}; echo [${{a[*]}}]")).0, "[l1 l2 l3]\n");
        let (o, s) = run(&format!("mapfile -- -t {feed} 2>&1"));
        assert_eq!((o.as_str(), s), ("osh: mapfile: `-t': not a valid identifier\n", 1));
        // The scan stops at the first operand, so an option written after the
        // name is just a word bash never looks at.
        assert_eq!(run(&format!("mapfile a -t {feed}; echo \"[${{a[0]}}]\"")).0, "[l1\n]\n");
        // An invalid letter is named on its own, not with the cluster it sat in.
        let (o, s) = run(&format!("mapfile -ta {feed} 2>&1"));
        assert!(o.starts_with("osh: mapfile: -a: invalid option\n"), "got {o:?}");
        assert_eq!(s, 2);
        // A missing option argument is a usage error, with the synopsis.
        let (o, s) = run("mapfile -n 2>&1");
        assert!(o.starts_with("osh: mapfile: -n: option requires an argument\n"), "got {o:?}");
        assert!(o.contains("mapfile: usage: mapfile [-d delim]"), "got {o:?}");
        assert_eq!(s, 2);
    }

    #[test]
    fn mapfile_checks_each_count_as_it_reads_it() {
        let feed = "<<< $'l1\\nl2\\nl3'";
        // The three counts are read the way every other number bash reads is:
        // surrounding blanks are skipped, a sign is allowed, and anything left
        // over means it was not a number.
        assert_eq!(run(&format!("mapfile -n ' 2 ' a {feed}; echo ${{#a[@]}}")).0, "2\n");
        assert_eq!(run(&format!("mapfile -n +2 a {feed}; echo ${{#a[@]}}")).0, "2\n");
        for (opt, val, what) in [
            ("-n", "x", "line count"),
            ("-n", "2x", "line count"),
            ("-n", "0x2", "line count"),
            ("-n", "-1", "line count"),
            ("-s", "-1", "line count"),
            ("-O", "y", "array origin"),
            ("-O", "-1", "array origin"),
            ("-c", "x", "callback quantum"),
            // A quantum of zero would call the callback endlessly often, so it
            // is refused rather than taken to mean "never".
            ("-c", "0", "callback quantum"),
        ] {
            let (o, s) = run(&format!("mapfile {opt} {val} a {feed} 2>&1"));
            assert_eq!((o.as_str(), s), (&*format!("osh: mapfile: {val}: invalid {what}\n"), 1));
        }
        // The check happens as the option is read, so the first bad one decides
        // — and it beats the generation a good one would have driven.
        let (o, _) =
            run(&format!("mapfile -n 2 -O y a {feed} 2>&1; echo rc=$?; declare -p a 2>&1"));
        assert!(o.starts_with("osh: mapfile: y: invalid array origin\nrc=1\n"), "got {o:?}");
        assert!(o.contains("declare: a: not found"), "the array must be untouched: {o:?}");
    }

    #[test]
    fn mapfile_leaves_the_input_a_bound_did_not_need() {
        // `-n` says how many records are wanted, so the rest of the input is
        // still there for whoever reads next on the same descriptor.
        let src = "{ mapfile -n 2 a; read r; } <<< $'l1\\nl2\\nl3\\nl4'\n\
                   echo \"${#a[@]} r=$r\"";
        assert_eq!(run(src).0, "2 r=l3\n");
        // The skipped records have to be read to be skipped, so they count
        // towards what is consumed.
        let src = "{ mapfile -s 1 -n 2 a; read r; } <<< $'l1\\nl2\\nl3\\nl4'\n\
                   echo \"[${a[0]}${a[1]}] r=$r\"";
        assert_eq!(run(src).0, "[l2\nl3\n] r=l4\n");
        // Two bounded reads in a row each pick up where the last one stopped.
        let src = "{ mapfile -t -n 2 a; mapfile -t -n 2 b; } <<< $'l1\\nl2\\nl3\\nl4'\n\
                   echo \"[${a[*]}][${b[*]}]\"";
        assert_eq!(run(src).0, "[l1 l2][l3 l4]\n");
        // Without a bound the whole input is wanted, and nothing is left.
        let src = "{ mapfile a; read r; } <<< $'l1\\nl2'\necho \"${#a[@]} r=[$r]\"";
        assert_eq!(run(src).0, "2 r=[]\n");
        // The bound counts records, which `-d` redefines.
        let src = "{ mapfile -d , -n 1 a; read r; } <<< 'x,y,z'\necho \"[${a[0]}] r=[$r]\"";
        assert_eq!(run(src).0, "[x,] r=[y,z]\n");
    }

    #[test]
    fn mapfile_reads_from_numbered_fd() {
        // `-u N` reads the array from a descriptor opened by `exec N< file`,
        // mirroring `read -u`. Uses a real temp file (the in-memory `run`
        // harness backs numbered fds with real handles via `exec N<`).
        let base = std::env::temp_dir();
        let f = base.join(format!("osh_mapfile_ufd_{}", std::process::id()));
        std::fs::write(&f, b"one\ntwo\nthree\n").unwrap();
        let fp = f.to_string_lossy().replace('\\', "/");
        let (o, s) = run(&format!(
            "exec 4< \"{fp}\"; mapfile -t -u 4 arr; echo \"${{#arr[@]}}:${{arr[0]}}-${{arr[2]}}\""
        ));
        assert_eq!(s, 0, "got {o:?}");
        assert_eq!(o, "3:one-three\n");
        let _ = std::fs::remove_file(&f);

        // A closed/out-of-range fd and a non-numeric spec reproduce bash's two
        // distinct diagnostics, both status 1.
        let (o, s) = run("mapfile -u 9 arr 2>&1");
        assert!(o.contains("mapfile: 9: invalid file descriptor: Bad file descriptor"), "got {o:?}");
        assert_eq!(s, 1);
        let (o, s) = run("readarray -u abc arr 2>&1");
        assert!(o.contains("readarray: abc: invalid file descriptor specification"), "got {o:?}");
        assert_eq!(s, 1);
    }

    #[test]
    fn printf_recycles_format() {
        // The format string repeats until all arguments are consumed.
        assert_eq!(run("printf '%s\\n' a b c").0, "a\nb\nc\n");
        assert_eq!(run("printf '[%s:%d]' x 1 y 2").0, "[x:1][y:2]");
        // No arg-consuming conversion → format emitted exactly once.
        assert_eq!(run("printf 'hi\\n'").0, "hi\n");
    }

    #[test]
    fn printf_assign_with_v() {
        assert_eq!(run("printf -v out '%s-%s' a b; echo \"$out\"").0, "a-b\n");
        // -v suppresses stdout output.
        assert_eq!(run("printf -v x 'hi'").0, "");
        // -v can target an array element.
        assert_eq!(
            run("printf -v 'arr[2]' '%d' 99; echo \"${arr[2]}\"").0,
            "99\n"
        );
        // -v into an associative-array key.
        assert_eq!(
            run("declare -A m; printf -v 'm[k]' '%s!' hi; echo \"${m[k]}\"").0,
            "hi!\n"
        );
        // A readonly target is rejected and left intact.
        assert_eq!(
            run("readonly r=orig; printf -v r '%s' new 2>/dev/null; echo \"$r\"").0,
            "orig\n"
        );
    }

    #[test]
    fn printf_integer_conversions() {
        assert_eq!(run("printf '%x' 255").0, "ff");
        assert_eq!(run("printf '%X' 255").0, "FF");
        assert_eq!(run("printf '%o' 8").0, "10");
        assert_eq!(run("printf '%i' 42").0, "42");
        assert_eq!(run("printf '%u' 5").0, "5");
        // Hex input to %d.
        assert_eq!(run("printf '%d' 0xff").0, "255");
    }

    #[test]
    fn printf_invalid_number_diagnostics() {
        // A non-numeric arg warns to stderr and makes printf fail, but the
        // best-effort value (0, or the leading numeric prefix) is still emitted.
        assert_eq!(run("printf '%d\\n' abc"), ("0\n".to_string(), 1));
        // Leading digits are used as the value (strtoimax semantics).
        assert_eq!(run("printf '%d\\n' 12x"), ("12\n".to_string(), 1));
        // A leading `0` selects octal; `010` is 8, `08` is invalid → 0.
        assert_eq!(run("printf '%d\\n' 010"), ("8\n".to_string(), 0));
        assert_eq!(run("printf '%d\\n' 08"), ("0\n".to_string(), 1));
        // Bad hex digits are invalid.
        assert_eq!(run("printf '%d\\n' 0xzz"), ("0\n".to_string(), 1));
        // Valid numbers do not warn.
        assert_eq!(run("printf '%d\\n' 9"), ("9\n".to_string(), 0));
        assert_eq!(run("printf '%d\\n' ''"), ("0\n".to_string(), 0));
        // Floats: leading numeric prefix, invalid trailing junk.
        assert_eq!(run("printf '%.1f\\n' 3.5x"), ("3.5\n".to_string(), 1));
        assert_eq!(run("printf '%.1f\\n' xyz"), ("0.0\n".to_string(), 1));
    }

    #[test]
    fn printf_diagnostics_interleave_with_stdout() {
        // `printf_output_segments` models bash's ordering: printf's stdout is
        // line-buffered (flushed at each newline) and its stderr unbuffered, so
        // a diagnostic at byte offset `off` lands after the complete lines
        // produced so far but before any pending partial line. Flatten the
        // segments back into the merged byte stream the terminal would see.
        // (The `run` harness captures stdout/stderr into *separate* buffers, so
        // it cannot exercise this ordering — hence a direct unit test.)
        fn merged(text: &str, diags: &[(usize, &str)]) -> String {
            let owned: Vec<(usize, Str)> =
                diags.iter().map(|(o, m)| (*o, (*m).as_bytes().to_vec())).collect();
            let mut s = Str::new();
            for seg in printf_output_segments(text.as_bytes(), &owned) {
                match seg {
                    PrintfSeg::Out(b) | PrintfSeg::Err(b) => s.extend_from_slice(b),
                }
            }
            String::from_utf8(s).unwrap()
        }
        // `printf '%d\n' 1 bad 2` → text "1\n0\n2\n", error tagged at offset 2
        // (start of the 2nd field, just after the flushed "1\n").
        assert_eq!(
            merged("1\n0\n2\n", &[(2, "E:bad\n")]),
            "1\nE:bad\n0\n2\n"
        );
        // `printf '%d %d %d\n' 1 bad 3` → text "1 0 3\n"; error at offset 2 has
        // no preceding newline, so it precedes the whole (buffered) line.
        assert_eq!(merged("1 0 3\n", &[(2, "E:bad\n")]), "E:bad\n1 0 3\n");
        // `printf 'x%dy' foo` → text "x0y" (no newline): error precedes it all.
        assert_eq!(merged("x0y", &[(1, "E:foo\n")]), "E:foo\nx0y");
        // Two bad fields on one line: both errors, then the buffered line.
        assert_eq!(
            merged("0 0\n", &[(0, "E:bad1\n"), (2, "E:bad2\n")]),
            "E:bad1\nE:bad2\n0 0\n"
        );
        // Fatal at end of a partial line ("X5Y", no newline): message first.
        assert_eq!(merged("X5Y", &[(3, "F:y\n")]), "F:y\nX5Y");
        // A completed line before the fatal directive is flushed first.
        assert_eq!(merged("X5\n", &[(3, "F:y\n")]), "X5\nF:y\n");
    }

    #[test]
    fn printf_invalid_and_missing_format_char() {
        // An unrecognized conversion character aborts printf with status 1,
        // keeping only the text produced before the bad directive (bash writes
        // `` `y': invalid format character `` to stderr, checked via probe).
        assert_eq!(run("printf '%y\\n' hi"), (String::new(), 1));
        assert_eq!(run("printf 'AB%yCD\\n' hi"), ("AB".to_string(), 1));
        assert_eq!(run("printf 'X%dY%yZ\\n' 5 9"), ("X5Y".to_string(), 1));
        // A `%` (optionally with flags/width/precision) at the end of the format
        // is a "missing format character" abort.
        assert_eq!(run("printf 'a%'"), ("a".to_string(), 1));
        assert_eq!(run("printf '%'"), (String::new(), 1));
        assert_eq!(run("printf '%5'"), (String::new(), 1));
        assert_eq!(run("printf '%.3'"), (String::new(), 1));
        // C length modifiers (`l ll h hh L j t z`) are accepted and ignored, so
        // the following conversion is what's rendered.
        assert_eq!(run("printf '%ld\\n' 42"), ("42\n".to_string(), 0));
        assert_eq!(run("printf '%lld\\n' 42"), ("42\n".to_string(), 0));
        assert_eq!(run("printf '%hhd\\n' 42"), ("42\n".to_string(), 0));
        assert_eq!(run("printf '%zx\\n' 42"), ("2a\n".to_string(), 0));
        assert_eq!(run("printf '%Lf\\n' 42"), ("42.000000\n".to_string(), 0));
        // `%q` is a conversion, not a modifier: `%qd` quotes then prints `d`.
        assert_eq!(run("printf '%qd\\n' 42"), ("42d\n".to_string(), 0));
        // A modifier with no following conversion is still a missing/invalid char.
        assert_eq!(run("printf '%l\\n' 42").1, 1);
    }

    #[test]
    fn printf_integer_overflow_saturates() {
        // bash parses signed conversions (`%d`/`%i`) with strtoimax — on overflow
        // it saturates to INTMAX_MIN/MAX and emits a *warning* (not an error), so
        // the exit status stays 0. Verified byte-for-byte against bash 5.x.
        assert_eq!(
            run("printf '%d' 99999999999999999999"),
            ("9223372036854775807".to_string(), 0)
        );
        assert_eq!(
            run("printf '%d' -99999999999999999999"),
            ("-9223372036854775808".to_string(), 0)
        );
        // i64::MAX is exact (no overflow); MAX+1 saturates.
        assert_eq!(
            run("printf '%d' 9223372036854775807"),
            ("9223372036854775807".to_string(), 0)
        );
        assert_eq!(
            run("printf '%d' 9223372036854775808"),
            ("9223372036854775807".to_string(), 0)
        );
        // i64::MIN is exact.
        assert_eq!(
            run("printf '%d' -9223372036854775808"),
            ("-9223372036854775808".to_string(), 0)
        );
        // Unsigned conversions (`%u`/`%x`/`%X`/`%o`) use strtoumax: overflow
        // saturates to UINTMAX_MAX, and a negative in range wraps two's-complement.
        assert_eq!(
            run("printf '%u' 99999999999999999999"),
            ("18446744073709551615".to_string(), 0)
        );
        assert_eq!(
            run("printf '%u' -99999999999999999999"),
            ("18446744073709551615".to_string(), 0)
        );
        assert_eq!(run("printf '%x' 99999999999999999999"), ("ffffffffffffffff".to_string(), 0));
        assert_eq!(run("printf '%o' -1").0, "1777777777777777777777");
        // u64::MAX is exact; MAX+1 saturates.
        assert_eq!(
            run("printf '%u' 18446744073709551615"),
            ("18446744073709551615".to_string(), 0)
        );
        assert_eq!(
            run("printf '%u' 18446744073709551616"),
            ("18446744073709551615".to_string(), 0)
        );
        // In-range negatives still wrap (unchanged behaviour).
        assert_eq!(run("printf '%u' -1"), ("18446744073709551615".to_string(), 0));
        assert_eq!(run("printf '%x' -1"), ("ffffffffffffffff".to_string(), 0));
    }

    #[test]
    fn printf_width_and_precision() {
        assert_eq!(run("printf '%5d' 42").0, "   42");
        assert_eq!(run("printf '%-5d|' 42").0, "42   |");
        assert_eq!(run("printf '%05d' 42").0, "00042");
        assert_eq!(run("printf '%.2s' abcd").0, "ab");
    }

    #[test]
    fn printf_integer_precision() {
        // For integer conversions, precision is the *minimum digit count*: the
        // body is zero-padded on the left (independent of field width). Verified
        // byte-for-byte against bash 5.x.
        assert_eq!(run("printf '[%.3d]' 7").0, "[007]");
        assert_eq!(run("printf '[%.5d]' 42").0, "[00042]");
        assert_eq!(run("printf '[%.3o]' 8").0, "[010]");
        assert_eq!(run("printf '[%.4x]' 255").0, "[00ff]");
        assert_eq!(run("printf '[%.4X]' 255").0, "[00FF]");
        assert_eq!(run("printf '[%.3u]' 7").0, "[007]");
        // A precision of 0 applied to the value 0 yields no digits at all.
        assert_eq!(run("printf '[%.0d]' 0").0, "[]");
        assert_eq!(run("printf '[%.0d]' 5").0, "[5]");
        assert_eq!(run("printf '[%.0x]' 0").0, "[]");
        // Precision disables the `0` flag → width is space-padded.
        assert_eq!(run("printf '[%08.3d]' 42").0, "[     042]");
        assert_eq!(run("printf '[%8.3d]' 42").0, "[     042]");
        assert_eq!(run("printf '[%-8.3d]' 42").0, "[042     ]");
        // Sign/space flags sit outside the zero-padded body.
        assert_eq!(run("printf '[%+.3d]' 42").0, "[+042]");
        assert_eq!(run("printf '[% .3d]' 42").0, "[ 042]");
        assert_eq!(run("printf '[%.3d]' -42").0, "[-042]");
        assert_eq!(run("printf '[%-8.3d]' -42").0, "[-042    ]");
        // `#` on octal forces a leading `0` after precision is applied.
        assert_eq!(run("printf '[%#.0o]' 0").0, "[0]");
        assert_eq!(run("printf '[%#.1o]' 8").0, "[010]");
        assert_eq!(run("printf '[%#.4x]' 255").0, "[0x00ff]");
        // Dynamic precision via `.*`.
        assert_eq!(run("printf '[%.*d]' 4 7").0, "[0007]");
    }

    #[test]
    fn printf_dynamic_width_and_precision() {
        // `*` takes the field width from the next argument.
        assert_eq!(run("printf '%*d' 5 42").0, "   42");
        // `.*` takes the precision from the next argument.
        assert_eq!(run("printf '%.*f' 2 3.14159").0, "3.14");
        // Both dynamic in one conversion.
        assert_eq!(run("printf '%*.*f' 8 2 3.14159").0, "    3.14");
        // A negative dynamic width left-justifies with the absolute magnitude.
        assert_eq!(run("printf '%*d|' -5 42").0, "42   |");
        // `.*` on a string precision truncates.
        assert_eq!(run("printf '%.*s' 2 abcd").0, "ab");
    }

    #[test]
    fn printf_q_b_and_c_conversions() {
        // bash's %q backslash-escapes shell-special chars (unlike @Q, which
        // single-quotes).
        assert_eq!(run("printf '%q' 'a b'").0, "a\\ b");
        assert_eq!(run("printf '%q' \"it's\"").0, "it\\'s");
        assert_eq!(run("printf '%q' ''").0, "''");
        assert_eq!(run("printf '%q' plain").0, "plain");
        assert_eq!(run("printf '%q' 'a$b`c'").0, "a\\$b\\`c");
        // @Q still uses single-quote style.
        assert_eq!(run("v='a b'; echo \"${v@Q}\"").0, "'a b'\n");
        assert_eq!(run("printf '%b' 'a\\tb'").0, "a\tb");
        assert_eq!(run("printf '%c' xyz").0, "x");
    }

    #[test]
    fn printf_format_string_escapes() {
        // The FORMAT string decodes octal, hex, and unicode escapes (not just
        // the named ones). Octal uses `\nnn` (a leading 0 is the first digit).
        assert_eq!(run("printf '\\x41'").0, "A");
        assert_eq!(run("printf '\\101'").0, "A");
        assert_eq!(run("printf '\\u0041'").0, "A");
        assert_eq!(run("printf '\\U00000041'").0, "A");
        assert_eq!(run("printf '\\e'").0, "\u{1b}");
        assert_eq!(run("printf '\\a'").0, "\u{07}");
        // `\0101` → `\010` (octal 010 = 0x08) then a literal `1`.
        assert_eq!(run("printf '\\0101'").0, "\u{08}1");
        assert_eq!(run("printf '\\07'").0, "\u{07}");
        assert_eq!(run("printf '\\0'").0, "\0");
        // Escapes and conversions interleave.
        assert_eq!(run("printf '%d\\n\\101' 5").0, "5\nA");
    }

    #[test]
    fn printf_byte_escapes_emit_one_byte_not_a_code_point() {
        // TD-OILS-BYTE-STRINGS: `\xHH` and `\nnn` name a *byte*. Before the
        // refactor the shell turned 0xa9 into U+00A9 and wrote its two-byte
        // UTF-8 encoding, so every high byte was silently doubled — a
        // `printf '\xff' > f` produced a file bash would not have produced.
        assert_eq!(run_raw("printf '\\xa9'").0, b"\xa9");
        assert_eq!(run_raw("printf '\\xff'").0, b"\xff");
        // Octal likewise: `\377` is one byte, and `\0377` (echo-style prefix)
        // is the same byte, not 0x1f followed by `7`.
        assert_eq!(run_raw("printf '\\377'").0, b"\xff");
        assert_eq!(run_raw("printf '%b' '\\0377'").0, b"\xff");
        // `\u`/`\U` name a *code point*, so they still UTF-8 encode.
        assert_eq!(run_raw("printf '\\u00e9'").0, b"\xc3\xa9");
        assert_eq!(run_raw("printf '%b' '\\u00e9'").0, b"\xc3\xa9");
        // `echo -e` shares the decoder and the same distinction.
        assert_eq!(run_raw("echo -e '\\xff'").0, b"\xff\n");
        assert_eq!(run_raw("echo -ne '\\xc3'").0, b"\xc3");
    }

    #[test]
    fn printf_field_ops_do_not_split_or_panic_on_stray_bytes() {
        // `%c` writes the first *character*, so a multibyte character is
        // written whole rather than cut to its lead byte.
        assert_eq!(run_raw("printf '%c' \"$(printf '\\u00e9x')\"").0, b"\xc3\xa9");
        // (The companion case — a lone 0xff as the *argument*, which `%c` must
        // treat as one character — cannot be staged from shell source yet:
        // command substitution still captures into a `String`, so the byte is
        // replaced before printf sees it. `bytes::char_at` covers it directly
        // until the capture path is byte-native.)
        // `%.Ns` truncates by bytes (C semantics). Landing mid-character used
        // to panic — `String::truncate` rejects a non-boundary index; over
        // bytes it simply cuts.
        assert_eq!(run_raw("printf '%.1s' \"$(printf '\\u00e9')\"").0, b"\xc3");
    }

    #[test]
    fn printf_b_conversion_escapes() {
        // `%b` uses `echo -e` octal rules: `\0nnn` (leading 0 is a prefix), so
        // `\0101` is the single character `A`.
        assert_eq!(run("printf '%b' '\\0101'").0, "A");
        // `\nnn` without the leading 0 also works in `%b`.
        assert_eq!(run("printf '%b' '\\101'").0, "A");
        assert_eq!(run("printf '%b' '\\x41'").0, "A");
        assert_eq!(run("printf '%b' '\\u0041'").0, "A");
        assert_eq!(run("printf '%b' '\\07'").0, "\u{07}");
        // `\c` stops all further output, including later literal text.
        assert_eq!(run("printf 'A%bC' '\\c stop'").0, "A");
        assert_eq!(run("printf '%b' 'x\\cy'").0, "x");
    }

    #[test]
    fn printf_sign_and_hash_flags() {
        // `+` forces a leading sign on non-negative numbers; negatives keep `-`.
        assert_eq!(run("printf '%+d %+d %+d' 5 -3 0").0, "+5 -3 +0");
        // The space flag reserves a sign column for non-negatives.
        assert_eq!(run("printf '% d|% d' 5 -3").0, " 5|-3");
        // Sign is placed before the zero padding, not swallowed by it.
        assert_eq!(run("printf '%+05d' 5").0, "+0005");
        assert_eq!(run("printf '%+05d' -5").0, "-0005");
        assert_eq!(run("printf '% 05d' 5").0, " 0005");
        // `+`/space apply to floats too.
        assert_eq!(run("printf '%+.2f' 3.5").0, "+3.50");
        assert_eq!(run("printf '% .2f' 3.5").0, " 3.50");
        // `#` adds base prefixes; the fill zeros go after the prefix.
        assert_eq!(run("printf '%#x' 255").0, "0xff");
        assert_eq!(run("printf '%#X' 255").0, "0XFF");
        assert_eq!(run("printf '%#06x' 255").0, "0x00ff");
        assert_eq!(run("printf '%#o' 8").0, "010");
        // `#` on zero produces no prefix (hex) / bare `0` (octal).
        assert_eq!(run("printf '%#x' 0").0, "0");
        assert_eq!(run("printf '%#o' 0").0, "0");
        // Left-justify keeps the sign attached to the number.
        assert_eq!(run("printf '%-+6d|' 5").0, "+5    |");
    }

    #[test]
    fn printf_float_conversion() {
        assert_eq!(run("printf '%.2f' 3.14159").0, "3.14");
        assert_eq!(run("printf '%f' 1").0, "1.000000");
    }

    #[test]
    fn printf_g_conversion() {
        // `%g` uses `prec` significant digits (default 6) and strips trailing
        // zeros; the exponent decides `%f`- vs `%e`-style.
        assert_eq!(run("printf '%.3g\\n' 3.14159").0, "3.14\n");
        assert_eq!(run("printf '%g\\n' 3.14159").0, "3.14159\n");
        assert_eq!(run("printf '%g\\n' 100000").0, "100000\n");
        assert_eq!(run("printf '%g\\n' 1000000").0, "1e+06\n");
        assert_eq!(run("printf '%g\\n' 0.0001").0, "0.0001\n");
        assert_eq!(run("printf '%g\\n' 0.00001").0, "1e-05\n");
        assert_eq!(run("printf '%.10g\\n' 3.14159").0, "3.14159\n");
        assert_eq!(run("printf '%G\\n' 0.00001").0, "1E-05\n");
        // `#` keeps trailing zeros.
        assert_eq!(run("printf '%#g\\n' 1.5").0, "1.50000\n");
        assert_eq!(run("printf '%g\\n' 0").0, "0\n");
    }

    #[test]
    fn printf_a_hex_float_conversion() {
        // `%a` renders IEEE-754 doubles in hexadecimal float form.
        assert_eq!(run("printf '%a\\n' 1.5").0, "0x1.8p+0\n");
        assert_eq!(run("printf '%A\\n' 1.5").0, "0X1.8P+0\n");
        assert_eq!(run("printf '%a\\n' 0").0, "0x0p+0\n");
        assert_eq!(run("printf '%a\\n' 2").0, "0x1p+1\n");
        assert_eq!(run("printf '%a\\n' -1.5").0, "-0x1.8p+0\n");
        assert_eq!(run("printf '%+a\\n' 1.5").0, "+0x1.8p+0\n");
        // Explicit precision rounds the fraction (round-half-to-even): 1.5's
        // `0x1.8` rounds to the even `0x2p+0`, not a renormalized `0x1p+1`.
        assert_eq!(run("printf '%.0a\\n' 1.5").0, "0x2p+0\n");
        // 0.1's 52-bit mantissa is exactly 13 hex digits.
        assert_eq!(run("printf '%a\\n' 0.1").0, "0x1.999999999999ap-4\n");
    }

    #[test]
    fn printf_thousands_flag_ignored() {
        // The `'` grouping flag is accepted; in the C locale it groups nothing.
        assert_eq!(run("printf \"%'d\\n\" 1234567").0, "1234567\n");
        assert_eq!(run("printf \"%'5d|\" 42").0, "   42|");
    }

    #[test]
    fn read_exact_n_no_ifs_split() {
        // `-N` reads exactly N characters and assigns them raw, without IFS
        // splitting or trimming (leading/trailing whitespace preserved).
        assert_eq!(run("read -N 3 x <<< 'ab cd'; echo \"[$x]\"").0, "[ab ]\n");
        assert_eq!(run("read -N 5 x <<< '  hi  there'; echo \"[$x]\"").0, "[  hi ]\n");
        // With several names the whole record goes to the first; the rest clear.
        assert_eq!(
            run("read -N 5 a b <<< 'x y z w'; echo \"[$a][$b]\"").0,
            "[x y z][]\n"
        );
        // An array target receives a single element holding the raw record.
        assert_eq!(
            run("read -N 5 -a arr <<< 'x y z w'; echo \"${#arr[@]}:[${arr[0]}]\"").0,
            "1:[x y z]\n"
        );
        // A custom IFS is likewise ignored under `-N`.
        assert_eq!(
            run("IFS=: read -N 3 x <<< 'a:b:c'; echo \"[$x]\"").0,
            "[a:b]\n"
        );
    }

    #[test]
    fn readonly_export_array_literal() {
        // `readonly arr=(1 2)` binds the array and applies the readonly attr,
        // formatting via `declare -p` as an indexed readonly array.
        assert_eq!(
            run("readonly arr=(1 2); echo \"${arr[1]}\"; declare -p arr").0,
            "2\ndeclare -ar arr=([0]=\"1\" [1]=\"2\")\n"
        );
        // `export arr=(1 2)` binds and marks the array exported (`-ax`).
        assert_eq!(
            run("export arr=(1 2); declare -p arr").0,
            "declare -ax arr=([0]=\"1\" [1]=\"2\")\n"
        );
        // `readonly -A m=([k]=v)` gives a readonly associative array.
        assert_eq!(
            run("readonly -A m=([k]=v); echo \"${m[k]}\"; declare -p m").0,
            "v\ndeclare -Ar m=([k]=\"v\" )\n"
        );
        // A scalar operand alongside an array literal is applied too.
        assert_eq!(
            run("readonly x=1 arr=(9 8); echo \"$x ${arr[0]}\"; declare -p x").0,
            "1 9\ndeclare -r x=\"1\"\n"
        );
    }

    #[test]
    fn hash_mid_word_is_literal() {
        // `#` only begins a comment at the *start* of a word; mid-word it is a
        // literal character (bash/POSIX), so `abc#def` is one word.
        assert_eq!(run("echo abc#def").0, "abc#def\n");
        assert_eq!(run("echo a#b#c").0, "a#b#c\n");
        assert_eq!(run("echo end#").0, "end#\n");
        // A `#` at word start (preceded by blanks) is still a comment.
        assert_eq!(run("echo abc #def").0, "abc\n");
        // The base-N arithmetic form survives as an assignment value. (Quoted,
        // because unbracketed `[16#ff]` is a glob that would match a one-letter
        // file another test happened to leave in the shared working directory.)
        assert_eq!(run("n=16#ff; echo \"[$n]\"").0, "[16#ff]\n");
        assert_eq!(run("declare -i n=16#ff; echo $n").0, "255\n");
        // A whole-line comment still works.
        assert_eq!(run("echo a; #comment\necho b").0, "a\nb\n");
    }

    #[test]
    fn readonly_array_element_cannot_unset() {
        // An element of a readonly array cannot be unset (bash reports the base
        // name), and the array is left intact.
        let (out, status) = run("readonly arr=(1 2); unset arr[0]; echo $?; declare -p arr");
        assert_eq!(
            out,
            "1\ndeclare -ar arr=([0]=\"1\" [1]=\"2\")\n"
        );
        assert_eq!(status, 0); // last command (declare -p) succeeds
        // A readonly associative element is likewise protected.
        assert_eq!(
            run("readonly -A m=([k]=v); unset m[k]; declare -p m").0,
            "declare -Ar m=([k]=\"v\" )\n"
        );
    }

    #[test]
    fn printf_time_conversion() {
        // Epoch 0 = 1970-01-01 00:00:00 UTC (a Thursday, day-of-year 001).
        assert_eq!(run("printf '%(%F)T\\n' 0").0, "1970-01-01\n");
        assert_eq!(run("printf '%(%A)T\\n' 0").0, "Thursday\n");
        assert_eq!(run("printf '%(%j)T\\n' 0").0, "001\n");
        // 12-hour clock: midnight is 12 AM.
        assert_eq!(run("printf '%(%I %p)T\\n' 0").0, "12 AM\n");
        // A known later timestamp: 1000000000 = 2001-09-09 01:46:40 UTC (Sunday).
        assert_eq!(
            run("printf '%(%Y-%m-%d %H:%M:%S)T\\n' 1000000000").0,
            "2001-09-09 01:46:40\n"
        );
        assert_eq!(run("printf '%(%B %a)T\\n' 1000000000").0, "September Sun\n");
        // `%T`/`%R` compound specifiers.
        assert_eq!(run("printf '%(%T)T\\n' 1000000000").0, "01:46:40\n");
        assert_eq!(run("printf '%(%R)T\\n' 1000000000").0, "01:46\n");
        // A negative argument means "now"; just check it produces 4-digit year.
        assert_eq!(run("printf '%(%Y)T\\n' -1").0.trim().len(), 4);
        // Zone specifiers reflect osh's UTC rendering (bash would use the local
        // zone; see TD-OILS9).
        assert_eq!(run("printf '%(%z %Z)T\\n' 0").0, "+0000 UTC\n");
        // Space-padded hours (%k 24h, %l 12h) and the %r 12-hour clock.
        assert_eq!(run("printf '%(%k|%l|%r)T\\n' 1000000000").0, " 1| 1|01:46:40 AM\n");
        // C-locale compound specifiers %c/%x/%X.
        assert_eq!(
            run("printf '%(%c)T\\n' 1000000000").0,
            "Sun Sep  9 01:46:40 2001\n"
        );
        assert_eq!(run("printf '%(%x %X)T\\n' 1000000000").0, "09/09/01 01:46:40\n");
        // ISO 8601 week date (%G week-year, %V week number, %g 2-digit year).
        // 2001-09-09 is ISO week 36 of 2001.
        assert_eq!(run("printf '%(%G-W%V-%g)T\\n' 1000000000").0, "2001-W36-01\n");
        // Boundary: 2021-01-01 (Fri) belongs to ISO week 53 of 2020.
        assert_eq!(run("printf '%(%G-W%V)T\\n' 1609459200").0, "2020-W53\n");
        // Boundary: 2018-12-31 (Mon) belongs to ISO week 01 of 2019.
        assert_eq!(run("printf '%(%G-W%V)T\\n' 1546214400").0, "2019-W01\n");
    }

    #[test]
    fn set_noexec_skips_execution() {
        // `set -n` (noexec) runs, then latches: every later command is parsed
        // but not executed. The `set -n` itself executes because noexec is off
        // when it is reached.
        assert_eq!(run("echo before; set -n; echo after; echo also").0, "before\n");
        // Assignments and expansions after noexec do not run either.
        assert_eq!(run("set -n; x=5; echo $x").0, "");
    }

    #[test]
    fn set_noexec_latches_and_ignores_plus_n() {
        // Under noexec, `set +n` cannot re-enable execution: it is itself
        // skipped, so the flag stays on (bash parity).
        assert_eq!(run("set -n; set +n; echo nope").0, "");
        // A `&&` continuation after `set -n` is also skipped.
        assert_eq!(run("set -n && echo x").0, "");
    }

    #[test]
    fn set_noexec_reported_in_options() {
        // `[[ -o noexec ]]` reflects the flag, and it appears in `set -o`.
        assert_eq!(run("[[ -o noexec ]] && echo on || echo off").0, "off\n");
        // `set -n` inside a condition still evaluates the condition itself
        // (noexec latches only for subsequent commands).
        assert_eq!(run("set -n; [[ -o noexec ]] && echo on").0, "");
        assert!(run("set -o").0.contains("noexec         \toff\n"));
    }

    /// Helper: run `src` in a `Shell` after `setup` has applied invocation-time
    /// options, capturing stdout. Mirrors [`run`] but lets the caller poke the
    /// command-line option methods (`apply_short_options`, …) first.
    fn run_with(setup: impl FnOnce(&mut Shell), src: &str) -> (String, i32) {
        let mut sh = Shell::new();
        setup(&mut sh);
        let buf = capture_sink();
        let prog = parse(src.as_bytes()).expect("parse");
        {
            let mut out = Out::Capture(buf.clone());
            if let Flow::Exit(code) = sh.exec_program_top(&prog, &mut out, &StdinSrc::Inherit) {
                sh.last_status = code;
            }
        }
        let buf = take_capture(&buf);
        (String::from_utf8_lossy(&buf).into_owned(), sh.last_status)
    }

    #[test]
    fn invocation_options_apply_set_and_shopt_state() {
        // `-e` (errexit): a failing command aborts before the next runs.
        let (out, _) = run_with(|sh| assert!(sh.apply_short_options("e", true).is_ok()), "false; echo after");
        assert_eq!(out, "", "errexit should stop before `echo after`");

        // A `-eu` cluster enables both; `[[ -o … ]]` reflects each.
        let (out, _) = run_with(
            |sh| assert!(sh.apply_short_options("eu", true).is_ok()),
            "[[ -o errexit ]] && [[ -o nounset ]] && echo both",
        );
        assert_eq!(out, "both\n");

        // `-o pipefail` (long option) is reflected in `set -o` / `[[ -o … ]]`.
        let (out, _) = run_with(
            |sh| assert!(sh.apply_named_option("pipefail", true)),
            "[[ -o pipefail ]] && echo pf",
        );
        assert_eq!(out, "pf\n");

        // `-O extglob` (shopt) enables extended globbing patterns.
        let (out, _) = run_with(
            |sh| assert!(sh.apply_shopt_option("extglob", true)),
            "shopt extglob",
        );
        assert_eq!(out, "extglob        \ton\n");

        // Invalid names are rejected (so the binary can exit 2).
        let mut sh = Shell::new();
        assert!(!sh.apply_named_option("bogus", true));
        assert!(!sh.apply_shopt_option("bogus", true));
        assert_eq!(sh.apply_short_options("eZx", true), Err('Z'));
    }

    // Trap-handler output is written through `run_source` (real stdout), not
    // the captured `out`, so these tests observe trap firing via a counter/flag
    // variable in `sh.vars` — the same convention as the existing DEBUG/RETURN
    // trap tests. (Whether a trap's *output* is captured by an enclosing command
    // substitution is a separate, subtler behaviour — see known-issues.)
    fn trap_var(src: &str, var: &str) -> Option<String> {
        let mut sh = Shell::new();
        sh.run_source(src.as_bytes());
        sh.vars.get(var).map(|v| as_text(v).to_string())
    }

    #[test]
    fn return_trap_not_inherited_without_functrace() {
        // A RETURN trap set at the top level does NOT fire when a called
        // function returns (bash: functrace off is the default).
        assert_eq!(trap_var("trap 'RET=1' RETURN\nf(){ :; }\nf", "RET"), None);
    }

    #[test]
    fn return_trap_inherited_under_functrace() {
        // `set -T` (functrace) makes the RETURN trap fire on function return.
        assert_eq!(
            trap_var("set -T\ntrap 'RET=1' RETURN\nf(){ :; }\nf", "RET").as_deref(),
            Some("1")
        );
        // `set -o functrace` is the long spelling of the same option.
        assert_eq!(
            trap_var("set -o functrace\ntrap 'RET=1' RETURN\nf(){ :; }\nf", "RET").as_deref(),
            Some("1")
        );
    }

    #[test]
    fn return_trap_set_inside_function_fires_then_masked() {
        // A RETURN trap set inside a function fires once on that function's own
        // return. It then persists globally (bash: `trap -p` still shows it), but
        // a later *untraced* function does not inherit it, so it does not re-fire
        // on g's return. Net: IR is incremented exactly once.
        assert_eq!(
            trap_var(
                "f(){ trap 'IR=$((IR+1))' RETURN; :; }\nf\ng(){ :; }\ng",
                "IR"
            )
            .as_deref(),
            Some("1")
        );
    }

    #[test]
    fn trap_set_inside_function_persists_globally() {
        // A DEBUG trap installed inside a function is not discarded on return
        // (bash): it stays in `self.traps` and fires for subsequent top-level
        // commands. `f` installs DEBUG; after `f` returns the two top-level
        // `:`/`echo` commands each fire it. `trap -p` output confirms persistence.
        let mut sh = Shell::new();
        sh.run_source("f(){ trap 'D=$((D+1))' DEBUG; }\nf\n:\n:".as_bytes());
        // Two top-level simple commands after the definition fire the persisted
        // DEBUG trap. (The `f` call itself fired it once before the body ran, but
        // the trap was not yet installed at that point, so it starts counting at
        // the first `:`.)
        assert_eq!(sh.vars.get("D").map(as_text), Some("2"));
    }

    #[test]
    fn debug_trap_not_inherited_without_functrace() {
        // Without functrace the DEBUG trap fires only before top-level commands
        // (the `f` call), not before the function-body commands. Here: the `f`
        // call fires once; the two body colons do not.
        assert_eq!(
            trap_var("trap 'D=$((D+1))' DEBUG\nf(){ :; :; }\nf", "D").as_deref(),
            Some("1")
        );
    }

    #[test]
    fn debug_trap_inherited_under_functrace() {
        // Under functrace the DEBUG trap also fires inside the function, plus an
        // extra entry firing on function entry. For `f(){ echo x; echo y; }; f`
        // that is: f-call, entry, echo x, echo y = 4 firings (matches bash).
        assert_eq!(
            trap_var(
                "set -T\ntrap 'D=$((D+1))' DEBUG\nf(){ echo x; echo y; }\nf",
                "D"
            )
            .as_deref(),
            Some("4")
        );
    }

    #[test]
    fn declare_ft_sets_and_clears_function_trace() {
        // `declare -ft NAME` makes just that function inherit RETURN traps even
        // with functrace off; other functions stay uninherited (R fires once).
        assert_eq!(
            trap_var(
                "trap 'R=$((R+1))' RETURN\nf(){ :; }\ng(){ :; }\ndeclare -ft f\nf\ng",
                "R"
            )
            .as_deref(),
            Some("1")
        );
        // `declare -f +t NAME` clears the trace attribute again (R never fires).
        assert_eq!(
            trap_var(
                "trap 'R=1' RETURN\nf(){ :; }\ndeclare -ft f\ndeclare -f +t f\nf",
                "R"
            ),
            None
        );
    }

    #[test]
    fn declare_plus_ft_does_not_clear_trace() {
        // bash only enters function mode from a minus-signed `-f`; a plus-signed
        // `+ft` does NOT touch the function's trace attribute, so RETURN still
        // fires after it.
        assert_eq!(
            trap_var(
                "trap 'R=1' RETURN\nf(){ :; }\ndeclare -ft f\ndeclare +ft f\nf",
                "R"
            )
            .as_deref(),
            Some("1")
        );
    }

    #[test]
    fn debug_trap_fires_per_simple_pipeline_stage() {
        // bash fires DEBUG in the parent once per pipeline stage that is a
        // simple command: `true | true | true` → 3 firings.
        assert_eq!(
            trap_var("trap 'D=$((D+1))' DEBUG\ntrue | true | true", "D").as_deref(),
            Some("3")
        );
        // Group/compound stages do NOT fire it (bash), so a two-group pipeline
        // leaves the counter unset.
        assert_eq!(
            trap_var("trap 'D=$((D+1))' DEBUG\n{ true; } | { true; }", "D"),
            None
        );
        // A mixed pipeline fires only for the simple stage.
        assert_eq!(
            trap_var(
                "trap 'D=$((D+1))' DEBUG\ntrue | while read _l; do :; done",
                "D"
            )
            .as_deref(),
            Some("1")
        );
    }

    #[test]
    fn functrace_reported_in_options() {
        // `[[ -o functrace ]]`, `$-`, and `set -o` all reflect the flag.
        assert_eq!(run("[[ -o functrace ]] && echo on || echo off").0, "off\n");
        assert_eq!(run("set -T; [[ -o functrace ]] && echo on").0, "on\n");
        assert!(run("set -T; echo \"$-\"").0.contains('T'));
        assert!(run("set -o").0.contains("functrace      \toff\n"));
        // Enabled functrace is listed in SHELLOPTS.
        assert!(run("set -T; echo \"$SHELLOPTS\"").0.contains("functrace"));
    }

    #[test]
    fn errtrace_reported_in_options() {
        // `[[ -o errtrace ]]`, `$-` (letter `E`), `set -o`, and SHELLOPTS all
        // reflect the flag, both short (`-E`) and long (`-o errtrace`) spellings.
        assert_eq!(run("[[ -o errtrace ]] && echo on || echo off").0, "off\n");
        assert_eq!(run("set -E; [[ -o errtrace ]] && echo on").0, "on\n");
        assert_eq!(run("set -o errtrace; [[ -o errtrace ]] && echo on").0, "on\n");
        assert!(run("set -E; echo \"$-\"").0.contains('E'));
        // bash orders `E` before `T` in `$-` (…,C,E,H,P,T).
        let dollar_dash = run("set -ET; echo \"$-\"").0;
        let e = dollar_dash.find('E');
        let t = dollar_dash.find('T');
        assert!(e.is_some() && t.is_some() && e < t);
        assert!(run("set -o").0.contains("errtrace       \toff\n"));
        assert!(run("set -E; echo \"$SHELLOPTS\"").0.contains("errtrace"));
    }

    #[test]
    fn err_trap_not_inherited_without_errtrace() {
        // Without `errtrace`, a failing command inside a called function does not
        // fire the caller's ERR trap; only the function call itself failing at
        // the caller level does. So ERR fires exactly once.
        assert_eq!(
            trap_var("trap 'E=$((E+1))' ERR\nf(){ false; }\nf", "E").as_deref(),
            Some("1")
        );
    }

    #[test]
    fn err_trap_inherited_under_errtrace() {
        // Under `set -E`, the ERR trap is inherited into the function: `false`
        // inside fires it, and the function call failing at the top fires it
        // again — two firings total.
        assert_eq!(
            trap_var("set -E\ntrap 'E=$((E+1))' ERR\nf(){ false; }\nf", "E").as_deref(),
            Some("2")
        );
    }

    #[test]
    fn err_trap_installed_in_function_not_double_fired() {
        // When a function installs its OWN ERR trap and then fails, with no ERR
        // trap present at the caller when the call started, the call's own
        // non-zero return must not fire it again (bash): the trap did not exist
        // at the caller frame when the call began. So ERR fires exactly once.
        assert_eq!(
            trap_var("f(){ trap 'E=$((E+1))' ERR; false; }\nf", "E").as_deref(),
            Some("1")
        );
    }

    #[test]
    fn set_errexit_exits_on_failure() {
        // A failing command aborts the script under `set -e`.
        let (o, s) = run("set -e; false; echo after");
        assert_eq!(o, "");
        assert_eq!(s, 1);
        // A successful command chain still runs to completion.
        assert_eq!(run("set -e; true; echo after").0, "after\n");
    }

    #[test]
    fn set_errexit_condition_exempt() {
        // Failing commands in a condition do not trigger errexit.
        assert_eq!(run("set -e; if false; then echo t; fi; echo done").0, "done\n");
        assert_eq!(run("set -e; while false; do echo x; done; echo done").0, "done\n");
        // A non-final `&&` operand failure is exempt; a negated command too.
        assert_eq!(run("set -e; false && echo skip; echo done").0, "done\n");
        assert_eq!(run("set -e; ! true; echo done").0, "done\n");
    }

    #[test]
    fn set_errexit_final_and_or_fires() {
        // The command after the final `&&` is subject to errexit.
        let (o, s) = run("set -e; true && false; echo after");
        assert_eq!(o, "");
        assert_eq!(s, 1);
    }

    #[test]
    fn set_errexit_exemption_propagates_into_functions() {
        // POSIX: errexit is ignored for any AND-OR command other than the one
        // after the final `&&`/`||`, and for a `!`-negated pipeline — and the
        // exemption PROPAGATES into the body of a function invoked there. So a
        // bare failing command inside such a function does not abort the shell.
        assert_eq!(run("set -e; f() { false; echo A; }; f || echo caught").0, "A\n");
        assert_eq!(run("set -e; f() { false; echo A; }; f && echo B; echo C").0, "A\nB\nC\n");
        assert_eq!(run("set -e; f() { false; echo A; }; ! f; echo done").0, "A\ndone\n");
        // A brace group in an exempt position is exempt throughout too.
        assert_eq!(run("set -e; { false; echo A; } || echo caught").0, "A\n");
        // The exemption reaches through a nested call chain.
        assert_eq!(
            run("set -e; f() { g() { false; echo inner; }; g; echo outer; }; f || echo c").0,
            "inner\nouter\n"
        );
        // But a function called in a NON-exempt position still honours errexit.
        let (o, s) = run("set -e; f() { false; echo A; }; f; echo after");
        assert_eq!(o, "");
        assert_eq!(s, 1);
    }

    #[test]
    fn set_errexit_exemption_propagates_into_subshells() {
        // A subshell executed where errexit is being ignored runs its whole body
        // with errexit suppressed (bash/POSIX): the intermediate failure does not
        // abort it. `( false; echo sub )` on the left of `||` prints `sub`.
        assert_eq!(run("set -e; ( false; echo sub ) || echo subcaught").0, "sub\n");
        // Same in an if-condition, and for a multi-failure body.
        assert_eq!(
            run("set -e; if ( false; echo X ); then echo t; else echo f; fi").0,
            "X\nt\n"
        );
        assert_eq!(
            run("set -e; ( false; echo A; true; false; echo B ) || echo c").0,
            "A\nB\n"
        );
        // A subshell in a NORMAL (non-exempt) context still honours errexit: the
        // intermediate failure aborts the subshell (and the failing subshell then
        // aborts the outer shell), so neither `sub` nor `after` prints.
        let (o, s) = run("set -e; ( false; echo sub ); echo after");
        assert_eq!(o, "");
        assert_eq!(s, 1);
    }

    #[test]
    fn command_sub_does_not_inherit_errexit_by_default() {
        // `inherit_errexit` is OFF by default: a command substitution runs with
        // errexit unset in its subshell, so an intermediate failure does not
        // abort it — `x=$(false; echo A)` still captures `A` (bash).
        assert_eq!(run(r#"set -e; x=$(false; echo A); echo "[$x]""#).0, "[A]\n");
        // Multiple intermediate failures are likewise tolerated; only the final
        // command's status becomes $? of the substitution.
        assert_eq!(run(r#"set -e; x=$(false; echo A; false; echo B; true); echo "[$x]""#).0, "[A\nB]\n");
    }

    #[test]
    fn command_sub_inherits_errexit_when_shopt_set() {
        // `shopt -s inherit_errexit`: the substitution subshell inherits the
        // caller's `set -e`, so the intermediate failure aborts it before `echo A`
        // runs. The substitution then exits non-zero, and under the outer `set -e`
        // the failing assignment aborts the whole shell — so `echo "[$x]"` never
        // runs and nothing is printed (bash).
        let (o, s) = run(r#"shopt -s inherit_errexit; set -e; x=$(false; echo A); echo "[$x]""#);
        assert_eq!(o, "");
        assert_eq!(s, 1);
    }

    #[test]
    fn set_errexit_enabled_and_failing_same_command_is_exempt() {
        // bash decides errexit-fatality from the flag state at the command's
        // *start*: a `set` that both enables `-e` and fails in one invocation
        // (`set -e -Z`, invalid option) is not fatal to itself — the shell
        // continues. `-Z` is reported but the following command still runs.
        let (o, s) = run("set -e -Z 2>/dev/null; echo after");
        assert_eq!(o, "after\n");
        assert_eq!(s, 0);
        // But a *separate* later command failing under the now-enabled errexit
        // is fatal (`set -Z` here begins with errexit already on).
        let (o2, s2) = run("set -e; set -Z 2>/dev/null; echo after");
        assert_eq!(o2, "");
        assert_eq!(s2, 2);
        // errexit enabled mid-AND-list still governs a later element of the
        // same list: `true && set -e && false` exits on the final `false`.
        let (o3, s3) = run("true && set -e && false; echo after");
        assert_eq!(o3, "");
        assert_eq!(s3, 1);
    }

    #[test]
    fn set_rejects_invalid_options() {
        // `set -o BADNAME`: status 2, `invalid option name`, and no later
        // options applied. The `run` harness is stdin-like (no line number).
        let (o, s) = run("set -o badoption 2>&1");
        assert_eq!(o, "osh: set: badoption: invalid option name\n");
        assert_eq!(s, 2);
        // A bad short option: status 2, `invalid option` + the usage line.
        let (o2, s2) = run("set -q 2>&1");
        assert_eq!(
            o2,
            "osh: set: -q: invalid option\n\
             set: usage: set [-abefhkmnptuvxBCEHPT] [-o option-name] [--] [-] [arg ...]\n"
        );
        assert_eq!(s2, 2);
        // `set` stops at the first invalid option: `-e` before `-Z` is applied
        // (errexit on) but processing aborts at `-Z` with status 2.
        assert_eq!(run("set -e -Z 2>&1 | head -1; echo x").1, 0);
        // Standard bash `-o` names osh does not model are accepted as no-ops.
        assert_eq!(run("set -o vi; set -o posix; set -o emacs; echo ok").0, "ok\n");
        assert_eq!(run("set -o vi; set -o posix; set -o emacs; echo ok").1, 0);
        // Short flags bash accepts but osh does not model are no-ops too.
        assert_eq!(run("set -h; set -m; set -b; echo ok").0, "ok\n");
        assert_eq!(run("set -h; set -m; set -b; echo ok").1, 0);
    }

    #[test]
    fn set_nounset_aborts_on_unset() {
        // A nounset reference aborts word expansion. bash's abort status is
        // invocation-mode dependent: a `-c` command-mode shell exits 127, while
        // a script/stdin/interactive shell exits 1. The `run` harness models the
        // non-command-mode shell, so the status here is 1.
        let (o, s) = run("set -u; echo $undefined; echo after");
        assert_eq!(o, "");
        assert_eq!(s, 1);
        // Under `-c` command mode, the same abort exits 127.
        assert_eq!(run_cmd_mode("set -u; echo $undefined; echo after").1, 127);
        // A default/alternate operator suppresses the error.
        assert_eq!(run("set -u; echo ${undefined:-ok}").0, "ok\n");
        // Special parameters are always considered set.
        assert_eq!(run("set -u; echo $#").0, "0\n");
        // Set variables expand normally.
        assert_eq!(run("set -u; x=hi; echo $x").0, "hi\n");
    }

    #[test]
    fn nounset_abort_under_errexit_is_one() {
        // With errexit enabled, bash treats a fatal expansion error (nounset or
        // `:?`) as a failed command and exits 1 — not the 127 a bare `-c`
        // nounset abort uses. This keys purely on the `-e` option being set,
        // regardless of whether errexit would fire in this context.
        assert_eq!(run_cmd_mode("set -eu; echo $undef; echo after").1, 1);
        // `-u` alone (no errexit) under `-c` still exits 127.
        assert_eq!(run_cmd_mode("set -u; echo $undef").1, 127);
        // The `-e` option flips it to 1 even where errexit is suppressed
        // (`|| true`), and even for `:?` on an unset variable.
        assert_eq!(run_cmd_mode("set -eu; echo $undef || true").1, 1);
        assert_eq!(run_cmd_mode("set -e; echo ${undef:?bye}").1, 1);
        // Without `-e`, a bare `:?` abort under `-c` is 127.
        assert_eq!(run_cmd_mode("echo ${undef:?bye}").1, 127);
    }

    #[test]
    fn local_shadows_global() {
        // A local variable does not leak out of the function.
        assert_eq!(
            run("x=outer; f() { local x=inner; echo $x; }; f; echo $x").0,
            "inner\nouter\n"
        );
        // A previously-unset name is restored to unset after the function.
        assert_eq!(
            run("f() { local y=hi; echo $y; }; f; echo \"[${y-unset}]\"").0,
            "hi\n[unset]\n"
        );
    }

    #[test]
    fn local_mutation_is_isolated() {
        // Assignments to a local inside the function don't affect the global.
        let src = "c=0; inc() { local c=$1; c=$((c+1)); echo $c; }; inc 5; echo $c";
        assert_eq!(run(src).0, "6\n0\n");
    }

    #[test]
    fn local_outside_function_errors() {
        // `local` at top level is an error (non-zero status), not a crash.
        let (_, s) = run("local x=1");
        assert_eq!(s, 1);
    }

    #[test]
    fn local_array_is_scoped() {
        let src = "a=(g1 g2); f() { local a=(l1 l2); echo \"${a[@]}\"; }; f; echo \"${a[@]}\"";
        assert_eq!(run(src).0, "l1 l2\ng1 g2\n");
    }

    #[test]
    fn funcname_reflects_call_stack() {
        // `$FUNCNAME` (element 0) is the current function.
        assert_eq!(run("f() { echo $FUNCNAME; }; f").0, "f\n");
        // The whole array is current-function … callers (no bottom `main`).
        assert_eq!(run("f() { echo \"${FUNCNAME[@]}\"; }; f").0, "f\n");
        assert_eq!(
            run("g() { echo \"${FUNCNAME[@]}\"; }; f() { g; }; f").0,
            "g f\n"
        );
        // Count is exactly the number of active call frames (no `main`).
        assert_eq!(run("f() { echo ${#FUNCNAME[@]}; }; f").0, "1\n");
        // Unset outside any function.
        assert_eq!(run("echo [${FUNCNAME[@]}]").0, "[]\n");
        // Restored after the function returns.
        assert_eq!(run("f() { :; }; f; echo [$FUNCNAME]").0, "[]\n");
    }

    #[test]
    fn funcnest_caps_recursion_like_bash() {
        // With `FUNCNEST=N`, the (N+1)th nested call is refused (with bash's
        // error to stderr, which the harness does not capture) and — like bash's
        // `jump_to_top_level(DISCARD)` — the rest of the offending top-level
        // command is aborted rather than recursing until the native stack
        // overflows. Exactly N frames run; the recursion increments a global
        // counter, and a probe on a *later source line* (which survives the
        // discard) confirms the depth reached. `c=5` proves the graceful cap
        // replaced a crash and that exactly 5 bodies executed.
        let (out, st) = run("FUNCNEST=5\nc=0\nf(){ c=$((c+1)); f; }\nf\necho \"c=$c\"");
        assert_eq!(st, 0); // the discard resumes at the next line; echo runs
        assert_eq!(out, "c=5\n");
        // The DISCARD aborts the *whole* offending top-level command, bypassing
        // `&&`/`||`/`;` on the same line (bash does not let `|| echo` catch it),
        // then resumes at the next line.
        assert_eq!(
            run("FUNCNEST=2\ng(){ g; }\ng || echo CAUGHT\necho AFTER").0,
            "AFTER\n"
        );
        // A zero / unset / non-numeric FUNCNEST disables the ceiling: a bounded
        // recursion of modest depth must run to completion with no error.
        assert_eq!(
            run("FUNCNEST=0; f(){ local n=$1; ((n<=0)) && return; f $((n-1)); }; f 20; echo ok").0,
            "ok\n"
        );
        assert_eq!(
            run("f(){ local n=$1; ((n<=0)) && return; f $((n-1)); }; f 20; echo ok").0,
            "ok\n"
        );
    }

    #[test]
    fn funcname_script_mode_has_main_frame() {
        // In script-file mode (bash `osh SCRIPT`), the call-stack arrays gain a
        // bottom `main` pseudo-frame; `-c`/interactive (the plain harness) do not.
        let script_run = |src: &str| {
            let mut sh = Shell::new();
            sh.set_name(b"scr.sh");
            sh.set_script_mode();
            sh.set_interactive_shell(false);
            let buf = capture_sink();
            let mut out = Out::Capture(buf.clone());
            let prog = parse(src.as_bytes()).expect("parse");
            sh.exec_program(&prog, &mut out, &StdinSrc::Inherit);
            String::from_utf8(take_capture(&buf)).unwrap()
        };
        // Inside `f` at top level: FUNCNAME is `(f main)`, length 2.
        assert_eq!(
            script_run("f() { echo \"${#FUNCNAME[@]}:[${FUNCNAME[*]}]\"; }; f"),
            "2:[f main]\n"
        );
        // Nested: `g f main`, and BASH_LINENO ends in 0 (the main call line).
        assert_eq!(
            script_run("g() { echo \"${FUNCNAME[*]}|${BASH_LINENO[*]}\"; }\nf() { g; }\nf"),
            "g f main|2 3 0\n"
        );
        // At the *top level* of a script bash still exposes the base frame in
        // BASH_SOURCE/BASH_LINENO (the script itself), even though FUNCNAME is
        // empty there. The three arrays therefore differ in length.
        assert_eq!(
            script_run(
                "echo \"[${BASH_SOURCE[0]}] bl=${BASH_LINENO[0]} \
                 fn=${#FUNCNAME[@]} bs=${#BASH_SOURCE[@]}\""
            ),
            "[scr.sh] bl=0 fn=0 bs=1\n"
        );
        // BASH_SOURCE reports the script path for the frames of functions
        // defined in it, and `caller` walks up to the `main` base frame.
        assert_eq!(
            script_run("f() { echo \"src=${BASH_SOURCE[0]}\"; caller 0; }\nf"),
            "src=scr.sh\n2 main scr.sh\n"
        );
    }

    #[test]
    fn bash_lineno_and_source_arrays() {
        // The harness runs like stdin/REPL (neither `-c` nor a script file), so
        // bash labels function frames `main` in BASH_SOURCE.
        assert_eq!(run("f() { echo ${BASH_SOURCE[0]}; }; f").0, "main\n");
        // BASH_LINENO[0] is the line where the current function was called.
        assert_eq!(run("f() { echo ${BASH_LINENO[0]}; }\nf").0, "2\n");
        // Nested: BASH_LINENO tracks each call site. The harness runs like
        // `-c` (not a script file), so there is no bottom `main` frame.
        let src = "g() { echo \"${BASH_LINENO[@]}\"; }\nf() { g; }\nf";
        // g called on line 2 (inside f), f called on line 3.
        assert_eq!(run(src).0, "2 3\n");
        // Parallel arrays are all unset outside any function.
        assert_eq!(run("echo [${BASH_LINENO[@]}][${BASH_SOURCE[@]}]").0, "[][]\n");
    }

    #[test]
    fn bash_argc_argv_extdebug_stack() {
        // Under `shopt -s extdebug`, enabling extdebug captures a base frame from
        // the current positional parameters (none in the harness → count 0), then
        // each function call pushes its argument count (front of BASH_ARGC) and
        // its args reversed (front of BASH_ARGV). BASH_ARGV is a single flat,
        // reversed stack across all frames.
        assert_eq!(
            run("shopt -s extdebug; f(){ echo \"[${BASH_ARGC[@]}][${BASH_ARGV[@]}]\"; }; f q r").0,
            "[2 0][r q]\n"
        );
        // Nested calls stack innermost-first; BASH_ARGV concatenates each frame's
        // reversed args (g's "3 2 1", then f's "a", then the empty base).
        assert_eq!(
            run("shopt -s extdebug; f(){ g 1 2 3; }; g(){ echo \"[${BASH_ARGC[@]}][${BASH_ARGV[@]}]\"; }; f a").0,
            "[3 1 0][3 2 1 a]\n"
        );
        // Returning from a call pops only the frame it pushed; the static base
        // frame (count 0) survives.
        assert_eq!(
            run("shopt -s extdebug; f(){ :; }; f a b c; echo \"[${BASH_ARGC[@]}][${BASH_ARGV[@]}]\"").0,
            "[0][]\n"
        );
        // Without extdebug, osh leaves BASH_ARGC/BASH_ARGV unset. (bash exposes an
        // undocumented top-level base frame here via a lazy-materialisation
        // artifact; osh follows the documented "extended debugging mode only"
        // contract — see known-issues.md TD-OILS-MISSING-SPECIAL-ARRAYS.)
        assert_eq!(run("f(){ echo \"[${BASH_ARGC[@]:-U}]\"; }; f a b").0, "[U]\n");
        // Enabling extdebug inside a function captures that function's positional
        // params as the base frame, then a nested call pushes on top.
        assert_eq!(
            run("f(){ shopt -s extdebug; g z; }; g(){ echo \"[${BASH_ARGC[@]}][${BASH_ARGV[@]}]\"; }; f a b").0,
            "[1 2][z b a]\n"
        );
    }

    #[test]
    fn bash_aliases_and_cmds_live_assoc() {
        // BASH_ALIASES is present-when-empty and rendered as an empty assoc.
        assert_eq!(run("declare -p BASH_ALIASES").0, "declare -A BASH_ALIASES=()\n");
        assert_eq!(run("declare -p BASH_CMDS").0, "declare -A BASH_CMDS=()\n");
        // Defining an alias makes it visible through the mirror (element read,
        // count, and declare -p all reflect the live alias table).
        assert_eq!(
            run("alias ll=\"ls -l\"; echo \"[${BASH_ALIASES[ll]}]\"").0,
            "[ls -l]\n"
        );
        assert_eq!(run("alias a=1 b=2; echo ${#BASH_ALIASES[@]}").0, "2\n");
        assert_eq!(
            run("alias ll=\"ls -l\"; declare -p BASH_ALIASES").0,
            "declare -A BASH_ALIASES=([ll]=\"ls -l\" )\n"
        );
        // Writing an element goes back to the source: BASH_ALIASES[x]=… creates a
        // real alias, and += appends to the existing alias value.
        assert_eq!(run("BASH_ALIASES[gg]=grep; alias gg").0, "alias gg='grep'\n");
        assert_eq!(
            run("BASH_ALIASES[x]=a; BASH_ALIASES[x]+=b; alias x").0,
            "alias x='ab'\n"
        );
        // unalias -a clears the table; the mirror goes back to empty.
        assert_eq!(
            run("alias z=1; unalias -a; declare -p BASH_ALIASES").0,
            "declare -A BASH_ALIASES=()\n"
        );
        // BASH_CMDS is writable too (hash a path without a $PATH search).
        assert_eq!(
            run("BASH_CMDS[foo]=/bin/foo; echo ${BASH_CMDS[foo]}").0,
            "/bin/foo\n"
        );
        assert_eq!(
            run("hash -p /bin/bar bar; echo ${BASH_CMDS[bar]}").0,
            "/bin/bar\n"
        );
        // Both names enumerate under the ${!BASH*} name-prefix expansion.
        let listing = run("echo ${!BASH_ALIASES@} ${!BASH_CMDS@}").0;
        assert!(
            listing.contains("BASH_ALIASES") && listing.contains("BASH_CMDS"),
            "listing: {listing}"
        );
    }

    #[test]
    fn bash_execution_string_set_for_dash_c() {
        // `set_execution_string` seeds $BASH_EXECUTION_STRING; the value is an
        // ordinary reassignable variable and appears under `${!BASH*}`.
        let mut sh = Shell::new();
        sh.set_command_mode();
        sh.set_interactive_shell(false);
        sh.set_execution_string(b"echo hi");
        let buf = capture_sink();
        let prog = parse("echo \"[$BASH_EXECUTION_STRING]\"; echo ${!BASH*}".as_bytes()).expect("parse");
        {
            let mut out = Out::Capture(buf.clone());
            sh.exec_program(&prog, &mut out, &StdinSrc::Inherit);
        }
        let buf = take_capture(&buf);
        let text = String::from_utf8_lossy(&buf);
        assert_eq!(text.lines().next(), Some("[echo hi]"));
        assert!(text.contains("BASH_EXECUTION_STRING"), "listing: {text}");
    }

    #[test]
    fn caller_builtin() {
        // The harness runs like stdin/interactive: no bottom `main` frame, and
        // the source of a top-level caller is reported as the literal `NULL`.
        // Bare `caller` prints "LINE SOURCE" of the current call site; the
        // source is BASH_SOURCE[1] (the caller's frame), here `NULL`.
        assert_eq!(run("f() { caller; }\nf").0, "2 NULL\n");
        // `caller 0` from a single function needs FUNCNAME[1] (the caller),
        // which doesn't exist without a `main` frame → status 1, no output.
        let (o, c) = run("f() { caller 0; }\nf");
        assert_eq!(o, "");
        assert_eq!(c, 1);
        // Nested: `caller 0` from g reports g's call site + its caller f, whose
        // frame source is `main` in stdin/interactive mode.
        assert_eq!(run("g() { caller 0; }\nf() { g; }\nf").0, "2 f main\n");
        // Bare `caller` from g reports g's call line and f's source (`main`).
        assert_eq!(run("g() { caller; }\nf() { g; }\nf").0, "2 main\n");
        // `caller 1` needs FUNCNAME[2] (the `main` base frame), absent here.
        let (o, c) = run("g() { caller 1; }\nf() { g; }\nf");
        assert_eq!(o, "");
        assert_eq!(c, 1);
        // Out of range → status 1, no output.
        let (o, c) = run("f() { caller 5; }\nf");
        assert_eq!(o, "");
        assert_eq!(c, 1);
        // Outside any function → status 1, and crucially *silent* (bash prints
        // no "no such frame" message). Even a bogus argument at top level is
        // swallowed because the empty-stack check precedes arg validation.
        let (o, c) = run("caller");
        assert_eq!(o, "");
        assert_eq!(c, 1);
        assert_eq!(run("caller bogus").1, 1);
        // A non-numeric argument *inside* a function → invalid-number error plus
        // the usage line, status 2 (matching bash's builtin_usage path).
        let (o, c) = run("f() { caller abc; }\nf");
        assert_eq!(o, "");
        assert_eq!(c, 2);
    }

    #[test]
    fn declare_in_function_is_local_by_default() {
        // Bash: `declare x=…` inside a function creates a *local*, so the global
        // is untouched after the function returns.
        let src = "x=outer; f() { declare x=inner; echo $x; }; f; echo $x";
        assert_eq!(run(src).0, "inner\nouter\n");
    }

    #[test]
    fn declare_g_forces_global_from_function() {
        // `declare -g` opts back out to global scope even inside a function.
        let src = "x=outer; f() { declare -g x=global; }; f; echo $x";
        assert_eq!(run(src).0, "global\n");
    }

    #[test]
    fn declare_g_array_forces_global_from_function() {
        // The array one-liner honors `-g` too.
        let src = "f() { declare -g -a a=(1 2 3); }; f; echo \"${a[@]}\"";
        assert_eq!(run(src).0, "1 2 3\n");
    }

    #[test]
    fn declare_array_in_function_is_local_by_default() {
        // Without `-g`, an array declaration inside a function is local.
        let src = "a=(g1 g2); f() { declare -a a=(l1 l2); echo \"${a[@]}\"; }; f; \
                   echo \"${a[@]}\"";
        assert_eq!(run(src).0, "l1 l2\ng1 g2\n");
    }

    #[test]
    fn declare_g_outside_function_is_plain_global() {
        // `-g` at global scope is a harmless no-op.
        assert_eq!(run("declare -g x=5; echo $x").0, "5\n");
    }

    #[test]
    fn local_integer_attr_does_not_leak() {
        // A `local -i` inside a function must not leave the integer attribute
        // set on the global after return: a later plain global assignment must
        // store the string verbatim, not evaluate it arithmetically.
        let src = "f() { local -i n; n=2+2; echo $n; }; f; n=3+4; echo $n";
        assert_eq!(run(src).0, "4\n3+4\n");
    }

    #[test]
    fn local_restores_shadowed_integer_attr() {
        // A bare `local g` does NOT inherit the global's `-i` attribute (bash
        // semantics), so `g=9+9` stores the string verbatim inside the
        // function. But the global's `-i` must be RESTORED on return, so the
        // later global `g=5+5` is evaluated arithmetically.
        let src = "declare -i g=1; f() { local g; g=9+9; echo $g; }; f; g=5+5; echo $g";
        assert_eq!(run(src).0, "9+9\n10\n");
    }

    #[test]
    fn local_dash_saves_and_restores_set_options() {
        // `local -` makes the `set` options local to the function: options
        // changed after the `local -` are reverted on return, matching bash.
        // xtrace enabled inside must not persist after the function returns.
        let src = "f(){ local -; set -x; :; }; f; echo \"$-\" | grep -q x && echo leaked || echo clean";
        assert_eq!(run(src).0, "clean\n");
        // The `$-` letters visible after the call must not include `x`.
        let src2 = "f(){ local -; set -x; :; }; f; case $- in *x*) echo has;; *) echo none;; esac";
        assert_eq!(run(src2).0, "none\n");
    }

    #[test]
    fn local_dash_first_call_baseline_wins() {
        // An option set *before* the first `local -` is part of the saved
        // baseline and persists after return; a second `local -` does not move
        // the baseline. Here `-u` (set before `local -`) survives, while `-e`
        // and `-x` (set after) are reverted.
        let src = "f(){ set -u; local -; set -e; local -; set -x; :; }; f; \
                   for o in u e x; do case $- in *$o*) echo \"$o:on\";; *) echo \"$o:off\";; esac; done";
        assert_eq!(run(src).0, "u:on\ne:off\nx:off\n");
    }

    #[test]
    fn local_dash_restores_set_o_pipefail() {
        // `local -` also covers `set -o` options such as pipefail.
        let src = "f(){ local -; set -o pipefail; :; }; f; \
                   case $(set -o | grep pipefail) in *on*) echo on;; *) echo off;; esac";
        assert_eq!(run(src).0, "off\n");
    }

    #[test]
    fn local_dash_coexists_with_named_local() {
        // `local - x=5` both saves options and declares a normal local `x`.
        let src = "f(){ local - x=5; set -x; echo \"x=$x\"; }; f; \
                   case $- in *x*) echo leaked;; *) echo clean;; esac";
        assert_eq!(run(src).0, "x=5\nclean\n");
    }

    #[test]
    fn local_nameref_does_not_leak() {
        // A `local -n` reference must not leave the nameref attribute set
        // globally after the function returns.
        let src = "target=orig; f() { local -n ref=target; ref=changed; }; f; \
                   echo $target; ref=plainvalue; echo $ref; echo $target";
        assert_eq!(run(src).0, "changed\nplainvalue\nchanged\n");
    }

    #[test]
    fn test_symlink_and_terminal_ops() {
        // -L/-h on a non-symlink is false; the operators parse without error in
        // both `[ ]` and `[[ ]]`.
        assert_eq!(run("[ -L . ]; echo $?").0, "1\n");
        assert_eq!(run("[[ -h . ]]; echo $?").0, "1\n");
        // -t on an invalid descriptor is false.
        assert_eq!(run("[ -t 99 ]; echo $?").0, "1\n");
        assert_eq!(run("[[ -t 99 ]]; echo $?").0, "1\n");
        // Negation composes with the new operators.
        assert_eq!(run("[ ! -L . ] && echo notlink").0, "notlink\n");
    }

    #[test]
    fn test_three_arg_negation_and_binary_precedence() {
        // Regression: `[ ! -f X ]` must negate the unary file test, not be
        // parsed as a bogus binary op. A missing file makes the negation true.
        assert_eq!(run("[ ! -f no_such_file_xyz ] && echo ok").0, "ok\n");
        assert_eq!(run("[ ! -d no_such_dir_xyz ] && echo ok").0, "ok\n");
        // A binary operator in the middle still wins over a leading `!`:
        // `[ ! = x ]` compares the strings "!" and "x" (not equal → false).
        assert_eq!(run("[ ! = x ]; echo $?").0, "1\n");
        // And a genuine equal comparison of "!" to itself is true.
        assert_eq!(run("[ ! = ! ]; echo $?").0, "0\n");
    }

    #[test]
    fn readonly_blocks_reassignment() {
        // Reassigning a readonly variable is fatal in a non-interactive shell
        // (bash): the shell exits with status 1 and the trailing `echo` never
        // runs.
        let (o, s) = run("readonly x=1; x=2; echo $x");
        assert_eq!(o, "");
        assert_eq!(s, 1);
        // The bare failing assignment alone also reports status 1.
        assert_eq!(run("readonly x=1; x=2").1, 1);
    }

    #[test]
    fn readonly_temporary_prefix_reports_but_runs_command() {
        // A readonly var used as a *temporary* command prefix (`readonly x; x=2 cmd`)
        // differs from a bare reassignment: bash (non-POSIX) reports the error but
        // STILL runs the command, dropping the failed assignment from the temporary
        // environment. The command's own status stands (so a success yields 0).
        let (o, s) = run("readonly c=1; c=2 echo hi 2>/dev/null; echo \"rc=$?\"");
        assert_eq!(o, "hi\nrc=0\n");
        assert_eq!(s, 0);
        // The command's failure status is preserved, not overridden by the error.
        assert_eq!(run("readonly c=1; c=2 false 2>/dev/null; echo \"rc=$?\"").0, "rc=1\n");
        // The readonly var is left unchanged; a *non*-readonly sibling prefix on
        // the same command still takes effect in the child environment.
        let (o2, _) = run("readonly c=1; c=2 export d=5 2>/dev/null; echo \"c=$c d=$d\"");
        assert_eq!(o2, "c=1 d=5\n");
        // The diagnostic still names the readonly variable.
        let err = run("readonly c=1; { c=2 echo hi; } 2>&1").0;
        assert!(err.contains("c: readonly variable"), "got: {err:?}");
    }

    #[test]
    fn readonly_refuses_an_arithmetic_write() {
        // Arithmetic is a way of assigning like any other, so the attribute
        // holds there too — and the complaint is about the *variable*, not the
        // expression: no `((`/`let` tag, no echoed source, no error token.
        let err = run("readonly x=1; { ((x=5)); } 2>&1; echo \"rc=$?\"; echo \"x=$x\"").0;
        assert_eq!(err, "osh: x: readonly variable\nrc=1\nx=1\n");
        // The refusal stops the expression where it stands: the assignment
        // before it has already happened, the one after it never does.
        let (o, _) = run("readonly x=1; ((y=1, x=2, z=3)) 2>/dev/null; echo \"y=$y z=$z x=$x\"");
        assert_eq!(o, "y=1 z= x=1\n");
        // Every store goes the same way — compound assignment and the two
        // increments included.
        for expr in ["x+=2", "x++", "++x", "x--"] {
            let (o, _) = run(&format!(
                "readonly x=1; (({expr})) 2>/dev/null; echo \"rc=$? x=$x\""
            ));
            assert_eq!(o, "rc=1 x=1\n", "for (({expr}))");
        }
        // An element write names the array, which is what carries the
        // attribute; `let` and the C-style `for` header reach the same store.
        assert_eq!(
            run("readonly -a a=(1 2); ((a[0]=5)) 2>/dev/null; echo \"${a[0]}\"").0,
            "1\n"
        );
        assert_eq!(run("readonly x=1; let x=5 2>/dev/null; echo \"rc=$?\"").0, "rc=1\n");
        assert_eq!(
            run("readonly x=1; for ((x=0;x<2;x++)); do echo hi; done 2>/dev/null; echo \"rc=$?\"").0,
            "rc=1\n"
        );
        // A branch not taken never reaches the store, so nothing is refused.
        assert_eq!(run("readonly x=1; ((0 ? x=2 : 5)); echo \"rc=$?\"").0, "rc=0\n");
    }

    #[test]
    fn binding_a_loop_variable_is_an_assignment_like_any_other() {
        // `for`/`select` used to write the word straight into the scalar table,
        // so the loop variable's attributes and the shell's own options — which
        // every other assignment obeys — passed it by.
        assert_eq!(run("declare -i n; for n in 1+1 x; do echo \"$n\"; done").0, "2\n0\n");
        assert_eq!(run("declare -u U; for U in ab; do echo \"$U\"; done").0, "AB\n");
        assert_eq!(run("set -a; for v in a b; do :; done; declare -p v").0, "declare -x v=\"b\"\n");
        // An existing array takes the word at element 0, leaving the rest.
        assert_eq!(run("q=(1 2 3); for q in x; do :; done; echo \"${q[@]}\"").0, "x 2 3\n");
        // A nameref is the exception: bash stores into the reference itself and
        // leaves what it refers to alone.
        assert_eq!(run("declare -n r=z; for r in a b; do :; done; echo \"[$z]\"").0, "[]\n");
        // `select` binds its choice the same way, and refuses a readonly name
        // once the choice has been read — giving up the loop with status 1.
        assert_eq!(
            run("declare -i n; select n in 1+1; do break; done <<< 1; echo \"$n\"").0,
            "2\n"
        );
        let (o, _) = run(
            "readonly x=1; select x in a b; do echo body; done <<< 1 2>/dev/null; echo \"rc=$? x=$x\"",
        );
        assert_eq!(o, "rc=1 x=1\n");
    }

    #[test]
    fn readonly_refuses_a_for_loop_variable() {
        // The loop variable is bound by assignment, so a readonly name cannot
        // serve as one: bash finds out at the first binding and gives up the
        // loop with status 1, leaving the value alone. The rest of the command
        // list still runs — only the loop is abandoned.
        let (o, _) =
            run("readonly x=1; for x in a b; do echo body; done 2>/dev/null; echo \"rc=$? x=$x\"; echo after");
        assert_eq!(o, "rc=1 x=1\nafter\n");
        // "At the first binding" is literal: a loop over an empty list never
        // tries, and so never complains.
        assert_eq!(
            run("readonly x=1; for x in; do :; done 2>/dev/null; echo \"rc=$?\"").0,
            "rc=0\n"
        );
        let err = run("readonly x=1; for x in a; do :; done 2>&1").0;
        assert_eq!(err, "osh: x: readonly variable\n");
    }

    #[test]
    fn readonly_blocks_unset() {
        let (o, _) = run("readonly x=hi; unset x; echo $x");
        assert_eq!(o, "hi\n");
        assert_eq!(run("readonly x=hi; unset x").1, 1);
    }

    #[test]
    fn export_respects_readonly() {
        // Regression: `export NAME=value` used to bypass the readonly check,
        // silently mutating the variable. bash reports an error, leaves the
        // value unchanged, and returns status 1.
        let (o, _) = run("readonly y=1; export y=2; echo \"$y\"");
        assert_eq!(o, "1\n", "readonly value must not be mutated by export");
        assert_eq!(run("readonly y=1; export y=2").1, 1);
        // The append form is likewise blocked.
        let (o, _) = run("readonly y=1; export y+=x; echo \"$y\"");
        assert_eq!(o, "1\n");
    }

    #[test]
    fn declare_readonly_error_carries_builtin_tag() {
        // bash tags the readonly-reassignment error with the invoking builtin's
        // name: `declare: y: readonly variable`, `typeset: …`, `local: …`.
        // (`2>&1` routes the command's stderr to the captured stdout.)
        let (o, s) = run("readonly y=1; declare y=2 2>&1");
        assert_eq!(o, "osh: declare: y: readonly variable\n");
        assert_eq!(s, 1);
        let (o, _) = run("readonly y=1; typeset y=2 2>&1");
        assert_eq!(o, "osh: typeset: y: readonly variable\n");
        // Inside a function the frame's source labels the error (bash's
        // `get_name_for_error`): `main` in the harness's stdin-like mode.
        let (o, _) = run("f(){ local y=1; readonly y; local y=2 2>&1; }; f");
        assert_eq!(o, "main: local: y: readonly variable\n");
    }

    #[test]
    fn declare_subscripted_target_and_bad_identifier() {
        // `declare name[sub]=value` assigns an array element, auto-creating an
        // indexed array (bash) — previously osh stored a scalar literally named
        // `name[sub]` and `declare -p` reported "not found".
        assert_eq!(
            run("declare \"x[5]=v\"; declare -p x").0,
            "declare -a x=([5]=\"v\")\n"
        );
        // The subscript is arith-evaluated for an indexed array.
        assert_eq!(
            run("declare \"x[2+3]=v\"; declare -p x").0,
            "declare -a x=([5]=\"v\")\n"
        );
        // `-i` makes the base an integer array; the value is arith-evaluated.
        assert_eq!(
            run("declare -i \"x[0]=2+3\"; declare -p x").0,
            "declare -ai x=([0]=\"5\")\n"
        );
        // An explicit `-A` makes the subscript a literal key.
        assert_eq!(
            run("declare -A \"m[k]=v\"; declare -p m").0,
            "declare -A m=([k]=\"v\" )\n"
        );
        // A subscripted name with no value auto-creates the (empty) array.
        assert_eq!(run("declare \"a[5]\"; declare -p a").0, "declare -a a\n");
        // Append to an element.
        assert_eq!(
            run("declare \"x[3]=a\"; declare \"x[3]+=b\"; declare -p x").0,
            "declare -a x=([3]=\"ab\")\n"
        );
        // A malformed *subscript* arith expression is a fatal, UNtagged syntax
        // error (like a command-position `a[x y]=v`), unlike a bad `-i` value
        // which bash tags `declare:`. The fatal expansion aborts the command.
        let (o, _) = run("declare \"x[a b]=v\" 2>&1");
        assert_eq!(o, "osh: a b: syntax error in expression (error token is \"b\")\n");
        // A non-identifier declare target is rejected with status 1, quoting the
        // original argument (`bad@name=v`, `1x=v`, unbalanced `h[a`).
        let (o, s) = run("declare bad@name=v 2>&1");
        assert_eq!(o, "osh: declare: `bad@name=v': not a valid identifier\n");
        assert_eq!(s, 1);
        let (o, _) = run("declare 1x=v 2>&1");
        assert_eq!(o, "osh: declare: `1x=v': not a valid identifier\n");
    }

    #[test]
    fn bad_array_subscript_underflow() {
        // WRITE, command position: a negative subscript that underflows below 0
        // is a "bad array subscript" naming the full computed reference
        // (`a[-5]`). The command is *discarded* along with the rest of its parse
        // unit (status 1, no `after`) — but the shell survives; see
        // `bad_array_subscript_discards_only_the_parse_unit`.
        let (o, s) = run("a=(1 2); { a[-5]=z; } 2>&1; echo after");
        assert_eq!(o, "osh: a[-5]: bad array subscript\n");
        assert_eq!(s, 1);
        // A valid negative index still overwrites from the end.
        assert_eq!(
            run("a=(1 2 3); a[-1]=z; declare -p a").0,
            "declare -a a=([0]=\"1\" [1]=\"2\" [2]=\"z\")\n"
        );
        // WRITE, `declare` context: the same underflow is NON-fatal (bash sets
        // status 1 but does not abort — `after` runs).
        let (o, _) = run("{ declare \"x[-9]=z\"; } 2>&1; echo after");
        assert_eq!(o, "osh: x[-9]: bad array subscript\nafter\n");
        // READ: an underflowing negative subscript errors too, naming just the
        // base (not the full ref), non-fatal, expanding to empty. The
        // diagnostic precedes `[]` because it is emitted while *expanding* the
        // word, before `echo` writes anything (bash prints the same order).
        let (o, _) = run("a=(1 2); { echo \"[${a[-5]}]\"; } 2>&1; echo after");
        assert_eq!(o, "osh: a: bad array subscript\n[]\nafter\n");
        // A valid negative read is fine and errors nothing.
        assert_eq!(run("a=(1 2 3); echo \"${a[-1]}\"").0, "3\n");
        // A positive out-of-range read is empty WITHOUT an error (bash).
        assert_eq!(run("a=(1 2); echo \"[${a[9]}]\" 2>&1").0, "[]\n");
        // The "bad array subscript" diagnostic names the RAW subscript source
        // (post word-expansion, pre-arithmetic), not the evaluated index — bash:
        // `a[1+2-20]` (write), `a[i]` (var), and `1+2-20]`/`i]` (length form).
        let (o, s) = run("a=(1 2); { a[1+2-20]=z; } 2>&1; echo after");
        assert_eq!(o, "osh: a[1+2-20]: bad array subscript\n");
        assert_eq!(s, 1);
        let (o, _) = run("a=(1 2); i=-5; { a[i]=z; } 2>&1; echo after");
        assert_eq!(o, "osh: a[i]: bad array subscript\n");
        // `declare` context keeps the raw source and stays non-fatal.
        let (o, _) = run("a=(1 2); { declare \"a[1+2-20]=z\"; } 2>&1; echo after");
        assert_eq!(o, "osh: a[1+2-20]: bad array subscript\nafter\n");
        // LENGTH form `${#a[neg]}` is a *fatal* obscure subcase naming the raw
        // subscript source followed by `]` (bash: `1+2-20]: bad array subscript`).
        let (o, s) = run("a=(1 2); { echo \"[${#a[1+2-20]}]\"; } 2>&1; echo after");
        assert_eq!(o, "osh: 1+2-20]: bad array subscript\n");
        assert_eq!(s, 1);
        // A valid negative length read is fine (no error).
        assert_eq!(run("a=(x yy zzz); echo ${#a[-1]}").0, "3\n");
        // A bad *subscript expression* (`a[x y]=v`) is untagged even under
        // `declare -i`, and discards the parse unit — no `after`.
        let (o, s) = run("{ declare -i \"a[x y]=v\"; } 2>&1; echo after");
        assert_eq!(o, "osh: x y: syntax error in expression (error token is \"y\")\n");
        assert_eq!(s, 1);
    }

    #[test]
    fn bad_array_subscript_discards_only_the_parse_unit() {
        // Regression guard for a script-truncation class of bug: osh used to
        // route these word-expansion errors through the *nounset* abort path,
        // which terminates the whole shell. bash only discards the current
        // command and the rest of its parse unit; the next line still runs.
        // Every case below therefore ends with a line that MUST appear.
        //
        // Write with an underflowing subscript.
        let (o, s) = run("a=(1 2 3)\n{ a[-9]=v; echo same-line; } 2>&1\necho \"next=$? n=${#a[@]}\"");
        assert_eq!(o, "osh: a[-9]: bad array subscript\nnext=1 n=3\n");
        assert_eq!(s, 0);
        // Length form.
        let (o, s) = run("a=(1 2 3)\n{ echo \"len=${#a[-9]}\"; } 2>&1\necho still-alive");
        assert_eq!(o, "osh: -9]: bad array subscript\nstill-alive\n");
        assert_eq!(s, 0);
        // Invalid indirect expansion (`${!ptr}` where the target is not a name).
        let (o, s) = run("ptr='not a name'\n{ echo \"v=${!ptr}\"; } 2>&1\necho \"st=$?\"\necho alive");
        assert_eq!(o, "osh: not a name: invalid variable name\nst=1\nalive\n");
        assert_eq!(s, 0);
        // `${a[@]=v}` on an unset array: bash reports status **2**, not 1.
        let (o, s) = run("unset arr\n{ echo \"x=${arr[@]=y}\"; } 2>&1\necho \"st=$?\"\necho alive");
        assert_eq!(o, "osh: arr[@]: bad array subscript\nst=2\nalive\n");
        assert_eq!(s, 0);
        // As a `declare` operand the underflow does not even discard — it only
        // fails the builtin, so the *same line* continues.
        let (o, s) = run("a=(1 2 3)\n{ declare a[-9]=v; echo \"same-line=$?\"; } 2>&1\necho \"next=$? n=${#a[@]}\"");
        // `declare` fails before `echo` runs, so its diagnostic comes first.
        assert_eq!(o, "osh: a[-9]: bad array subscript\nsame-line=1\nnext=0 n=3\n");
        assert_eq!(s, 0);
        // …but a malformed arithmetic *value* under `-i` still discards.
        let (o, s) = run("{ declare -i b=1+*2; echo \"same=$?\"; } 2>&1\necho \"next=$?\"");
        assert_eq!(
            o,
            "osh: declare: 1+*2: syntax error: operand expected (error token is \"*2\")\nnext=1\n"
        );
        assert_eq!(s, 0);
    }

    #[test]
    fn assoc_all_elements_subscript_is_a_literal_key_when_assigning() {
        // In an associative array a subscript is a *string key*, and that holds
        // for the assign-default forms too: `${m[@]:=v}` on an empty `declare -A`
        // creates the literal key `@` rather than erroring. Only an indexed (or
        // undeclared) array rejects `[@]`/`[*]` as a write target.
        assert_eq!(
            run("declare -A m; echo \"y=${m[@]:=z}\"; declare -p m").0,
            "y=z\ndeclare -A m=([\"@\"]=\"z\" )\n"
        );
        assert_eq!(
            run("declare -A m; echo \"y=${m[*]=s}\"; declare -p m").0,
            "y=s\ndeclare -A m=([\"*\"]=\"s\" )\n"
        );
        // A non-empty associative array is "active", so nothing is assigned.
        assert_eq!(
            run("declare -A m=([k]=v); echo \"y=${m[@]:=z}\"; declare -p m").0,
            "y=v\ndeclare -A m=([k]=\"v\" )\n"
        );
        // Indexed arrays keep the error (status 2, discards the parse unit).
        let (o, _) = run("declare -a i\n{ echo \"y=${i[@]:=z}\"; } 2>&1\necho \"st=$?\"");
        assert_eq!(o, "osh: i[@]: bad array subscript\nst=2\n");
    }

    #[test]
    fn declare_p_quotes_associative_keys_like_bash() {
        // bash's `sh_contains_shell_metas` plus its all-elements special case:
        // a lone `@`/`*`, a *leading* `#` or `~`, and any glob/quoting/expansion
        // metacharacter force double quotes; everything else is emitted raw.
        let src = "declare -A k; k[@]=1; k['@@']=2; k['a@b']=3; k['#']=4; k['#x']=5; \
                   k['a#b']=6; k['~']=7; k['a~b']=8; k['a,b']=9; k['a-b']=10; k[a.b]=11; \
                   k['a b']=12; k[plain]=13; declare -p k";
        assert_eq!(
            run(src).0,
            "declare -A k=([\"@\"]=\"1\" [@@]=\"2\" [a@b]=\"3\" [\"#\"]=\"4\" [\"#x\"]=\"5\" \
             [a#b]=\"6\" [\"~\"]=\"7\" [a~b]=\"8\" [a,b]=\"9\" [a-b]=\"10\" [a.b]=\"11\" \
             [\"a b\"]=\"12\" [plain]=\"13\" )\n"
        );
    }

    #[test]
    fn error_prefix_uses_frame_source_inside_function() {
        // bash's `get_name_for_error`: a diagnostic emitted at the top level is
        // labelled with the shell/script name, but one emitted *inside a
        // function* is labelled with that frame's source (`${BASH_SOURCE[0]}`).
        // In the harness's stdin-like mode the shell name is `osh` and a
        // function frame's source is `main`, so the same command-not-found
        // error is prefixed differently by nesting depth. (`2>&1` routes the
        // diagnostic to the captured stdout; a *bare* readonly-reassignment
        // error is written to the real fd 2 before the redirect, matching bash,
        // so command-not-found is the reliable probe here.)
        let (top, _) = run("nosuchcmd_zz 2>&1");
        assert_eq!(top, "osh: nosuchcmd_zz: command not found\n");
        let (infn, _) = run("g(){ nosuchcmd_zz 2>&1; }; g");
        assert_eq!(infn, "main: nosuchcmd_zz: command not found\n");
        // A builtin diagnostic (readonly reassignment) follows the same rule and
        // additionally carries the builtin's name tag.
        let (bi, _) = run("readonly z=1; h(){ declare z=2 2>&1; }; h");
        assert_eq!(bi, "main: declare: z: readonly variable\n");
    }

    #[test]
    fn source_frames_interleave_with_function_frames() {
        // bash puts a `source`d script on the *same* frame stack as function
        // calls: FUNCNAME shows it as the literal name `source`, BASH_SOURCE
        // carries its path as written, BASH_LINENO the line the `.` sat on, and
        // diagnostics raised while it is being read are labelled with it rather
        // than with the top-level shell name. Verified against bash 5.2; the
        // end-to-end shapes live in tests/corpus/source-frames.sh and
        // tests/corpus/source-error-name.sh.
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("clock")
            .as_nanos();
        let dir = std::env::temp_dir().join(format!("osh_srcframe_{}_{nanos}", std::process::id()));
        std::fs::create_dir_all(&dir).expect("mkdir");
        // Absolute forward-slash paths, so the test needs no cwd mutation and
        // the label the shell reports is exactly what we pass in.
        let base = dir.to_string_lossy().replace('\\', "/");
        let show = "echo \"F=[${FUNCNAME[@]}] set=${FUNCNAME+yes} \
                    S=[${BASH_SOURCE[@]}] L=[${BASH_LINENO[@]}]\"";
        let inner = format!("{base}/inner.sh");
        let outer = format!("{base}/outer.sh");
        std::fs::write(&inner, format!("{show}\nnosuchcmd_frame 2>&1\n")).expect("write inner");
        // A function *defined* by a sourced file keeps naming that file.
        std::fs::write(&outer, format!("d() {{\n{show}\ncaller 0\n}}\n")).expect("write outer");

        // Top level of a sourced file: FUNCNAME is unset even though the other
        // two arrays show the source frame, and its errors name the file.
        let (o, _) = run(&format!(". {inner}"));
        assert_eq!(
            o,
            format!("F=[] set= S=[{inner}] L=[1]\n{inner}: nosuchcmd_frame: command not found\n")
        );

        // Calling that function back at the top level: only its own frame is
        // live, but BASH_SOURCE still names the file it was *defined* in. There
        // is no bottom frame in stdin mode, so `caller 0` fails silently.
        let (o, _) = run(&format!(". {outer}\nd"));
        assert_eq!(o, format!("F=[d] set=yes S=[{outer}] L=[2]\n"));

        // source -> function: called *from* a sourced file, the function frame
        // sits above that source frame and `caller 0` names it.
        let call = format!("{base}/call.sh");
        std::fs::write(&call, "d\n").expect("write call");
        let (o, _) = run(&format!(". {outer}\n. {call}"));
        assert_eq!(
            o,
            format!("F=[d source] set=yes S=[{outer} {call}] L=[1 2]\n1 source {call}\n")
        );

        // source -> function -> source: three frames, outermost last.
        let nested = format!("{base}/nested.sh");
        std::fs::write(&nested, format!("e() {{\n. {inner}\n}}\ne\n")).expect("write nested");
        let (o, _) = run(&format!(". {nested}"));
        assert_eq!(
            o,
            format!(
                "F=[source e source] set=yes S=[{inner} {nested} {nested}] L=[2 4 1]\n\
                 {inner}: nosuchcmd_frame: command not found\n"
            )
        );

        // The stack unwinds cleanly: after the source returns, the top-level
        // label and the empty frame arrays are back.
        let (o, _) = run(&format!(". {inner}\nnosuchcmd_after 2>&1\n{show}"));
        assert!(
            o.ends_with("osh: nosuchcmd_after: command not found\nF=[] set= S=[] L=[]\n"),
            "frames should unwind after the source returns, got {o:?}"
        );

        std::fs::remove_dir_all(&dir).ok();
    }

    /// `$0` and every label derived from it are bytes.
    ///
    /// A script path may hold any byte but `/` and NUL, and `BASH_ARGV0=`
    /// accepts any shell word at all. `Shell::name`, `SourceFrame::path`,
    /// `func_sources` and `fn_source_stack` were `String`, so such a name was
    /// stored already mangled: `$0`, `${BASH_SOURCE[0]}` and `caller` all named
    /// a file the user could not then open, which is the whole complaint of
    /// TD-OILS-BYTE-STRINGS.
    #[test]
    fn the_shell_name_and_source_labels_hold_bytes_that_are_not_text() {
        // `BASH_ARGV0=` sets `$0`; both read back byte for byte.
        let (o, s) = run_raw("BASH_ARGV0=$'a\\xffb'; printf '%s|%s' \"$0\" \"$BASH_ARGV0\"");
        assert_eq!(o, b"a\xffb|a\xffb");
        assert_eq!(s, 0);
        // `+=` appends to it rather than replacing (osh's deliberate divergence
        // from bash's lazy-materialization quirk — see `apply_assignment`).
        let (o, _) = run_raw("BASH_ARGV0=$'a\\xff'; BASH_ARGV0+=$'\\xfeb'; printf %s \"$0\"");
        assert_eq!(o, b"a\xff\xfeb");

        // A script whose *path* is not text labels its frames with those bytes:
        // `$0`, `${BASH_SOURCE[0]}` read from inside a function (which reports
        // where the function was *defined*), and `caller`'s source field all
        // agree, and none of them goes through a decode.
        let mut sh = Shell::new();
        sh.set_name(b"/tmp/a\xffb.sh");
        sh.set_script_mode();
        sh.set_interactive_shell(false);
        let buf = capture_sink();
        let status = {
            let mut out = Out::Capture(buf.clone());
            sh.run_source_out(
                b"f() { printf '%s|%s|' \"$0\" \"${BASH_SOURCE[0]}\"; caller 0; }\nf\n",
                &mut out,
                0,
            )
        };
        assert_eq!(status, 0);
        assert_eq!(take_capture(&buf), b"/tmp/a\xffb.sh|/tmp/a\xffb.sh|2 main /tmp/a\xffb.sh\n");
    }

    #[test]
    fn declare_r_marks_readonly() {
        // Reassigning a `declare -r` readonly is fatal (bash): the shell exits
        // with status 1 before the `echo` runs.
        let (o, s) = run("declare -r y=const; y=other; echo $y");
        assert_eq!(o, "");
        assert_eq!(s, 1);
    }

    #[test]
    fn readonly_bare_name_then_assign_fails() {
        // `readonly x` marks an existing name; a later assignment is fatal in a
        // non-interactive shell (bash): the shell exits before the `echo`.
        let (o, s) = run("x=v; readonly x; x=w; echo $x");
        assert_eq!(o, "");
        assert_eq!(s, 1);
    }

    #[test]
    fn readonly_print_lists_vars() {
        // `readonly -p` reuses `declare -p` formatting (bash), not the old
        // `readonly name=value` form. Filter to the names under test so the
        // always-readonly BASH_VERSINFO line doesn't interfere.
        let (o, _) = run("readonly a=1; readonly b=2; readonly -p | grep ' [ab]='");
        assert_eq!(o, "declare -r a=\"1\"\ndeclare -r b=\"2\"\n");
    }

    #[test]
    fn declare_p_scalar() {
        assert_eq!(run("x=5; declare -p x").0, "declare -- x=\"5\"\n");
        // Readonly / exported attributes show in the flag group.
        assert_eq!(run("readonly x=5; declare -p x").0, "declare -r x=\"5\"\n");
        assert_eq!(run("export x=5; declare -p x").0, "declare -x x=\"5\"\n");
    }

    #[test]
    fn declare_p_arrays() {
        assert_eq!(run("a=(x y); declare -p a").0, "declare -a a=([0]=\"x\" [1]=\"y\")\n");
        // bash prints a non-empty associative array with a trailing space
        // before the closing paren.
        assert_eq!(
            run("declare -A m; m[k]=v; declare -p m").0,
            "declare -A m=([k]=\"v\" )\n"
        );
        // An empty array (indexed or associative) prints as the bare name.
        assert_eq!(run("declare -a e; declare -p e").0, "declare -a e\n");
        assert_eq!(run("declare -A me; declare -p me").0, "declare -A me\n");
    }

    #[test]
    fn declare_p_missing_is_error() {
        assert_eq!(run("declare -p nope").1, 1);
    }

    #[test]
    fn declare_p_writes_each_answer_where_it_is_reached() {
        // Not all the definitions after all the complaints: with the two
        // streams merged, each name's answer stands in its own place.
        assert_eq!(
            run("a=1; c=2; declare -p nope a nope2 c 2>&1; echo rc=$?").0,
            "osh: declare: nope: not found\n\
             declare -- a=\"1\"\n\
             osh: declare: nope2: not found\n\
             declare -- c=\"2\"\n\
             rc=1\n"
        );
        // And with the listing going to a `>` file, where each definition is a
        // separate write, the second must not start the file over. (The tests
        // share one working directory, so the file is named distinctively and
        // removed again — a stray short name is glob bait for another test.)
        assert_eq!(
            run("a=1; c=2; declare -p a nope c >declp.tmp 2>/dev/null; cat declp.tmp; rm -f declp.tmp").0,
            "declare -- a=\"1\"\ndeclare -- c=\"2\"\n"
        );
    }

    #[test]
    fn a_declaration_without_a_value_still_brings_the_name_into_being() {
        // Declaring is not assigning, so the name stays unset — but it now
        // exists, which is the difference `declare -p` reports. See
        // `Shell::declared`.
        assert_eq!(run("declare n; declare -p n").0, "declare -- n\n");
        assert_eq!(run("declare -i n; declare -p n").0, "declare -i n\n");
        assert_eq!(run("readonly q; declare -p q").0, "declare -r q\n");
        assert_eq!(run("export e; declare -p e").0, "declare -x e\n");
        assert_eq!(run("declare n; [[ -v n ]]; echo $?; echo [${n-unset}]").0, "1\n[unset]\n");
        // Clearing the last attribute leaves the variable behind, not nothing.
        assert_eq!(run("declare -i n; declare +i n; declare -p n").0, "declare -- n\n");
        // The attribute-filtered listing counts it; a bare `set` and
        // `${!prefix@}`, which are about values, pass over it.
        assert_eq!(run("declare -i zq; declare -i").0.lines().filter(|l| l.ends_with(" zq")).count(), 1);
        assert_eq!(run("declare -i zq; set | grep -c '^zq'").0, "0\n");
        assert_eq!(run("declare -i zq; echo [${!zq@}]").0, "[]\n");
        // `unset` takes it away again — and because it *is* a variable, it is the
        // variable that goes, leaving a function of the same name callable.
        assert_eq!(run("declare n; unset n; declare -p n").1, 1);
        assert_eq!(run("f() { echo fn; }; declare f; unset f; f").0, "fn\n");
        // A `local` declaration exists for the call only.
        assert_eq!(run("f() { local n; declare -p n; }; f; declare -p n").0, "declare -- n\n");
        assert_eq!(run("f() { local n; }; f; declare -p n").1, 1);
    }

    #[test]
    fn declare_p_quotes_specials() {
        // A value with a double quote and `$` is backslash-escaped.
        assert_eq!(run("x='a\"b$c'; declare -p x").0, "declare -- x=\"a\\\"b\\$c\"\n");
    }

    #[test]
    fn declare_p_control_chars_use_ansi_c_form() {
        // A value containing a control byte is rendered in ANSI-C `$'…'` form
        // (bash: `declare -- x=$'a\tb'`), not double-quoted with the raw byte.
        assert_eq!(run("x=$'a\\tb'; declare -p x").0, "declare -- x=$'a\\tb'\n");
        // The named escapes match bash exactly: \a \b \t \n \v \f \r \E.
        assert_eq!(
            run("x=$'\\a\\b\\t\\n\\v\\f\\r\\E'; declare -p x").0,
            "declare -- x=$'\\a\\b\\t\\n\\v\\f\\r\\E'\n"
        );
        // Other control bytes are 3-digit octal (bash's re-input form), not \xHH:
        // 0x01 -> \001, 0x7f (DEL) -> \177.
        assert_eq!(
            run("x=$'\\001\\177'; declare -p x").0,
            "declare -- x=$'\\001\\177'\n"
        );
    }

    #[test]
    fn set_can_disable_options() {
        // `set +e` turns errexit back off.
        assert_eq!(run("set -e; set +e; false; echo after").0, "after\n");
        // Long-form option names work too; the nounset abort exits 1 in a
        // script/stdin shell (127 only under `-c` command mode).
        let (_, s) = run("set -o nounset; echo $undefined; echo after");
        assert_eq!(s, 1);
    }

    #[test]
    fn brace_expansion_command_words() {
        assert_eq!(run("echo a{b,c,d}e").0, "abe ace ade\n");
        assert_eq!(run("echo {1..5}").0, "1 2 3 4 5\n");
        assert_eq!(run("echo {1..9..2}").0, "1 3 5 7 9\n");
        assert_eq!(run("echo file{01..03}.txt").0, "file01.txt file02.txt file03.txt\n");
        assert_eq!(run("echo {a..c}{1,2}").0, "a1 a2 b1 b2 c1 c2\n");
        // Quoted braces stay literal; invalid braces stay literal.
        assert_eq!(run("echo '{a,b}'").0, "{a,b}\n");
        assert_eq!(run("echo {abc}").0, "{abc}\n");
    }

    #[test]
    fn brace_expansion_in_for_loop() {
        let (o, _) = run("for i in {1..3}; do echo x$i; done");
        assert_eq!(o, "x1\nx2\nx3\n");
    }

    #[test]
    fn brace_expansion_with_param() {
        // A parameter reference inside an alternative expands after braces.
        assert_eq!(run("v=Z; echo {$v,b}").0, "Z b\n");
    }

    #[test]
    fn brace_expansion_in_array_literal() {
        // Brace expansion runs on array-literal positional elements, just like
        // command words: `a=({1..3})` yields three elements, not one literal.
        assert_eq!(run("a=({1..3}); echo \"${a[@]}\" ${#a[@]}").0, "1 2 3 3\n");
        assert_eq!(run("a=(x{1..3}y); echo \"${a[@]}\"").0, "x1y x2y x3y\n");
        assert_eq!(run("a=(a{b,c}d); echo \"${a[@]}\"").0, "abd acd\n");
    }

    #[test]
    fn param_transform_quote_and_case() {
        // @Q quotes a value with a space; @U/@u/@L transform case.
        assert_eq!(run("x=\"a b\"; echo \"${x@Q}\"").0, "'a b'\n");
        assert_eq!(run("x=hello; echo \"${x@U}\"").0, "HELLO\n");
        assert_eq!(run("x=hello; echo \"${x@u}\"").0, "Hello\n");
        assert_eq!(run("x=HeLLo; echo \"${x@L}\"").0, "hello\n");
        // There is no `@l`: bash has no lowercase-first operator, so `${x@l}`
        // on a *set* variable is a "bad substitution" (fatal, empty output).
        assert_eq!(
            run("x=HeLLo; { echo \"${x@l}\"; } 2>&1").0,
            "osh: ${x@l}: bad substitution\n"
        );
        // ...but an *unset* variable yields empty with no error.
        assert_eq!(run("unset x; echo \"[${x@l}]\"; echo done").0, "[]\ndone\n");
        // bash single-quotes every set value under @Q, even a plain word.
        assert_eq!(run("x=word; echo \"${x@Q}\"").0, "'word'\n");
        // An unset variable yields empty; a set-but-empty one yields `''`.
        assert_eq!(run("unset x; echo \"[${x@Q}]\"").0, "[]\n");
        assert_eq!(run("x=; echo \"[${x@Q}]\"").0, "['']\n");
        // Control chars force the ANSI-C `$'…'` form and must use bash's exact
        // escapes: named for `\a \b \t \n \v \f \r \E`, 3-digit octal otherwise
        // (`\001`, `\177`) — never `\xHH`. Both @Q and printf %q share this.
        assert_eq!(run("v=$'\\x01'; echo \"${v@Q}\"").0, "$'\\001'\n");
        assert_eq!(run("v=$'\\a'; echo \"${v@Q}\"").0, "$'\\a'\n");
        assert_eq!(run("v=$'\\x1b'; echo \"${v@Q}\"").0, "$'\\E'\n");
        assert_eq!(run("v=$'\\x7f'; echo \"${v@Q}\"").0, "$'\\177'\n");
        assert_eq!(run("v=$'a\\tb\\x01c'; echo \"${v@Q}\"").0, "$'a\\tb\\001c'\n");
        assert_eq!(run("printf '%q\\n' $'\\x01'").0, "$'\\001'\n");
        assert_eq!(run("printf '%q\\n' $'\\x1b'").0, "$'\\E'\n");
    }

    #[test]
    fn param_transform_invalid_op_bad_substitution() {
        // An empty (`@`), unknown (`@Z`), or multi-char (`@QU`) transform
        // operator is deferred to expansion: empty for an UNSET parameter
        // (status 0), but a fatal "bad substitution" for a SET one.
        assert_eq!(run("echo \"[${x@Z}]\"; echo done").0, "[]\ndone\n");
        assert_eq!(run("echo \"[${x@}]\"; echo done").0, "[]\ndone\n");
        assert_eq!(run("echo \"[${x@QU}]\"; echo done").0, "[]\ndone\n");
        assert_eq!(
            run("x=hi; { echo \"${x@Z}\"; } 2>&1").0,
            "osh: ${x@Z}: bad substitution\n"
        );
        assert_eq!(
            run("x=hi; { echo \"${x@}\"; } 2>&1").0,
            "osh: ${x@}: bad substitution\n"
        );
        assert_eq!(
            run("x=hi; { echo \"${x@QU}\"; } 2>&1").0,
            "osh: ${x@QU}: bad substitution\n"
        );
        // Element form: unset element → empty; set element → bad substitution.
        assert_eq!(run("a=(p q); echo \"[${a[9]@Z}]\"; echo done").0, "[]\ndone\n");
        assert_eq!(
            run("a=(p q); { echo \"${a[0]@Z}\"; } 2>&1").0,
            "osh: ${a[0]@Z}: bad substitution\n"
        );
        // Bulk form: an empty array/positional set → empty; ≥1 element → error.
        assert_eq!(run("a=(); echo \"[${a[@]@Z}]\"; echo done").0, "[]\ndone\n");
        assert_eq!(
            run("a=(1 2 3); { echo \"${a[@]@Z}\"; } 2>&1").0,
            "osh: ${a[@]@Z}: bad substitution\n"
        );
        assert_eq!(run("set --; echo \"[${@@Z}]\"; echo done").0, "[]\ndone\n");
        assert_eq!(
            run("set -- x y; { echo \"${@@Z}\"; } 2>&1").0,
            "osh: ${@@Z}: bad substitution\n"
        );
    }

    #[test]
    fn command_and_builtin_builtins() {
        assert_eq!(run("command echo hi").0, "hi\n");
        assert_eq!(run("builtin echo hi").0, "hi\n");
        assert_eq!(run("command -v echo").0, "echo\n");
        assert_eq!(run("command -V echo").0, "echo is a shell builtin\n");
        // A function shadowing a builtin is bypassed by `command`.
        assert_eq!(run("echo() { printf OVERRIDE; }; command echo hi").0, "hi\n");
        // -v on a function prints the name; an unknown name → status 1, no output.
        assert_eq!(run("greet() { :; }; command -v greet").0, "greet\n");
        assert_eq!(run("command -v no_such_cmd_xyz; echo $?").0, "1\n");
    }

    #[test]
    fn special_var_random() {
        // Deterministic when reseeded, and within bash's 15-bit range.
        assert_eq!(run("RANDOM=1; a=$RANDOM; RANDOM=1; b=$RANDOM; [ \"$a\" = \"$b\" ] && echo same").0, "same\n");
        assert_eq!(run("RANDOM=7; r=$RANDOM; [ \"$r\" -ge 0 ] && [ \"$r\" -lt 32768 ] && echo ok").0, "ok\n");
    }

    #[test]
    fn special_var_bash_version() {
        // BASH_VERSION is seeded (non-empty, 5.x compatibility level).
        assert_eq!(run("echo $BASH_VERSION").0, "5.2.0(1)-release\n");
        // BASH_VERSINFO is a 6-element array; [0] is the major version.
        assert_eq!(run("echo ${BASH_VERSINFO[0]}").0, "5\n");
        assert_eq!(run("echo ${#BASH_VERSINFO[@]}").0, "6\n");
        assert_eq!(run("echo ${BASH_VERSINFO[4]}").0, "release\n");
    }

    #[test]
    fn special_var_identity_uid_euid() {
        // Default reported identity is root (0/0) per the operator's Q28
        // decision — SlateOS runs single-user-as-root until a login/session
        // layer injects a per-user identity via OSH_UID/OSH_EUID.
        assert_eq!(run("echo $UID").0, "0\n");
        assert_eq!(run("echo $EUID").0, "0\n");
        // The canonical root check scripts use works out to "root".
        assert_eq!(
            run("if [ \"$EUID\" -ne 0 ]; then echo notroot; else echo root; fi").0,
            "root\n"
        );
        // bash marks both readonly-integer (`declare -ir`); reassignment fails.
        assert!(run("declare -p UID").0.starts_with("declare -ir UID="));
        assert!(run("declare -p EUID").0.starts_with("declare -ir EUID="));
        // A bare reassignment of a readonly var reports status 1 and (as osh
        // does non-interactively) aborts the list, so the value is untouched.
        assert_eq!(run("UID=1000").1, 1);
        assert_eq!(run("EUID=1000").1, 1);
        assert_eq!(run("echo $UID").0, "0\n");
        // The `\\$` prompt escape resolves to `#` for the root EUID.
        assert_eq!(run("PS1='\\$ '; echo \"${PS1@P}\"").0, "# \n");
    }

    #[test]
    fn special_var_platform_identity() {
        // bash always defines these; we report SlateOS's own values.
        assert_eq!(run("echo $HOSTTYPE").0, "x86_64\n");
        assert_eq!(run("echo $OSTYPE").0, "slateos\n");
        assert_eq!(run("echo $MACHTYPE").0, "x86_64-slateos\n");
        // Ordinary shell variables: reassignable, unlike readonly BASH_VERSINFO.
        assert_eq!(run("OSTYPE=custom; echo $OSTYPE").0, "custom\n");
    }

    #[test]
    fn special_var_ppid() {
        // `$PPID` expands to a numeric parent pid (bash always defines it). The
        // exact value is environment-dependent, so assert it is all-digits and
        // stable within a single shell (bash fixes PPID at startup).
        let (out, st) = run("echo $PPID");
        assert_eq!(st, 0);
        let v = out.trim_end();
        assert!(!v.is_empty() && v.bytes().all(|b| b.is_ascii_digit()), "got {out:?}");
        // Constant across two reads, and across a subshell (bash carries the
        // startup value into `( … )` unchanged).
        assert_eq!(run("a=$PPID; b=$( echo $PPID ); [ \"$a\" = \"$b\" ] && echo same").0, "same\n");
        // Prefix listing includes it, and `declare -p` reports it readonly-int.
        assert!(run("echo ${!P*}").0.split_whitespace().any(|n| n == "PPID"));
        assert!(run("declare -p PPID").0.starts_with("declare -ir PPID="));
    }

    #[test]
    fn special_var_seconds_and_epoch() {
        assert_eq!(run("echo $SECONDS").0, "0\n");
        assert_eq!(run("SECONDS=100; echo $SECONDS").0, "100\n");
        assert_eq!(run("[ $EPOCHSECONDS -gt 1000000000 ] && echo ok").0, "ok\n");
    }

    #[test]
    fn special_var_lineno() {
        // $LINENO reflects the 1-based source line of the executing item.
        assert_eq!(run("echo $LINENO").0, "1\n");
        assert_eq!(run("echo $LINENO\necho $LINENO").0, "1\n2\n");
        // Blank and comment lines still advance the counter.
        assert_eq!(run("\n\necho $LINENO").0, "3\n");
        assert_eq!(run("# comment\necho $LINENO").0, "2\n");
        // Semicolon-separated commands on one line share a line number.
        assert_eq!(run("echo $LINENO; echo $LINENO").0, "1\n1\n");
    }

    /// `$LINENO` inside `$( … )` counts up from the *closing* delimiter's line,
    /// by the 0-based rank of the body line among the body's command-bearing
    /// lines — bash re-parses the captured body after the outer scan has already
    /// passed the substitution, and the body's own blank lines never took part in
    /// that scan. Every expectation here was measured against bash 5.x; see
    /// known-issues.md BUG-OILS-LINENO-IN-CMDSUB for the full probe table.
    #[test]
    fn lineno_inside_command_substitution_counts_from_the_closing_paren() {
        // Single line: close line 1, rank 0.
        assert_eq!(run("x=$(echo $LINENO); echo $x").0, "1\n");
        // Two body lines, close on line 2 → 2 and 3, *not* 1 and 2.
        assert_eq!(run("y=$(echo $LINENO\necho $LINENO)\necho \"$y\"").0, "2\n3\n");
        // A blank body line carries no command, so it does not advance the rank:
        // close line 3 → 3 and 4, not 3 and 5.
        assert_eq!(
            run("q=$(echo $LINENO\n\necho $LINENO)\necho \"$q\"").0,
            "3\n4\n"
        );
        // Two commands on one body line share a rank.
        assert_eq!(
            run("r=$(echo $LINENO; echo $LINENO\necho $LINENO)\necho \"$r\"").0,
            "2\n2\n3\n"
        );
        // The opening line's empty remainder is not a body line either.
        assert_eq!(run("z=$(\necho $LINENO)\necho \"$z\"").0, "2\n");
        // A substitution nested inside one body is rebased through the outer
        // body's numbering rather than its own.
        assert_eq!(run("n=$(echo $(echo $LINENO)); echo $n").0, "1\n");
        // The enclosing script's own numbering is unaffected by the body.
        assert_eq!(
            run("echo $LINENO\nv=$(\necho $LINENO\n)\necho \"$v\"\necho $LINENO").0,
            "1\n4\n6\n"
        );
    }

    /// A backtick body numbers its lines by a *plain offset* from `close_line -
    /// 1` — unlike the rank-based renumbering above — because bash parses it as
    /// its own input at expansion time rather than folding it back into the
    /// enclosing scan. The two schemes agree only when the body is one line.
    /// Measured against bash 5.2; see known-issues.md
    /// TD-OILS-CMDSUB-ERR-FATALITY item 1.
    #[test]
    fn lineno_inside_backticks_is_a_plain_offset_from_the_closing_tick() {
        // One line: close line 1 → 1, same answer either scheme would give.
        assert_eq!(run("b=`echo $LINENO`; echo $b").0, "1\n");
        // Two body lines, close on line 2 → 2 and 3.
        assert_eq!(run("y=`echo $LINENO\necho $LINENO`\necho \"$y\"").0, "2\n3\n");
        // A blank body line *does* advance here (rank-based would say 3 and 4).
        assert_eq!(
            run("q=`echo $LINENO\n\necho $LINENO`\necho \"$q\"").0,
            "3\n5\n"
        );
        // So does the opening line's empty remainder (rank-based would say 2).
        assert_eq!(run("z=`\necho $LINENO`\necho \"$z\"").0, "3\n");
        // Two commands on one body line still share a line, of course.
        assert_eq!(
            run("r=`echo $LINENO; echo $LINENO\necho $LINENO`\necho \"$r\"").0,
            "2\n2\n3\n"
        );
    }

    #[test]
    fn special_var_underscore() {
        // `$_` is the last argument of the previous simple command.
        assert_eq!(run("echo hello world; echo $_").0, "hello world\nworld\n");
        assert_eq!(run("true a b c; echo $_").0, "c\n");
        // A single-word command leaves `$_` as that word (the command name).
        assert_eq!(run("echo solo; echo $_").0, "solo\nsolo\n");
        // Updates across commands.
        assert_eq!(run(": one; : two; echo $_").0, "two\n");
    }

    #[test]
    fn special_var_bash_command() {
        // $BASH_COMMAND holds the *unexpanded* source of the running command.
        assert_eq!(run("echo $BASH_COMMAND").0, "echo $BASH_COMMAND\n");
        // Redirections and prefix assignments are part of the reconstructed text.
        assert_eq!(run("x=1 echo $BASH_COMMAND").0, "x=1 echo $BASH_COMMAND\n");
        // An ERR trap sees the command that failed. (Trap stdout is not captured
        // by the harness, so capture BASH_COMMAND into a variable and read it
        // back after the trap has run.)
        assert_eq!(run("trap 'ERRCMD=$BASH_COMMAND' ERR\nfalse\necho \"$ERRCMD\"").0, "false\n");
    }

    #[test]
    fn special_var_dash_flags() {
        // $- reports enabled single-letter option flags; h and B are always on.
        assert_eq!(run_script("echo $-").0, "hB\n");
        // set -e adds 'e' in the fixed flag order (a e f h u x B C).
        assert_eq!(run_script("set -e; echo $-").0, "ehB\n");
        // Multiple flags appear in canonical order, not the order set.
        assert_eq!(run_script("set -xu; echo $-").0, "huxB\n");
        // Disabling drops the flag again.
        assert_eq!(run_script("set -e; set +e; echo $-").0, "hB\n");
    }

    #[test]
    fn special_var_dash_reports_interactivity() {
        // An interactive shell adds `i` (from bash's `interactive_shell`) and `H`
        // (whose default *is* `interactive_shell`), in the canonical letter order
        // `a e f h i m n u v x B C E H T`. Measured against
        // `bash --norc --noprofile -i -c 'echo $-'` on a pipe, which reports
        // `hiBHc`: no `m`, because job control cannot be enabled there — so osh
        // must not invent it either.
        assert_eq!(run("echo $-").0, "hiBH\n");
        assert_eq!(run("set -e; echo $-").0, "ehiBH\n");
        assert_eq!(run("set -u; echo $-").0, "hiuBH\n");
        // `+H` overrides the interactive default, and `-H` overrides the script
        // one, so the letter tracks the option rather than the shell.
        assert_eq!(run("set +H; echo $-").0, "hiB\n");
        assert_eq!(run_script("set -H; echo $-").0, "hBH\n");
    }

    #[test]
    fn special_var_dash_command_mode() {
        // A `-c` invocation appends `c` last (bash: `hBc`, `ehBc`, `hBCc`).
        let cmd_dash = |src: &str| {
            let mut sh = Shell::new();
            sh.set_command_mode();
            sh.set_interactive_shell(false);
            let buf = capture_sink();
            let mut out = Out::Capture(buf.clone());
            let prog = parse(src.as_bytes()).expect("parse");
            sh.exec_program(&prog, &mut out, &StdinSrc::Inherit);
            String::from_utf8(take_capture(&buf)).unwrap()
        };
        assert_eq!(cmd_dash("echo $-"), "hBc\n");
        assert_eq!(cmd_dash("set -eC; echo $-"), "ehBCc\n");
    }

    #[test]
    fn compgen_wordlist_and_prefix() {
        // `-W` splits on IFS; the trailing word prefix-filters the candidates,
        // preserving wordlist order (no sort).
        assert_eq!(run("compgen -W 'foo bar baz' ba").0, "bar\nbaz\n");
        // No trailing word: every candidate is offered.
        assert_eq!(run("compgen -W 'one two three'").0, "one\ntwo\nthree\n");
        // No match: no output, status 1.
        let (o, st) = run("compgen -W 'foo bar' xyz; echo \"st=$?\"");
        assert_eq!(o, "st=1\n");
        assert_eq!(st, 0);
    }

    /// The completion surface carries whatever bytes it was given. A wordlist,
    /// a `-P`/`-S` decoration and a `-X` filter are all ordinary shell data, so
    /// a byte that begins no valid UTF-8 sequence has to survive them intact —
    /// a candidate the shell hands back is a word the script will then act on,
    /// and an *altered* one names something else.
    #[test]
    fn compgen_carries_bytes_that_are_not_text() {
        // A candidate holding a lone high byte comes back as that byte, and the
        // trailing word prefix-filters on bytes too.
        assert_eq!(
            run_raw("compgen -W \"$(printf 'a\\xffb a\\xfeb c')\" \"$(printf 'a\\xff')\"").0,
            b"a\xffb\n"
        );
        // Splitting is per *byte*, as everywhere else IFS is used: a delimiter
        // that decodes to nothing still delimits. (IFS is set through `printf`
        // rather than `$'\xff'` because the lexer is `str`-typed until
        // TD-OILS-BYTE-STRINGS step 8, so ANSI-C quoting cannot yet carry the
        // byte — see the `$'\xa9'` row of that entry.)
        assert_eq!(
            run_raw("IFS=$(printf '\\xff'); compgen -W \"$(printf 'x\\xffy')\"").0,
            b"x\ny\n"
        );
        // -P/-S decorate with their own bytes rather than a replacement.
        assert_eq!(
            run_raw("compgen -P \"$(printf '\\xff')\" -W 'a' a").0,
            b"\xffa\n"
        );
        // A pattern with a lone high byte matches that byte and nothing else,
        // so `-X` drops exactly the one candidate holding it.
        assert_eq!(
            run_raw("compgen -W \"$(printf 'a\\xffb a\\xfeb')\" -X \"$(printf 'a\\xffb')\"").0,
            b"a\xfeb\n"
        );
    }

    /// `complete -p` must reproduce a definition byte for byte — that is the
    /// whole reason osh stores specs it never generates from. A `-W` wordlist
    /// holding a byte that is not text is still what the script wrote.
    #[test]
    fn complete_round_trips_a_wordlist_that_is_not_text() {
        assert_eq!(
            run_raw("complete -W \"$(printf 'a\\xffb')\" foo; complete -p foo").0,
            b"complete -W 'a\xffb' foo\n"
        );
    }

    #[test]
    fn compgen_command_skips_non_executables() {
        // `compgen -c` must offer only genuine executables from $PATH — never a
        // stray config file that happens to sit in a PATH directory. Build a
        // throwaway PATH dir with one executable-extension file and one `.json`.
        use std::io::Write as _;
        let dir = std::env::temp_dir().join(format!("osh_compgen_test_{}", std::process::id()));
        let _ = std::fs::create_dir_all(&dir);
        // On Windows the gate is the extension; on Unix it is the execute bit.
        #[cfg(windows)]
        let exe = dir.join("mycmd.exe");
        #[cfg(not(windows))]
        let exe = dir.join("mycmd");
        {
            let mut f = std::fs::File::create(&exe).expect("create exe");
            let _ = f.write_all(b"");
        }
        #[cfg(not(windows))]
        {
            use std::os::unix::fs::PermissionsExt;
            let _ = std::fs::set_permissions(&exe, std::fs::Permissions::from_mode(0o755));
        }
        let cfg = dir.join("mycfg.json");
        {
            let mut f = std::fs::File::create(&cfg).expect("create cfg");
            let _ = f.write_all(b"{}");
        }

        let mut sh = Shell::new();
        sh.vars.insert("PATH".to_string(), bytes::path_to_bytes(&dir));
        let cmds = sh.compgen_path_commands(b"");
        // The executable is offered by its bare name; the `.json` is not (in
        // either its raw or extension-stripped form).
        assert!(cmds.iter().any(|c| c.as_slice() == b"mycmd"), "expected mycmd in {cmds:?}");
        assert!(
            !cmds.iter().any(|c| c.as_slice() == b"mycfg" || c.as_slice() == b"mycfg.json"),
            "config file leaked into {cmds:?}"
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn path_search_skips_non_executable_files() {
        // A PATH search must resolve to a genuine executable, mirroring bash's
        // `access(X_OK)` probe: a non-executable data file sharing a command's
        // name must not be treated as that command.
        use std::io::Write as _;
        let dir = std::env::temp_dir().join(format!("osh_path_test_{}", std::process::id()));
        let _ = std::fs::create_dir_all(&dir);

        // A real executable — gated by extension on Windows, by the exec bit on
        // Unix. `find_in_path` must locate it.
        #[cfg(windows)]
        let exe = dir.join("mytool.exe");
        #[cfg(not(windows))]
        let exe = dir.join("mytool");
        {
            let mut f = std::fs::File::create(&exe).expect("create exe");
            let _ = f.write_all(b"");
        }
        #[cfg(not(windows))]
        {
            use std::os::unix::fs::PermissionsExt;
            let _ = std::fs::set_permissions(&exe, std::fs::Permissions::from_mode(0o755));
        }

        let mut sh = Shell::new();
        sh.vars.insert("PATH".to_string(), bytes::path_to_bytes(&dir));
        assert!(sh.find_in_path(b"mytool").is_some(), "executable not found in PATH");

        // A non-executable, plain-named data file. On Unix the missing exec bit
        // must make the search skip it (returning None); on Windows executability
        // is by extension, so this assertion is Unix-specific.
        #[cfg(not(windows))]
        {
            let data = dir.join("mydata");
            {
                let mut f = std::fs::File::create(&data).expect("create data");
                let _ = f.write_all(b"x");
            }
            use std::os::unix::fs::PermissionsExt;
            let _ = std::fs::set_permissions(&data, std::fs::Permissions::from_mode(0o644));
            assert!(
                sh.find_in_path("mydata").is_none(),
                "non-executable file was resolved as a command"
            );
        }

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn compgen_actions_and_decorate() {
        // Function/builtin/variable actions draw from live shell state.
        assert_eq!(run("f1(){ :; }; f2(){ :; }; compgen -A function f2").0, "f2\n");
        assert_eq!(run("compgen -b tru").0, "true\n");
        // Variables come from a hash map (unordered); sort before asserting.
        let vout = run("xy=1; xyz=2; z=3; compgen -v xy").0;
        let mut vars: Vec<&str> = vout.lines().collect();
        vars.sort_unstable();
        assert_eq!(vars, vec!["xy", "xyz"]);
        // -P prefix / -S suffix wrap each match (applied after filtering).
        assert_eq!(run("compgen -P 'p_' -S '!' -W 'a ab' a").0, "p_a!\np_ab!\n");
    }

    #[test]
    fn compgen_filter_pattern() {
        // -X removes matches; a leading '!' keeps only matches.
        assert_eq!(
            run("compgen -W 'a.txt b.log c.txt' -X '*.log'").0,
            "a.txt\nc.txt\n"
        );
        assert_eq!(run("compgen -W 'a b c' -X '!b'").0, "b\n");
    }

    #[test]
    fn compgen_double_dash_ends_options() {
        // `--` terminates options; the following argument is the word to
        // complete — even when it begins with `-`. Regression: previously `--`
        // itself was consumed as the word, so nothing prefix-matched.
        assert_eq!(run("compgen -W 'apple apricot banana' -- ap").0, "apple\napricot\n");
        assert_eq!(run("compgen -W '-a -b -c' -- -a").0, "-a\n");
        // `--` with no following word offers every candidate.
        assert_eq!(run("compgen -W 'one two' --").0, "one\ntwo\n");
    }

    #[test]
    fn compgen_answers_the_actions_that_read_shell_tables() {
        // Option names come out in the order their own builtin lists them:
        // `shopt`'s table order, `set -o`'s alphabetical one.
        assert_eq!(run("compgen -A shopt a").0, "autocd\nassoc_expand_once\n");
        assert_eq!(run("compgen -A setopt no").0, "noclobber\nnoexec\nnoglob\nnolog\nnotify\nnounset\n");
        // `enabled`/`disabled` are the two halves of the builtin table, and a
        // name moves between them as `enable -n` turns it off.
        assert_eq!(run("compgen -A disabled").0, "");
        assert_eq!(run("compgen -A enabled ech").0, "echo\n");
        assert_eq!(run("enable -n echo; compgen -A disabled").0, "echo\n");
        assert_eq!(run("enable -n echo; compgen -A enabled ech").0, "");
        // Every spec `trap` accepts: EXIT, the signals in number order under
        // their SIG names, then the pseudo-signals.
        assert_eq!(run("compgen -A signal SIGT").0, "SIGTRAP\nSIGTERM\nSIGTSTP\nSIGTTIN\nSIGTTOU\n");
        assert_eq!(run("compgen -A signal E").0, "EXIT\nERR\n");
        assert_eq!(run("compgen -A signal RET").0, "RETURN\n");
        // Help topics are the builtins and the compound-command constructs
        // together, sorted — so the punctuation ones lead.
        assert_eq!(run("compgen -A helptopic '['").0, "[\n[[ ... ]]\n");
        assert_eq!(run("compgen -A helptopic whi").0, "while\n");
    }

    #[test]
    fn compgen_answers_in_bashs_order_not_the_options_order() {
        // Actions are a set, not a sequence: each generates once, in the
        // action table's alphabetical order, whichever way round they are
        // written — and the -W wordlist comes after all of them.
        assert_eq!(run("tr1=x; compgen -v -b tr").0, "trap\ntrue\ntr1\n");
        assert_eq!(run("tr1=x; compgen -b -v tr").0, "trap\ntrue\ntr1\n");
        assert_eq!(run("compgen -b -b tr").0, "trap\ntrue\n");
        assert_eq!(run("compgen -W 'if1' -k i").0, "if\nin\nif1\n");
        // …but a repeated -W is one slot in the spec, so the last one wins.
        assert_eq!(run("compgen -W 'x y' -W 'p q'").0, "p\nq\n");
        // Reserved words keep the grammar's table order, not alphabetical.
        assert_eq!(run("compgen -k i").0, "if\nin\n");
        // Names come out sorted, however they went into the shell's tables.
        assert_eq!(run("zf(){ :;}; af(){ :;}; compgen -A function").0, "af\nzf\n");
        assert_eq!(run("zv=1; za=2; compgen -v z").0, "za\nzv\n");
        assert_eq!(run("export ZB=1 ZA=2; compgen -e Z").0, "ZA\nZB\n");
        // `arrayvar` is the array-valued subset, not every variable.
        assert_eq!(
            run("declare -a zar=(1); declare -A zmap=([k]=v); zv=1; compgen -A arrayvar z").0,
            "zar\nzmap\n"
        );
        // A command name is offered the way the shell would look it up:
        // alias, reserved word, function, builtin — and only then $PATH, so
        // only the head of the list is fixed here.
        let out = run("dofn(){ :;}; compgen -c d").0;
        assert_eq!(
            out.lines().take(6).collect::<Vec<_>>(),
            vec!["do", "done", "dofn", "declare", "dirs", "disown"]
        );
    }

    #[test]
    fn compgen_reads_its_options_the_way_bash_does() {
        // An argument-taking letter swallows the rest of its cluster, and a
        // no-argument letter can share a cluster with it.
        assert_eq!(run("compgen -Wab").0, "ab\n");
        assert_eq!(run("compgen -W'a b'").0, "a\nb\n");
        assert_eq!(run("compgen -aW 'x y'").0, "x\ny\n");
        assert_eq!(run("f1(){ :; }; compgen -Afunction f").0, "f1\n");
        // The scan stops at the first operand, so a word placed before an
        // option hides it: nothing is asked for, and nothing is reported.
        assert_eq!(run("compgen zzz -W 'a b' 2>&1"), (String::new(), 0));
        // Asking for nothing at all succeeds; asking and getting nothing is 1.
        assert_eq!(run("compgen"), (String::new(), 0));
        assert_eq!(run("compgen --"), (String::new(), 0));
        assert_eq!(run("compgen -W ''"), (String::new(), 1));
        assert_eq!(run("compgen -P ''"), (String::new(), 1));
        // `-A`/`-o` names are checked against the same tables `complete` uses.
        let (o, s) = run("compgen -A nosuch x 2>&1");
        assert_eq!((o.as_str(), s), ("osh: compgen: nosuch: invalid action name\n", 2));
        let (o, s) = run("compgen -o nosuchopt 2>&1");
        assert_eq!((o.as_str(), s), ("osh: compgen: nosuchopt: invalid option name\n", 2));
        // The check happens as the option is read, so it beats a later error
        // and beats the generation a valid option would have driven.
        let (o, s) = run("compgen -W 'a b' -A nosuch 2>&1");
        assert_eq!((o.as_str(), s), ("osh: compgen: nosuch: invalid action name\n", 2));
        // A missing option argument is a usage error, with the synopsis.
        let (o, s) = run("compgen -W 2>&1");
        assert!(o.starts_with("osh: compgen: -W: option requires an argument\n"), "got {o:?}");
        assert!(o.contains("compgen: usage: compgen [-abcdefgjksuv]"), "got {o:?}");
        assert_eq!(s, 2);
    }

    #[test]
    fn compgen_path_holds_back_only_dot_and_dotdot() {
        // Path completion treats a leading dot as an ordinary character, so a
        // hidden name is offered to an empty word like any other; `.` and `..`
        // are the only entries an empty word does not see.
        let _cwd = cwd_guard();
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("clock")
            .as_nanos();
        let dir = std::env::temp_dir().join(format!("osh_compgen_p_{}_{nanos}", std::process::id()));
        std::fs::create_dir_all(dir.join("adir")).expect("mkdir");
        std::fs::write(dir.join("a1"), b"").expect("a1");
        std::fs::write(dir.join(".ahid"), b"").expect("hidden");
        let base = dir.to_string_lossy().replace('\\', "/");
        let orig = std::env::current_dir().expect("cwd");
        // Compare as sets: the order is the directory's own, which is the
        // filesystem's business rather than the shell's.
        let g = |rest: &str| {
            let mut v: Vec<String> =
                run(&format!("cd {base}\ncompgen {rest}")).0.lines().map(str::to_string).collect();
            v.sort();
            v
        };

        assert_eq!(g("-f ''"), [".ahid", "a1", "adir"]);
        assert_eq!(g("-d ''"), ["adir"]);
        // A word that is itself a dot reaches all three dot entries.
        assert_eq!(g("-f ."), [".", "..", ".ahid"]);
        assert_eq!(g("-d ."), [".", ".."]);
        assert_eq!(g("-f .."), [".."]);
        // A word with no dot never sees them.
        assert_eq!(g("-f a"), ["a1", "adir"]);
        // The rule follows the word's directory component, not the cwd.
        assert_eq!(g("-f adir/."), ["adir/.", "adir/.."]);

        std::env::set_current_dir(&orig).expect("restore cwd");
        std::fs::remove_dir_all(&dir).ok();
    }

    #[test]
    fn compgen_o_fallbacks_stand_outside_the_compspec() {
        // `-o plusdirs`/`dirnames`/`default` are readline's own completions
        // rather than compspec sources, so the compspec's -X, -P and -S do not
        // reach them.
        let _cwd = cwd_guard();
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("clock")
            .as_nanos();
        let dir = std::env::temp_dir().join(format!("osh_compgen_o_{}_{nanos}", std::process::id()));
        std::fs::create_dir_all(dir.join("adir")).expect("mkdir");
        std::fs::create_dir_all(dir.join("bdir")).expect("mkdir");
        std::fs::write(dir.join("a1"), b"").expect("a1");
        let base = dir.to_string_lossy().replace('\\', "/");
        let orig = std::env::current_dir().expect("cwd");
        let g = |rest: &str| run(&format!("cd {base}\ncompgen {rest}"));

        // plusdirs adds directories to whatever the compspec found, after the
        // decoration and past the filter.
        assert_eq!(g("-o plusdirs -W 'aw' -P '<' -S '>' a").0, "<aw>\nadir\n");
        assert_eq!(g("-o plusdirs -W 'aw' -X 'a*' a").0, "adir\n");
        // …and it counts, so an answer it fills is not an empty one.
        assert_eq!(g("-o default -o plusdirs a").0, "adir\n");
        assert_eq!(g("-o plusdirs -W 'zz' a"), ("adir\n".to_string(), 0));
        // default and dirnames step in only for an answer that came out empty —
        // even one the filter emptied — and directories win over filenames.
        assert_eq!(g("-o default a").0, "a1\nadir\n");
        assert_eq!(g("-o dirnames a").0, "adir\n");
        assert_eq!(g("-W 'a1' -o default -X '*' a").0, "a1\nadir\n");
        assert_eq!(g("-o default -o dirnames a").0, "adir\n");
        assert_eq!(g("-o default -P '<' -S '>' a").0, "a1\nadir\n");
        // An empty word reaches the whole directory; a word nothing starts with
        // reaches nothing, and that is the ordinary empty answer.
        assert_eq!(g("-o dirnames ''").0, "adir\nbdir\n");
        assert_eq!(g("-o default -o plusdirs zz"), (String::new(), 1));
        // An -o that says nothing about candidates still asks for a compspec,
        // so it gets the empty-answer status rather than the silent success.
        assert_eq!(g("-o nosort a"), (String::new(), 1));

        std::env::set_current_dir(&orig).expect("restore cwd");
        std::fs::remove_dir_all(&dir).ok();
    }

    #[test]
    fn compgen_globpat_is_offered_whole_and_reversed() {
        // `-G` is the one source the word does not narrow: the pattern is
        // expanded as a pathname and the whole expansion is handed back, in
        // reverse. Give it a directory of its own so nothing else can match.
        let _cwd = cwd_guard();
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("clock")
            .as_nanos();
        let dir = std::env::temp_dir().join(format!("osh_compgen_g_{}_{nanos}", std::process::id()));
        std::fs::create_dir_all(dir.join("adir")).expect("mkdir");
        std::fs::write(dir.join("a1"), b"").expect("a1");
        std::fs::write(dir.join("b1"), b"").expect("b1");
        let base = dir.to_string_lossy().replace('\\', "/");
        let orig = std::env::current_dir().expect("cwd");
        let g = |rest: &str| run(&format!("cd {base}\ncompgen {rest}")).0;

        // Reverse order, and a word operand leaves the list alone.
        assert_eq!(g("-G '*1'"), "b1\na1\n");
        assert_eq!(g("-G '*1' zzz"), "b1\na1\n");
        // …but `-X` and `-P`/`-S` still apply to it.
        assert_eq!(g("-G '*1' -X 'b*'"), "a1\n");
        assert_eq!(g("-G '*1' -P '<' -S '>'"), "<b1>\n<a1>\n");
        // A second `-G` overwrites the first: it is one compspec slot.
        assert_eq!(g("-G 'a*' -G 'b*'"), "b1\n");
        // A pattern that matches nothing contributes nothing, and with no other
        // source the empty answer is status 1.
        assert_eq!(run(&format!("cd {base}\ncompgen -G 'nosuch*'")), (String::new(), 1));
        // Sources are emitted in bash's fixed order: actions, then -G, then -W.
        assert_eq!(g("-k -G 'a*' -W 'iq' i"), "if\nin\nadir\na1\niq\n");

        std::env::set_current_dir(&orig).expect("restore cwd");
        std::fs::remove_dir_all(&dir).ok();
    }

    #[test]
    fn compgen_f_runs_the_completion_function() {
        // The function is called with the command being completed, the word,
        // and the (always empty) word before it — and answers with COMPREPLY,
        // unnarrowed by the word, since choosing is the function's own job.
        let warn = "osh: compgen: warning: -F option may not work as you expect\n";
        assert_eq!(
            run("f() { COMPREPLY=(\"$1|$2|$3\" zz); }; compgen -F f wo 2>&1").0,
            format!("{warn}compgen|wo|\nzz\n")
        );
        // It runs in the current shell, so what it changes stays changed…
        assert_eq!(run("f() { x=$2; COMPREPLY=(a); }; compgen -F f q >/dev/null 2>&1; echo \"<$x>\"").0, "<q>\n");
        // …but the completion environment it reads is bound only for the call,
        // and describes an empty line, there being none.
        assert_eq!(
            run("f() { echo \"$COMP_LINE|$COMP_POINT|$COMP_TYPE|$COMP_KEY|$COMP_CWORD|${#COMP_WORDS[@]}\"; }; compgen -F f q 2>/dev/null; declare -p COMP_LINE COMP_CWORD 2>&1").0,
            "|0|0|0|-1|0\nosh: declare: COMP_LINE: not found\nosh: declare: COMP_CWORD: not found\n"
        );
        // COMPREPLY is not cleared before the call but is gone after it.
        assert_eq!(
            run("f() { :; }; COMPREPLY=(kept); compgen -F f q 2>/dev/null; declare -p COMPREPLY 2>&1").0,
            "kept\nosh: declare: COMPREPLY: not found\n"
        );
        // A scalar answers as one match (even an empty one); an associative
        // COMPREPLY answers nothing at all, as in bash.
        assert_eq!(run("f() { COMPREPLY=one; }; compgen -F f q 2>/dev/null").0, "one\n");
        assert_eq!(run("f() { COMPREPLY=; }; compgen -F f q 2>/dev/null"), ("\n".to_string(), 0));
        assert_eq!(
            run("f() { declare -A COMPREPLY=([k]=v); }; compgen -F f q 2>/dev/null"),
            (String::new(), 1)
        );
        // 124 asks for the compspec to be rebuilt; there is none, so the
        // function's matches are dropped.
        assert_eq!(
            run("f() { COMPREPLY=(a); return 124; }; compgen -F f q 2>/dev/null"),
            (String::new(), 1)
        );
        // An undefined function is reported by the completion machinery, which
        // does not name the builtin that asked.
        assert_eq!(
            run("compgen -F nosuch q 2>&1"),
            (format!("{warn}osh: completion: function `nosuch' not found\n"), 1)
        );
        // The warning waits for the whole option scan, so a usage error wins…
        assert_eq!(run("f() { :; }; compgen -F f -A bogus q 2>&1").0, "osh: compgen: bogus: invalid action name\n");
        // …and it is said once however many times `-F` was written, the last
        // one being the function that runs (one compspec slot).
        assert_eq!(
            run("f() { COMPREPLY=(ff); }; g() { COMPREPLY=(gg); }; compgen -F f -F g q 2>&1").0,
            format!("{warn}gg\n")
        );
        // Its matches sit after the actions and the wordlist, and -X/-P/-S
        // still apply to them.
        assert_eq!(
            run("f() { COMPREPLY=(iq ix); }; compgen -k -W 'iw' -F f -X 'ix' -P '<' i 2>/dev/null").0,
            "<if\n<in\n<iw\n<iq\n"
        );
    }

    #[test]
    fn compgen_c_substitutes_the_completion_command() {
        // The three completion words are appended to the command *text*, so
        // they land on whatever it ends with — and each is quoted, so a word
        // with a space stays one argument.
        let warn = "osh: compgen: warning: -C option may not work as you expect\n";
        assert_eq!(
            run("compgen -C 'printf \"[%s]\\n\"' 'a b' 2>&1").0,
            format!("{warn}[compgen]\n[a b]\n[]\n")
        );
        assert_eq!(run("compgen -C 'echo hi' x 2>/dev/null").0, "hi compgen x \n");
        // Output is split into lines with the blank ones dropped; the rest are
        // kept verbatim, and none of them is narrowed to the word.
        assert_eq!(
            run("compgen -C 'printf \"zz\\n\\n  sp  \\nqq\"' a 2>/dev/null").0,
            "zz\n  sp  \nqq\n"
        );
        // It is a subshell, so nothing it assigns survives; and its status is
        // ignored — an empty answer is what makes the status 1.
        assert_eq!(run("y=out; compgen -C 'y=in; echo z' q 2>/dev/null; echo \"<$y>\"").0, "z compgen q \n<out>\n");
        assert_eq!(run("compgen -C 'exit 3' q 2>/dev/null"), (String::new(), 1));
        // Both warnings are printed when both sources are asked for, always in
        // this order rather than the order they were written.
        assert_eq!(
            run("f() { COMPREPLY=(ff); }; compgen -C 'echo cc' -F f q 2>&1").0,
            format!(
                "osh: compgen: warning: -F option may not work as you expect\n\
                 {warn}ff\ncc compgen q \n"
            )
        );
        // A second -C overwrites the first — one compspec slot — and -X/-P
        // still apply to what the command answered.
        assert_eq!(run("compgen -C 'echo aa' -C 'echo bb' q 2>/dev/null").0, "bb compgen q \n");
        assert_eq!(
            run("compgen -C 'printf \"keep\\ndrop\\n\"' -X 'drop' -P '<' q 2>/dev/null").0,
            "<keep\n"
        );
    }

    #[test]
    fn compgen_job_actions_read_the_job_table() {
        // Newest job first, and only the first space-delimited word of each
        // job's command line — so a pipeline offers its first command and a
        // group its brace. Nothing is deduplicated.
        assert_eq!(
            run("sleep 0.4 & { sleep 0.4; } & true | sleep 0.4 & compgen -A job").0,
            "true\n{\nsleep\n"
        );
        // `-j` is the same action by its shortcut letter, and the word narrows
        // the answer as it does for every other action.
        assert_eq!(run("sleep 0.4 & true & compgen -j s").0, "sleep\n");
        assert_eq!(run("sleep 0.4 & compgen -j x"), (String::new(), 1));
        // `running` drops a job that has already finished; `job` keeps it,
        // because a job stays in the table until something sweeps it.
        assert_eq!(run("true & sleep 0.3; compgen -A job").0, "true\n");
        assert_eq!(run("true & sleep 0.3; compgen -A running"), (String::new(), 1));
        // osh has no stopped jobs, so that action never answers anything.
        assert_eq!(run("sleep 0.4 & compgen -A stopped"), (String::new(), 1));
        // With no jobs at all there is nothing to offer.
        assert_eq!(run("compgen -A job"), (String::new(), 1));
    }

    #[test]
    fn hosts_file_names_are_every_field_but_the_address() {
        let names = |src: &str| {
            let nanos = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .expect("clock")
                .as_nanos();
            let p = std::env::temp_dir()
                .join(format!("osh_hosts_{}_{nanos}.txt", std::process::id()));
            std::fs::write(&p, src).expect("write");
            let got = read_hostnames(p.to_string_lossy().replace('\\', "/").as_bytes());
            std::fs::remove_file(&p).ok();
            got.iter().map(|n| String::from_utf8_lossy(n).into_owned()).collect::<Vec<_>>()
        };
        // The first field is the address; every field after it is a name, and
        // tabs separate as well as spaces.
        assert_eq!(names("1.2.3.4 alpha alpha.example\n5.6.7.8\tbeta\n"), [
            "alpha",
            "alpha.example",
            "beta"
        ]);
        // A `#` starts a comment wherever it is: the names before it on the
        // line still count, and a line that begins with one contributes none.
        assert_eq!(names("# all comment\n1.1.1.1 a b # c d\n"), ["a", "b"]);
        // An address with no names, and a blank line, contribute nothing.
        assert_eq!(names("9.9.9.9\n\n   \n1.1.1.1 z\n"), ["z"]);
        // Nothing is deduplicated — a name is offered once per line naming it.
        assert_eq!(names("1.1.1.1 dup\n2.2.2.2 dup\n"), ["dup", "dup"]);
        // A file with no final newline still yields its last line's names.
        assert_eq!(names("1.1.1.1 tail"), ["tail"]);
        // A file that cannot be read is simply no names.
        assert!(read_hostnames(b"no/such/file/at/all").is_empty());
    }

    #[test]
    fn hostname_completion_follows_hostfile_and_is_kept_between_changes() {
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("clock")
            .as_nanos();
        let dir = std::env::temp_dir().join(format!("osh_hostfile_{}_{nanos}", std::process::id()));
        std::fs::create_dir_all(&dir).expect("mkdir");
        std::fs::write(dir.join("a"), "1.1.1.1 alpha alpha.example\n").expect("a");
        std::fs::write(dir.join("b"), "2.2.2.2 beta\n").expect("b");
        let base = dir.to_string_lossy().replace('\\', "/");

        let mut sh = Shell::new();
        run_in(&mut sh, &format!("HOSTFILE={base}/a"));
        assert_eq!(run_in(&mut sh, "compgen -A hostname").0, "alpha\nalpha.example\n");
        // The word narrows the answer, as for every other action.
        assert_eq!(run_in(&mut sh, "compgen -A hostname alpha.").0, "alpha.example\n");
        assert_eq!(run_in(&mut sh, "compgen -A hostname zz"), (String::new(), 1));

        // Naming a different file *adds* to what is already offered…
        run_in(&mut sh, &format!("HOSTFILE={base}/b"));
        assert_eq!(run_in(&mut sh, "compgen -A hostname").0, "alpha\nalpha.example\nbeta\n");
        // …while unsetting the variable throws the list away, so the next file
        // named starts from nothing.
        run_in(&mut sh, "unset HOSTFILE");
        run_in(&mut sh, &format!("HOSTFILE={base}/a"));
        assert_eq!(run_in(&mut sh, "compgen -A hostname").0, "alpha\nalpha.example\n");

        // A file that cannot be read adds nothing and is not an error: the list
        // already there still answers.
        run_in(&mut sh, &format!("HOSTFILE={base}/nosuch"));
        assert_eq!(run_in(&mut sh, "compgen -A hostname").0, "alpha\nalpha.example\n");
        // With the list cleared and no readable file, there is nothing to
        // offer — `compgen`'s ordinary empty answer, not a diagnostic.
        run_in(&mut sh, "unset HOSTFILE");
        run_in(&mut sh, &format!("HOSTFILE={base}/nosuch"));
        assert_eq!(run_in(&mut sh, "compgen -A hostname 2>&1"), (String::new(), 1));

        std::fs::remove_dir_all(&dir).ok();
    }

    #[test]
    fn service_file_names_are_the_first_field_only() {
        let names = |src: &str| {
            let nanos = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .expect("clock")
                .as_nanos();
            let p =
                std::env::temp_dir().join(format!("osh_svcs_{}_{nanos}.txt", std::process::id()));
            std::fs::write(&p, src).expect("write");
            let got = read_service_names(p.to_string_lossy().replace('\\', "/").as_bytes());
            std::fs::remove_file(&p).ok();
            got.iter().map(|n| String::from_utf8_lossy(n).into_owned()).collect::<Vec<_>>()
        };
        // The name is the first field; the port/protocol and every alias after
        // it are skipped, and tabs separate as well as spaces.
        assert_eq!(names("echo\t7/tcp\ndiscard 9/tcp sink null\n"), ["echo", "discard"]);
        // A `#` starts a comment wherever it is: a trailing one leaves the name
        // alone, and a line that begins with one contributes nothing.
        assert_eq!(names("# a header\nsystat 11/tcp users  #Active users\n"), ["systat"]);
        // Blank and whitespace-only lines contribute nothing.
        assert_eq!(names("\n   \nftp 21/tcp\n"), ["ftp"]);
        // Nothing is deduplicated — a service with a tcp and a udp line is two
        // entries, so it is offered twice (bash's `compgen -s` does the same).
        assert_eq!(names("echo 7/tcp\necho 7/udp\n"), ["echo", "echo"]);
        // A file with no final newline still yields its last line's name.
        assert_eq!(names("tail 99/tcp"), ["tail"]);
        // A file that cannot be read is simply no names.
        assert!(read_service_names(b"no/such/file/at/all").is_empty());
    }

    /// Write `src` to a fresh temp file, hand its path to `f`, then remove it.
    fn with_temp_file<T>(tag: &str, src: &str, f: impl FnOnce(&[u8]) -> T) -> T {
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("clock")
            .as_nanos();
        let p =
            std::env::temp_dir().join(format!("osh_{tag}_{}_{nanos}.txt", std::process::id()));
        std::fs::write(&p, src).expect("write");
        let got = f(p.to_string_lossy().replace('\\', "/").as_bytes());
        std::fs::remove_file(&p).ok();
        got
    }

    #[test]
    fn passwd_and_group_names_are_the_first_colon_field() {
        let names = |src: &str| {
            with_temp_file("pw", src, |p| {
                read_colon_table_names(p)
                    .iter()
                    .map(|n| String::from_utf8_lossy(n).into_owned())
                    .collect::<Vec<_>>()
            })
        };
        // A passwd record's name is everything before the first colon.
        assert_eq!(names("root:x:0:0:root:/root:/bin/sh\namy:x:1000:1000::/home/amy:/bin/sh\n"), [
            "root", "amy"
        ]);
        // A group record has fewer fields but the same first one.
        assert_eq!(names("wheel:x:10:amy,bo\nusers:x:100:\n"), ["wheel", "users"]);
        // Blank lines, and lines whose first non-blank byte is `#`, are skipped
        // — that is glibc's whole comment rule for these files.
        assert_eq!(names("\n   \n# a comment\n\t# an indented one\nroot:x:0:0::/:/sh\n"), ["root"]);
        // A `#` anywhere else is data: it is part of a GECOS field, not the
        // start of a comment, so the record still counts.
        assert_eq!(names("bo:x:1:1:B #1:/home/bo:/bin/sh\n"), ["bo"]);
        // Leading blanks are skipped rather than made part of the name.
        assert_eq!(names("  amy:x:1:1::/home/amy:/bin/sh\n"), ["amy"]);
        // A record with no colon does not parse, and an empty name is no name.
        assert_eq!(names("nonsense\n:x:0:0::/:/sh\namy:x:1:1::/:/sh\n"), ["amy"]);
        // Nothing is deduplicated, and a file with no final newline still
        // yields its last record.
        assert_eq!(names("a:x:1:1::/:/sh\na:x:2:2::/:/sh"), ["a", "a"]);
        // A file that cannot be read is simply no names.
        assert!(read_colon_table_names(b"no/such/file/at/all").is_empty());
    }

    #[test]
    fn a_tilde_prefix_names_a_user_whose_home_comes_from_the_passwd_file() {
        let home = |user: &str| {
            with_temp_file(
                "pwhome",
                "# a comment\nroot:x:0:0:root:/root:/bin/sh\n\
                 amy:x:1000:1000:Amy #1:/home/amy:/bin/sh\n\
                 amy:x:1001:1001::/home/other:/bin/sh\n\
                 nohome:x:1:1:::/bin/sh\n\
                 short:x:1:1\n",
                |p| {
                    read_passwd_home(p, user.as_bytes())
                        .map(|h| String::from_utf8_lossy(&h).into_owned())
                },
            )
        };
        // Field 5 is the home directory — past the password, uid, gid and a
        // GECOS field that may itself contain a `#`.
        assert_eq!(home("root").as_deref(), Some("/root"));
        // The first matching record wins, as it does for `getpwnam`, so the
        // second `amy` never answers.
        assert_eq!(home("amy").as_deref(), Some("/home/amy"));
        assert_eq!(home("nosuch"), None);
        // An *empty* home field is still an answer — `getpwnam` succeeds and
        // hands back an empty `pw_dir`, so `~nohome/x` expands to `/x`.
        assert_eq!(home("nohome").as_deref(), Some(""));
        // A record with too few fields does not parse at all, so it does not
        // match and the tilde is left alone.
        assert_eq!(home("short"), None);
        // A comment line is not a user, even one whose text looks like a name.
        assert_eq!(home("# a comment"), None);
        // No database at all is simply no answer.
        assert_eq!(read_passwd_home(b"no/such/file/at/all", b"root"), None);
    }

    /// `$GROUPS` is built the way `initgroups(3)` builds a credential: the
    /// passwd record with the reported UID names the user and its primary
    /// group, and the group file supplies the rest. See [`reported_groups`].
    #[test]
    fn groups_come_from_the_passwd_and_group_files() {
        let pw = |uid: u32| {
            with_temp_file(
                "gpw",
                "# a comment\nroot:x:0:0:root:/root:/bin/sh\n\
                 amy:x:1000:100:Amy:/home/amy:/bin/sh\n\
                 dup:x:1000:101::/home/dup:/bin/sh\n\
                 bad:x:x7:1::/home/bad:/bin/sh\n\
                 nogid:x:7\n",
                |p| {
                    passwd_record_for_uid(p, uid)
                        .map(|(n, g)| (String::from_utf8_lossy(&n).into_owned(), g))
                },
            )
        };
        assert_eq!(pw(0), Some(("root".to_string(), 0)));
        // The first record with the UID wins, as it does for `getpwuid`.
        assert_eq!(pw(1000), Some(("amy".to_string(), 100)));
        // A UID field that is not a number does not parse, so the record
        // matches nothing rather than being mistaken for some other user.
        assert_eq!(pw(7), None);
        assert_eq!(pw(4242), None);
        // No database at all is no answer — which is the Windows host, where
        // `reported_groups` therefore falls back to group 0.
        assert_eq!(passwd_record_for_uid(b"no/such/file/at/all", 0), None);

        let member = |user: &str| {
            with_temp_file(
                "ggrp",
                "# a comment\nroot:x:0:\n\
                 wheel:x:10:amy,bo\n\
                 staff:x:20:bo\n\
                 devs:x:30:amy\n\
                 badgid:x:xx:amy\n\
                 nomembers:x:40\n",
                |p| group_ids_for_member(p, user.as_bytes()),
            )
        };
        // File order, and only the groups that actually list the name — a
        // substring of a member name (`am` in `amy`) is not a member.
        assert_eq!(member("amy"), [10, 30]);
        assert_eq!(member("bo"), [10, 20]);
        assert_eq!(member("am"), [] as [u32; 0]);
        assert_eq!(member("nosuch"), [] as [u32; 0]);
        // An empty member field matches nobody, and neither does an empty name.
        assert_eq!(member(""), [] as [u32; 0]);
        assert!(group_ids_for_member(b"no/such/file/at/all", b"amy").is_empty());
    }

    /// The six variables the shell maintains refuse assignment *silently*, in
    /// two shapes that differ only in status — and a failed one abandons the
    /// rest of the parse unit, exactly as a readonly rejection does. See
    /// [`Shell::noassign`]; the whole family is exercised against bash by the
    /// `noassign-vars` corpus case.
    #[test]
    fn the_variables_the_shell_maintains_refuse_assignment() {
        // Scalar: not performed, no diagnostic, and the command succeeds.
        assert_eq!(run("GROUPS=5; echo $?").0, "0\n");
        assert_eq!(run("GROUPS[0]=5; echo $?").0, "0\n");
        assert_eq!(run("GROUPS+=x; echo $?").0, "0\n");
        assert_eq!(run("f() { echo ${FUNCNAME[0]}; }; FUNCNAME=z; f").0, "f\n");
        // Array literal: not performed either, but it fails — and the failure
        // discards the rest of the parse unit, so the `echo` never runs.
        for name in NOASSIGN_VARS {
            let (out, st) = run(&format!("{name}=(1 2); echo reached"));
            assert_eq!((out.as_str(), st), ("", 1), "{name}=(1 2)");
            assert_eq!(run(&format!("{name}+=(1); echo reached")).0, "", "{name}+=(1)");
        }
        // A *following line* is a separate parse unit and still runs, which is
        // what makes this a discard rather than an exit.
        assert_eq!(run("GROUPS=(1)\necho after=$?").0, "after=1\n");
        // Writing through the name from elsewhere fails, silently, with the
        // status as the only sign: `read`, and a `for` loop's control variable
        // (which gives up the loop on its first iteration, so an empty list is
        // still a success).
        assert_eq!(run("read FUNCNAME <<<hi; echo $?").0, "1\n");
        assert_eq!(run("for FUNCNAME in a b; do echo body; done; echo $?").0, "1\n");
        assert_eq!(run("for FUNCNAME in; do echo body; done; echo $?").0, "0\n");
        // `unset` sheds the attribute along with the rest, leaving an ordinary
        // name — for the two of the six that can be unset at all.
        assert_eq!(run("unset FUNCNAME; FUNCNAME=(1 2); echo \"${FUNCNAME[*]}\"").0, "1 2\n");
        assert_eq!(run("unset GROUPS; GROUPS=9; echo $GROUPS").0, "9\n");
        for name in NOUNSET_VARS {
            let (out, _) = run(&format!("unset {name} 2>&1; echo $?"));
            assert!(
                out.contains(&format!("unset: {name}: cannot unset\n")) && out.ends_with("1\n"),
                "unset {name}: {out:?}"
            );
        }
    }

    /// Every *builtin* write path refuses them too, and just as silently: the
    /// status is the only sign, and — unlike the array-literal assignment — the
    /// rest of the parse unit still runs.
    #[test]
    fn the_builtin_write_paths_refuse_the_variables_the_shell_maintains() {
        for script in [
            "printf -v GROUPS x",
            "printf -v 'GROUPS[0]' x",
            "printf -v FUNCNAME x",
            "mapfile GROUPS <<<hi",
            "mapfile -t BASH_SOURCE <<<hi",
            "read -a GROUPS <<<hi",
        ] {
            let (out, _) = run(&format!("{script} 2>&1; echo \"rc=$?\"; echo after"));
            assert_eq!(out, "rc=1\nafter\n", "{script}");
        }
        // Arithmetic refuses it as an *error* would: the expression is abandoned
        // where it stands, so `(( ))`/`let` report 1 …
        for expr in ["(( GROUPS = 5 ))", "(( GROUPS[0] = 5 ))", "(( GROUPS++ ))", "let GROUPS=7"] {
            let (out, _) = run(&format!("{expr} 2>&1; echo \"rc=$?\"; echo after"));
            assert_eq!(out, "rc=1\nafter\n", "{expr}");
        }
        // … an assignment earlier in a comma list stands and a later one never
        // happens …
        assert_eq!(run("x=9; (( x = 3, GROUPS = 5 )); echo \"$? $x\"").0, "1 3\n");
        assert_eq!(run("x=9; (( GROUPS = 5, x = 3 )); echo \"$? $x\"").0, "1 9\n");
        // … and in expansion position it is fatal to the command list.
        assert_eq!(run("echo \"[$(( GROUPS = 5 ))]\"; echo unreachable"), (String::new(), 1));
        // Shedding the attribute makes every one of them ordinary again.
        assert_eq!(run("unset GROUPS; printf -v GROUPS x; echo \"$? $GROUPS\"").0, "0 x\n");
        assert_eq!(run("unset GROUPS; (( GROUPS = 5 )); echo \"$? $GROUPS\"").0, "0 5\n");
    }

    /// A declaration builtin refuses them by *where the binding would land*: a
    /// global one silently, a local one with a diagnostic tagged by the builtin.
    #[test]
    fn a_declaration_builtin_refuses_the_variables_the_shell_maintains() {
        // Global scope: the value is dropped, and `declare` applies none of its
        // attributes either — the operand is abandoned whole — while `export` and
        // `readonly` apply theirs and report success.
        assert_eq!(run("declare GROUPS=5; echo $?").0, "1\n");
        // The value is not printed anywhere: it is the host's, so only the
        // rendered *attributes* are host-independent enough to assert on.
        let attrs = |script: &str| {
            let (out, _) = run(script);
            out.split_once("GROUPS").map(|(a, _)| a.to_string()).unwrap_or(out)
        };
        assert_eq!(attrs("declare -x GROUPS=5; declare -p GROUPS"), "declare -a ");
        assert_eq!(attrs("export GROUPS=5; echo $?; declare -p GROUPS"), "0\ndeclare -ax ");
        assert_eq!(attrs("readonly GROUPS=5; echo $?; declare -p GROUPS"), "0\ndeclare -ar ");
        // A valueless declaration asks for no assignment, so nothing is refused.
        assert_eq!(run("declare GROUPS; echo $?").0, "0\n");
        assert_eq!(attrs("declare -u GROUPS; declare -p GROUPS"), "declare -au ");
        // Only this operand is skipped; the ones after it still bind.
        assert_eq!(run("declare GROUPS=5 z=9; declare -p z").0, "declare -- z=\"9\"\n");
        // A *local* one says so, tagged with the builtin — even with no value,
        // because binding a local of the name is itself the refused assignment.
        for (script, tag) in [
            ("f() { local GROUPS=5; echo $?; }; f", "local"),
            ("f() { local GROUPS; echo $?; }; f", "local"),
            ("f() { local GROUPS[0]=5; echo $?; }; f", "local"),
            ("f() { declare GROUPS; echo $?; }; f", "declare"),
            ("f() { typeset GROUPS=5; echo $?; }; f", "typeset"),
        ] {
            let (out, _) = run(&format!("{{ {script} ; }} 2>&1"));
            let want = format!("{tag}: GROUPS: variable may not be assigned value\n1\n");
            assert!(out.ends_with(&want), "{script}: {out:?}");
        }
        // `-g` and `export` name the global, so they take the global refusal.
        assert_eq!(run("f() { declare -g GROUPS=5; echo $?; }; f 2>&1").0, "1\n");
        assert_eq!(run("f() { export GROUPS=5; echo $?; }; f 2>&1").0, "0\n");
        // A compound literal splits the same way — and the local half is reported
        // *twice*: by the compound-assignment machinery, which inside a function
        // tags its diagnostics with the function's name, and by the builtin.
        let (out, _) = run("zebra() { declare GROUPS=(1 2) after=(9); declare -p after; }; zebra 2>&1");
        assert!(
            out.contains("zebra: GROUPS: variable may not be assigned value\n")
                && out.contains("declare: GROUPS: variable may not be assigned value\n")
                && out.ends_with("declare -a after=([0]=\"9\")\n"),
            "{out:?}"
        );
        assert_eq!(run("f() { declare -g GROUPS=(1 2); echo $?; }; f 2>&1").0, "0\n");
        // At top level a compound is not special-cased: it takes the same silent
        // parse-unit discard a bare `GROUPS=(1 2)` does, so `after` never binds.
        assert_eq!(run("declare GROUPS=(1 2) after=(9); declare -p after").0, "");
    }

    /// A readonly target refuses `export NAME=value`'s *store*, but the export
    /// attribute is applied anyway — bash marks the name before it tries the
    /// value. `declare -x` is not the same thing, and `-a`/`-A` changes only
    /// which diagnostic comes out.
    #[test]
    fn a_refused_export_still_exports() {
        for script in ["export q=2", "export q+=2", "export -a q=2", "export -p q=2"] {
            let (out, _) = run(&format!("readonly q=1; {script}; echo \"rc=$?\"; declare -p q"));
            assert_eq!(out, "rc=1\ndeclare -rx q=\"1\"\n", "{script}");
        }
        // …and `-n` takes it off by the same route.
        assert_eq!(
            run("q=1; export q; readonly q; export -n q=2; echo \"rc=$?\"; declare -p q").0,
            "rc=1\ndeclare -r q=\"1\"\n"
        );
        // `-a`/`-A` tag the diagnostic with the builtin's name; nothing else does.
        for (flag, want) in [
            ("", "q: readonly variable\n"),
            ("-n", "q: readonly variable\n"),
            ("-p", "q: readonly variable\n"),
            ("--", "q: readonly variable\n"),
            ("-a", "export: q: readonly variable\n"),
            ("-A", "export: q: readonly variable\n"),
            ("-na", "export: q: readonly variable\n"),
        ] {
            let (out, _) = run(&format!("readonly q=1; {{ export {flag} q=2; }} 2>&1"));
            assert!(out.ends_with(want), "export {flag}: {out:?}");
        }
        for (flag, want) in [
            ("", "q: readonly variable\n"),
            ("-p", "q: readonly variable\n"),
            ("--", "q: readonly variable\n"),
            ("-a", "readonly: q: readonly variable\n"),
            ("-A", "readonly: q: readonly variable\n"),
        ] {
            let (out, _) = run(&format!("readonly q=1; {{ readonly {flag} q=2; }} 2>&1"));
            assert!(out.ends_with(want), "readonly {flag}: {out:?}");
        }
        // `declare -x` names itself and applies nothing.
        assert_eq!(
            run("readonly q=1; declare -x q=2; echo \"rc=$?\"; declare -p q").0,
            "rc=1\ndeclare -r q=\"1\"\n"
        );
    }

    /// `export`/`readonly` bind at the global scope wherever they are invoked —
    /// for an array literal as much as for a scalar. It is the builtin's *name*
    /// that decides and not the attribute, so `declare -x`/`local -x` still make
    /// locals.
    #[test]
    fn an_exported_array_literal_declared_in_a_function_is_global() {
        assert_eq!(
            run("f() { export q=(1 2); }; f; declare -p q").0,
            "declare -ax q=([0]=\"1\" [1]=\"2\")\n"
        );
        assert_eq!(
            run("f() { readonly q=(1 2); }; f; declare -p q").0,
            "declare -ar q=([0]=\"1\" [1]=\"2\")\n"
        );
        for script in ["declare -x", "declare -r", "local -x"] {
            let (out, _) = run(&format!("f() {{ {script} q=(1 2); }}; f; declare -p q 2>/dev/null"));
            assert_eq!(out, "", "{script}");
        }
    }

    /// The `OSH_GROUPS` override, the counterpart of `OSH_UID`/`OSH_EUID`.
    #[test]
    fn the_group_override_list_takes_numbers_in_order_without_repeats() {
        assert_eq!(parse_group_list(b"10 20 30"), [10, 20, 30]);
        // Commas as well as blanks, because both spellings look natural.
        assert_eq!(parse_group_list(b"10,20,30"), [10, 20, 30]);
        assert_eq!(parse_group_list(b" 10, ,20\t30\n"), [10, 20, 30]);
        // `getgroups` never reports an ID twice, so a repeat is dropped rather
        // than duplicated into the array.
        assert_eq!(parse_group_list(b"10 20 10"), [10, 20]);
        // Anything that is not a plain non-negative number is not an ID.
        assert_eq!(parse_group_list(b"10 x -1 0x20 1.5 40"), [10, 40]);
        assert_eq!(parse_group_list(b""), [] as [u32; 0]);
        assert_eq!(parse_group_list(b"  ,, "), [] as [u32; 0]);
    }

    /// bash always has `$GROUPS` bound as a non-empty indexed array of numeric
    /// IDs. The *values* depend on the host identity, so only that contract is
    /// asserted here; the sources are tested above.
    #[test]
    fn groups_is_a_bound_non_empty_array_of_ids() {
        assert_eq!(run("echo ${GROUPS+set}").0, "set\n");
        let (out, _) = run(r#"echo "${#GROUPS[@]}"; printf '%s\n' "${GROUPS[@]}""#);
        let mut lines = out.lines();
        let n: usize = lines.next().expect("count").parse().expect("numeric count");
        assert!(n >= 1, "GROUPS must have at least one element: {out:?}");
        let ids: Vec<&str> = lines.collect();
        assert_eq!(ids.len(), n, "element count disagrees with ${{#GROUPS[@]}}");
        for id in ids {
            assert!(
                !id.is_empty() && id.bytes().all(|b| b.is_ascii_digit()),
                "not a group ID: {id:?}"
            );
        }
        // An indexed array, as `declare -a` — not a scalar, and not readonly:
        // bash lets the name be `unset`, after which it is an ordinary name.
        assert!(run("declare -p GROUPS").0.starts_with("declare -a GROUPS="));
        assert_eq!(run("unset GROUPS; echo ${GROUPS+set}-${GROUPS[@]+set}").0, "-\n");
    }

    #[test]
    fn complete_register_and_print() {
        // A registered spec round-trips through `complete -p NAME` verbatim.
        assert_eq!(run("complete -W 'x y z' foo; complete -p foo").0, "complete -W 'x y z' foo\n");
        // `-F` function name is printed unquoted; other values are single-quoted.
        assert_eq!(
            run("complete -F _f -o bashdefault prog; complete -p prog").0,
            "complete -o bashdefault -F _f prog\n"
        );
        // Redefinition replaces the previous spec (keeps its slot).
        assert_eq!(run("complete -W a c; complete -W b c; complete -p c").0, "complete -W 'b' c\n");
        // A bare name stores an empty spec.
        assert_eq!(run("complete cmd; complete -p cmd").0, "complete cmd\n");
    }

    #[test]
    fn complete_canonical_option_order() {
        // Options are emitted in bash's fixed print order regardless of input
        // order: -o opts, shortcut actions, -A actions, then -G -W -P -S -X -C -F.
        let src = "complete -o nospace -o bashdefault -A function -S SUF -P PRE \
                   -X '*.x' -W 'w1 w2' -G '*.g' -C mycmd -F myf cmd; complete -p cmd";
        assert_eq!(
            run(src).0,
            "complete -o bashdefault -o nospace -A function -G '*.g' -W 'w1 w2' \
             -P 'PRE' -S 'SUF' -X '*.x' -C 'mycmd' -F myf cmd\n"
        );
        // Shortcut actions print before -A-only actions; each group in table order.
        assert_eq!(
            run("complete -A signal -v -a cmd; complete -p cmd").0,
            "complete -a -v -A signal cmd\n"
        );
        // Clustered shortcut flags expand in canonical order.
        assert_eq!(
            run("complete -abcdefgjksuv cmd; complete -p cmd").0,
            "complete -a -b -c -d -e -f -g -j -k -s -u -v cmd\n"
        );
    }

    #[test]
    fn complete_quotes_embedded_single_quotes() {
        // Values are single-quoted with the POSIX `'\''` escape for embedded quotes.
        assert_eq!(
            run("complete -W \"a 'b' c\" cmd; complete -p cmd").0,
            "complete -W 'a '\\''b'\\'' c' cmd\n"
        );
    }

    #[test]
    fn complete_remove_and_special_targets() {
        // `-r NAME` removes just that spec; `-r` with no args clears all.
        assert_eq!(run("complete -W a x; complete -r x; complete -p x; echo rc=$?").0, "rc=1\n");
        assert_eq!(run("complete -W a x; complete -W b y; complete -r; complete -p").0, "");
        // `-D`/`-E`/`-I` store the special default/empty/initial specs.
        assert_eq!(run("complete -F _d -D; complete -pD").0, "complete -F _d -D\n");
        // With -D present, command names are ignored.
        assert_eq!(run("complete -D -W x -F _f name; complete -p").0, "complete -W 'x' -F _f -D\n");
    }

    #[test]
    fn complete_error_status_codes() {
        // `-p` on an unknown spec is status 1 (message goes to stderr).
        assert_eq!(run("complete -p nope; echo rc=$?").0, "rc=1\n");
        // Invalid option / option name / action name are usage errors (status 2).
        assert_eq!(run("complete -Z cmd; echo rc=$?").0, "rc=2\n");
        assert_eq!(run("complete -o badopt cmd; echo rc=$?").0, "rc=2\n");
        assert_eq!(run("complete -A badaction cmd; echo rc=$?").0, "rc=2\n");
        // Defining options with no name/target is a usage error.
        assert_eq!(run("complete -o nospace; echo rc=$?").0, "rc=2\n");
        // A missing required argument is a usage error.
        assert_eq!(run("complete -F; echo rc=$?").0, "rc=2\n");
        // Bare `complete` and `complete -r nope` succeed.
        assert_eq!(run("complete; echo rc=$?").0, "rc=0\n");
        assert_eq!(run("complete -r nope; echo rc=$?").0, "rc=0\n");
    }

    #[test]
    fn compopt_modifies_options() {
        // `-o` adds an option, `+o` removes it, both preserving canonical order.
        assert_eq!(
            run("complete -W a cmd; compopt -o nospace -o plusdirs cmd; complete -p cmd").0,
            "complete -o nospace -o plusdirs -W 'a' cmd\n"
        );
        assert_eq!(
            run("complete -o nospace -o dirnames -W a cmd; compopt +o nospace cmd; complete -p cmd").0,
            "complete -o dirnames -W 'a' cmd\n"
        );
        // A nameless compopt (no completion function running) is status 1.
        assert_eq!(run("compopt -o nospace; echo rc=$?").0, "rc=1\n");
        // compopt on an unknown spec is status 1.
        assert_eq!(run("compopt -o nospace nope; echo rc=$?").0, "rc=1\n");
        // An invalid compopt option is a usage error (status 2).
        assert_eq!(run("compopt -Z; echo rc=$?").0, "rc=2\n");
    }

    #[test]
    fn complete_is_a_builtin() {
        // Both builtins are recognised by `type -t` and `compgen -b`.
        assert_eq!(run("type -t complete").0, "builtin\n");
        assert_eq!(run("type -t compopt").0, "builtin\n");
        assert_eq!(run("compgen -b complete").0, "complete\n");
    }

    #[test]
    fn shopt_full_inventory_listing() {
        // The bare listing reports every option in bash's table order with the
        // `NAME<pad-to-15>\ton|off` status form. Spot-check a few known entries.
        let out = run("shopt").0;
        assert!(out.contains("autocd         \toff\n"), "got: {out}");
        assert!(out.contains("interactive_comments\ton\n"), "got: {out}");
        assert!(out.contains("progcomp       \ton\n"), "got: {out}");
        // The test harness leaves neither command nor script mode set, so it
        // behaves interactively — `expand_aliases` defaults on.
        assert!(out.contains("expand_aliases \ton\n"), "got: {out}");
    }

    #[test]
    fn shopt_p_reinput_form() {
        // `-p` prints re-inputtable `shopt -s/-u NAME` lines.
        let out = run("shopt -p progcomp autocd").0;
        assert_eq!(out, "shopt -s progcomp\nshopt -u autocd\n");
    }

    #[test]
    fn shopt_s_filters_to_enabled() {
        // `shopt -s` with no names lists only currently-enabled options.
        let out = run("shopt -s").0;
        assert!(out.contains("progcomp       \ton\n"), "got: {out}");
        assert!(!out.contains("autocd"), "got: {out}");
    }

    #[test]
    fn shopt_refuses_both_verbs_at_once() {
        // `-s` and `-u` ask for opposite things, so the call is refused outright
        // — with a plain sentence rather than the usage line an unknown flag
        // gets, and without falling back to the listing.
        let (out, st) = run("shopt -su nocaseglob 2>&1");
        assert_eq!(out, "osh: shopt: cannot set and unset shell options simultaneously\n");
        assert_eq!(st, 1);
        assert_eq!(run("shopt -su nocaseglob 2>/dev/null; shopt nocaseglob").0, "nocaseglob     \toff\n");
        // An unknown flag is the earlier complaint of the two.
        assert_eq!(run("shopt -zsu 2>/dev/null").1, 2);
    }

    #[test]
    fn shopt_query_steps_over_an_unknown_name() {
        // Every name gets its answer; the unknown one only costs the status.
        let (out, st) = run("shopt nocaseglob bogus 2>/dev/null");
        assert_eq!(out, "nocaseglob     \toff\n");
        assert_eq!(st, 1);
        // …even when every name it *could* answer for is on, so the failure is
        // the name and not the state.
        assert_eq!(run("shopt -s nocaseglob; shopt bogus nocaseglob 2>/dev/null").1, 1);
    }

    #[test]
    fn shopt_o_renders_the_reinput_form_as_a_set_command() {
        // Under `-o` the option belongs to `set`, so the command that would
        // restore it is a `set` one — where the plain status form is shared.
        assert_eq!(run("shopt -o -p xtrace nounset").0, "set +o xtrace\nset +o nounset\n");
        assert_eq!(run("set -o pipefail; shopt -o -p pipefail").0, "set -o pipefail\n");
        assert_eq!(run("shopt -o xtrace").0, "xtrace         \toff\n");
    }

    #[test]
    fn shopt_o_forgives_an_unknown_name_when_setting() {
        // bash hands each name to the same code `set -o` uses and does not pass
        // on its verdict: the complaint is made and the call still succeeds.
        let (out, st) = run("shopt -o -s bogus 2>&1");
        assert_eq!(out, "osh: shopt: bogus: invalid option name\n");
        assert_eq!(st, 0);
        assert_eq!(run("shopt -o -u bogus 2>/dev/null").1, 0);
        // Setting *without* `-o` is the strict path, and asking is strict either
        // way — the unknown name fails those.
        assert_eq!(run("shopt -s bogus 2>/dev/null").1, 1);
        assert_eq!(run("shopt -o bogus 2>/dev/null").1, 1);
    }

    #[test]
    fn shopt_read_only_options_are_reported_but_never_changed() {
        // `login_shell` says how the shell was started, so there is nothing for
        // a script to decide: the verb is accepted and does nothing, which is
        // not the failure an unknown name would give.
        assert_eq!(run("shopt -s login_shell 2>&1"), (String::new(), 0));
        assert_eq!(run("shopt -s login_shell; shopt login_shell").0, "login_shell    \toff\n");
        assert_eq!(run("shopt -s restricted_shell; shopt restricted_shell").0, "restricted_shell\toff\n");
        // …and nothing reaches $BASHOPTS either.
        assert!(!run("shopt -s login_shell; echo $BASHOPTS").0.contains("login_shell"));
    }

    /// The `-l`/`--login` side of `login_shell`, which only the binary can set —
    /// so this drives [`Shell::set_login_shell`] directly rather than through
    /// [`run`]. Everything a script can *observe* about it is pinned against
    /// bash in `tests/corpus/logout.sh`, which reaches a login shell by
    /// re-invoking `$BASH -l`; this covers the in-process half.
    #[test]
    fn a_login_shell_reports_itself_and_lets_logout_work() {
        let out = |sh: &mut Shell, src: &str| -> (String, i32) {
            let buf = capture_sink();
            let status = {
                let mut o = Out::Capture(buf.clone());
                sh.run_source_out(src.as_bytes(), &mut o, 0)
            };
            (String::from_utf8_lossy(&take_capture(&buf)).into_owned(), status)
        };

        let mut sh = Shell::new();
        sh.set_login_shell();
        assert_eq!(out(&mut sh, "shopt login_shell"), ("login_shell    \ton\n".to_string(), 0));
        assert_eq!(out(&mut sh, "shopt -p login_shell").0, "shopt -s login_shell\n");
        assert!(out(&mut sh, "echo $BASHOPTS").0.contains("login_shell"));
        // Still read-only: `shopt -u` is accepted and does nothing, exactly as
        // `shopt -s` is on a shell that was not started as a login shell.
        assert_eq!(out(&mut sh, "shopt -u login_shell; shopt login_shell").0, "login_shell    \ton\n");
        // And `logout` is now `exit` — the refusal is gone, and the status is
        // the operand's.
        let mut sh = Shell::new();
        sh.set_login_shell();
        assert_eq!(out(&mut sh, "logout 7; echo not-reached").1, 7);
        let mut sh = Shell::new();
        sh.set_login_shell();
        assert_eq!(out(&mut sh, "logout 7; echo not-reached").0, "");
    }

    #[test]
    fn logout_outside_a_login_shell_refuses_before_reading_its_operand() {
        // The gate comes first, so a bad operand is never even looked at: all
        // three of these are the same one-line refusal with status 1, and none
        // of them ends the shell.
        for src in ["logout", "logout abc", "logout 3 4"] {
            let (o, st) = run(&format!("{src} 2>&1; echo \"rc=$?\"; echo alive"));
            assert_eq!(o, "osh: logout: not login shell: use `exit'\nrc=1\nalive\n", "{src}");
            assert_eq!(st, 0, "{src}");
        }
    }

    #[test]
    fn a_second_status_operand_discards_the_unit_instead_of_exiting() {
        // bash's `no_args`: "too many arguments", then `top_level_cleanup()` +
        // `jump_to_top_level(DISCARD)`. Not an exit — the rest of the current
        // top-level unit goes, the next one runs, and the status is 1.
        for name in ["exit", "return"] {
            let (o, st) = run(&format!("{name} 3 4 2>&1; echo same-unit\necho next-unit rc=$?\n"));
            assert_eq!(o, format!("osh: {name}: too many arguments\nnext-unit rc=1\n"), "{name}");
            assert_eq!(st, 0, "{name}");
        }
        // The `--` form is stripped first, so the second operand is still found.
        assert_eq!(
            run("exit -- 3 4 2>&1\necho after\n").0,
            "osh: exit: too many arguments\nafter\n"
        );
        // Because of the cleanup the unwind escapes an enclosing `eval` — it is
        // `Flow::Abort`, not the `Flow::Discard` an expansion error raises, so
        // the `echo` *after* the eval on the same unit goes too.
        assert_eq!(
            run("eval \"exit 1 2\nnot-run\" 2>&1; echo also-not-run\necho after\n").0,
            "osh: exit: too many arguments\nafter\n"
        );
        // A non-numeric operand is checked first and returns immediately, so it
        // never reaches the too-many test — and it still exits, with 2.
        let (o, st) = run("exit abc def 2>&1; echo not-reached\n");
        assert_eq!(o, "osh: exit: abc: numeric argument required\n");
        assert_eq!(st, 2);
    }

    #[test]
    fn bashopts_is_sorted_enabled_options() {
        // $BASHOPTS is a colon-joined, alphabetically-sorted list of enabled
        // shopt options; toggling one updates it.
        // The harness is interactive-like, so `expand_aliases` is enabled and
        // appears in the sorted list.
        assert_eq!(
            run("echo $BASHOPTS").0,
            "checkwinsize:cmdhist:complete_fullquote:expand_aliases:extquote:\
             force_fignore:globasciiranges:globskipdots:hostcomplete:\
             interactive_comments:patsub_replacement:progcomp:promptvars:sourcepath\n"
        );
        // Enabling `autocd` inserts it in sorted position.
        assert!(run("shopt -s autocd; echo $BASHOPTS").0.starts_with("autocd:checkwinsize:"));
    }

    #[test]
    fn bashopts_is_readonly() {
        // bash marks $BASHOPTS readonly; `readonly -p` renders it as such.
        assert!(run("readonly -p").0.contains("declare -r BASHOPTS="));
    }

    #[test]
    fn bash_var_is_reassignable() {
        // $BASH is defined and, unlike $BASHOPTS, is reassignable.
        assert!(!run("echo $BASH").0.trim().is_empty());
        assert_eq!(run("BASH=foo; echo $BASH").0, "foo\n");
    }

    #[test]
    fn readonly_and_export_take_only_plain_identifiers() {
        // Neither builtin accepts the subscripted target `declare` does, and the
        // text each complaint quotes is decided by how far the scan for the `=`
        // gets: `a[0]=9` reaches one, so only the name is quoted; `h[a=1` never
        // does, so the whole word is. See `attr_assignment_split`.
        let (o, s) = run("a=(1 2); readonly 'a[0]=9' 2>&1; echo rc=$?; declare -p a");
        assert_eq!(
            o,
            "osh: readonly: `a[0]': not a valid identifier\nrc=1\ndeclare -a a=([0]=\"1\" [1]=\"2\")\n"
        );
        assert_eq!(s, 0);
        assert_eq!(
            run("export 'h[a'=1 2>&1").0,
            "osh: export: `h[a=1': not a valid identifier\n"
        );
        assert_eq!(
            run("readonly 1bad=2 2>&1").0,
            "osh: readonly: `1bad=2': not a valid identifier\n"
        );
        assert_eq!(run("export '' 2>&1").0, "osh: export: `': not a valid identifier\n");
        // One bad name costs only itself: the rest are still declared, and the
        // call reports the failure once it has worked through them all.
        let (o, _) = run("readonly x=1 1bad=2 y=3 2>&1; echo rc=$?; declare -p x y");
        assert_eq!(
            o,
            "osh: readonly: `1bad=2': not a valid identifier\nrc=1\ndeclare -r x=\"1\"\ndeclare -r y=\"3\"\n"
        );
    }

    #[test]
    fn readonly_p_with_names_marks_them_instead_of_listing() {
        // `-p` only decides what a *nameless* `readonly` does. Given names there
        // is nothing left for it to answer, so bash marks them exactly as a plain
        // `readonly` would and prints nothing at all.
        assert_eq!(run("readonly -p q=5; echo \"[$q]\"; q=6; echo rc=$?").0, "[5]\n");
        assert_eq!(run("readonly -p q=5; { q=6; } 2>&1").0, "osh: q: readonly variable\n");
        // …whereas with no names it is the listing, which `-p` merely spells out.
        assert!(run("readonly q=5; readonly -p").0.contains("declare -r q=\"5\"\n"));
    }

    #[test]
    fn readonly_functions() {
        // `readonly -f NAME` marks a function readonly: it can't be redefined or
        // `unset -f`, and `declare -F` reports it with the `-fr` flag.
        assert_eq!(
            run("foo() { echo hi; }; readonly -f foo; foo() { echo bye; }; echo rc=$?").0,
            "rc=1\n"
        );
        assert_eq!(
            run("foo() { echo hi; }; readonly -f foo; unset -f foo; echo rc=$?").0,
            "rc=1\n"
        );
        assert_eq!(
            run("foo() { :; }; readonly -f foo; declare -F").0,
            "declare -fr foo\n"
        );
        // `readonly -f` on a non-function is an error (status 1); `declare -fr`
        // fails silently on a non-function.
        assert_eq!(run("readonly -f nofn; echo rc=$?").0, "rc=1\n");
        assert_eq!(run("declare -fr nofn; echo rc=$?").0, "rc=1\n");
        // `declare -fr NAME` marks readonly just like `readonly -f`.
        assert_eq!(
            run("foo() { :; }; declare -fr foo; foo() { echo x; }; echo rc=$?").0,
            "rc=1\n"
        );
        // The listing form prints the body then a `declare -fr NAME` line.
        assert_eq!(
            run("foo() { echo hi; }; readonly -f foo; readonly -f").0,
            "foo () \n{ \n    echo hi\n}\ndeclare -fr foo\n"
        );
    }

    #[test]
    fn lastpipe_runs_final_stage_in_current_shell() {
        // Without lastpipe the final stage is a subshell, so `read` cannot set a
        // variable in the parent (the value is lost).
        assert_eq!(run("echo hi | read x; echo \"${x:-empty}\"").0, "empty\n");
        // With `shopt -s lastpipe` the final stage runs in the current shell, so
        // `read` persists, a `while read` accumulator survives, and `mapfile`
        // populates a parent array.
        assert_eq!(
            run("shopt -s lastpipe; echo hi | read x; echo \"${x:-empty}\"").0,
            "hi\n"
        );
        assert_eq!(
            run("shopt -s lastpipe; seq 3 | while read l; do s=$((s+l)); done; echo sum=$s").0,
            "sum=6\n"
        );
        assert_eq!(
            run("shopt -s lastpipe; printf 'a\\nb\\nc\\n' | mapfile -t arr; echo ${arr[1]}").0,
            "b\n"
        );
    }

    #[test]
    fn builtin_help() {
        // `help NAME` prints a "NAME: usage" line then an indented description
        // (bash prefixes the synopsis with the builtin name and a colon).
        let out = run("help cd").0;
        assert!(out.contains("cd: cd [-L|[-P [-e]] [-@]] [dir]"), "got: {out:?}");
        assert!(out.contains("    Change the shell working directory."), "got: {out:?}");
        // `-s` prints only the "NAME: usage" line, no description.
        let out = run("help -s pwd").0;
        assert_eq!(out, "pwd: pwd [-LPW]\n");
        // `-d` prints only the short description.
        assert_eq!(run("help -d true").0, "true - Return a successful (zero) exit status.\n");
        // A glob pattern (contains `*`/`?`) matches whole topic names and is
        // headed by bash's keyword banner.
        let out = run("help -s 'tru*'").0;
        assert_eq!(out, "Shell commands matching keyword `tru*'\n\ntrue: true\n");
        // A plain pattern is a case-sensitive *prefix* match, listed
        // alphabetically with no banner (bash's `help ech` → echo).
        assert_eq!(run("help -s ech").0, "echo: echo [-neE] [arg ...]\n");
        assert_eq!(
            run("help -s un").0,
            "unalias: unalias [-a] name [name ...]\nunset: unset [-f] [-v] [-n] [name ...]\nuntil: until COMMANDS; do COMMANDS-2; done\n"
        );
        // An exact topic-name match wins over a longer prefix sibling: `help
        // for` resolves to `for` alone (not `for ((`), `help time` to `time`
        // (not `times`). Only a non-exact prefix lists every sibling.
        assert_eq!(run("help -s for").0, "for: for NAME [in WORDS ... ] ; do COMMANDS; done\n");
        assert_eq!(run("help -s time").0, "time: time [-p] pipeline\n");
        assert_eq!(
            run("help -s ti").0,
            "time: time [-p] pipeline\ntimes: times\n"
        );
        // Shell keywords are documented topics too: `help while` etc. resolve.
        let out = run("help while").0;
        assert!(out.contains("while: while COMMANDS; do COMMANDS-2; done"), "got: {out:?}");
        assert_eq!(run("help -s if").0, "if: if COMMANDS; then COMMANDS; [ elif COMMANDS; then COMMANDS; ]... [ else COMMANDS; ] fi\n");
        // Topic names with punctuation resolve via the prefix rule.
        assert_eq!(run("help -s '(('").0, "(( ... )): (( expression ))\n");
        assert_eq!(run("help -s '[['").0, "[[ ... ]]: [[ expression ]]\n");
        // No-arg prints an osh-identity header (never "GNU bash") + the guidance
        // lines, then every builtin synopsis (sorted); spot-check.
        let out = run("help").0;
        assert!(out.starts_with("osh (Oils for SlateOS) "), "got: {out:?}");
        assert!(!out.contains("GNU bash"), "must not claim GNU bash: {out:?}");
        assert!(out.contains("Type `help name' to find out more"), "got: {out:?}");
        assert!(out.contains("echo [-neE] [arg ...]"), "got: {out:?}");
        assert!(out.contains("help [-dms] [pattern ...]"), "got: {out:?}");
        // Unknown topic is a status-1 error with no stdout.
        let (o, code) = run("help nosuchbuiltin");
        assert_eq!(o, "");
        assert_eq!(code, 1);
    }

    #[test]
    fn tilde_expand_in_assignment() {
        // A bare assignment tilde-expands after each unquoted `:` (bash's
        // assignment-context rule), not just at the start of the value.
        assert_eq!(run("HOME=/h; x=~/a:~/b; echo \"$x\"").0, "/h/a:/h/b\n");
        // A tilde inside a preceding parameter expansion is preserved, while a
        // literal tilde following a literal `:` is expanded.
        assert_eq!(run("HOME=/h; p=/one; x=$p:~/bin; echo \"$x\"").0, "/one:/h/bin\n");
        // A quoted tilde is NOT expanded.
        assert_eq!(run("HOME=/h; x=~/a:'~/b'; echo \"$x\"").0, "/h/a:~/b\n");
        // ~+ / ~- work in assignment position too.
        assert_eq!(run("PWD=/p; x=~+/sub; echo \"$x\"").0, "/p/sub\n");
    }

    /// bash marks what a tilde expanded to as *quoted*, so it is never re-read
    /// as a pattern — while the rest of the word, after the tilde-prefix, stays
    /// unquoted and still globs. A `HOME` holding a glob metacharacter is the
    /// only way to see the two halves come apart.
    #[test]
    fn tilde_expansion_result_is_quoted() {
        // The expansion is a literal in a `[[ ]]` pattern: it matches itself,
        // and does not match a string its metacharacter would have globbed.
        assert_eq!(run("HOME='a*'; [[ 'a*' == ~ ]]; echo $?").0, "0\n");
        assert_eq!(run("HOME='a*'; [[ ab == ~ ]]; echo $?").0, "1\n");
        assert_eq!(run("HOME='a*'; [[ 'a*/x' == ~/x ]]; echo $?").0, "0\n");
        // …but only the prefix is quoted: the tail is a live pattern. (`~*` is
        // not that case — its tilde-*prefix* is `*`, which resolves to nothing,
        // so the whole word stays literal.)
        assert_eq!(run("HOME='a'; [[ 'a/b' == ~/* ]]; echo $?").0, "0\n");
        assert_eq!(run("HOME='a'; [[ ab == ~* ]]; echo $?").0, "1\n");
        // The tilde-prefix is expanded in a pattern operand at all, which is the
        // position it used to be skipped in.
        assert_eq!(run("HOME=/xyz; [[ /xyz == ~ ]]; echo $?").0, "0\n");
        assert_eq!(run("HOME=/xyz; [[ /xyz/a == ~/a ]]; echo $?").0, "0\n");
        // An unresolvable prefix is no expansion, and the word stays as written.
        assert_eq!(run("[[ '~nosuchuser' == ~nosuchuser ]]; echo $?").0, "0\n");
        // A tilde that is not in prefix position is ordinary text.
        assert_eq!(run("HOME=/h; [[ 'a~b' == a~b ]]; echo $?").0, "0\n");
    }

    #[test]
    fn tilde_expand_in_declaration_builtin() {
        // export/declare/typeset/readonly operands are assignments: the RHS
        // tilde-expands after `:`/at value start, just like a bare NAME=value.
        assert_eq!(run("HOME=/h; export X=~/foo; echo \"$X\"").0, "/h/foo\n");
        assert_eq!(
            run("HOME=/h; declare Y=~/a:~/b; echo \"$Y\"").0,
            "/h/a:/h/b\n"
        );
        assert_eq!(
            run("HOME=/h; Z=/pre; typeset Z=$Z:~/bin; echo \"$Z\"").0,
            "/pre:/h/bin\n"
        );
        assert_eq!(run("HOME=/h; readonly R=~/r; echo \"$R\"").0, "/h/r\n");
        // A quoted tilde stays literal even for a declaration builtin.
        assert_eq!(run("HOME=/h; export Q=~/a:'~/b'; echo \"$Q\"").0, "/h/a:~/b\n");
        // The append form NAME+=value expands its RHS too, for declare, export,
        // and readonly alike (previously mis-parsed as a var named "NAME+").
        assert_eq!(
            run("HOME=/h; A=/pre; declare A+=:~/bin; echo \"$A\"").0,
            "/pre:/h/bin\n"
        );
        assert_eq!(
            run("HOME=/h; B=/pre; export B+=:~/bin; echo \"$B\"").0,
            "/pre:/h/bin\n"
        );
        assert_eq!(
            run("HOME=/h; C=/pre; readonly C+=:~/bin; echo \"$C\"").0,
            "/pre:/h/bin\n"
        );
        // Under -i, += performs numeric addition.
        assert_eq!(run("declare -i n=10; declare n+=5; echo \"$n\"").0, "15\n");
        // `local` inside a function gets assignment-context expansion.
        assert_eq!(
            run("HOME=/h; f() { local L=~/lib; echo \"$L\"; }; f").0,
            "/h/lib\n"
        );
        // The RHS is not word-split even when it contains spaces (assignment
        // context), unlike an ordinary command word.
        assert_eq!(
            run("HOME=/h; v='a b'; export S=$v; echo \"$S\"").0,
            "a b\n"
        );
    }

    #[test]
    fn tilde_expand_plus_minus_and_home() {
        // ~ expands to $HOME; ~/path keeps the remainder.
        assert_eq!(run("HOME=/home/me; echo ~").0, "/home/me\n");
        assert_eq!(run("HOME=/home/me; echo ~/docs").0, "/home/me/docs\n");
        // ~+ = $PWD, ~- = $OLDPWD, both with an optional trailing path.
        assert_eq!(run("PWD=/a/b; echo ~+").0, "/a/b\n");
        assert_eq!(run("PWD=/a/b; echo ~+/c").0, "/a/b/c\n");
        assert_eq!(run("OLDPWD=/x/y; echo ~-").0, "/x/y\n");
        assert_eq!(run("OLDPWD=/x/y; echo ~-/z").0, "/x/y/z\n");
        // ~+0 is the current directory-stack top (a real path, not literal).
        let out = run("echo ~+0").0;
        assert!(!out.starts_with('~'), "got: {out:?}");
        // A `~user` prefix is looked up in the user database (see
        // `read_passwd_home`); one that does not resolve is left untouched,
        // rather than falling back on `$HOME`.
        assert_eq!(run("echo ~nosuchuser42/bin").0, "~nosuchuser42/bin\n");
        assert_eq!(run("HOME=/home/me; echo ~nosuchuser42").0, "~nosuchuser42\n");
    }

    #[test]
    fn param_transform_escape_and_attrs() {
        // @E expands backslash escapes; @a reports array attributes.
        assert_eq!(run("x='a\\tb'; printf '%s' \"${x@E}\"").0, "a\tb");
        assert_eq!(run("declare -A m; m[k]=v; echo \"${m@a}\"").0, "A\n");
        assert_eq!(run("a=(1 2 3); echo \"${a@a}\"").0, "a\n");
        // Scalar attributes: integer, readonly, export, lower/upper.
        assert_eq!(run("declare -i n=5; echo \"${n@a}\"").0, "i\n");
        assert_eq!(run("readonly r=1; echo \"${r@a}\"").0, "r\n");
        assert_eq!(run("export e=1; echo \"${e@a}\"").0, "x\n");
        assert_eq!(run("declare -l lo=X; echo \"${lo@a}\"").0, "l\n");
        // Combined attributes render in bash's reporting order — the kind, then
        // `n`, `i`, `r`, `x`, and last the case-folding trio `l`/`u`/`c` — not in
        // the order the flags were written.
        assert_eq!(run("declare -ir z=5; echo \"${z@a}\"").0, "ir\n");
        assert_eq!(run("declare -alrx v=A; echo \"${v@a}\"").0, "arxl\n");
        assert_eq!(run("declare -aurx v=(A); echo \"${v@a}\"").0, "arxu\n");
        assert_eq!(run("declare -lx s=q; echo \"${s@a}\"").0, "xl\n");
        assert_eq!(run("declare -Acrx m; echo \"${m@a}\"").0, "Arxc\n");
        // `declare -p`, `readonly -p` and `${v@A}` share the one builder, so they
        // agree with it.
        assert_eq!(
            run("declare -alrx v=A; declare -p v").0,
            "declare -arxl v=([0]=\"a\")\n"
        );
        assert_eq!(
            run("declare -alrx v=A; echo \"${v@A}\"").0,
            "declare -arxl v='a'\n"
        );
        // `readonly -p` shares it too (its listing also carries the shell's own
        // readonly variables, so only the new name is asserted here).
        assert!(
            run("declare -irx q=5; readonly -p")
                .0
                .contains("declare -irx q=\"5\"\n")
        );
        // A plain scalar has no attribute flags.
        assert_eq!(run("p=1; echo \"[${p@a}]\"").0, "[]\n");
    }

    #[test]
    fn param_transform_prompt() {
        // @P expands prompt escapes using shell state.
        assert_eq!(
            run("USER=alice; HOSTNAME=box.example.com; p='\\u@\\h'; echo \"${p@P}\"").0,
            "alice@box\n"
        );
        // \H is the full hostname; \n/\\ and unknown escapes.
        assert_eq!(
            run("HOSTNAME=box.example.com; p='\\H'; echo \"${p@P}\"").0,
            "box.example.com\n"
        );
        // \w with HOME contraction is exercised indirectly; here test \s (shell
        // name from $0), octal, and a literal-preserving unknown escape.
        assert_eq!(run("p='\\061\\062'; echo \"${p@P}\"").0, "12\n"); // \061=1 \062=2
        assert_eq!(run("p='a\\qb'; echo \"${p@P}\"").0, "a\\qb\n"); // unknown escape kept
        // Defaults when every name the user is looked up under is empty. (Set
        // empty rather than unset: with no environment imported, `param_value`
        // still falls back to the host environment for an unset name, and the
        // machine running the tests does have a `USERNAME`.)
        assert_eq!(
            run("USER= LOGNAME= USERNAME=; p='\\u'; echo \"${p@P}\"").0,
            "user\n"
        );
        // The decoded prompt is then expanded as if inside double quotes, over
        // the whole of it — so `$…` from the value *and* from an escape's output
        // both expand, `'`/`"` stay literal, and nothing is split or globbed.
        assert_eq!(run("x='a b'; p='<$x>'; echo \"${p@P}\"").0, "<a b>\n");
        assert_eq!(run("p='$((3*4))'; echo \"${p@P}\"").0, "12\n");
        assert_eq!(run("p='x$(echo s)y'; echo \"${p@P}\"").0, "xsy\n");
        assert_eq!(run("p=\"a'b\\\"c\"; echo \"${p@P}\"").0, "a'b\"c\n");
        assert_eq!(run("p='a\\\\$b'; echo \"${p@P}\"").0, "a$b\n");
    }

    /// `set -x` reads its prefix out of `PS4`, expanding it as a prompt (escapes
    /// *and* substitutions) before every line — and `PS4` is a real variable
    /// seeded with `+ `, so unsetting it leaves no prefix at all.
    #[test]
    fn xtrace_prefix_comes_from_ps4() {
        let trace = |src: &str| run(&format!("{{ set -x; {src}; }} 2>&1")).0;
        assert_eq!(run("echo \"[$PS4]\"").0, "[+ ]\n");
        assert_eq!(trace("PS4='T '; :"), "+ PS4='T '\nT :\n");
        assert_eq!(trace("PS4=; :"), "+ PS4=\n:\n");
        assert_eq!(trace("unset PS4; :"), "+ unset PS4\n:\n");
        // Substitution inside PS4: expanded per line, and an empty result
        // contributes nothing rather than printing the unexpanded text.
        assert_eq!(trace("PS4='+${x:+ }'; x=; :"), "+ PS4='+${x:+ }'\n+x=\n+:\n");
        assert_eq!(trace("PS4='+ $((1+1)) '; :"), "+ PS4='+ $((1+1)) '\n+ 2 :\n");
        // Tracing is off while PS4 expands, so a command substitution in it
        // cannot trace itself into the prefix.
        assert_eq!(trace("PS4='+$(echo q) '; :"), "+ PS4='+$(echo q) '\n+q :\n");
    }

    /// A command substitution's body traces one level deeper: `PS4`'s first
    /// character is repeated once per level of expansion indirection. A plain
    /// subshell, a function call and a pipeline are not expansions and do not
    /// count.
    #[test]
    fn xtrace_repeats_the_prefix_inside_a_substitution() {
        let trace = |src: &str| run(&format!("{{ set -x; {src}; }} 2>&1")).0;
        assert_eq!(trace("v=$(echo a)"), "++ echo a\n+ v=a\n");
        assert_eq!(trace("v=`echo c`"), "++ echo c\n+ v=c\n");
        assert_eq!(
            trace("v=$(echo $(echo b))"),
            "+++ echo b\n++ echo b\n+ v=b\n"
        );
        // The level is a property of the substitution, not of the shell nesting:
        // a `( … )` inside one keeps it, a `( … )` outside never had it.
        assert_eq!(trace("( echo s )"), "+ echo s\ns\n");
        assert_eq!(trace("v=$( ( echo t ) )"), "++ echo t\n+ v=t\n");
        assert_eq!(trace("f() { echo F; }; v=$(f)"), "++ f\n++ echo F\n+ v=F\n");
        // It is the *first character* of the expanded PS4 that repeats, not the
        // whole prefix — and an empty PS4 stays empty however deep.
        assert_eq!(
            trace("PS4='XY '; v=$(echo a)"),
            "+ PS4='XY '\nXXY echo a\nXY v=a\n"
        );
        assert_eq!(trace("PS4=; v=$(echo a)"), "+ PS4=\necho a\nv=a\n");
    }

    #[test]
    fn readarray_default_var_and_count() {
        // Alias readarray, default MAPFILE array, and -n limit.
        let src = "readarray -t -n 2 <<< $'1\\n2\\n3\\n4'\n\
                   echo \"${#MAPFILE[@]} ${MAPFILE[0]} ${MAPFILE[1]}\"";
        assert_eq!(run(src).0, "2 1 2\n");
    }

    #[test]
    fn param_substring() {
        assert_eq!(run("x=abcdef; echo ${x:2}").0, "cdef\n");
        assert_eq!(run("x=abcdef; echo ${x:2:3}").0, "cde\n");
        assert_eq!(run("x=abcdef; echo ${x: -2}").0, "ef\n");
        assert_eq!(run("x=abcdef; echo ${x:1:-1}").0, "bcde\n");
        // A negative length whose absolute end lands before the start offset is a
        // DISCARD-class "substring expression < 0" error (bash): the command is
        // discarded, `$?` is 1, and — as it's one parse unit — a same-line
        // follow-on is dropped too.
        let (o, s) = run("v=abc; echo ${v:2:-10}; echo after");
        assert_eq!(o, "");
        assert_eq!(s, 1);
        // The offending length appears verbatim in the diagnostic. The error is
        // emitted during word expansion, before a simple command's `2>&1` is
        // installed, so wrap in a brace group whose redirect is already active.
        let err = run("v=abc; { echo ${v:2:-10}; } 2>&1").0;
        assert!(
            err.contains("-10: substring expression < 0"),
            "got: {err:?}"
        );
    }

    #[test]
    fn param_substring_negative_offset_beyond_start_is_empty() {
        // A negative offset whose magnitude exceeds the string length lands
        // before the start: bash yields the EMPTY string (it does not clamp to 0
        // and return the whole value). `${v: -N}` with N > len ⇒ empty.
        assert_eq!(run(r#"v=hello; echo "[${v: -10}]""#).0, "[]\n");
        assert_eq!(run(r#"v=hello; echo "[${v: -6}]""#).0, "[]\n");
        // Exactly `-len` is in range and returns the whole string.
        assert_eq!(run(r#"v=hello; echo "[${v: -5}]""#).0, "[hello]\n");
        // With a length, an out-of-range negative offset is still empty.
        assert_eq!(run(r#"v=hello; echo "[${v: -10:2}]""#).0, "[]\n");
    }

    #[test]
    fn array_slice_negative_offset_beyond_start_is_empty() {
        // Same rule for array / positional slices: a negative offset past the
        // start yields an empty slice, not the whole array.
        assert_eq!(run(r#"a=(1 2 3); echo "[${a[@]: -10}]""#).0, "[]\n");
        assert_eq!(run(r#"a=(1 2 3); echo "[${a[@]: -10:2}]""#).0, "[]\n");
        assert_eq!(run(r#"a=(1 2 3); echo "[${a[@]: -2}]""#).0, "[2 3]\n");
    }

    #[test]
    fn unrecognized_brace_form_is_runtime_bad_substitution() {
        // An unrecognised `${…}` form is not a parse error (bash accepts it at
        // parse time); it is a runtime "bad substitution" — a DISCARD-class
        // word-expansion error printing `${raw}: bad substitution`, status 1,
        // aborting the current parse unit but not exiting the shell.
        //
        // `run_script` throughout, not `run`: history expansion inhibits `!` only
        // directly after a `${`, so the `!` in `${x!}` is an event designator that
        // an interactive shell rewrites (or rejects) before the parser ever sees
        // the word — measured in bash, which answers `!}: event not found`.
        assert!(parse("echo ${x!}".as_bytes()).is_ok());
        let (o, s) = run_script("echo ${x!} 2>/dev/null; echo after");
        assert_eq!(o, "");
        assert_eq!(s, 1);
        // The raw inner text is reproduced verbatim in the diagnostic, behind
        // bash's `line N:` token — which a *non-interactive* shell prints even
        // when its input is stdin rather than a named script (measured:
        // `echo 'echo ${x!}' | bash` answers `bash: line 1: …`).
        assert_eq!(
            run_script("{ echo ${x!}; } 2>&1").0,
            "osh: line 1: ${x!}: bad substitution\n"
        );
        assert_eq!(
            run_script("x=hi; { echo ${!x*junk}; } 2>&1").0,
            "osh: line 1: ${!x*junk}: bad substitution\n"
        );
        // A trailing remnant after a `${#name[i]}` length is also bad.
        assert_eq!(
            run_script("{ echo ${#a[0]extra}; } 2>&1").0,
            "osh: line 1: ${#a[0]extra}: bad substitution\n"
        );
        // DISCARD semantics: a following *line* still runs (not fatal).
        let (o2, s2) = run_script("echo ${x!} 2>/dev/null\necho after");
        assert_eq!(o2, "after\n");
        assert_eq!(s2, 0);
        // A subshell contains the error; the parent survives.
        assert_eq!(
            run_script("( echo ${x!} ) 2>/dev/null; echo parent").0,
            "parent\n"
        );
    }

    #[test]
    fn param_replace_forms() {
        assert_eq!(run("x=aXbXc; echo ${x/X/-}").0, "a-bXc\n");
        assert_eq!(run("x=aXbXc; echo ${x//X/-}").0, "a-b-c\n");
        assert_eq!(run("x=abcabc; echo ${x/#abc/Z}").0, "Zabc\n");
        assert_eq!(run("x=abcabc; echo ${x/%abc/Z}").0, "abcZ\n");
        assert_eq!(run("x=hello; echo ${x//l/}").0, "heo\n");
    }

    #[test]
    fn escaped_metachar_is_literal_in_patterns() {
        // A backslash-escaped glob metacharacter is a *literal*, matching bash
        // (`a\*b` ≡ `a'*'b`): it must not act as a live `*`/`?`/`[` in `case`,
        // `[[ == ]]`, or the `${…#pat}`/`${…/pat/…}`/`${…^pat}` operators.

        // case: escaped `*` matches only a literal `*`.
        assert_eq!(run(r#"case "aXb" in a\*b) echo M;; *) echo N;; esac"#).0, "N\n");
        assert_eq!(run(r#"case "a*b" in a\*b) echo M;; *) echo N;; esac"#).0, "M\n");
        // [[ == ]]: same, plus escaped `?`.
        assert_eq!(run(r#"[[ "aXb" == a\*b ]] && echo M || echo N"#).0, "N\n");
        assert_eq!(run(r#"[[ "a*b" == a\*b ]] && echo M || echo N"#).0, "M\n");
        assert_eq!(run(r#"[[ "aXb" == a\?b ]] && echo M || echo N"#).0, "N\n");
        assert_eq!(run(r#"[[ "a?b" == a\?b ]] && echo M || echo N"#).0, "M\n");
        // A quoted RHS metacharacter is equivalent to an escaped one.
        assert_eq!(run(r#"[[ "aXb" == "a*b" ]] && echo M || echo N"#).0, "N\n");

        // ${x#pat} / ${x%pat}: escaped `*` does not strip arbitrary text.
        assert_eq!(run(r#"x=aXb; echo "${x#a\*b}""#).0, "aXb\n");
        assert_eq!(run(r#"x=a*b; echo "${x#a\*b}""#).0, "\n");
        assert_eq!(run(r#"x=foo*bar; echo "${x%\*bar}""#).0, "foo\n");
        // ${x//pat/repl}: escaped `*` replaces only literal `*` occurrences.
        assert_eq!(run(r#"x=aXbXc; echo "${x//\*/_}""#).0, "aXbXc\n");
        assert_eq!(run(r#"x=a*b*c; echo "${x//\*/_}""#).0, "a_b_c\n");
        // Escaped bracket expression is literal.
        assert_eq!(run(r#"x=a[b]c; echo "${x//\[b\]/_}""#).0, "a_c\n");

        // Regression guard: a metacharacter supplied by an *unquoted* expansion
        // stays LIVE (only the literal backslash escape suppresses it).
        assert_eq!(run(r#"pat="a*b"; [[ "aXYZb" == $pat ]] && echo M || echo N"#).0, "M\n");
        assert_eq!(run(r#"x=aXbc; p="a?b"; echo "${x#$p}""#).0, "c\n");
        assert_eq!(run(r#"x=a.b.c; echo "${x//./_}""#).0, "a_b_c\n");

        // Escaped tilde is literal (no home-directory expansion).
        assert_eq!(run(r#"echo \~"#).0, "~\n");
    }

    #[test]
    fn param_replace_empty_extglob_match() {
        // Extglob quantifiers that can match the empty string (`?(x)`, `*(x)`)
        // produce zero-width matches in `${var//pat/repl}`: bash inserts the
        // replacement at each such position and advances one character. An
        // *empty* pattern (`${x///-}`) is a no-op, so it must NOT trigger this.
        assert_eq!(run("shopt -s extglob; x=aXbXc; echo ${x//?(X)/-}").0, "-a--b--c\n");
        assert_eq!(run("shopt -s extglob; x=aXbXc; echo ${x//*(X)/-}").0, "-a--b--c\n");
        assert_eq!(run("shopt -s extglob; x=abc; echo ${x//?(z)/-}").0, "-a-b-c\n");
        // Single (non-global) replace inserts at the first position only.
        assert_eq!(run("shopt -s extglob; x=abc; echo ${x/?(z)/-}").0, "-abc\n");
        // Empty pattern stays a no-op (regression guard for the fix).
        assert_eq!(run("x=abc; echo ${x///-}").0, "abc\n");
    }

    #[test]
    fn param_replace_ampersand_matched_text() {
        // bash's `patsub_replacement` (default on): an unquoted `&` in the
        // replacement stands for the text matched by the pattern.
        assert_eq!(run("x=abc; echo \"${x/b/[&]}\"").0, "a[b]c\n");
        assert_eq!(run("x=abc; echo \"${x/b/&}\"").0, "abc\n");
        assert_eq!(run("x=abc; echo \"${x/b/&&}\"").0, "abbc\n");
        // Each match in a global replace expands `&` to its own matched text.
        assert_eq!(run("x=abcabc; echo \"${x//b/<&>}\"").0, "a<b>ca<b>c\n");
        assert_eq!(run("x=hello; echo \"${x//[aeiou]/[&]}\"").0, "h[e]ll[o]\n");
        // `#`/`%` anchored replaces expand `&` to the anchored match.
        assert_eq!(run("x=abc; echo \"${x/#a/[&]}\"").0, "[a]bc\n");
        assert_eq!(run("x=abc; echo \"${x/%c/[&]}\"").0, "ab[c]\n");
        // A `*` match captures the whole span.
        assert_eq!(run("x=fooXbar; echo \"${x/o*a/<&>}\"").0, "f<ooXba>r\n");
        // Array bulk replace applies per element.
        assert_eq!(
            run("a=(one two three); echo \"${a[@]/t/[&]}\"").0,
            "one [t]wo [t]hree\n"
        );
    }

    #[test]
    fn param_replace_ampersand_escaping_and_quoting() {
        // `\&` is a literal ampersand (escaped, never the match) — whether the
        // escape is in the literal source or produced by an unquoted expansion.
        assert_eq!(run("x=abc; echo \"${x/b/\\&}\"").0, "a&c\n");
        assert_eq!(run("x=abc; r='\\&'; echo \"${x/b/$r}\"").0, "a&c\n");
        // `\\` is a literal backslash; other backslashes in an unquoted
        // expansion stay verbatim (`\n` is kept, not stripped).
        assert_eq!(run("x=abc; r='\\n'; echo \"${x/b/$r}\"").0, "a\\nc\n");
        // Quoting (single or double) makes `&` an ordinary literal.
        assert_eq!(run("x=abc; echo \"${x/b/'&'}\"").0, "a&c\n");
        assert_eq!(run("x=abc; echo \"${x/b/\"&\"}\"").0, "a&c\n");
        // A quoted expansion is not scanned for `&` either.
        assert_eq!(run("x=abc; r='[&]'; echo \"${x/b/\"$r\"}\"").0, "a[&]c\n");
        // With the shopt off, `&` is a plain literal everywhere.
        assert_eq!(
            run("shopt -u patsub_replacement; x=abc; echo \"${x/b/[&]}\"").0,
            "a[&]c\n"
        );
        // …but a literal `\&` still collapses to `&` (normal quote removal),
        // while an unquoted expansion is copied verbatim when the shopt is off.
        assert_eq!(
            run("shopt -u patsub_replacement; x=abc; echo \"${x/b/\\&}\"").0,
            "a&c\n"
        );
        assert_eq!(
            run("shopt -u patsub_replacement; x=abc; r='\\&'; echo \"${x/b/$r}\"").0,
            "a\\&c\n"
        );
    }

    #[test]
    fn param_ops_still_work() {
        assert_eq!(run("echo ${u:-default}").0, "default\n");
        assert_eq!(run("x=set; echo ${x:+yes}").0, "yes\n");
    }

    #[test]
    fn param_replace_preserves_literal_whitespace() {
        // The pattern and replacement of `${var/pat/repl}` are single words —
        // bash applies expansion and quote removal but neither word-splitting nor
        // operator tokenization, so leading/trailing/embedded whitespace is
        // literal (previously osh trimmed it via the word-splitting lexer).
        assert_eq!(run("s=world; echo \"[${s/#/hello }]\"").0, "[hello world]\n");
        assert_eq!(run("s=world; echo \"[${s/o/O }]\"").0, "[wO rld]\n");
        assert_eq!(run("s=world; echo \"[${s/w/ X}]\"").0, "[ Xorld]\n");
        // A literal space as the pattern.
        assert_eq!(run("s='a b c'; echo \"[${s/ /_}]\"").0, "[a_b c]\n");
        assert_eq!(run("s='a b c'; echo \"[${s// /_}]\"").0, "[a_b_c]\n");
        // Expansion inside the replacement still applies.
        assert_eq!(run("s=x; r='A B'; echo \"[${s/x/$r}]\"").0, "[A B]\n");
    }

    #[test]
    fn param_brace_closes_at_first_unescaped_brace() {
        // bash's `${…}` scanner closes at the first unquoted, unescaped `}`
        // that is not part of a nested `$…` construct. A bare `{` does NOT
        // open a new nesting level, so `${x//[{}]/_}` closes at the `}` inside
        // `[{}]` (leaving `]/_}` as literal text after the expansion). Pattern
        // is therefore `[{` which matches nothing in `a{b}c`.
        assert_eq!(run("x=a{b}c; echo \"${x//[{}]/_}\"").0, "a{b}c]/_}\n");
        // A backslash-escaped `}` inside the body is a literal, not a
        // terminator: pattern `\}` matches the literal `}`.
        assert_eq!(run("x=a}c; echo \"${x/\\}/X}\"").0, "aXc\n");
        // A backslash-escaped `{` is likewise literal.
        assert_eq!(run("x=a{b; echo \"${x/\\{/X}\"").0, "aXb\n");
        // The realistic JSON-stripping case: remove `{`, `}`, and `"`.
        assert_eq!(
            run("json='{\"a\":1}'; echo \"${json//[\\{\\}\\\"]/}\"").0,
            "a:1\n"
        );
    }

    #[test]
    fn param_brace_balances_nested_dollar_constructs() {
        // Nested `${…}`, `$(…)`, `$((…))`, and backtick spans inside a `${…}`
        // must balance with their own terminators, so a `}` or `)` within them
        // is not mistaken for the outer terminator.
        assert_eq!(run("unset x; y=hi; echo \"${x:-${y}}\"").0, "hi\n");
        assert_eq!(run("x=; echo \"${x:-$(echo })}\"").0, "}\n");
        assert_eq!(run("x=; echo \"${x:-`echo }`}\"").0, "}\n");
        assert_eq!(run("x=q; echo \"${x:-$((1+1))}\"").0, "q\n");
        // A `}` protected by quotes inside the body is also not a terminator.
        assert_eq!(run("x=; echo \"${x:-$(echo \"}\")}\"").0, "}\n");
    }

    #[test]
    fn param_ops_preserve_literal_whitespace() {
        // The pattern of `#`/`%` trims and `^`/`,` case ops, and the argument of
        // the `:-`/`:=`/`:+`/`:?` default ops, are single words with literal
        // whitespace — bash applies expansion and quote removal but not
        // word-splitting (previously osh trimmed embedded/leading/trailing
        // spaces via the word-splitting lexer, corrupting the pattern).
        // Trim with a trailing-space suffix pattern.
        assert_eq!(run("s='hello '; echo \"[${s% }]\"").0, "[hello]\n");
        // Longest-suffix trim with a space in the pattern: `${f%% *}` strips
        // from the first space onward. osh used to collapse ` *` → `*`.
        assert_eq!(run("f='my dog runs'; echo \"[${f%% *}]\"").0, "[my]\n");
        // Prefix trim where the pattern itself contains a space.
        assert_eq!(run("s='foo bar'; echo \"[${s#foo }]\"").0, "[bar]\n");
        // Default value preserves embedded and leading spaces when quoted.
        assert_eq!(run("echo \"[${x:-a  b}]\"").0, "[a  b]\n");
        assert_eq!(run("echo \"[${x:-  lead}]\"").0, "[  lead]\n");
        // Trailing space in an alternate value.
        assert_eq!(run("x=set; echo \"[${x:+hi }]\"").0, "[hi ]\n");
    }

    #[test]
    fn param_transform_assign() {
        // `@A` on a plain scalar → short `name='value'` (bash single-quotes
        // every value, even a plain word).
        assert_eq!(run("x=hello; echo \"${x@A}\"").0, "x='hello'\n");
        assert_eq!(run("x='a b'; echo \"${x@A}\"").0, "x='a b'\n");
        // An attributed scalar renders as a full `declare` statement whose
        // value is single-quoted (bash's `@A` uses single quotes even for the
        // attributed form, unlike `declare -p`'s double quotes).
        assert_eq!(
            run("declare -i n=5; echo \"${n@A}\"").0,
            "declare -i n='5'\n"
        );
        assert_eq!(
            run("declare -r x=5; echo \"${x@A}\"").0,
            "declare -r x='5'\n"
        );
        assert_eq!(
            run("declare -x x='a b'; echo \"${x@A}\"").0,
            "declare -x x='a b'\n"
        );
        // A bare array/assoc name is element 0 / key "0" (bash: `${a@A}` ==
        // `${a[0]@A}`), rendered as the array's declare flags with that single
        // element's value in scalar single-quoted form — NOT the whole array.
        assert_eq!(run("a=(x y); echo \"${a@A}\"").0, "declare -a a='x'\n");
        assert_eq!(run("a=(x y); echo \"${a[0]@A}\"").0, "declare -a a='x'\n");
        // A specific element likewise: `${a[1]@A}` uses element 1's value.
        assert_eq!(run("a=(x y); echo \"${a[1]@A}\"").0, "declare -a a='y'\n");
        // An unset element drops the value entirely (`declare -a a`).
        assert_eq!(run("a=(x y); echo \"${a[9]@A}\"").0, "declare -a a\n");
        // Associative: bare name is key "0"; unset there → no value.
        assert_eq!(run("declare -A m; m[k]=v; echo \"[${m@A}]\"").0, "[declare -A m]\n");
        assert_eq!(run("declare -A m; m[0]=z; echo \"${m@A}\"").0, "declare -A m='z'\n");
        // The WHOLE array/assoc form is `${a[@]@A}` / `${a[*]@A}` — a full
        // re-inputtable `declare` (see `array_transform_at_a_whole`).
        assert_eq!(
            run("a=(x y); echo \"${a[@]@A}\"").0,
            "declare -a a=([0]=\"x\" [1]=\"y\")\n"
        );
        // An unset variable yields the empty string.
        assert_eq!(run("echo \"[${nope@A}]\"").0, "[]\n");
    }

    #[test]
    fn array_transform_at_a_whole() {
        // `${arr[@]@A}` / `${arr[*]@A}` produce one field: the full re-inputtable
        // `declare` (matching `declare -p`), not a per-element transform.
        assert_eq!(
            run("declare -a a=(1 2 3); echo \"${a[@]@A}\"").0,
            "declare -a a=([0]=\"1\" [1]=\"2\" [2]=\"3\")\n"
        );
        assert_eq!(
            run("declare -a a=(1 2 3); echo \"${a[*]@A}\"").0,
            "declare -a a=([0]=\"1\" [1]=\"2\" [2]=\"3\")\n"
        );
        // A readonly array carries its flags through.
        assert_eq!(
            run("declare -ar a=(1 2); echo \"${a[@]@A}\"").0,
            "declare -ar a=([0]=\"1\" [1]=\"2\")\n"
        );
        // Positional params render as a single `set -- 'a' 'b' …` statement.
        assert_eq!(run("set -- a b c; echo \"${@@A}\"").0, "set -- 'a' 'b' 'c'\n");
        assert_eq!(run("set -- a b c; echo \"${*@A}\"").0, "set -- 'a' 'b' 'c'\n");
        // `@a` yields one attribute-letter field per element.
        assert_eq!(run("declare -a a=(1 2 3); echo \"${a[@]@a}\"").0, "a a a\n");
        assert_eq!(run("declare -ar a=(1 2); echo \"${a[@]@a}\"").0, "ar ar\n");
        assert_eq!(run("declare -a a=(1 2 3); echo \"${a[1]@a}\"").0, "a\n");
    }

    #[test]
    fn nameref_scalar_read_write() {
        // Reading a nameref returns the target's value.
        assert_eq!(run("target=hi; declare -n ref=target; echo $ref").0, "hi\n");
        // Writing through a nameref updates the target.
        assert_eq!(
            run("target=old; declare -n ref=target; ref=new; echo $target").0,
            "new\n"
        );
        // Retargeting: create the target lazily through the nameref.
        assert_eq!(
            run("declare -n ref=t; ref=made; echo $t").0,
            "made\n"
        );
    }

    #[test]
    fn nameref_array_access() {
        // A nameref to an array reads/writes its elements.
        assert_eq!(
            run("a=(x y z); declare -n r=a; echo ${r[1]}").0,
            "y\n"
        );
        assert_eq!(
            run("a=(x y z); declare -n r=a; echo \"${r[@]}\"").0,
            "x y z\n"
        );
        assert_eq!(
            run("a=(x y z); declare -n r=a; echo ${#r[@]}").0,
            "3\n"
        );
        // Writing an element through the nameref hits the target array.
        assert_eq!(
            run("a=(x y z); declare -n r=a; r[1]=Y; echo \"${a[@]}\"").0,
            "x Y z\n"
        );
    }

    #[test]
    fn nameref_in_function() {
        // The canonical "pass an array by reference to a function" pattern.
        let src = "fill() { declare -n out=$1; out=(1 2 3); }; \
                   fill data; echo \"${data[@]}\"";
        assert_eq!(run(src).0, "1 2 3\n");
    }

    #[test]
    fn nameref_unset_and_declare_p() {
        // `unset -n` drops the nameref; the target survives.
        assert_eq!(
            run("t=keep; declare -n r=t; unset -n r; echo \"[${r}][$t]\"").0,
            "[][keep]\n"
        );
        // Plain `unset` through a nameref removes the target.
        assert_eq!(
            run("t=gone; declare -n r=t; unset r; echo \"[$t]\"; echo done").0,
            "[]\ndone\n"
        );
        // `declare -p` shows the `-n` attribute.
        assert_eq!(
            run("t=v; declare -n r=t; declare -p r").0,
            "declare -n r=\"t\"\n"
        );
    }

    #[test]
    fn valueless_nameref_declaration_judges_the_stored_value() {
        // A nameref's value *is* the name it refers to, so `declare -n NAME`
        // judges what the binding already holds, exactly as the assignment
        // form judges what it is given.
        assert_eq!(run("q=0; declare -n q; declare -p q").0, "declare -- q=\"0\"\n");
        assert_eq!(run("q=0; declare -n q; echo rc=$?").0, "rc=1\n");
        assert_eq!(run("q=zz; declare -n q; declare -p q").0, "declare -n q=\"zz\"\n");
        // A subscript is an ordinary shell word; only the base must be a name.
        assert_eq!(
            run("q='a[1]'; declare -n q; declare -p q").0,
            "declare -n q=\"a[1]\"\n"
        );
        // The self-reference rule of the assignment form does *not* apply: this
        // command supplied no value, so there is no circle it could have made.
        assert_eq!(run("q=q; declare -n q; declare -p q").0, "declare -n q=\"q\"\n");
        assert_eq!(run("q=q; declare -n q=q; echo rc=$?").0, "rc=1\n");
        // Nothing stored is nothing to judge.
        assert_eq!(run("declare -n q; declare -p q").0, "declare -n q\n");
        // An array cannot be a nameref whatever its elements say.
        assert_eq!(
            run("declare -a q=(zz); declare -n q; declare -p q").0,
            "declare -a q=([0]=\"zz\")\n"
        );
        assert_eq!(run("declare -a q; declare -n q; echo rc=$?").0, "rc=1\n");
        // The refusal abandons the whole operand — neither `-n` nor the letters
        // beside it are applied — while later operands still bind.
        assert_eq!(run("q=0; declare -rnu q; declare -p q").0, "declare -- q=\"0\"\n");
        assert_eq!(run("q=0; declare -n q z=zz; declare -p z").0, "declare -n z=\"zz\"\n");
        // `+n` removes the attribute and so judges nothing.
        assert_eq!(run("q=0; declare +n q; echo rc=$?").0, "rc=0\n");
        // A `local` shadows the value before it can be judged; `-g` names the
        // global, which still holds it.
        assert_eq!(
            run("q=0; f() { declare -n q; declare -p q; }; f").0,
            "declare -n q\n"
        );
        assert_eq!(run("q=0; f() { declare -gn q; }; f; declare -p q").0, "declare -- q=\"0\"\n");
        // A dynamic variable is judged by the value its function computes.
        assert_eq!(run("declare -n SECONDS; echo rc=$?").0, "rc=1\n");
        assert_eq!(run("declare -n BASH_SOURCE; echo rc=$?").0, "rc=1\n");
        // …and once `unset` has taken that function away, there is nothing left
        // to judge, so the attribute simply lands.
        assert_eq!(
            run("unset SECONDS; declare -n SECONDS; declare -p SECONDS").0,
            "declare -n SECONDS\n"
        );
    }

    #[test]
    fn nameref_cycle_reads_as_unset() {
        // A cycle is a reference with nowhere to go. osh used to stop at the
        // last name walked, so `$a` expanded to the *string* `b`.
        assert_eq!(run("declare -n a=b; declare -n b=a; echo \"[$a]\"").0, "[]\n");
        assert_eq!(
            run("declare -n a=b; declare -n b=a; echo \"[${a:-def}]\"").0,
            "[def]\n"
        );
        assert_eq!(
            run("declare -n a=b; declare -n b=a; echo \"[${#a}]\"").0,
            "[0]\n"
        );
        assert_eq!(
            run("declare -n a=b; declare -n b=a; echo \"[${a[@]}]\"").0,
            "[]\n"
        );
        // Longer chains close the same way, from whichever link is read.
        assert_eq!(
            run("declare -n a=b; declare -n b=c; declare -n c=a; echo \"[$c]\"").0,
            "[]\n"
        );
        // `-v` reports it unset, and the reference does not resolve to itself.
        assert_eq!(
            run("declare -n a=b; declare -n b=a; [ -v a ]; echo rc=$?").0,
            "rc=1\n"
        );
    }

    #[test]
    fn nameref_cycle_write_fails_and_leaves_the_cycle_intact() {
        // Writing through a cycle has no target: bash fails the assignment and
        // discards the rest of that list, but the shell (and the cycle) survive.
        assert_eq!(
            run("declare -n a=b; declare -n b=a; a=5; echo nope\necho rc=$?\ndeclare -p a b").0,
            "rc=1\ndeclare -n a=\"b\"\ndeclare -n b=\"a\"\n"
        );
    }

    #[test]
    fn nameref_to_unset_or_element_target_is_not_v_set() {
        // `-v ref` asks whether the *target* is set, not whether the reference
        // exists — which it always does.
        assert_eq!(
            run("declare -n r=missing; [ -v r ]; echo rc=$?").0,
            "rc=1\n"
        );
        assert_eq!(
            run("declare -n r=t; t=1; [ -v r ]; echo rc=$?").0,
            "rc=0\n"
        );
        // A target naming an array *element* reads through, but `-v` looks the
        // resolved text up as a plain variable name and so never finds it.
        assert_eq!(
            run("a=(p q); declare -n r=a[1]; [ -v r ]; echo \"rc=$? val=[$r]\"").0,
            "rc=1 val=[q]\n"
        );
    }

    #[test]
    fn param_transform_keyvalue() {
        // `@k` interleaves subscripts and values as separate words.
        assert_eq!(run("a=(x y z); echo ${a[@]@k}").0, "0 x 1 y 2 z\n");
        // `@K` yields one field: subscripts with double-quoted values. An
        // *indexed* array's field has no trailing space.
        assert_eq!(run("a=(x y); echo \"${a[@]@K}\"").0, "0 \"x\" 1 \"y\"\n");
        // An *associative* array's `@K` field carries a bash trailing space so
        // the re-inputtable form round-trips exactly.
        assert_eq!(
            run("declare -A h=([m]=1); echo \"[${h[@]@K}]\"").0,
            "[m \"1\" ]\n"
        );
        // Associative arrays interleave string keys.
        assert_eq!(
            run("declare -A m; m[a]=1; m[b]=2; echo ${m[@]@k}").0,
            "a 1 b 2\n"
        );
        // The positional parameters are not an array, so `@k`/`@K` degrade to
        // `@Q` (each value quoted, no interleaved index) — matching bash, which
        // reserves the key-value interleave for real indexed/associative arrays.
        assert_eq!(run("set -- p q; echo ${@@k}").0, "'p' 'q'\n");
        assert_eq!(run("set -- p q; echo ${@@K}").0, "'p' 'q'\n");
        // `@k` keeps each word separate even when quoted.
        assert_eq!(
            run("a=('x 1' y); for w in \"${a[@]@k}\"; do echo \"[$w]\"; done").0,
            "[0]\n[x 1]\n[1]\n[y]\n"
        );
        // On a *scalar* (or single array element) `@K`/`@k` quote like `@Q`.
        assert_eq!(run("v=abc; echo ${v@K}").0, "'abc'\n");
        assert_eq!(run("v=abc; echo ${v@k}").0, "'abc'\n");
        assert_eq!(run("v='a b'; echo ${v@K}").0, "'a b'\n");
        assert_eq!(run("v=; echo ${v@K}").0, "''\n");
        assert_eq!(run("a=(x y z); echo ${a[1]@K}").0, "'y'\n");
    }

    #[test]
    fn glob_match_basics() {
        let g = |p: &str, t: &str| {
            glob_match(
                &bytes::chars(p.as_bytes()).collect::<Vec<_>>(),
                &bytes::chars(t.as_bytes()).collect::<Vec<_>>(),
                false,
            )
        };
        assert!(g("*", "anything"));
        assert!(g("h?llo", "hello"));
        assert!(g("a*c", "abbbc"));
        assert!(!g("a*c", "abbb"));
        assert!(g("[a-c]x", "bx"));
        assert!(!g("[a-c]x", "dx"));
        assert!(g("[!0-9]", "z"));
        assert!(!g("[!0-9]", "5"));
        assert!(g("file.txt", "file.txt"));
        assert!(!g("file.txt", "file.md"));
    }

    /// A filename on this OS is any byte sequence without `/` or NUL, so the
    /// glob engine must match one that is not valid UTF-8 — and must treat an
    /// undecodable byte as exactly one *character*, so `?` neither swallows
    /// two of them nor matches a third of a multi-byte character.
    #[test]
    fn glob_matches_a_name_that_is_not_utf8() {
        let g = |p: &[u8], t: &[u8]| {
            glob_match(
                &bytes::chars(p).collect::<Vec<_>>(),
                &bytes::chars(t).collect::<Vec<_>>(),
                false,
            )
        };
        // `?` is one character: one undecodable byte, or one whole `é`.
        assert!(g(b"?", b"\xff"));
        assert!(!g(b"??", b"\xff"));
        assert!(g(b"?", "\u{e9}".as_bytes()));
        assert!(!g(b"??", "\u{e9}".as_bytes()));
        // An undecodable byte falls in no character range and matches no
        // class: it is not a letter, and it is not U+FFFD either.
        assert!(!g(b"[a-z]", b"\xff"));
        assert!(!g(b"[[:alpha:]]", b"\xff"));
        assert!(!g(b"\xef\xbf\xbd", b"\xff"));
        assert!(g(b"[!a-z]", b"\xff"));
        // The interesting case: the byte survives both sides of the match.
        assert!(g(b"a?b", b"a\xffb"));
        assert!(g(b"a*b", b"a\xff\xfeb"));
        assert!(g(b"a\xffb", b"a\xffb"));
        assert!(!g(b"a\xffb", b"a\xfeb"));
    }

    /// The parameter-expansion operators are character-defined, so they must
    /// agree with the glob engine that an undecodable byte is one character —
    /// and must pass it through untouched rather than case-fold or drop it.
    #[test]
    fn param_operators_pass_an_undecodable_byte_through() {
        // `${v^^}` upper-cases the letters and leaves the stray byte alone.
        assert_eq!(
            param_case(b"a\xffb", &[], crate::ast::CaseMode::Upper, true, false),
            b"A\xffB"
        );
        // `${v:1:1}` counts that byte as exactly one character.
        assert_eq!(param_substr(b"a\xffb", 1, Some(1)), Ok(b"\xff".to_vec()));
        assert_eq!(param_substr(b"a\xffb", 2, None), Ok(b"b".to_vec()));
        // `${v#?}` strips it as a single character.
        assert_eq!(param_trim(b"\xffab", &field_lit("?"), false, false, false), b"ab");
        // `${v//?/-}` replaces it with one replacement, not three.
        assert_eq!(
            param_replace(
                b"a\xffb",
                &field_lit("?"),
                &[ReplTok::Lit(Ch::U('-'))],
                true,
                ReplaceAnchor::None,
                false,
            ),
            b"---"
        );
    }

    #[test]
    fn glob_posix_char_classes() {
        let g = |p: &str, t: &str| {
            glob_match(
                &bytes::chars(p.as_bytes()).collect::<Vec<_>>(),
                &bytes::chars(t.as_bytes()).collect::<Vec<_>>(),
                false,
            )
        };
        // Single POSIX classes match one appropriate character.
        assert!(g("[[:digit:]]", "5"));
        assert!(!g("[[:digit:]]", "a"));
        assert!(g("[[:alpha:]]", "a"));
        assert!(g("[[:space:]]", " "));
        assert!(g("[[:upper:]]", "A"));
        assert!(!g("[[:upper:]]", "a"));
        // Negated class: `[![:space:]]` = a non-space char.
        assert!(g("[![:space:]]", "x"));
        assert!(!g("[![:space:]]", " "));
        // Mixed with literals/ranges inside one bracket.
        assert!(g("[[:digit:]_]", "_"));
        assert!(g("[a-c[:digit:]]", "7"));
        // The classic left-trim idiom: strip everything from the first
        // non-space onward, leaving the leading whitespace.
        assert_eq!(param_trim(b"  trim  ", &field_lit("[![:space:]]*"), true, true, false), b"  ");
        // Shortest leading-whitespace `#` strip removes just one space char.
        assert_eq!(
            param_trim(b"  trim  ", &field_lit("[[:space:]]*"), false, false, false),
            b" trim  "
        );
    }

    #[test]
    fn cond_string_equality() {
        assert_eq!(run("[[ foo == foo ]]").1, 0);
        assert_eq!(run("[[ foo == bar ]]").1, 1);
        assert_eq!(run("[[ foo != bar ]]").1, 0);
        assert_eq!(run("x=hello; [[ $x = hello ]]").1, 0);
    }

    #[test]
    fn cond_glob_and_quoting() {
        // Unquoted RHS is a glob pattern.
        assert_eq!(run("[[ foobar == foo* ]]").1, 0);
        assert_eq!(run("[[ foobar == baz* ]]").1, 1);
        // Quoted RHS is a literal, so the `*` does not match.
        assert_eq!(run("[[ foobar == \"foo*\" ]]").1, 1);
        assert_eq!(run("[[ 'foo*' == \"foo*\" ]]").1, 0);
    }

    #[test]
    fn cond_numeric() {
        assert_eq!(run("[[ 3 -gt 2 ]]").1, 0);
        assert_eq!(run("[[ 2 -gt 3 ]]").1, 1);
        assert_eq!(run("[[ 5 -eq 5 ]]").1, 0);
        assert_eq!(run("x=4; [[ $x -le 4 ]]").1, 0);
        // Operands undergo arithmetic evaluation.
        assert_eq!(run("[[ 2+2 -eq 4 ]]").1, 0);
    }

    #[test]
    fn cond_string_len() {
        assert_eq!(run("[[ -z \"\" ]]").1, 0);
        assert_eq!(run("[[ -n foo ]]").1, 0);
        assert_eq!(run("x=; [[ -z $x ]]").1, 0);
        assert_eq!(run("x=set; [[ -n $x ]]").1, 0);
    }

    #[test]
    fn cond_logical_and_grouping() {
        assert_eq!(run("[[ 1 -eq 1 && 2 -eq 2 ]]").1, 0);
        assert_eq!(run("[[ 1 -eq 1 && 2 -eq 3 ]]").1, 1);
        assert_eq!(run("[[ 1 -eq 2 || 3 -eq 3 ]]").1, 0);
        assert_eq!(run("[[ ! 1 -eq 2 ]]").1, 0);
        assert_eq!(run("[[ ( 1 -eq 1 || 1 -eq 2 ) && 3 -eq 3 ]]").1, 0);
    }

    #[test]
    fn cond_string_ordering() {
        assert_eq!(run("[[ abc < abd ]]").1, 0);
        assert_eq!(run("[[ abd < abc ]]").1, 1);
        assert_eq!(run("[[ b > a ]]").1, 0);
    }

    #[test]
    fn cond_in_if() {
        assert_eq!(run("if [[ foo == foo ]]; then echo yes; fi").0, "yes\n");
        assert_eq!(
            run("x=3; if [[ $x -gt 5 ]]; then echo big; else echo small; fi").0,
            "small\n"
        );
    }

    #[test]
    fn cond_regex_match() {
        // Basic ERE match sets a zero exit status.
        assert_eq!(run("[[ abc123 =~ ^[a-z]+[0-9]+$ ]]").1, 0);
        // Non-match yields status 1.
        assert_eq!(run("[[ abc =~ ^[0-9]+$ ]]").1, 1);
    }

    #[test]
    fn cond_regex_in_if() {
        assert_eq!(
            run("if [[ foo42 =~ [0-9]+ ]]; then echo num; else echo none; fi").0,
            "num\n"
        );
    }

    #[test]
    fn cond_regex_bash_rematch() {
        // Whole match in [0], captures in [1..]; extract via ${BASH_REMATCH[n]}.
        let (o, _) = run(
            "[[ 2026-07-18 =~ ([0-9]+)-([0-9]+)-([0-9]+) ]]; \
             echo \"${BASH_REMATCH[0]} ${BASH_REMATCH[1]} ${BASH_REMATCH[2]} ${BASH_REMATCH[3]}\"",
        );
        assert_eq!(o, "2026-07-18 2026 07 18\n");
    }

    /// A subject or a pattern that holds a byte which is not text — a SlateOS
    /// filename may hold any byte but `/` and NUL. `crate::ere` used to be
    /// `&str`-typed, so `cond_regex` refused: such a subject matched nothing and
    /// such a pattern made `[[` exit 2 as though the regex were malformed.
    #[test]
    fn cond_regex_matches_a_value_that_is_not_text() {
        // `^a` against `a\xffb`, the case named in TD-OILS-ERE-TEXT-ONLY.
        assert_eq!(run("f=$'a\\xffb'; [[ $f =~ ^a ]]").1, 0);
        assert_eq!(run("f=$'a\\xffb'; [[ $f =~ ^b ]]").1, 1);
        // `.` matches the byte as one character, so this is `a`, one, `b`.
        assert_eq!(run("f=$'a\\xffb'; [[ $f =~ ^a.b$ ]]").1, 0);
        assert_eq!(run("f=$'a\\xffb'; [[ $f =~ ^a..b$ ]]").1, 1);
        // The byte is writable in the pattern too, and still exits 0/1 rather
        // than 2 — it is a literal, not a malformed regex.
        assert_eq!(run("f=$'a\\xffb'; [[ $f =~ $'\\xff' ]]").1, 0);
        assert_eq!(run("f=$'a\\xffb'; [[ $f =~ $'\\xfe' ]]").1, 1);
        // And the capture that reaches BASH_REMATCH is the bytes themselves —
        // read through `run_raw`, since `run`'s lossy decode would hide it.
        let (o, s) = run_raw("f=$'a\\xffb'; [[ $f =~ ^a(.)b$ ]]; printf %s \"${BASH_REMATCH[1]}\"");
        assert_eq!(o, b"\xff");
        assert_eq!(s, 0);
    }

    #[test]
    fn cond_regex_rhs_expansion() {
        // The RHS undergoes parameter expansion before compilation.
        assert_eq!(run("p='^h.*o$'; [[ hello =~ $p ]]").1, 0);
    }

    #[test]
    fn cond_regex_invalid_pattern() {
        // A malformed regex makes `[[` exit with status 2 (bash's distinct
        // "regex error" status), not 1 "no match", and prints nothing.
        let (o, s) = run("[[ x =~ [ ]] 2>&1");
        assert_eq!(o, "");
        assert_eq!(s, 2);
        // The status-2 propagates: `&&` short-circuits, `||` sees a non-match.
        assert_eq!(run("[[ x =~ [ ]] && echo y || echo n").0, "n\n");
        assert_eq!(run("[[ x =~ [ ]] && echo y || echo n").1, 0);
        // A valid regex that fails to match still returns the ordinary 1.
        assert_eq!(run("[[ x =~ ^z ]]").1, 1);
    }

    #[test]
    fn cond_regex_negated() {
        assert_eq!(run("[[ ! abc =~ [0-9] ]] && echo nonum").0, "nonum\n");
    }

    #[test]
    fn cond_regex_double_quoted_rhs_is_literal() {
        // A double-quoted RHS matches literally: `.` is a real dot, not "any".
        assert_eq!(run("[[ a.b =~ \"a.b\" ]]").1, 0);
        assert_eq!(run("[[ axb =~ \"a.b\" ]]").1, 1);
        // Unquoted, the same text is a regex and `.` matches any char.
        assert_eq!(run("[[ axb =~ a.b ]]").1, 0);
    }

    #[test]
    fn cond_regex_single_quoted_rhs_is_literal() {
        assert_eq!(run("[[ a.b =~ 'a.b' ]]").1, 0);
        assert_eq!(run("[[ axb =~ 'a.b' ]]").1, 1);
    }

    #[test]
    fn cond_regex_mixed_quoting() {
        // Only the quoted `.` is literal; the surrounding text stays regex.
        assert_eq!(run("[[ a.b =~ a\".\"b ]]").1, 0);
        assert_eq!(run("[[ axb =~ a\".\"b ]]").1, 1);
    }

    #[test]
    fn cond_regex_inline_backslash_escapes_metachar() {
        // A backslash in the inline `=~` regex escapes the metacharacter for the
        // ERE engine (bash passes `\X` through to regcomp), so `\+`/`\.`/`\(`
        // match a *literal* `+`/`.`/`(` — exactly as a variable-supplied regex
        // does. Previously osh stripped the backslash, turning `\+` into a `+`
        // quantifier and `\.` into any-char. (Root-caused in read_word_regex.)
        assert_eq!(run("[[ a+b =~ a\\+b ]]").1, 0); // literal + matches
        assert_eq!(run("[[ axb =~ a\\+b ]]").1, 1); // no literal + present
        assert_eq!(run("[[ aXb =~ a\\.b ]]").1, 1); // \. is a literal dot
        assert_eq!(run("[[ a.b =~ a\\.b ]]").1, 0);
        assert_eq!(run("[[ 'a(b' =~ a\\(b ]]").1, 0); // literal paren, not a group
        // Consistency: inline and variable-supplied regex agree.
        assert_eq!(run("re='a\\+b'; [[ a+b =~ $re ]]").1, 0);
    }

    #[test]
    fn cond_regex_quoted_var_is_literal() {
        // Quoted expansion is literal; unquoted expansion is a live pattern.
        assert_eq!(run("p='a.b'; [[ a.b =~ \"$p\" ]]").1, 0);
        assert_eq!(run("p='a.b'; [[ axb =~ \"$p\" ]]").1, 1);
        assert_eq!(run("p='a.b'; [[ axb =~ $p ]]").1, 0);
    }

    #[test]
    fn arith_command_status() {
        assert_eq!(run("(( 1 + 1 ))").1, 0);
        assert_eq!(run("(( 0 ))").1, 1);
        assert_eq!(run("(( 5 > 3 ))").1, 0);
        assert_eq!(run("(( 3 > 5 ))").1, 1);
    }

    /// Run `src` on a shell that has imported the real process environment
    /// (as the binary does at startup). Reads process env — no mutation — so
    /// it is safe under the parallel test harness.
    fn run_imported(src: &str) -> (String, i32) {
        let mut sh = Shell::new();
        sh.import_environment();
        let buf = capture_sink();
        let prog = parse(src.as_bytes()).expect("parse");
        {
            let mut out = Out::Capture(buf.clone());
            sh.exec_program(&prog, &mut out, &StdinSrc::Inherit);
        }
        let buf = take_capture(&buf);
        (String::from_utf8_lossy(&buf).into_owned(), sh.last_status)
    }

    #[test]
    fn env_import_env_vars_are_shell_vars() {
        // After importing the environment, an inherited env variable behaves
        // exactly like a shell variable: it is readable, appears in prefix
        // name-matching (`${!PATH*}`), and `unset` truly hides it (no silent
        // std::env resurrection). PATH is present in every environment.
        assert_eq!(run_imported("echo \"${PATH:+yes}\"").0, "yes\n");
        // Prefix matching includes the inherited PATH.
        assert_eq!(
            run_imported("for n in ${!PATH*}; do [ \"$n\" = PATH ] && echo found; done").0,
            "found\n"
        );
        // unset removes it — no fallback to the real process environment.
        assert_eq!(run_imported("unset PATH; echo \"[${PATH-gone}]\"").0, "[gone]\n");
    }

    #[test]
    fn env_import_increments_shlvl() {
        // bash increments $SHLVL per nested shell. import_environment does the
        // same: the value is at least 1, exported, and a plain subshell keeps
        // the same level (it is not a new shell invocation).
        let (out, _) = run_imported("echo $SHLVL");
        let lvl: i64 = out.trim().parse().expect("SHLVL numeric");
        assert!(lvl >= 1, "SHLVL should be >= 1, got {lvl}");
        // A `(...)` subshell does not re-increment.
        let (out2, _) = run_imported("(echo $SHLVL)");
        assert_eq!(out2.trim(), lvl.to_string());
    }

    #[test]
    fn dollar_literal_before_closing_dquote() {
        // A `$` immediately before the closing `"` is a literal `$` (bash),
        // and inside double quotes `$'…'`/`$"…"` are NOT the ANSI-C-quote /
        // locale forms — the `$` is literal and the quote is handled by the
        // enclosing double-quote scanner. Previously osh's `read_dollar`
        // consumed the closing quote, giving "unterminated double quote".
        assert_eq!(run("echo \"abc$\"").0, "abc$\n");
        assert_eq!(run("echo \"^[0-9]+$\"").0, "^[0-9]+$\n");
        assert_eq!(run("echo \"$\"").0, "$\n");
        assert_eq!(run("x=5; echo \"val=$x$\"").0, "val=5$\n");
        // `$'x'` inside double quotes is the 4 literal chars `$'x'`.
        assert_eq!(run("echo \"a$'x'\"").0, "a$'x'\n");
    }

    #[test]
    fn legacy_dollar_bracket_arith() {
        // `$[ … ]` is bash's deprecated arithmetic expansion, an alias for
        // `$(( … ))`. Verify basic evaluation, spacing, variables, array
        // subscripts, and use inside a double-quoted context.
        assert_eq!(run("echo $[1+2]").0, "3\n");
        assert_eq!(run("echo $[ 2 * 3 ]").0, "6\n");
        assert_eq!(run("x=4; echo $[x*x]").0, "16\n");
        assert_eq!(run("a=(10 20 30); echo $[a[1]+5]").0, "25\n");
        assert_eq!(run("echo \"$[10/3]\"").0, "3\n");
    }

    #[test]
    fn arith_command_with_vars() {
        assert_eq!(run("x=4; (( x > 3 ))").1, 0);
        assert_eq!(run("x=2; (( x > 3 ))").1, 1);
        // Used as a condition.
        assert_eq!(run("x=10; if (( x > 5 )); then echo big; fi").0, "big\n");
    }

    #[test]
    fn let_builtin_assigns_and_status() {
        // `let` evaluates the expression, mutating the variable.
        assert_eq!(run("let x=3+4; echo $x").0, "7\n");
        // Status is 0 when the last expression is non-zero, 1 when zero.
        assert_eq!(run("let '1 + 1'").1, 0);
        assert_eq!(run("let '0'").1, 1);
        // Multiple expressions: the last one drives the status.
        assert_eq!(run("let 'a=5' 'a>3'").1, 0);
        // Increment operators work.
        assert_eq!(run("x=4; let x++; echo $x").0, "5\n");
    }

    #[test]
    fn let_no_args_fails() {
        assert_eq!(run("let").1, 1);
    }

    #[test]
    fn nested_subshell_still_works() {
        // `( ( … ) )` with an inner space is nested subshells, not arithmetic.
        assert_eq!(run("( ( echo hi ) )").0, "hi\n");
    }

    #[test]
    fn bash_subshell_depth() {
        // `$BASH_SUBSHELL` is 0 at top level and increments in each subshell.
        assert_eq!(run("echo $BASH_SUBSHELL").0, "0\n");
        assert_eq!(run("( echo $BASH_SUBSHELL )").0, "1\n");
        assert_eq!(run("( ( echo $BASH_SUBSHELL ) )").0, "2\n");
        // A command substitution is also a subshell.
        assert_eq!(run("echo $(echo $BASH_SUBSHELL)").0, "1\n");
    }

    #[test]
    fn arith_ternary_and_comma() {
        // Ternary in `$(( … ))` is a common idiom for conditional values.
        assert_eq!(run("x=5; echo $(( x > 3 ? 100 : 200 ))").0, "100\n");
        assert_eq!(run("x=1; echo $(( x > 3 ? 100 : 200 ))").0, "200\n");
        // Comma evaluates all, yields the last.
        assert_eq!(run("echo $(( 1 + 1, 2 * 5 ))").0, "10\n");
        // As a `(( … ))` command, the exit status reflects the final value.
        assert_eq!(run("(( 1 ? 1 : 0 ))").1, 0);
        assert_eq!(run("(( 1 ? 0 : 1 ))").1, 1);
    }

    #[test]
    fn arith_number_bases() {
        // base#num and leading-zero octal survive `$(( … ))` expansion:
        // the `#` must not be mistaken for a comment.
        assert_eq!(run("echo $(( 2#1010 ))").0, "10\n");
        assert_eq!(run("echo $(( 16#ff ))").0, "255\n");
        assert_eq!(run("echo $(( 8#17 ))").0, "15\n");
        assert_eq!(run("echo $(( 017 ))").0, "15\n");
        assert_eq!(run("echo $(( 64#_ ))").0, "63\n");
    }

    #[test]
    fn declare_integer_attribute() {
        // `declare -i` makes later plain assignments evaluate arithmetically.
        assert_eq!(run("declare -i x; x=5+3; echo $x").0, "8\n");
        // The initializer on the declare itself is also evaluated.
        assert_eq!(run("declare -i y=2*3; echo $y").0, "6\n");
        // `+=` on an integer variable performs numeric addition.
        assert_eq!(run("declare -i z=10; z+=5; echo $z").0, "15\n");
        // A non-numeric expression evaluates to 0.
        assert_eq!(run("declare -i q=abc; echo $q").0, "0\n");
        // `+i` removes the attribute; assignments become plain strings again.
        assert_eq!(run("declare -i w=4; declare +i w; w=1+2; echo $w").0, "1+2\n");
        // Integer array elements are evaluated too.
        assert_eq!(run("declare -ia arr; arr[0]=3+4; echo ${arr[0]}").0, "7\n");
        // `declare -p` reflects the integer attribute.
        assert_eq!(run("declare -i n=9; declare -p n").0, "declare -i n=\"9\"\n");
    }

    #[test]
    fn declare_case_attributes() {
        // `-l` lowercases assigned values; `-u` uppercases them.
        assert_eq!(run("declare -l x; x=HeLLo; echo $x").0, "hello\n");
        assert_eq!(run("declare -u y; y=HeLLo; echo $y").0, "HELLO\n");
        // The initializer on the declare itself is folded too.
        assert_eq!(run("declare -u z=abc; echo $z").0, "ABC\n");
        // Across separate `declare` commands the later flag wins (`-u` replaces
        // the earlier `-l`).
        assert_eq!(run("declare -l w; declare -u w; w=AbC; echo $w").0, "ABC\n");
        // But *within one cluster* two conflicting case flags cancel to none
        // (bash: `-ul`/`-lu`/`-cl`… store the value unchanged, no attribute).
        assert_eq!(run("declare -ul v=AbC; echo $v").0, "AbC\n");
        assert_eq!(run("declare -ul v=AbC; declare -p v").0, "declare -- v=\"AbC\"\n");
        // `+u` removes the attribute.
        assert_eq!(run("declare -u q=abc; declare +u q; q=def; echo $q").0, "def\n");
        // Array elements are folded too.
        assert_eq!(run("declare -u arr; arr[0]=xy; echo ${arr[0]}").0, "XY\n");
        // `declare -p` reflects the case attribute.
        assert_eq!(run("declare -l s=Hi; declare -p s").0, "declare -l s=\"hi\"\n");
    }

    #[test]
    fn declare_capcase_attribute() {
        // `declare -c` (bash's att_capcase): uppercase the first character and
        // lowercase the rest. Verified byte-for-byte against bash 5.x.
        assert_eq!(run("declare -c x=hELLO; echo $x").0, "Hello\n");
        assert_eq!(run("declare -c x='hello world'; echo \"$x\"").0, "Hello world\n");
        assert_eq!(run("declare -c x=HELLO; echo $x").0, "Hello\n");
        assert_eq!(run("declare -c x=a; echo $x").0, "A\n");
        // A leading non-letter blocks capitalization; the rest is lowercased.
        assert_eq!(run("declare -c x=123abc; echo $x").0, "123abc\n");
        // The attribute persists across reassignment.
        assert_eq!(run("declare -c x=foo; x=bAR; echo $x").0, "Bar\n");
        // Array elements are capitalized too.
        assert_eq!(run("declare -c a; a=(oNE tWO); echo \"${a[@]}\"").0, "One Two\n");
        // `typeset -c` and `local -c` behave identically.
        assert_eq!(run("typeset -c x=wORLD; echo $x").0, "World\n");
        assert_eq!(run("f() { local -c y=hELLO; echo \"$y\"; }; f").0, "Hello\n");
        // A function-local `-c` does not leak to the caller's variable.
        assert_eq!(run("f() { local -c y=hi; }; y=OUTER; f; echo $y").0, "OUTER\n");
        // `declare -p` shows `-c`, ordered after i/r/x (`-rc`, `-xc`, `-ic`).
        assert_eq!(run("declare -c x=foo; declare -p x").0, "declare -c x=\"Foo\"\n");
        assert_eq!(run("declare -cr x=foo; declare -p x").0, "declare -rc x=\"Foo\"\n");
        // `${x@a}` reports the `c` flag (after i/r/x).
        assert_eq!(run("declare -c x=Ab; echo ${x@a}").0, "c\n");
        assert_eq!(run("declare -cx x=Ab; echo ${x@a}").0, "xc\n");
        // `+c` removes the attribute.
        assert_eq!(run("declare -c x=foo; declare +c x; x=bAR; echo $x").0, "bAR\n");
    }

    #[test]
    fn arith_assignment_command() {
        // `(( x = … ))` writes back to the shell scalar.
        assert_eq!(run("(( x = 5 )); echo $x").0, "5\n");
        // Compound assignment reads-modifies-writes.
        assert_eq!(run("x=5; (( x += 3 )); echo $x").0, "8\n");
        assert_eq!(run("x=10; (( x -= 4 )); echo $x").0, "6\n");
        assert_eq!(run("x=3; (( x *= 4 )); echo $x").0, "12\n");
        assert_eq!(run("x=20; (( x /= 6 )); echo $x").0, "3\n");
        assert_eq!(run("x=20; (( x %= 6 )); echo $x").0, "2\n");
        assert_eq!(run("x=1; (( x <<= 4 )); echo $x").0, "16\n");
        assert_eq!(run("x=6; (( x &= 4 )); echo $x").0, "4\n");
        // The exit status reflects the assigned value (0 → exit 1).
        assert_eq!(run("(( x = 0 ))").1, 1);
        assert_eq!(run("(( x = 7 ))").1, 0);
    }

    #[test]
    fn arith_increment_command() {
        // Pre/post increment and decrement mutate the shell scalar.
        assert_eq!(run("x=5; (( x++ )); echo $x").0, "6\n");
        assert_eq!(run("x=5; (( ++x )); echo $x").0, "6\n");
        assert_eq!(run("x=5; (( x-- )); echo $x").0, "4\n");
        assert_eq!(run("x=5; (( --x )); echo $x").0, "4\n");
        // Post-increment yields the old value in `$(( … ))`.
        assert_eq!(run("x=5; echo $(( x++ )); echo $x").0, "5\n6\n");
        // Pre-increment yields the new value.
        assert_eq!(run("x=5; echo $(( ++x )); echo $x").0, "6\n6\n");
        // Increment on an unset variable starts from 0.
        assert_eq!(run("echo $(( n++ )); echo $n").0, "0\n1\n");
    }

    #[test]
    fn arith_assignment_array_elements() {
        // Assign to an indexed array element inside arithmetic.
        assert_eq!(run("a=(10 20 30); (( a[1] = 99 )); echo ${a[1]}").0, "99\n");
        assert_eq!(run("a=(10 20 30); (( a[0] += 5 )); echo ${a[0]}").0, "15\n");
        assert_eq!(run("a=(10 20 30); (( a[2]++ )); echo ${a[2]}").0, "31\n");
        // Assign to an associative element by string key.
        assert_eq!(
            run("declare -A m; m[foo]=7; (( m[foo] += 3 )); echo ${m[foo]}").0,
            "10\n"
        );
    }

    #[test]
    fn arith_c_style_for_loop() {
        // Classic counting loop.
        assert_eq!(
            run("for (( i=0; i<3; i++ )); do echo $i; done").0,
            "0\n1\n2\n"
        );
        // Multiple init/update via comma.
        assert_eq!(
            run("for (( i=0, j=10; i<3; i++, j-- )); do echo $i:$j; done").0,
            "0:10\n1:9\n2:8\n"
        );
        // Empty sections mean forever/true; `break` exits.
        assert_eq!(
            run("i=0; for (( ; ; )); do echo $i; (( i++ )); (( i >= 2 )) && break; done").0,
            "0\n1\n"
        );
        // A false condition from the start runs the body zero times.
        assert_eq!(run("for (( i=5; i<3; i++ )); do echo $i; done").0, "");
    }

    #[test]
    fn arith_associative_subscript() {
        // Inside `(( … ))`/`$(( … ))` an associative element is read by its
        // string key (not an arithmetic subscript), like bash.
        assert_eq!(
            run("declare -A m; m[foo]=7; m[bar]=13; echo $(( m[foo] + m[bar] ))").0,
            "20\n"
        );
        // Used as a condition.
        assert_eq!(
            run("declare -A m; m[on]=1; if (( m[on] )); then echo yes; fi").0,
            "yes\n"
        );
        // A key supplied via expansion works too (`$k` expands before arith).
        assert_eq!(
            run("declare -A m; m[foo]=5; k=foo; echo $(( m[$k] ))").0,
            "5\n"
        );
        // An indexed array still uses arithmetic subscripts.
        assert_eq!(run("a=(10 20 30); echo $(( a[1] + a[2] ))").0, "50\n");
    }

    fn field_lit(s: &str) -> Vec<EChar> {
        bytes::chars(s.as_bytes()).map(|c| EChar { c, quoted: false }).collect()
    }

    #[test]
    fn glob_toks_match() {
        let f = |p: &str, n: &str| {
            match_glob_toks(
                &compile_glob(&field_lit(p), false),
                &bytes::chars(n.as_bytes()).collect::<Vec<_>>(),
            )
        };
        assert!(f("*.txt", "a.txt"));
        assert!(!f("*.txt", "a.log"));
        assert!(f("h?llo", "hello"));
        assert!(f("[ab]?", "a1"));
        assert!(!f("[ab]?", "c1"));
        assert!(f("[!0-9]x", "zx"));
        assert!(!f("[!0-9]x", "5x"));
    }

    #[test]
    fn glob_quoted_metachar_is_literal() {
        // A quoted `*` is a literal star, never a pattern.
        let mut field = field_lit("");
        field.push(EChar { c: Ch::U('*'), quoted: true });
        let toks = compile_glob(&field, false);
        assert!(match_glob_toks(&toks, &[Ch::U('*')]));
        assert!(!match_glob_toks(&toks, &[Ch::U('a')]));
    }

    #[test]
    fn glob_filesystem_expansion() {
        let _cwd = cwd_guard();
        // Use a uniquely-named cwd-relative dir to avoid the process-wide-cwd
        // race between parallel tests (no `set_current_dir`).
        let uniq = format!(
            "osh_globtest_{}_{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .expect("clock")
                .as_nanos()
        );
        let dir = std::path::Path::new(&uniq);
        std::fs::create_dir_all(dir).expect("mkdir");
        for n in ["a.txt", "b.txt", "c.log", ".hidden"] {
            std::fs::File::create(dir.join(n)).expect("touch");
        }

        let basename = |p: &Str| p.rsplit(|&b| b == b'/').next().unwrap_or(p).to_vec();

        // `*.txt` matches the two text files (sorted), not the log or hidden.
        let mut txt: Vec<Str> =
            glob_expand_field(b"", &field_lit(&format!("{uniq}/*.txt")), false, false, false, false)
                .iter()
                .map(&basename)
                .collect();
        txt.sort();
        assert_eq!(txt, vec![b"a.txt".to_vec(), b"b.txt".to_vec()]);

        // `*` honors the leading-dot rule (no `.hidden`).
        let all = glob_expand_field(b"", &field_lit(&format!("{uniq}/*")), false, false, false, false);
        assert!(all.iter().all(|p| !p.ends_with(b".hidden")));
        assert_eq!(all.len(), 3);

        // An explicit leading `.` matches hidden files.
        let dot = glob_expand_field(b"", &field_lit(&format!("{uniq}/.*")), false, false, false, false);
        assert!(dot.iter().any(|p| p.ends_with(b".hidden")));

        std::fs::remove_dir_all(dir).ok();
    }

    #[test]
    fn cwd_paths_use_forward_slashes() {
        // The shell's path model is `/`-separated (design.txt), and every shell
        // idiom depends on it. On the Windows dev host `current_dir()` and
        // `canonicalize()` hand back `C:\a\b` and `\\?\C:\a\b`; neither form may
        // reach `$PWD`, `pwd`, `$OLDPWD` or `$DIRSTACK`.
        let _cwd = cwd_guard();
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("clock")
            .as_nanos();
        let dir = std::env::temp_dir().join(format!("osh_slash_{}_{nanos}", std::process::id()));
        std::fs::create_dir_all(dir.join("sub")).expect("mkdir");
        let base = dir.to_string_lossy().replace('\\', "/");
        let orig = std::env::current_dir().expect("cwd");
        // `cd`, `cd -P`, `pwd`, `pwd -P` and the directory stack must all agree
        // and all be free of `\` and of the extended-length `\\?\` prefix.
        let (o, _) = run(&format!(
            "cd {base}/sub\n\
             echo \"pwd=[$(pwd)] PWD=[$PWD] OLD=[$OLDPWD] D=[${{DIRSTACK[0]}}]\"\n\
             echo \"base=${{PWD##*/}}\"\n\
             cd -P {base}/sub\n\
             echo \"P=[$PWD] pP=[$(pwd -P)]\"\n"
        ));
        std::env::set_current_dir(&orig).expect("restore cwd");
        assert!(!o.contains('\\'), "no backslash may appear in reported paths: {o:?}");
        assert!(!o.contains("//?/"), "the \\\\?\\ prefix must be stripped: {o:?}");
        assert!(o.contains("base=sub\n"), "${{PWD##*/}} must yield the basename: {o:?}");
        for line in o.lines() {
            assert!(
                line.matches(&format!("{base}/sub")).count() >= 1
                    || line.starts_with("base="),
                "every path should be the shell-form path: {line:?}"
            );
        }
        std::fs::remove_dir_all(&dir).ok();
    }

    #[test]
    fn dirstack_reflects_pushd_popd() {
        let _cwd = cwd_guard();
        // Initially DIRSTACK holds exactly the current directory (DIRSTACK[0]
        // tracks the live cwd, like `pwd`), matching bash's dynamic array.
        // (Compare against `$(pwd)`, not `$PWD`: osh does not yet re-derive the
        // inherited `$PWD` env var from the live cwd at startup, so under the
        // test harness the two can name different directories.)
        let (out, _) =
            run("test \"${DIRSTACK[0]}\" = \"$(pwd)\" && echo eq; echo \"n=${#DIRSTACK[@]}\"");
        assert_eq!(out, "eq\nn=1\n");
        // pushd grows the stack to two entries with the new dir on top and the
        // previous cwd saved beneath it; popd restores it to one.
        let t = std::env::temp_dir().to_string_lossy().replace('\\', "/");
        let src = format!(
            "orig=$(pwd); pushd \"{t}\" >/dev/null; echo \"n=${{#DIRSTACK[@]}}\"; \
             test \"${{DIRSTACK[0]}}\" = \"$(pwd)\" && echo top; \
             test \"${{DIRSTACK[1]}}\" = \"$orig\" && echo saved; \
             popd >/dev/null; echo \"n2=${{#DIRSTACK[@]}}\""
        );
        let (out2, _) = run(&src);
        assert_eq!(out2, "n=2\ntop\nsaved\nn2=1\n");
    }

    #[test]
    fn dirstack_writes_back_into_the_directory_stack() {
        let _cwd = cwd_guard();
        let t = std::env::temp_dir().to_string_lossy().replace('\\', "/");
        // A write to a saved entry reaches the stack itself, so `dirs +1` and a
        // later `popd` both see it — the assign function bash gives the name.
        let (out, _) = run(&format!(
            "pushd \"{t}\" >/dev/null; DIRSTACK[1]=/; echo \"rc=$? [${{DIRSTACK[1]}}]\"; \
             dirs +1; popd >/dev/null; echo \"pwd=$(pwd)\""
        ));
        assert_eq!(out, "rc=0 [/]\n/\npwd=/\n");
        // Element 0 is the current directory, which the stack does not own:
        // writing it is ignored and never moves the shell.
        let (out, _) = run(
            "DIRSTACK[0]=/nowhere; \
             test \"${DIRSTACK[0]}\" = \"$(pwd)\" && echo unchanged; echo \"rc=$?\"",
        );
        assert_eq!(out, "unchanged\nrc=0\n");
        // An element past the end has nowhere to go and is dropped, so neither
        // an explicit index nor an append can grow the array.
        assert_eq!(run("DIRSTACK[5]=q; echo \"$? ${#DIRSTACK[@]}\"").0, "0 1\n");
        assert_eq!(run("DIRSTACK+=(zz); echo \"$? ${#DIRSTACK[@]}\"").0, "0 1\n");
        // Being elementwise, a whole-array assignment does not replace the
        // array: with two entries, `a` is ignored, `b` written and `c` dropped.
        let (out, _) = run(&format!(
            "pushd \"{t}\" >/dev/null; DIRSTACK=(a b c); \
             echo \"$? ${{#DIRSTACK[@]}} ${{DIRSTACK[1]}}\""
        ));
        assert_eq!(out, "0 2 b\n");
        // Unsetting an element changes nothing — the value function refills it.
        let (out, _) = run(&format!(
            "pushd \"{t}\" >/dev/null; unset 'DIRSTACK[1]'; echo \"$? ${{#DIRSTACK[@]}}\""
        ));
        assert_eq!(out, "0 2\n");
        // Every other write path goes through the same hook.
        for w in [
            "printf -v 'DIRSTACK[1]' /etc",
            "(( DIRSTACK[1] = 5 ))",
            "declare 'DIRSTACK[1]'=/etc",
        ] {
            let (out, _) = run(&format!(
                "pushd \"{t}\" >/dev/null; {w}; echo \"$? ${{#DIRSTACK[@]}}\""
            ));
            assert_eq!(out, "0 2\n", "{w}");
        }
        // `unset DIRSTACK` drops the dynamic hooks with the variable and nothing
        // puts them back: the name is ordinary, and `pushd` stops touching it.
        let (out, _) = run(&format!(
            "unset DIRSTACK; DIRSTACK=(a b c); echo \"${{#DIRSTACK[@]}} ${{DIRSTACK[*]}}\"; \
             pushd \"{t}\" >/dev/null; echo \"${{DIRSTACK[*]}}\""
        ));
        assert_eq!(out, "3 a b c\na b c\n");
        // A `local` of the name is ordinary too, for the length of the call —
        // the hooks belong to the global, which catches up when the frame pops.
        let (out, _) = run(&format!(
            "f() {{ local DIRSTACK=(a b); cd \"{t}\"; echo \"${{#DIRSTACK[@]}} ${{DIRSTACK[*]}}\"; }}; \
             f; echo \"${{#DIRSTACK[@]}}\"; \
             test \"${{DIRSTACK[0]}}\" = \"$(pwd)\" && echo caught-up"
        ));
        assert_eq!(out, "2 a b\n1\ncaught-up\n");
    }

    #[test]
    fn unset_drops_a_dynamic_variables_value_function() {
        // Every one of them is unset afterwards, and ordinary: the name holds
        // whatever is assigned to it next, rather than answering dynamically.
        for n in [
            "SECONDS",
            "RANDOM",
            "SRANDOM",
            "LINENO",
            "BASHPID",
            "BASH_SUBSHELL",
            "EPOCHSECONDS",
            "EPOCHREALTIME",
            "HISTCMD",
            "BASH_ARGV0",
        ] {
            let (out, _) = run(&format!(
                "unset {n}; echo \"$? [${{{n}-UNSET}}]\"; {n}=zz; echo \"[${{{n}-UNSET}}]\""
            ));
            assert_eq!(out, "0 [UNSET]\n[zz]\n", "{n}");
        }
        // The hook each assignment used to run goes with the value function, so
        // `RANDOM=5` stores 5 instead of reseeding the generator…
        let (out, _) = run("unset RANDOM; RANDOM=5; a=$RANDOM; b=$RANDOM; [ \"$a\" = \"$b\" ] && echo stable");
        assert_eq!(out, "stable\n");
        // …and `SECONDS=5` stores 5 instead of rebasing the counter. The
        // attributes went with the binding too, so it is `--`, not `-i`.
        let (out, _) = run("unset SECONDS; SECONDS=5; declare -p SECONDS");
        assert_eq!(out, "declare -- SECONDS=\"5\"\n");
        // A name with no value function left and nothing assigned expands to
        // nothing at all.
        assert_eq!(run("unset LINENO; echo \"[$LINENO]\"").0, "[]\n");
        // It is gone from the listings and from `${!prefix@}` as well.
        assert_eq!(run("unset SECONDS; declare -p SECONDS").1, 1);
        assert_eq!(run("unset EPOCHSECONDS; echo \"${!EPOCH@}\"").0, "EPOCHREALTIME\n");
        let listed = "case \"$(declare -i)\" in *'declare -i RANDOM'*) echo present;; \
                      *) echo gone;; esac";
        assert_eq!(run(&format!("unset RANDOM; {listed}")).0, "gone\n");
        assert_eq!(run(listed).0, "present\n");
        // `unset` names the *variable*, not a function of the same name.
        let (out, _) = run("RANDOM() { echo hi; }; unset RANDOM; RANDOM; echo \"[${RANDOM-UNSET}]\"");
        assert_eq!(out, "hi\n[UNSET]\n");
        // `PPID` is readonly, so it never gets there: the unset fails and the
        // value function survives.
        let (out, status) = run("unset PPID; echo \"rc=$? [$PPID]\"");
        assert_eq!(status, 0);
        assert!(out.starts_with("rc=1 [") && !out.starts_with("rc=1 []"), "{out}");
        // A subshell's `unset` does not reach the parent.
        assert_eq!(run("( unset RANDOM ); echo \"${RANDOM:+dynamic}\"").0, "dynamic\n");
    }

    #[test]
    fn looking_a_dynamic_variable_up_fills_its_slot_in() {
        // A pristine `SECONDS` has an empty slot: no value, and not even the
        // `-i` its named form reports. One read fills both in, for every
        // listing at once.
        let i = "case \"$(declare -i)\" in *'declare -i SECONDS='*) echo valued;; \
                 *'declare -i SECONDS'*) echo bare;; *) echo gone;; esac";
        let p = "case \"$(declare -p)\" in *'declare -i SECONDS='*) echo valued;; \
                 *'declare -- SECONDS'*) echo bare;; *) echo gone;; esac";
        let s = "case \"$(set)\" in *'SECONDS='*) echo listed;; *) echo absent;; esac";
        assert_eq!(run(i).0, "gone\n");
        assert_eq!(run(p).0, "bare\n");
        assert_eq!(run(s).0, "absent\n");
        // Every way of *looking it up* counts — an expansion, a default, an
        // arithmetic mention, a set-test, and the named `declare -p`.
        for touch in [
            ": $SECONDS",
            ": ${SECONDS-x}",
            ": ${#SECONDS}",
            "(( SECONDS ))",
            "[ -v SECONDS ]",
            "declare -p SECONDS >/dev/null",
        ] {
            assert_eq!(run(&format!("{touch}; {i}")).0, "valued\n", "{touch}");
            assert_eq!(run(&format!("{touch}; {p}")).0, "valued\n", "{touch}");
            assert_eq!(run(&format!("{touch}; {s}")).0, "listed\n", "{touch}");
        }
        // Naming one without asking for a value does not: `${!prefix@}` walks
        // the table but never calls the value function.
        assert_eq!(run(&format!(": ${{!SEC@}}; {i}")).0, "gone\n");
        // A subshell's lookup does not reach the parent…
        assert_eq!(run(&format!("( : $SECONDS ); {i}")).0, "gone\n");
        assert_eq!(run(&format!("x=$( : $SECONDS ); {i}")).0, "gone\n");
        // …while a function's does, there being only the one binding.
        assert_eq!(run(&format!("f() {{ : $SECONDS; }}; f; {i}")).0, "valued\n");
        // `unset` empties the slot again, along with the rest of the binding.
        assert_eq!(run(&format!(": $SECONDS; unset SECONDS; {i}")).0, "gone\n");
        assert_eq!(run(&format!(": $SECONDS; unset SECONDS; {s}")).0, "absent\n");
        // `PPID` starts out valued, so it is in every listing from the first
        // line — including a bare `set`.
        assert_eq!(
            run("case \"$(set)\" in *'PPID='*) echo listed;; *) echo absent;; esac").0,
            "listed\n"
        );
    }

    #[test]
    fn assigning_a_dynamic_variable_fills_its_value_cell_only() {
        // The assignment stores the string in the name's value cell without
        // filling the attributes in, so `SECONDS=7` lists *with* a value and
        // *without* the `-i` a lookup would have added.
        let p = |name: &str| {
            format!(
                "case \"$(declare -p)\" in *'declare -i {name}=\"7\"'*) echo int;; \
                 *'declare -- {name}=\"7\"'*) echo plain;; \
                 *'{name}='*) echo other;; *) echo bare;; esac"
            )
        };
        assert_eq!(run(&format!("SECONDS=7; {}", p("SECONDS"))).0, "plain\n");
        assert_eq!(run(&format!("RANDOM=7; {}", p("RANDOM"))).0, "int\n");
        assert_eq!(run(&format!("SRANDOM=7; {}", p("SRANDOM"))).0, "int\n");
        assert_eq!(run(&format!("LINENO=7; {}", p("LINENO"))).0, "plain\n");
        assert_eq!(run(&format!("HISTCMD=7; {}", p("HISTCMD"))).0, "int\n");
        // …and the names whose assign function drops the string leave the slot
        // exactly as it was.
        for name in ["BASHPID", "EPOCHSECONDS", "EPOCHREALTIME", "BASH_SUBSHELL"] {
            assert_eq!(run(&format!("{name}=7; {}", p(name))).0, "bare\n", "{name}");
        }
        // A filled cell is a value, so a bare `set` lists the name…
        let s = "case \"$(set)\" in *'SECONDS=7'*) echo listed;; *) echo absent;; esac";
        assert_eq!(run(&format!("SECONDS=7; {s}")).0, "listed\n");
        // …but the attribute half is untouched, so `declare -i` still is not.
        let i = "case \"$(declare -i)\" in *'SECONDS'*) echo listed;; *) echo absent;; esac";
        assert_eq!(run(&format!("SECONDS=7; {i}")).0, "absent\n");
        assert_eq!(run(&format!("SECONDS=7; : $SECONDS; {i}")).0, "listed\n");
        // The read is still live: the assignment rebases the counter or is
        // dropped, but it never freezes the name at the assigned string.
        assert_eq!(run("LINENO=7; echo $LINENO").0, "1\n");
        assert_eq!(run("BASHPID=7; [ \"$BASHPID\" = 7 ] && echo frozen || echo live").0, "live\n");
        assert_eq!(
            run("EPOCHSECONDS=7; [ \"$EPOCHSECONDS\" = 7 ] && echo frozen || echo live").0,
            "live\n"
        );
        // A listing prints the cell, not a fresh reading, so it goes stale
        // where the named form does not: the same `RANDOM` twice running.
        let (out, _) = run(
            "declare -p RANDOM >/dev/null; \
             a=$(declare -p | grep '^declare -i RANDOM'); \
             b=$(declare -p | grep '^declare -i RANDOM'); \
             [ \"$a\" = \"$b\" ] && echo same || echo differ",
        );
        assert_eq!(out, "same\n");
        // `unset` empties the cell with the rest of the binding, and what a
        // later assignment makes is an ordinary variable.
        assert_eq!(run(&format!("SECONDS=7; unset SECONDS; {}", p("SECONDS"))).0, "bare\n");
        assert_eq!(run("SECONDS=7; unset SECONDS; SECONDS=9; echo $SECONDS").0, "9\n");
    }

    #[test]
    fn assigning_a_dynamic_variable_stores_the_number_not_the_text() {
        // What lands in the cell is the parse, and which parse depends on the
        // slot's `-i`: an arithmetic expression with it, a plain decimal
        // without — so `3+4` is 7 for `RANDOM` and 0 for `SECONDS`, until a
        // lookup has given `SECONDS` its `-i` too.
        let cell = |src: &str, name: &str| {
            run(&format!(
                "{src}; case \"$(declare -p)\" in \
                 *'{name}=\"'*) x=\"$(declare -p | grep -E '^declare -[^ ]+ {name}=')\"; \
                 echo \"${{x##*=}}\";; *) echo none;; esac"
            ))
            .0
        };
        for (val, secs, rand) in [
            ("7", "\"7\"\n", "\"7\"\n"),
            ("007", "\"7\"\n", "\"7\"\n"),
            ("-3", "\"-3\"\n", "\"-3\"\n"),
            ("zz", "\"0\"\n", "\"0\"\n"),
            ("3+4", "\"0\"\n", "\"7\"\n"),
        ] {
            assert_eq!(cell(&format!("SECONDS={val}"), "SECONDS"), secs, "SECONDS={val}");
            assert_eq!(cell(&format!("RANDOM={val}"), "RANDOM"), rand, "RANDOM={val}");
        }
        assert_eq!(cell(": $SECONDS; SECONDS=3+4", "SECONDS"), "\"7\"\n");
        // `+=` resolves against the cell: string append without the `-i`,
        // numeric addition with it.
        assert_eq!(cell("SECONDS=100; SECONDS+=5", "SECONDS"), "\"1005\"\n");
        assert_eq!(cell(": $SECONDS; SECONDS=100; SECONDS+=5", "SECONDS"), "\"105\"\n");
        assert_eq!(cell("RANDOM=100; RANDOM+=5", "RANDOM"), "\"105\"\n");
        assert_eq!(cell("SECONDS+=5", "SECONDS"), "\"5\"\n");
        // The number is what the side effect acts on, so the counter counts on
        // from it — from a negative one as readily as a positive one.
        assert_eq!(run("SECONDS=-3; echo $SECONDS").0, "-3\n");
        assert_eq!(run("SECONDS=100; SECONDS+=5; echo $SECONDS").0, "1005\n");
        // A bad expression prints its diagnostic, leaves the slot alone and
        // carries on — where the same one assigned to an ordinary `-i`
        // variable abandons the script.
        let (out, _) = run("RANDOM=1/0; echo \"rc=$? here\"");
        assert_eq!(out, "rc=0 here\n");
        assert_eq!(run("declare -i x=5; x=1/0; echo unreachable").0, "");
    }

    #[test]
    fn giving_a_dynamic_variable_an_array_kind_converts_it() {
        // The conversion carries a last reading of the value function into
        // element 0, and the slot's own attribute letters — the ones
        // `declare -p NAME` reports — along with it, as real attributes.
        // `$HISTCMD` is whatever the harness's history is up to, so take a
        // reading rather than writing the number in.
        let h = run("echo $HISTCMD").0.trim_end().to_string();
        for (decl, want) in [
            ("declare -a HISTCMD", format!("declare -ai HISTCMD=([0]=\"{h}\")\n")),
            ("declare -A HISTCMD", format!("declare -Ai HISTCMD=([0]=\"{h}\" )\n")),
            ("HISTCMD[1]=9", format!("declare -ai HISTCMD=([0]=\"{h}\" [1]=\"9\")\n")),
            ("HISTCMD+=(9)", format!("declare -ai HISTCMD=([0]=\"{h}\" [1]=\"9\")\n")),
            // The carried `-i` reaches the very element being assigned…
            ("HISTCMD[1]=3+4", format!("declare -ai HISTCMD=([0]=\"{h}\" [1]=\"7\")\n")),
            // …and the elements a literal supplies, which replace the carried
            // one outright (so `zz` is the `-i` reading of element 0 here, not
            // the value function's).
            ("declare -a HISTCMD=(zz 3+4)", "declare -ai HISTCMD=([0]=\"0\" [1]=\"7\")\n".to_string()),
            // A `local` shadowed the binding first, so there is nothing to
            // convert and the local array starts empty.
            ("f() { local -a HISTCMD; declare -p HISTCMD; }; f #", "declare -a HISTCMD\n".to_string()),
        ] {
            assert_eq!(run(&format!("{decl}; declare -p HISTCMD")).0, want, "{decl}");
        }
        // `PPID` brings its `r` across and goes on refusing.
        assert!(run("declare -a PPID; declare -p PPID").0.starts_with("declare -air PPID=([0]=\""));
        assert_eq!(run("declare -a PPID; PPID[1]=3; echo unreachable").0, "");
        // A malformed subscript converts nothing: the name is still the scalar
        // it was, `-i` and all.
        assert_eq!(run("HISTCMD[zz zz]=9; :").0, "");
        assert_eq!(
            run("(HISTCMD[zz zz]=9); declare -p HISTCMD").0,
            format!("declare -i HISTCMD=\"{h}\"\n")
        );
    }

    #[test]
    fn converting_a_dynamic_variable_takes_its_value_function_away() {
        // Element 0 is frozen at the reading the conversion took: a converted
        // `LINENO` reports the same line for ever after…
        assert_eq!(run("declare -a LINENO\necho $LINENO\necho $LINENO").0, "1\n1\n");
        // …and a converted `RANDOM` stops varying.
        let varies = "a=$RANDOM; b=$RANDOM; [ \"$a\" = \"$b\" ] && echo stable || echo varying";
        assert_eq!(run(varies).0, "varying\n");
        assert_eq!(run(&format!("declare -a RANDOM; {varies}")).0, "stable\n");
        // The binding is gone in the sense `unset` means it: nothing comes back.
        assert_eq!(run("declare -a HISTCMD; unset HISTCMD; declare -p HISTCMD").0, "");
        assert_eq!(
            run("declare -a HISTCMD; unset HISTCMD; HISTCMD=zz; declare -p HISTCMD").0,
            "declare -- HISTCMD=\"zz\"\n"
        );
        // An ordinary scalar widens the same way, which is where the carried
        // element 0 a negative subscript counts back from comes from.
        assert_eq!(run("w=5; w[1]=9; declare -p w").0, "declare -a w=([0]=\"5\" [1]=\"9\")\n");
        assert_eq!(run("w=5; w[-1]=9; declare -p w").0, "declare -a w=([0]=\"9\")\n");
    }

    #[test]
    fn a_declaration_naming_a_nameref_declares_its_target() {
        // Every attribute, kind and value lands on the target; the reference is
        // left the reference it was.
        for (decl, want) in [
            ("declare -i r", "declare -i w=\"5\""),
            ("typeset -x r", "declare -x w=\"5\""),
            ("export r", "declare -x w=\"5\""),
            ("readonly r", "declare -r w=\"5\""),
            ("declare -a r", "declare -a w=([0]=\"5\")"),
            ("declare -i r=9", "declare -i w=\"9\""),
            ("export r=9", "declare -x w=\"9\""),
            ("readonly r=9", "declare -r w=\"9\""),
            ("export -a r=9", "declare -ax w=([0]=\"9\")"),
            // …and a `-n` operand is exempt: it is about the reference.
            ("declare -n r", "declare -- w=\"5\""),
        ] {
            assert_eq!(
                run(&format!("w=5; declare -n r=w; {decl}; declare -p w r")).0,
                format!("{want}\ndeclare -n r=\"w\"\n"),
                "{decl}"
            );
        }
        // `+n` is exempt too — it takes the attribute off the reference, which
        // is then an ordinary scalar holding the target's name.
        assert_eq!(
            run("w=5; declare -n r=w; declare +n r; declare -p w r").0,
            "declare -- w=\"5\"\ndeclare -- r=\"w\"\n"
        );
        // `export -n` has no exemption either: it unexports the *target*.
        assert_eq!(
            run("w=5; declare -n r=w; export w; export -n r; declare -p w").0,
            "declare -- w=\"5\"\n"
        );
        // A chain is followed the whole way, and a target need not exist yet.
        assert_eq!(
            run("w=5; declare -n a=w; declare -n b=a; declare -i b; declare -p w").0,
            "declare -i w=\"5\"\n"
        );
        assert_eq!(
            run("declare -n r=nope; export r=5; declare -p nope").0,
            "declare -x nope=\"5\"\n"
        );
    }

    #[test]
    fn a_declaration_through_a_reference_to_an_element_splits_the_two_builtins() {
        // `declare` marks the array and stores into the element…
        let elem = "declare -a arr=(1 2); declare -n r=arr[1]";
        assert_eq!(
            run(&format!("{elem}; declare -i r; declare -p arr")).0,
            "declare -ai arr=([0]=\"1\" [1]=\"2\")\n"
        );
        assert_eq!(
            run(&format!("{elem}; declare r=zz; declare -p arr")).0,
            "declare -a arr=([0]=\"1\" [1]=\"zz\")\n"
        );
        // …while `export`/`readonly` refuse a subscript outright — yet still
        // store through the reference, and still report success.
        for tag in ["export", "readonly"] {
            assert_eq!(
                run(&format!("{elem}; {tag} r=9; echo \"rc=$?\"; declare -p arr")).0,
                "rc=0\ndeclare -a arr=([0]=\"1\" [1]=\"9\")\n",
                "{tag}"
            );
        }
        assert_eq!(
            run(&format!("{elem}; export r+=9; declare -p arr")).0,
            "declare -a arr=([0]=\"1\" [1]=\"29\")\n"
        );
        // The refused `readonly` really did not take.
        assert_eq!(
            run(&format!("{elem}; readonly r; arr[1]=x; declare -p arr")).0,
            "declare -a arr=([0]=\"1\" [1]=\"x\")\n"
        );
        // A circular chain declares nothing, and only a value that had nowhere
        // to go makes it a failure.
        let circ = "declare -n a=b; declare -n b=a";
        for decl in ["declare -i a", "export a", "readonly a"] {
            assert_eq!(run(&format!("{circ}; {decl}; echo \"rc=$?\"")).0, "rc=0\n", "{decl}");
        }
        for decl in ["export a=5", "readonly a=5"] {
            assert_eq!(run(&format!("{circ}; {decl}; echo \"rc=$?\"")).0, "rc=1\n", "{decl}");
        }
        assert_eq!(run(&format!("{circ}; declare -i a; declare -p a")).0, "declare -n a=\"b\"\n");
    }

    #[test]
    fn declaring_a_dynamic_variable_keeps_its_value_function() {
        // The attribute lands on the binding that is already there, so the
        // table's own letters stay and the value is still computed.
        for (decl, want) in [
            ("export SECONDS", "-ix"),
            ("readonly SECONDS", "-ir"),
            ("declare -u SECONDS", "-iu"),
            ("declare -t SECONDS", "-it"),
            ("declare SECONDS", "-i"),
            ("export SECONDS; export -n SECONDS", "-i"),
            ("declare -u RANDOM", "-iu"),
        ] {
            let name = if decl.contains("RANDOM") { "RANDOM" } else { "SECONDS" };
            let (out, _) = run(&format!("{decl}; declare -p {name}"));
            assert!(
                out.starts_with(&format!("declare {want} {name}=\"")) && !out.contains("=\"\""),
                "{decl}: {out}"
            );
        }
        // `PPID` is readonly to begin with, so `export` adds to `-ir`.
        assert!(run("export PPID; declare -p PPID").0.starts_with("declare -irx PPID=\""));
        // The value function is still doing the computing.
        let (out, _) = run("declare RANDOM; a=$RANDOM; b=$RANDOM; [ \"$a\" != \"$b\" ] && echo varying");
        assert_eq!(out, "varying\n");
        // What the declaration changes is that the name's slot is filled in:
        // bash's listings walk the variable table and pass over the ones that
        // are still empty, until something looks them up.
        let listed = "case \"$(declare -i)\" in *'declare -i SECONDS='*) echo valued;; \
                      *'declare -i SECONDS'*) echo bare;; *) echo gone;; esac";
        assert_eq!(run(listed).0, "gone\n");
        assert_eq!(run(&format!("declare SECONDS; {listed}")).0, "valued\n");
        // …and `RANDOM`, which a listing does report, gains its value.
        let rnd = "case \"$(declare -i)\" in *'declare -i RANDOM='*) echo valued;; \
                   *'declare -i RANDOM'*) echo bare;; *) echo gone;; esac";
        assert_eq!(run(rnd).0, "bare\n");
        assert_eq!(run(&format!("declare RANDOM; {rnd}")).0, "valued\n");
        // A bare `set` is about values, and reports it once it is visible.
        let setline = "case \"$(set)\" in *'SECONDS='*) echo listed;; *) echo absent;; esac";
        assert_eq!(run(setline).0, "absent\n");
        assert_eq!(run(&format!("declare SECONDS; {setline}")).0, "listed\n");
        // A `local` is a different thing entirely: an ordinary, unset variable
        // shadowing the dynamic one, which comes back when the frame pops.
        let (out, _) = run(
            "f() { local SECONDS; declare -p SECONDS; echo \"[${SECONDS-UNSET}]\"; }; f; \
             declare -p SECONDS",
        );
        assert!(out.starts_with("declare -- SECONDS\n[UNSET]\ndeclare -i SECONDS=\""), "{out}");
        // `unset` drops the declaration with the rest of the binding.
        assert_eq!(run("export SECONDS; unset SECONDS; declare -p SECONDS").1, 1);
        // And none of it escapes the subshell that did it.
        assert_eq!(run(&format!("( declare SECONDS ); {listed}")).0, "gone\n");
    }

    #[test]
    fn globignore_pattern_matching() {
        // Pathname-style: `*` does not cross `/`.
        let pats = build_globignore(b"*.log", false);
        assert_eq!(pats.len(), 1);
        assert!(pats[0].matches_path(b"c.log"));
        assert!(!pats[0].matches_path(b"sub/e.log"));
        assert!(!pats[0].matches_path(b"a.txt"));

        // A `/`-bearing pattern matches component-for-component.
        let pats = build_globignore(b"sub/*.log", false);
        assert!(pats[0].matches_path(b"sub/e.log"));
        assert!(!pats[0].matches_path(b"e.log"));
        assert!(!pats[0].matches_path(b"sub/d.txt"));

        // `:` separates multiple patterns; empty entries are skipped.
        let pats = build_globignore(b"*.log::*.txt:", false);
        assert_eq!(pats.len(), 2);
        assert!(pats.iter().any(|p| p.matches_path(b"c.log")));
        assert!(pats.iter().any(|p| p.matches_path(b"a.txt")));
        assert!(!pats.iter().any(|p| p.matches_path(b"keep.md")));
    }

    #[test]
    fn globignore_filesystem_filtering() {
        let _cwd = cwd_guard();
        let uniq = format!(
            "osh_globignore_{}_{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .expect("clock")
                .as_nanos()
        );
        let dir = std::path::Path::new(&uniq);
        std::fs::create_dir_all(dir).expect("mkdir");
        for n in ["a.txt", "b.txt", "c.log", ".hidden"] {
            std::fs::File::create(dir.join(n)).expect("touch");
        }
        let basename = |p: &Str| p.rsplit(|&b| b == b'/').next().unwrap_or(p).to_vec();

        // GLOBIGNORE=*.log active: drops c.log, and the dotglob effect surfaces
        // .hidden (which `*` would normally skip).
        let gi = build_globignore(format!("{uniq}/*.log").as_bytes(), false);
        let mut out = Vec::new();
        let mut failed = None;
        glob_or_literal(
            b"",
            &field_lit(&format!("{uniq}/*")),
            &mut out,
            false,
            false,
            false,
            false,
            false,
            false,
            true,
            &gi,
            &mut failed,
        );
        let mut names: Vec<Str> = out.iter().map(&basename).collect();
        names.sort();
        assert_eq!(
            names,
            vec![b".hidden".to_vec(), b"a.txt".to_vec(), b"b.txt".to_vec()]
        );

        // With GLOBIGNORE active, a `.*` pattern still excludes `.` and `..`.
        let mut out = Vec::new();
        let mut failed = None;
        glob_or_literal(
            b"",
            &field_lit(&format!("{uniq}/.*")),
            &mut out,
            false,
            false,
            false,
            false,
            false,
            false,
            true,
            &[],
            &mut failed,
        );
        let names: Vec<Str> = out.iter().map(&basename).collect();
        assert!(names.iter().all(|n| n != b"." && n != b".."));
        assert!(names.contains(&b".hidden".to_vec()));

        std::fs::remove_dir_all(dir).ok();
    }

    #[test]
    fn glob_globstar_recursive() {
        let _cwd = cwd_guard();
        // Build a small tree:  root/{a.rs, sub/{b.rs, deep/c.rs}}
        let uniq = format!(
            "osh_gstar_{}_{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .expect("clock")
                .as_nanos()
        );
        let root = std::path::Path::new(&uniq);
        std::fs::create_dir_all(root.join("sub").join("deep")).expect("mkdir");
        std::fs::File::create(root.join("a.rs")).expect("touch");
        std::fs::File::create(root.join("sub").join("b.rs")).expect("touch");
        std::fs::File::create(root.join("sub").join("deep").join("c.rs")).expect("touch");

        // `root/**/*.rs` with globstar finds every .rs at any depth.
        let mut rs = glob_expand_field(
            b"",
            &field_lit(&format!("{uniq}/**/*.rs")),
            false,
            false,
            false,
            true,
        );
        rs.sort();
        assert_eq!(
            rs,
            vec![
                format!("{uniq}/a.rs").into_bytes(),
                format!("{uniq}/sub/b.rs").into_bytes(),
                format!("{uniq}/sub/deep/c.rs").into_bytes(),
            ]
        );

        // Without globstar, `**` behaves like `*` (single level only).
        let one = glob_expand_field(
            b"",
            &field_lit(&format!("{uniq}/**/*.rs")),
            false,
            false,
            false,
            false,
        );
        assert_eq!(one, vec![format!("{uniq}/sub/b.rs").into_bytes()]);

        // Terminal `**` lists every descendant file and directory.
        let mut all = glob_expand_field(
            b"",
            &field_lit(&format!("{uniq}/**")),
            false,
            false,
            false,
            true,
        );
        all.sort();
        assert_eq!(
            all,
            vec![
                format!("{uniq}/a.rs").into_bytes(),
                format!("{uniq}/sub").into_bytes(),
                format!("{uniq}/sub/b.rs").into_bytes(),
                format!("{uniq}/sub/deep").into_bytes(),
                format!("{uniq}/sub/deep/c.rs").into_bytes(),
            ]
        );

        std::fs::remove_dir_all(root).ok();
    }

    #[test]
    fn shopt_nocaseglob_matches_case_insensitively() {
        let _cwd = cwd_guard();
        let uniq = format!(
            "osh_nocaseglob_test_{}_{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .expect("clock")
                .as_nanos()
        );
        let dir = std::path::Path::new(&uniq);
        std::fs::create_dir_all(dir).expect("mkdir");
        for n in ["README.md", "Notes.TXT"] {
            std::fs::File::create(dir.join(n)).expect("touch");
        }

        // Case-sensitive: lowercase pattern misses the uppercase-extension file.
        let field = field_lit(&format!("{uniq}/*.txt"));
        let cs = glob_expand_field(b"", &field, false, false, false, false);
        assert!(cs.is_empty());
        // With nocaseglob, `*.txt` matches `Notes.TXT`.
        let ci = glob_expand_field(b"", &field, false, true, false, false);
        assert_eq!(ci.len(), 1);
        assert!(ci[0].ends_with(b"Notes.TXT"));

        std::fs::remove_dir_all(dir).ok();
    }

    #[test]
    fn glob_no_match_stays_literal() {
        // With no match and no `nullglob`, the pattern is left as the word.
        assert_eq!(run("echo osh_definitely_no_such_glob_*.zzz").0, "osh_definitely_no_such_glob_*.zzz\n");
    }

    #[test]
    fn shopt_nullglob_removes_unmatched() {
        // With `nullglob`, an unmatched glob produces no word at all.
        assert_eq!(
            run("shopt -s nullglob; echo x osh_no_such_glob_*.zzz y").0,
            "x y\n"
        );
        // Unsetting restores the literal-word default.
        assert_eq!(
            run("shopt -s nullglob; shopt -u nullglob; echo osh_no_such_glob_*.zzz").0,
            "osh_no_such_glob_*.zzz\n"
        );
    }

    #[test]
    fn shopt_failglob_aborts_on_no_match() {
        // With `failglob`, an unmatched command-word glob is a DISCARD-class
        // expansion error: the command does not run, `$?` is 1, and the rest of
        // the *current parse unit* (the same `;`-joined line) is discarded.
        // A following *line* still runs (see the last case below).
        let (out, st) = run("shopt -s failglob; echo osh_no_such_glob_*.zzz; echo after");
        assert_eq!(out, "");
        assert_eq!(st, 1);
        // A non-glob word is unaffected by failglob.
        assert_eq!(run("shopt -s failglob; echo hello").0, "hello\n");
        // failglob also aborts an unmatched glob in an array-literal value.
        let (aout, ast) = run("shopt -s failglob; a=(osh_no_such_*.zzz); echo after");
        assert_eq!(aout, "");
        assert_eq!(ast, 1);
        // A failglob error is DISCARD-class: it aborts the rest of the current
        // parse unit (line), but a following *line* still runs and resets `$?`.
        // (Matches bash: the script continues, so the final status is 0.)
        let (nout, nst) = run("shopt -s failglob; echo osh_no_*.zzz\necho ok");
        assert_eq!(nout, "ok\n");
        assert_eq!(nst, 0);
        // Multi-line script (TD-OILS-FAILGLOB-SCRIPT): the discard scope is the
        // offending line only. A same-line trailing command is swallowed, but a
        // command on the *next* line still runs — bash discards only the failing
        // line, not the whole script. Verified byte-for-byte against bash 5.2.
        let (mout, mst) =
            run("shopt -s failglob\necho osh_no_*.zzz; echo also_skipped\necho done");
        assert_eq!(mout, "done\n");
        assert_eq!(mst, 0);
    }

    #[test]
    fn shopt_query_status() {
        // `shopt -q name` returns 0 iff the option is set.
        assert_eq!(run("shopt -q nullglob; echo $?").0, "1\n");
        assert_eq!(run("shopt -s nullglob; shopt -q nullglob; echo $?").0, "0\n");
    }

    #[test]
    fn shopt_unknown_name_errors() {
        // An unknown option name is a status-1 error.
        assert_eq!(run("shopt -s no_such_option_xyz; echo $?").0, "1\n");
    }

    #[test]
    fn shopt_o_queries_set_o_options() {
        // `shopt -o NAME` operates on `set -o` options, not shopt options.
        // Off by default → status 1, and the listing uses `%-15s\t%s`.
        assert_eq!(
            run("shopt -o noclobber; echo $?").0,
            "noclobber      \toff\n1\n"
        );
        // Enabling via `set -o` is reflected; `-q` suppresses output.
        assert_eq!(
            run("set -o noclobber; shopt -qo noclobber; echo $?").0,
            "0\n"
        );
        // `shopt -so NAME` enables the option (like `set -o NAME`).
        assert_eq!(
            run("shopt -so noclobber; [[ -o noclobber ]] && echo on").0,
            "on\n"
        );
        // A truly unknown option name is a status-1 error.
        assert_eq!(run("shopt -o bogus_xyz 2>/dev/null; echo $?").0, "1\n");
    }

    #[test]
    fn shopt_listing_is_padded() {
        // The plain `shopt` listing pads the name to 15 then a TAB (bash).
        assert_eq!(run("shopt nullglob").0, "nullglob       \toff\n");
    }

    #[test]
    fn shopt_dotglob_includes_hidden() {
        let _cwd = cwd_guard();
        let uniq = format!(
            "osh_dotglob_test_{}_{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .expect("clock")
                .as_nanos()
        );
        let dir = std::path::Path::new(&uniq);
        std::fs::create_dir_all(dir).expect("mkdir");
        for n in ["a.txt", ".hidden"] {
            std::fs::File::create(dir.join(n)).expect("touch");
        }

        // Without dotglob, `*` skips the dotfile; with it, the dotfile is
        // included (but never `.`/`..`).
        let field = field_lit(&format!("{uniq}/*"));
        let plain = glob_expand_field(b"", &field, false, false, false, false);
        assert!(plain.iter().all(|p| !p.ends_with(b".hidden")));
        let with_dot = glob_expand_field(b"", &field, true, false, false, false);
        assert!(with_dot.iter().any(|p| p.ends_with(b".hidden")));
        assert!(with_dot.iter().all(|p| {
            let b = p.rsplit(|&b| b == b'/').next().unwrap_or(p);
            b != b"." && b != b".."
        }));

        std::fs::remove_dir_all(dir).ok();
    }

    #[test]
    fn dir_stack_pushd_popd_dirs() {
        // Mutates the process-global cwd, so serialize against the cwd-relative
        // glob tests.
        let _cwd = cwd_guard();
        let orig = std::env::current_dir().expect("cwd");
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("clock")
            .as_nanos();
        let uniq = format!("osh_dirstack_{}_{}", std::process::id(), nanos);
        let da = std::env::temp_dir().join(format!("{uniq}_a"));
        let db = std::env::temp_dir().join(format!("{uniq}_b"));
        std::fs::create_dir_all(&da).expect("mkdir a");
        std::fs::create_dir_all(&db).expect("mkdir b");
        // Feed the shell forward-slash paths (accepted by the OS on all
        // platforms); the stored/echoed paths come back in native form.
        let pa = da.to_string_lossy().replace('\\', "/");
        let pb = db.to_string_lossy().replace('\\', "/");

        // pushd a, pushd b -> stack top is b, next is a. popd returns to a.
        let script = format!(
            "pushd {pa}\npushd {pb}\necho ---\ndirs +0\ndirs +1\npopd\necho ===\ndirs +0"
        );
        let (o, _) = run(&script);

        // Restore the process cwd before asserting (run() moved it).
        std::env::set_current_dir(&orig).expect("restore cwd");

        let lines: Vec<&str> = o.lines().collect();
        let dash = lines.iter().position(|l| *l == "---").expect("--- marker");
        let eq = lines.iter().position(|l| *l == "===").expect("=== marker");
        // After both pushes: +0 is b, +1 is a.
        assert!(
            lines[dash + 1].ends_with(&format!("{uniq}_b")),
            "dirs +0 should be b, got {:?}",
            lines[dash + 1]
        );
        assert!(
            lines[dash + 2].ends_with(&format!("{uniq}_a")),
            "dirs +1 should be a, got {:?}",
            lines[dash + 2]
        );
        // After popd, the current directory is a.
        assert!(
            lines[eq + 1].ends_with(&format!("{uniq}_a")),
            "dirs +0 after popd should be a, got {:?}",
            lines[eq + 1]
        );

        std::fs::remove_dir_all(&da).ok();
        std::fs::remove_dir_all(&db).ok();
    }

    #[test]
    fn cd_uses_cdpath_and_echoes() {
        // Mutates the process-global cwd; serialize with the other cwd tests.
        let _cwd = cwd_guard();
        let orig = std::env::current_dir().expect("cwd");
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("clock")
            .as_nanos();
        let uniq = format!("osh_cdpath_{}_{}", std::process::id(), nanos);
        let tmp = std::env::temp_dir();
        let base = tmp.join(&uniq);
        let sub = base.join("proj");
        std::fs::create_dir_all(&sub).expect("mkdir");
        let ptmp = tmp.to_string_lossy().replace('\\', "/");

        // `CDPATH` is a colon-separated list; on the Windows host we use a
        // *relative* entry (the unique dir name) so the drive-letter `:` in an
        // absolute path does not collide with the list separator. First cd into
        // the temp dir (an explicit absolute path, so CDPATH is not consulted),
        // then `cd proj` resolves through CDPATH=<uniq> to <uniq>/proj.
        let (o, st) = run(&format!("cd {ptmp}\nCDPATH={uniq}\ncd proj\npwd"));
        std::env::set_current_dir(&orig).expect("restore cwd");

        assert_eq!(st, 0, "cd via CDPATH should succeed; output {o:?}");
        // `pwd` (captured) confirms the relative name resolved under CDPATH.
        // (The `cd` destination echo itself goes to the real stdout, matching
        // the existing `cd -` behavior, so it is not in the captured buffer.)
        assert!(o.contains(&uniq), "expected cwd under {uniq}, got {o:?}");
        assert!(o.contains("proj"), "expected to land in proj, got {o:?}");

        std::fs::remove_dir_all(&base).ok();
    }

    #[test]
    fn cd_physical_flag_changes_directory() {
        let _cwd = cwd_guard();
        let orig = std::env::current_dir().expect("cwd");
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("clock")
            .as_nanos();
        let uniq = format!("osh_cdp_{}_{}", std::process::id(), nanos);
        let dir = std::env::temp_dir().join(&uniq);
        std::fs::create_dir_all(&dir).expect("mkdir");
        let pdir = dir.to_string_lossy().replace('\\', "/");

        // `cd -P dir` accepts the flag and changes directory (canonical PWD).
        let (o, st) = run(&format!("cd -P {pdir}\npwd"));
        std::env::set_current_dir(&orig).expect("restore cwd");

        assert_eq!(st, 0, "cd -P should succeed; output {o:?}");
        assert!(o.contains(&uniq), "expected cwd under {uniq}, got {o:?}");

        std::fs::remove_dir_all(&dir).ok();
    }

    #[test]
    fn time_keyword_runs_pipeline() {
        // `time` runs the pipeline transparently: stdout is unaffected (the
        // report goes to stderr) and the pipeline's exit status is preserved.
        assert_eq!(run("time echo hi").0, "hi\n");
        assert_eq!(run("time false").1, 1);
        assert_eq!(run("time -p true").1, 0);
        // Timing a multi-stage pipeline still streams stdout normally.
        assert_eq!(run("time echo hi | cat").0, "hi\n");
    }

    #[test]
    fn time_report_formatting() {
        // POSIX `-p` form: two decimals, space-separated, no leading newline.
        let p = Shell::format_time_report(1.5, true);
        assert_eq!(p, "real 1.50\nuser 0.00\nsys 0.00\n");
        // Default (bash) form: leading newline, tab-separated, NmS.SSSs.
        let d = Shell::format_time_report(62.25, false);
        assert_eq!(d, "\nreal\t1m2.250s\nuser\t0m0.000s\nsys\t0m0.000s\n");
        let z = Shell::format_time_report(0.0, false);
        assert_eq!(z, "\nreal\t0m0.000s\nuser\t0m0.000s\nsys\t0m0.000s\n");
    }

    #[test]
    fn trap_set_print_reset() {
        // Setting a trap and printing it back in re-inputtable form.
        let (o, _) = run("trap 'echo bye' EXIT; trap -p");
        assert!(o.contains("trap -- 'echo bye' EXIT"), "got {o:?}");

        // A signal name with/without SIG prefix, case-insensitive, normalizes.
        // `trap -p` renders real signals with bash's `SIG` prefix.
        let (o, _) = run("trap 'x' sigint; trap -p int");
        assert!(o.contains("trap -- 'x' SIGINT"), "got {o:?}");

        // `trap - SIG` resets (removes) the handler.
        let (o, _) = run("trap 'x' INT; trap - INT; trap -p");
        assert!(!o.contains("INT"), "reset should remove INT, got {o:?}");

        // Ignore form ('') round-trips (real signal → `SIG`-prefixed display).
        let (o, _) = run("trap '' TERM; trap -p TERM");
        assert!(o.contains("trap -- '' SIGTERM"), "got {o:?}");

        // An invalid spec is a status-1 error.
        let (_, st) = run("trap 'x' NOPE");
        assert_eq!(st, 1);
    }

    #[test]
    fn trap_print_sig_prefix_and_order() {
        // bash's `trap -p` prints real signals with a `SIG` prefix but the
        // pseudo-signals (EXIT/ERR/DEBUG/RETURN) bare, ordered EXIT, then real
        // signals by number, then DEBUG, ERR, RETURN.
        let (o, _) = run(
            "trap 'e' EXIT; trap 'h' HUP; trap 'i' INT; \
             trap 'd' DEBUG; trap 'r' RETURN; trap 'x' ERR; trap -p",
        );
        // The DEBUG trap fires before each command, emitting stray `d` lines;
        // keep only the `trap --` listing lines to check prefix and ordering.
        let lines: Vec<&str> = o.lines().filter(|l| l.starts_with("trap --")).collect();
        assert_eq!(
            lines,
            vec![
                "trap -- 'e' EXIT",
                "trap -- 'h' SIGHUP",
                "trap -- 'i' SIGINT",
                "trap -- 'd' DEBUG",
                "trap -- 'x' ERR",
                "trap -- 'r' RETURN",
            ],
            "got {o:?}"
        );
    }

    #[test]
    fn io_error_message_maps_posix_strerror() {
        // The mapper renders bash/POSIX strerror text rather than the host
        // `std::io::Error` Display (which on Windows reads e.g. "The system
        // cannot find the file specified. (os error 2)").
        use std::io::{Error, ErrorKind};
        assert_eq!(
            io_error_message(&Error::from(ErrorKind::NotFound)),
            "No such file or directory"
        );
        assert_eq!(
            io_error_message(&Error::from(ErrorKind::PermissionDenied)),
            "Permission denied"
        );
        assert_eq!(
            io_error_message(&Error::from(ErrorKind::AlreadyExists)),
            "File exists"
        );
        // No host `os error NN` suffix leaks through for a mapped kind.
        assert!(!io_error_message(&Error::from(ErrorKind::NotFound)).contains("os error"));
    }

    #[test]
    fn return_numeric_arg_required() {
        // A non-numeric `return` arg prints the diagnostic, yields status 2, and
        // still unwinds the function (the trailing echo must not run). `f 2>&1`
        // folds the error onto the captured stdout.
        let (o, _) = run("f() { return abc; echo unreached; }; f 2>&1; echo rc=$?");
        assert!(!o.contains("unreached"), "return did not unwind: {o:?}");
        assert!(o.contains("return: abc: numeric argument required"), "got {o:?}");
        assert!(o.contains("rc=2"), "got {o:?}");
        // A numeric arg still works normally.
        assert_eq!(run("f() { return 7; }; f; echo $?").0, "7\n");
        // At top level (no function/sourced-script context) bash validates the
        // argument numerically *before* the context check, so a non-numeric
        // `return` arg emits BOTH the "numeric argument required" line and the
        // "can only return" line, exiting 2.
        let (o, s) = run("return -Z 2>&1");
        assert!(o.contains("return: -Z: numeric argument required"), "got {o:?}");
        assert!(o.contains("return: can only `return' from a function or sourced script"), "got {o:?}");
        assert_eq!(s, 2);
    }

    #[test]
    fn getopts_rejects_leading_options() {
        // getopts has no options of its own; bash's internal_getopt rejects any
        // leading `-X` letter (`getopts: -X: invalid option` + usage, exit 2),
        // treats `--` as end-of-options, and a bare `-` as the optstring operand.
        let (o, s) = run("getopts -Z 2>&1");
        assert!(o.contains("getopts: -Z: invalid option"), "got {o:?}");
        assert!(o.contains("getopts: usage: getopts optstring name [arg ...]"), "got {o:?}");
        assert_eq!(s, 2);
        let (o, s) = run("getopts -ab name 2>&1");
        assert!(o.contains("getopts: -a: invalid option"), "got {o:?}");
        assert_eq!(s, 2);
        // `--` ends option parsing: optstring "ab", no args to scan → status 1.
        assert_eq!(run("getopts -- ab name 2>&1").1, 1);
        // A bare `-` is the optstring, not an option.
        assert_eq!(run("getopts - name 2>&1").1, 1);
    }

    #[test]
    fn trap_list_uses_tab_separators() {
        // Entries within a row are tab-separated (not space-padded), matching
        // bash's `trap -l`/`kill -l` layout.
        let (o, _) = run("trap -l");
        let first = o.lines().next().unwrap_or("");
        assert!(first.starts_with(" 1) SIGHUP\t"), "got {first:?}");
        assert!(first.contains("\t 2) SIGINT\t"), "got {first:?}");
    }

    #[test]
    fn kill_is_a_builtin() {
        // `kill` must be an osh builtin (not delegated to an external), so it
        // works on the SlateOS target where no `/usr/bin/kill` exists and can
        // resolve osh's own job specs.
        assert_eq!(run("type -t kill").0, "builtin\n");
    }

    #[test]
    fn kill_l_lists_and_translates() {
        // `kill -l` prints the same columnar table as `trap -l`.
        assert_eq!(run("kill -l").0, run("trap -l").0);
        // `-L` is an accepted alias.
        assert_eq!(run("kill -L").0, run("kill -l").0);
        // Number → name and name → number (with and without a SIG prefix).
        assert_eq!(run("kill -l 9").0, "KILL\n");
        assert_eq!(run("kill -l 9 15").0, "KILL\nTERM\n");
        assert_eq!(run("kill -l TERM").0, "15\n");
        assert_eq!(run("kill -l SIGTERM").0, "15\n");
        // Exit-status form (128 + signum) decodes to the signal name.
        assert_eq!(run("kill -l 137").0, "KILL\n");
    }

    #[test]
    fn kill_l_rejects_bad_specs() {
        // An unknown name and an out-of-range number are invalid specs (rc 1).
        let (o, s) = run("kill -l BOGUS 2>&1");
        assert!(o.contains("kill: BOGUS: invalid signal specification"), "got {o:?}");
        assert_eq!(s, 1);
        let (o, s) = run("kill -l 99 2>&1");
        assert!(o.contains("kill: 99: invalid signal specification"), "got {o:?}");
        assert_eq!(s, 1);
    }

    #[test]
    fn nsig_is_one_past_the_last_real_signal() {
        // `NSIG` is what bounds a *numeric* signal spec and where the pseudo
        // signals are filed, so it has to stay in step with the table it bounds:
        // if a signal is ever appended to `SIGNALS`, `NSIG` must move with it or
        // `kill -l` would refuse the new signal's number and `DEBUG` would
        // collide with it.
        let last = SIGNALS.last().expect("the signal table is not empty").0;
        assert_eq!(u16::from(last) + 1, NSIG);
        // …and the pseudo signals sit directly above, in bash's order.
        assert_eq!(PSEUDO_SIGNALS.first().map(|(n, _)| *n), Some(NSIG));
        for (i, (num, _)) in PSEUDO_SIGNALS.iter().enumerate() {
            assert_eq!(*num, NSIG + u16::try_from(i).expect("three entries fit"));
            // A number can never name one of them, however it is spelled.
            assert_eq!(decode_signal(num.to_string().as_bytes()), None);
        }
    }

    #[test]
    fn kill_usage_and_bad_signal_errors() {
        // No operands → the usage message, which (like bash) carries no
        // `line N:` location prefix, and exits 2.
        let (o, s) = run("kill 2>&1");
        assert!(o.starts_with("kill: usage: kill [-s sigspec"), "got {o:?}");
        assert_eq!(s, 2);
        // A bad `-SIGSPEC` is an invalid signal specification (rc 1).
        let (o, s) = run("kill -BOGUS 123 2>&1");
        assert!(o.contains("kill: BOGUS: invalid signal specification"), "got {o:?}");
        assert_eq!(s, 1);
        // A pid osh never spawned is "No such process" (rc 1).
        let (o, s) = run("kill 999999 2>&1");
        assert!(o.contains("kill: (999999) - No such process"), "got {o:?}");
        assert_eq!(s, 1);
    }

    #[test]
    fn self_kill_fires_trap() {
        // `kill -SIG $$` delivers the signal to the shell's own trap machinery
        // (SlateOS/Windows have no real Unix signals, so self-delivery is
        // simulated synchronously). A registered handler runs, then execution
        // continues — matching bash. (The handler sets a variable rather than
        // echoing, since the test harness captures fd 1 while a trap body writes
        // to the inherited fd 1; in a real `-c`/script shell the two coincide.)
        assert_eq!(
            run("trap 'M=hit' USR1; kill -USR1 $$; echo \"$M after\"").0,
            "hit after\n"
        );
        // Signal names, not numbers, key the handler: TERM fires just the same.
        assert_eq!(
            run("trap 'T=1' TERM; kill -TERM $$; echo \"done$T\"").0,
            "done1\n"
        );
    }

    #[test]
    fn self_kill_default_disposition() {
        // With no trap, a terminating signal unwinds the shell with 128+signum;
        // `echo after` never runs. TERM=15 → 143.
        let (o, s) = run("kill -TERM $$; echo after");
        assert_eq!(o, "");
        assert_eq!(s, 143);
        // A default-ignore signal (CHLD=17) is a no-op; the shell continues.
        assert_eq!(run("kill -CHLD $$; echo survived").0, "survived\n");
        // bash ignores QUIT for the shell process, so it too is survivable.
        assert_eq!(run("kill -QUIT $$; echo survived").0, "survived\n");
        // `trap '' SIG` (ignore) overrides the terminating default.
        assert_eq!(
            run("trap '' TERM; kill -TERM $$; echo survived").0,
            "survived\n"
        );
    }

    #[test]
    fn self_kill_trap_exit_unwinds() {
        // An `exit` inside a signal trap terminates the shell with the trap's
        // code; the command after the `kill` does not run (bash). The trap sets
        // a side-effect var rather than echoing, since the capture harness does
        // not intercept trap-emitted stdout (in a real `-c`/script shell it
        // would). What matters here: `echo after` is unwound and the status is
        // the trap's exit code.
        let (o, s) = run("trap 'RAN=1; exit 7' TERM; kill -TERM $$; echo after");
        assert_eq!(o, "");
        assert_eq!(s, 7);
    }

    #[test]
    fn trap_list_names() {
        let (o, st) = run("trap -l");
        assert_eq!(st, 0);
        assert!(o.contains("SIGINT"));
        assert!(o.contains("SIGTERM"));
        assert!(o.contains("SIGKILL"));
    }

    #[test]
    fn trap_exit_fires_once() {
        let mut sh = Shell::new();
        sh.run_source("trap 'TRAP_MARK=1' EXIT".as_bytes());
        // The handler has not run yet — only stored.
        assert!(!sh.vars.contains_key("TRAP_MARK"));
        sh.run_exit_trap();
        assert_eq!(sh.vars.get("TRAP_MARK").map(as_text), Some("1"));
        // A second call is a no-op (fires at most once).
        sh.vars.remove("TRAP_MARK");
        sh.run_exit_trap();
        assert!(!sh.vars.contains_key("TRAP_MARK"));
    }

    #[test]
    fn subshell_lists_inherited_traps_but_does_not_fire_them() {
        // bash resets a subshell's non-ignored traps for *firing* but keeps the
        // inherited command strings listable via `trap -p`. osh mirrors this with
        // a display-only shadow map.
        // (The `run` harness does not fire the top-level EXIT trap on return, so
        // the only output is the subshell's `trap -p` listing of the inherited
        // trap string.)
        let (o, _) = run("trap 'echo hi' EXIT; (trap -p)");
        assert_eq!(o, "trap -- 'echo hi' EXIT\n");
        // The inherited EXIT trap does not re-fire on subshell exit.
        let (o2, _) = run("trap 'echo hi' EXIT; (echo insub); echo end");
        assert_eq!(o2, "insub\nend\n");
        // Re-setting the trap inside the subshell replaces the shadow entry, and
        // `trap - SIG` clears it so `trap -p SIG` prints nothing.
        let (o3, _) = run("trap 'echo a' INT; (trap 'echo new' INT; trap -p INT)");
        assert_eq!(o3, "trap -- 'echo new' SIGINT\n");
        let (o4, _) = run("trap 'echo a' INT; (trap - INT; trap -p INT; echo cleared)");
        assert_eq!(o4, "cleared\n");
        // A *pipeline stage* is also a subshell, so it likewise displays the
        // inherited trap string (TD-OILS-SUBSHELL-TRAP-DISPLAY symptom): bash
        // prints `trap -- 'echo x' SIGINT` for `trap -p | cat`.
        let (o5, _) = run("trap 'echo x' INT; trap -p | cat");
        assert_eq!(o5, "trap -- 'echo x' SIGINT\n");
        // The default `DEBUG` pseudo-trap is *not* inherited for firing in a
        // subshell (no `functrace`), yet its string is still listable there.
        let (o6, _) = run("trap 'echo dbg' DEBUG; (trap -p DEBUG)");
        assert_eq!(o6, "trap -- 'echo dbg' DEBUG\n");
    }

    #[test]
    fn subshell_exit_trap_fires() {
        // A subshell that installs its own EXIT trap fires it when the subshell
        // exits — for `( … )`, a command substitution, and a pipeline stage —
        // while the parent's inherited EXIT trap is *not* re-fired in a subshell.
        // Output is folded into stdout with `2>&1`-free echoes so `run` captures.
        let (o, _) = run("( trap 'echo sub' EXIT; echo insub ); echo out");
        assert_eq!(o, "insub\nsub\nout\n");

        // An explicit `exit N` inside the subshell still fires the trap, and the
        // subshell's status ($?) is the exit code, not the trap's.
        let (o2, _) = run("( trap 'echo sub' EXIT; exit 3 ); echo \"out=$?\"");
        assert_eq!(o2, "sub\nout=3\n");

        // The parent EXIT trap is reset (not fired) inside a subshell that does
        // not set its own — only the parent's fires, once, at real exit.
        let mut sh = Shell::new();
        let buf = capture_sink();
        {
            let mut out = Out::Capture(buf.clone());
            let prog = parse("trap 'echo P' EXIT; ( echo in ); echo out".as_bytes()).expect("parse");
            sh.exec_program(&prog, &mut out, &StdinSrc::Inherit);
        }
        let buf = take_capture(&buf);
        assert_eq!(String::from_utf8_lossy(&buf), "in\nout\n");
        // The parent's EXIT trap only fires now, at the real shell exit.
        let buf2 = capture_sink();
        {
            let mut out = Out::Capture(buf2.clone());
            sh.run_exit_trap_out(&mut out, &StdinSrc::Inherit);
        }
        let buf2 = take_capture(&buf2);
        assert_eq!(String::from_utf8_lossy(&buf2), "P\n");

        // A command substitution captures its own EXIT-trap output in the result.
        let (o3, _) = run("x=$( trap 'echo t' EXIT; echo body ); echo \"[$x]\"");
        assert_eq!(o3, "[body\nt]\n");

        // A pipeline-stage subshell fires its own EXIT trap.
        let (o4, _) = run("false | ( trap 'echo PS' EXIT; cat >/dev/null ); echo done");
        assert_eq!(o4, "PS\ndone\n");
    }

    #[test]
    fn trap_err_fires_on_failure() {
        let mut sh = Shell::new();
        sh.run_source("trap 'ERR_HIT=1' ERR\nfalse".as_bytes());
        assert_eq!(sh.vars.get("ERR_HIT").map(as_text), Some("1"));

        // ERR does not fire for a successful command...
        let mut sh = Shell::new();
        sh.run_source("trap 'ERR_HIT=1' ERR\ntrue".as_bytes());
        assert!(!sh.vars.contains_key("ERR_HIT"));

        // ...nor for a failure inside an `if` condition (exempt context).
        let mut sh = Shell::new();
        sh.run_source("trap 'ERR_HIT=1' ERR\nif false; then :; fi".as_bytes());
        assert!(!sh.vars.contains_key("ERR_HIT"));
    }

    #[test]
    fn trap_debug_fires_before_each_command() {
        let mut sh = Shell::new();
        sh.run_source("trap 'DBG=$((DBG+1))' DEBUG\n:\n:\n:".as_bytes());
        assert_eq!(sh.vars.get("DBG").map(as_text), Some("3"));
    }

    #[test]
    fn trap_return_fires_on_function_return() {
        // A RETURN trap fires on function return only when the trap is inherited
        // by the function — i.e. under `functrace` (`set -T`), the function's
        // trace attribute, or when the trap is installed inside the function.
        // Without any of those it does NOT fire (bash's default); see the
        // `return_trap_*` tests for the full matrix.
        let mut sh = Shell::new();
        sh.run_source("set -T\ntrap 'RET=1' RETURN\nf() { :; }\nf".as_bytes());
        assert_eq!(sh.vars.get("RET").map(as_text), Some("1"));
    }

    #[test]
    fn exit_inside_synchronous_trap_unwinds_shell() {
        // bash: `exit N` executed inside an ERR/DEBUG/RETURN/EXIT handler
        // terminates the *shell* with N — it does not merely end the handler.
        // Commands after the triggering command must not run.

        // ERR: `false` fires the handler, which exits 7.
        let (o, s) = run("trap 'exit 7' ERR; false; echo after");
        assert_eq!(o, "");
        assert_eq!(s, 7);

        // DEBUG: fires *before* the first command, so nothing runs at all.
        let (o, s) = run("trap 'exit 5' DEBUG; echo a; echo b");
        assert_eq!(o, "");
        assert_eq!(s, 5);

        // RETURN (under functrace, so the function inherits the trap): the
        // handler exits when `f` returns, so `echo after` is unwound.
        let (o, s) = run("set -T; trap 'exit 4' RETURN; f() { echo in; }; f; echo after");
        assert_eq!(o, "in\n");
        assert_eq!(s, 4);

        // A handler that does *not* exit still leaves `$?` untouched.
        let (o, s) = run("trap 'true' ERR; false; echo after");
        assert_eq!(o, "after\n");
        assert_eq!(s, 0);
    }

    /// Write `body` to a fresh temp script and return its path. The caller
    /// removes it.
    fn scratch_script(tag: &str, body: &str) -> String {
        let path = uniq_path(tag);
        std::fs::write(&path, body).expect("write script");
        path
    }

    /// Run `src` and return the final value of shell variable `var`. Asserting
    /// trap-firing *order* through an accumulator variable rather than stdout
    /// keeps these cases independent of where each handler's output is routed
    /// (see `trap_output_goes_to_the_callers_sink` for that half).
    fn run_marker(src: &str, var: &str) -> String {
        let mut sh = Shell::new();
        sh.run_source(src.as_bytes());
        sh.vars.get(var).map(|v| as_text(v).to_string()).unwrap_or_default()
    }

    #[test]
    fn return_trap_fires_for_sourced_script() {
        // bash fires the RETURN trap when a script run with `.`/`source`
        // finishes — and, unlike the function case, *without* needing
        // functrace. Every expectation below was captured from bash 5.x running
        // the identical script.
        let plain = scratch_script("srcret", "S=\"$S insrc\"\n");
        let ret3 = scratch_script("srcret3", "S=\"$S insrc\"\nreturn 3\nS=\"$S never\"\n");
        let nested = scratch_script("srcnest", &format!(". {plain}\nS=\"$S outertail\"\n"));
        let withfn = scratch_script("srcfn", "g() { :; }\ng\n");
        let t = "trap 'S=\"$S ret\"' RETURN";

        // Natural end of the script.
        assert_eq!(
            run_marker(&format!("{t}; . {plain}; S=\"$S after\""), "S"),
            " insrc ret after"
        );
        // `return N` from the script: the trap still fires, and the script's
        // status survives it (the trap must not clobber `$?`).
        assert_eq!(
            run_marker(&format!("{t}; . {ret3}; S=\"$S after=$?\""), "S"),
            " insrc ret after=3"
        );
        // A nested `source` fires its own RETURN too — a source frame does not
        // mask RETURN for an inner source.
        assert_eq!(
            run_marker(&format!("{t}; . {nested}; S=\"$S after\""), "S"),
            " insrc ret outertail ret after"
        );
        // But the firing IS gated on the *caller's* mask: a `source` inside an
        // untraced function fires neither the source's nor the function's
        // RETURN. With functrace both fire.
        assert_eq!(
            run_marker(&format!("{t}; h() {{ . {plain}; }}; h; S=\"$S after\""), "S"),
            " insrc after"
        );
        assert_eq!(
            run_marker(
                &format!("set -T; {t}; h() {{ . {plain}; }}; h; S=\"$S after\""),
                "S"
            ),
            " insrc ret ret after"
        );
        // A function *defined and called inside* the script keeps the normal
        // no-functrace masking: only the source's own RETURN fires.
        assert_eq!(
            run_marker(&format!("{t}; . {withfn}; S=\"$S after\""), "S"),
            " ret after"
        );

        for p in [&plain, &ret3, &nested, &withfn] {
            std::fs::remove_file(p).ok();
        }
    }

    #[test]
    fn sourced_script_is_a_debug_trap_frame() {
        // bash masks the DEBUG trap for commands *inside* a sourced script
        // unless functrace is on — the same rule as an untraced function — but
        // still fires it for the `. script` word itself. ERR, by contrast,
        // fires inside a source regardless of `errtrace`.
        let plain = scratch_script("srcdbg", "S=\"$S insrc\"\n");
        let dbg = "trap 'D=\"$D|$BASH_COMMAND\"' DEBUG";

        assert_eq!(
            run_marker(&format!("{dbg}; . {plain}; X=1"), "D"),
            format!("|. {plain}|X=1")
        );
        assert_eq!(
            run_marker(&format!("set -T; {dbg}; . {plain}; X=1"), "D"),
            format!("|. {plain}|S=\"$S insrc\"|X=1")
        );

        let failing = scratch_script("srcerr", "false\nS=\"$S tail\"\n");
        for prelude in ["", "set -E; "] {
            assert_eq!(
                run_marker(
                    &format!("{prelude}trap 'S=\"$S err\"' ERR; . {failing}; S=\"$S after\""),
                    "S"
                ),
                " err tail after",
                "prelude {prelude:?}"
            );
        }

        std::fs::remove_file(&plain).ok();
        std::fs::remove_file(&failing).ok();
    }

    #[test]
    fn eval_and_source_write_to_the_callers_sink() {
        // bash: `x=$(eval echo hi)` and `x=$(. script)` both capture. osh used
        // to run both through a fresh `Out::Inherit`, so the output escaped to
        // the real fd 1 and the substitution came back empty.
        assert_eq!(run("x=$(eval echo hi); echo \"cap=[$x]\"").0, "cap=[hi]\n");
        let plain = scratch_script("srccap", "echo in-src\n");
        assert_eq!(
            run(&format!("y=$(. {plain}); echo \"cap=[$y]\"")).0,
            "cap=[in-src]\n"
        );
        std::fs::remove_file(&plain).ok();
    }

    #[test]
    fn exit_unwinds_out_of_eval() {
        // `eval 'exit 3'` terminates the shell (bash), rather than just ending
        // the evaluated string.
        let (o, s) = run("eval 'echo a; exit 3'; echo after");
        assert_eq!(o, "a\n");
        assert_eq!(s, 3);
    }

    #[test]
    fn exit_unwinds_out_of_a_sourced_script() {
        // `exit N` inside a sourced script terminates the *shell*, not just the
        // script (`return` is the script-only unwind). Same for an `exit` in the
        // RETURN trap that fires when the script finishes.
        let quitter = scratch_script("srcexit", "echo in-src\nexit 6\necho never\n");
        let (o, s) = run(&format!(". {quitter}; echo after"));
        assert_eq!(o, "in-src\n");
        assert_eq!(s, 6);

        let plain = scratch_script("srcexit2", "echo in-src\n");
        let (o, s) = run(&format!("trap 'exit 4' RETURN; . {plain}; echo after"));
        assert_eq!(o, "in-src\n");
        assert_eq!(s, 4);

        std::fs::remove_file(&quitter).ok();
        std::fs::remove_file(&plain).ok();
    }

    #[test]
    fn exit_inside_exit_trap_overrides_status() {
        // bash: an `exit N` inside the EXIT trap replaces the shell's exit
        // status with N. Without one, the pre-trap status is preserved.
        let mut sh = Shell::new();
        sh.run_source("trap 'exit 9' EXIT".as_bytes());
        sh.last_status = 2;
        sh.run_exit_trap();
        assert_eq!(sh.last_status, 9);

        let mut sh = Shell::new();
        sh.run_source("trap 'MARK=1' EXIT".as_bytes());
        sh.last_status = 3;
        sh.run_exit_trap();
        assert_eq!(sh.last_status, 3);
        assert_eq!(sh.vars.get("MARK").map(as_text), Some("1"));
    }

    /// A trap handler runs in the current shell, so its output goes to whatever
    /// the shell's stdout currently is — inside `$( … )` that is the capture, not
    /// the terminal. (In bash the handler literally runs in the substitution's
    /// subshell, whose fd 1 is the pipe; osh emulates the subshell with an
    /// `Out::Capture` sink, so the sink has to be threaded into the handler.)
    #[test]
    fn trap_output_goes_to_the_callers_sink() {
        let (o, _) = run("x=$(trap 'echo T' DEBUG; :); echo \"[$x]\"");
        assert_eq!(o, "[T]\n");
        // …and an EXIT trap set inside the substitution likewise.
        let (o, _) = run("x=$(trap 'echo E' EXIT; echo body); echo \"[$x]\"");
        assert_eq!(o, "[body\nE]\n");
    }

    /// A command substitution is an ordinary subshell for trap inheritance: it
    /// gets the DEBUG/RETURN traps only under `functrace` and ERR only under
    /// `errtrace`, and any that do fire write into the captured result. Verified
    /// byte-for-byte against bash 5.x.
    #[test]
    fn cmdsub_inherits_trace_traps_only_under_functrace() {
        let (o, _) = run("f() { echo body; }\nset -T\ntrap 'echo RET' RETURN\nx=$(f)\necho \"[$x]\"");
        assert_eq!(o, "[body\nRET]\n");
        // Without `set -T` the trap is reset in the subshell, so nothing fires
        // there — and nothing leaks to the terminal either.
        let (o, _) = run("f() { echo body; }\ntrap 'echo RET' RETURN\nx=$(f)\necho \"[$x]\"");
        assert_eq!(o, "[body]\n");
        // ERR follows `errtrace`, not `functrace`.
        let (o, _) = run("trap 'echo E' ERR\nx=$(false; echo body)\necho \"[$x]\"");
        assert_eq!(o, "[body]\n");
        let (o, _) = run("set -E\ntrap 'echo E' ERR\nx=$(false; echo body)\necho \"[$x]\"");
        assert_eq!(o, "[E\nbody]\n");
    }

    /// Nested shell code runs *in* the current shell, so it reads the shell's
    /// stdin — including a pipe fed to the enclosing compound command. bash:
    /// `echo hi | { eval "read v"; }` sets `v=hi`.
    #[test]
    fn eval_and_source_read_the_callers_stdin() {
        let (o, _) = run("echo hi | { eval 'read v; echo \"[$v]\"'; }");
        assert_eq!(o, "[hi]\n");

        let path = scratch_script("src_reads_stdin", "read v\necho \"[$v]\"\n");
        let (o, _) = run(&format!("echo ho | {{ . {path}; }}"));
        assert_eq!(o, "[ho]\n");
        let _ = std::fs::remove_file(&path);
    }

    /// The status the driver finally exits with: `run_exit_trap` must *report*
    /// the handler's own `exit N` (not merely record it in `$?`), because the
    /// driver's status can come from a path that never ran a command — e.g. 127
    /// for an unreadable script file.
    #[test]
    fn exit_trap_reports_its_own_exit_to_the_driver() {
        let mut sh = Shell::new();
        sh.run_source("trap 'exit 9' EXIT".as_bytes());
        sh.last_status = 2;
        assert_eq!(sh.run_exit_trap(), Some(9));

        let mut sh = Shell::new();
        sh.run_source("trap 'echo bye > /dev/null' EXIT".as_bytes());
        sh.last_status = 2;
        assert_eq!(sh.run_exit_trap(), None, "a normal handler leaves the status alone");

        // Fired at most once, and a shell with no EXIT trap reports nothing.
        let mut sh = Shell::new();
        assert_eq!(sh.run_exit_trap(), None);
    }

    /// A subshell's EXIT trap fires *after* the body's `exit N` has landed as
    /// `$?`, so the handler both sees that status and can replace it. bash:
    /// `( trap 'exit 9' EXIT; exit 2 ); echo $?` prints 9.
    #[test]
    fn subshell_exit_trap_exit_replaces_body_status() {
        let (o, _) = run("( trap 'exit 9' EXIT; exit 2 ); echo \"sub=$?\"");
        assert_eq!(o, "sub=9\n");
        // …and the handler observes the body's status as `$?`.
        let (o, _) = run("( trap 'echo saw=$?' EXIT; exit 2 ); echo \"sub=$?\"");
        assert_eq!(o, "saw=2\nsub=2\n");
    }

    /// `exit` reaching the *top level* latches `exit_requested`, which is how the
    /// read-eval loop knows to stop reading (bash: `printf 'echo a\nexit 3\necho
    /// b\n' | bash` prints only `a` and exits 3). An exit confined to a subshell
    /// must NOT latch it — the parent shell keeps running.
    #[test]
    fn top_level_exit_latches_exit_requested() {
        let mut sh = Shell::new();
        sh.run_source("echo hi > /dev/null".as_bytes());
        assert!(!sh.exit_requested(), "an ordinary command does not request exit");

        assert_eq!(sh.run_source("exit 3".as_bytes()), 3);
        assert!(sh.exit_requested());

        let mut sh = Shell::new();
        sh.run_source("( exit 4 )".as_bytes());
        assert!(!sh.exit_requested(), "a subshell exit stays inside the subshell");
        assert_eq!(sh.last_status, 4);
    }

    /// bash runs a `mapfile -C` callback in the *current* shell, so an `exit` in
    /// it terminates the whole shell: the read loop stops and the array is never
    /// assigned. (Verified against bash 5.x.)
    #[test]
    fn mapfile_callback_exit_unwinds_shell() {
        let path = scratch_script("mapfile_cb_exit", "a\nb\nc\n");
        let mut sh = Shell::new();
        let code = sh.run_source(format!(
            "cb() {{ CB=\"$CB $1\"; exit 5; }}\nmapfile -C cb -c 1 arr < {path}\nAFTER=1"
        ).as_bytes());
        assert_eq!(code, 5);
        assert!(sh.exit_requested());
        assert_eq!(sh.vars.get("CB").map(as_text), Some(" 0"), "one callback, then unwind");
        assert!(sh.arrays.get("arr").is_none_or(BTreeMap::is_empty), "array not assigned");
        assert!(!sh.vars.contains_key("AFTER"), "commands after the mapfile do not run");
        let _ = std::fs::remove_file(&path);
    }

    /// The array is filled *incrementally*, so a `-C` callback sees every
    /// element read before it (bash evaluates the callback after the line is
    /// read but before *that* element is assigned, so the count lags the index
    /// by one). osh used to buffer the whole read and insert at the end, which
    /// made the array invisible to every callback. Verified against bash 5.x:
    /// `cb 0 [a] have=-1`, `cb 1 [b] have=0`, `cb 2 [c] have=1`.
    #[test]
    fn mapfile_callback_sees_earlier_elements() {
        let path = scratch_script("mapfile_cb_incr", "a\nb\nc\n");
        let (o, _) = run(&format!(
            "cb() {{ echo \"cb $1 [$2] have=$((${{#arr[@]}} - 1))\"; }}\n\
             mapfile -t -C cb -c 1 arr < {path}\n\
             echo \"final=${{arr[*]}}\""
        ));
        assert_eq!(
            o,
            "cb 0 [a] have=-1\ncb 1 [b] have=0\ncb 2 [c] have=1\nfinal=a b c\n"
        );
        let _ = std::fs::remove_file(&path);
    }

    /// Plain `mapfile` discards the array's previous contents; `-O origin` does
    /// NOT — it overwrites in place, so elements outside the written range
    /// survive. bash: `arr=(x y z w v)` + three lines at `-O 1` → `x a b c v`.
    #[test]
    fn mapfile_origin_overwrites_without_clearing() {
        let path = scratch_script("mapfile_origin", "a\nb\nc\n");
        let (o, _) = run(&format!(
            "arr=(x y z w v); mapfile -t -O 1 arr < {path}; echo \"${{arr[*]}}\""
        ));
        assert_eq!(o, "x a b c v\n", "-O keeps elements outside the written range");
        // Without -O the array is replaced wholesale, trailing elements gone.
        let (o2, _) = run(&format!(
            "arr=(x y z w v); mapfile -t arr < {path}; echo \"${{arr[*]}}\""
        ));
        assert_eq!(o2, "a b c\n", "plain mapfile clears first");
        // `-O` past the end leaves a gap rather than compacting: indices 0,2,3,4.
        let (o3, _) = run(&format!(
            "arr=(x); mapfile -t -O 2 arr < {path}; echo \"${{!arr[*]}} / ${{arr[*]}}\""
        ));
        assert_eq!(o3, "0 2 3 4 / x a b c\n");
        let _ = std::fs::remove_file(&path);
    }

    #[test]
    fn return_outside_function_is_error_and_continues() {
        // Top-level `return` is an error (status 2) that does NOT unwind: the
        // following command still runs. (bash: same behaviour.)
        let (o, _) = run("echo before; return; echo after");
        assert_eq!(o, "before\nafter\n");
        // The error message and status-2 are observable via a group's 2>&1.
        let (o2, _) = run("{ return; } 2>&1; echo \"s=$?\"");
        assert_eq!(
            o2,
            "osh: return: can only `return' from a function or sourced script\ns=2\n"
        );
        // Inside a function, `return` unwinds normally with its status.
        assert_eq!(run("f() { echo in; return 7; echo out; }; f; echo $?").0, "in\n7\n");
        // A `return` in a subshell inside a function exits just the subshell.
        assert_eq!(
            run("f() { ( echo a; return 5; echo b ); echo \"s=$?\"; }; f").0,
            "a\ns=5\n"
        );
        // A `return` in a top-level subshell is still an error (no unwind).
        let (o3, _) = run("( echo a; return 3; echo b ) 2>/dev/null; echo done");
        assert_eq!(o3, "a\nb\ndone\n");
    }

    #[test]
    fn exit_and_return_status_masked_to_8_bits() {
        // A status only carries 8 bits. bash masks in the `exit`/`return`
        // builtins, not merely where the shell process finally exits, so an
        // in-process status -- out of a subshell or a function -- is truncated
        // too. (bash 5: 256 -> 0, 300 -> 44, -1 -> 255, -300 -> 212.)
        let (o, _) = run("( exit 256 ); echo \"a=$?\"; ( exit 300 ); echo \"b=$?\"");
        assert_eq!(o, "a=0\nb=44\n");
        let (o2, _) = run("( exit -1 ); echo \"c=$?\"; ( exit -300 ); echo \"d=$?\"");
        assert_eq!(o2, "c=255\nd=212\n");
        let (o3, _) = run("f() { return 260; }; f; echo \"e=$?\"; g() { return -1; }; g; echo \"f=$?\"");
        assert_eq!(o3, "e=4\nf=255\n");
        // Beyond i32 range is a legitimate value to bash (it masks it), not the
        // "numeric argument required" error a narrower parse would produce.
        let (o4, _) = run("( exit 99999999999 ) 2>/dev/null; echo \"g=$?\"");
        assert_eq!(o4, "g=255\n");
    }

    #[test]
    fn wait_on_reaped_pid_replays_remembered_status() {
        // A targeted `wait` is repeatable: the terminated job's status stays
        // answerable, silently, rather than degrading to "not a child".
        let (o, _) = run(
            "( exit 6 ) & p=$!; wait $p; echo \"a=$?\"; wait $p 2>/dev/null; echo \"b=$?\"; wait $p 2>/dev/null; echo \"c=$?\"",
        );
        assert_eq!(o, "a=6\nb=6\nc=6\n");
        // The memory is separate from the `jobs` table: a reaped job leaves the
        // listing at once even while `wait` still answers for it.
        let (o2, _) = run("( exit 6 ) & p=$!; wait $p >/dev/null; jobs; echo \"empty=$?\"");
        assert_eq!(o2, "empty=0\n");
        // An argument-less `wait` purges the memory.
        let (o3, _) = run(
            "( exit 6 ) & p=$!; wait $p >/dev/null; wait; wait $p 2>/dev/null; echo \"purged=$?\"",
        );
        assert_eq!(o3, "purged=127\n");
        // `wait -n` reaps the same way, so its status is remembered too.
        let (o4, _) = run("( exit 9 ) & p=$!; wait -n >/dev/null; wait $p 2>/dev/null; echo \"n=$?\"");
        assert_eq!(o4, "n=9\n");
        // A pid that was never ours is still the 127 error case.
        let (o5, _) = run("wait 1 2>/dev/null; echo \"stranger=$?\"");
        assert_eq!(o5, "stranger=127\n");
    }

    #[test]
    fn declare_cannot_convert_between_array_kinds() {
        // `declare -A` on an existing *indexed* array is an error, not a silent
        // shadow: bash refuses, reports on stderr, and leaves the array intact.
        // Before the guard the empty associative map took over every read while
        // the indexed values sat unreachable in the other table.
        let (o, _) = run(
            "declare -a a=(x y); declare -A a 2>&1; echo \"s=$? n=${#a[@]} first=${a[0]-unset}\"",
        );
        assert_eq!(
            o,
            "osh: declare: a: cannot convert indexed to associative array\ns=1 n=2 first=x\n"
        );
        // Symmetric in the other direction.
        let (o2, _) = run(
            "declare -A m=([k]=v); declare -a m 2>&1; echo \"s=$? n=${#m[@]} k=${m[k]-unset}\"",
        );
        assert_eq!(
            o2,
            "osh: declare: m: cannot convert associative to indexed array\ns=1 n=1 k=v\n"
        );
        // A compound assignment carrying the wrong kind is rejected too, but by
        // bash's assignment machinery rather than the builtin: the message has
        // no `declare:` tag and the rest of the parse unit is discarded, so the
        // status has to be read on the following line.
        let (o3, _) = run(
            "declare -a b=(x)\n{ declare -A b=([k]=v); } 2>&1\necho \"s=$? b0=${b[0]} n=${#b[@]}\"",
        );
        assert_eq!(
            o3,
            "osh: b: cannot convert indexed to associative array\ns=1 b0=x n=1\n"
        );
        let (o6, _) = run(
            "declare -a d=(x)\ndeclare -A d=([k]=v) 2>/dev/null; echo unreachable\necho \"s=$?\"",
        );
        assert_eq!(o6, "s=1\n");
        // `local -A` shadowing a global of the *other* kind is legal — the local
        // is a fresh variable, not a conversion of the global.
        let (o4, _) = run(
            "declare -a g=(x y); f() { local -A g=([k]=v); echo \"in=${g[k]} n=${#g[@]}\"; }; f; echo \"out=${g[0]} n=${#g[@]}\"",
        );
        assert_eq!(o4, "in=v n=1\nout=x n=2\n");
    }

    #[test]
    fn giving_a_scalar_an_array_kind_keeps_its_value_as_element_zero() {
        // Widening the type does not discard the value: bash reports
        // `declare -a x=([0]="5")`, and a subscript-less read still finds it.
        // osh used to create an *empty* array and leave the `5` in the scalar
        // slot, where nothing could reach it — `$x`, `${x[0]}` and `${#x[@]}`
        // all came back empty, so the value was lost rather than shadowed.
        assert_eq!(
            run("x=5; declare -a x; declare -p x; echo \"[$x] [${x[0]}] n=${#x[@]}\"").0,
            "declare -a x=([0]=\"5\")\n[5] [5] n=1\n"
        );
        // `-A` the same, under the numeric key `0`.
        assert_eq!(
            run("y=5; declare -A y; echo \"[${y[0]}] n=${#y[@]}\"").0,
            "[5] n=1\n"
        );
        // Even an empty scalar migrates, which is what leaves the array *valued*
        // — `declare -p` prints `=(…)` rather than the bare form. A name holding
        // nothing at all stays unvalued.
        assert_eq!(
            run("n=; declare -a n; declare -p n; declare -a fresh; declare -p fresh").0,
            "declare -a n=([0]=\"\")\ndeclare -a fresh\n"
        );
        // The value carries across the other spellings, and is *not* re-read as
        // an arithmetic expression by a simultaneous `-i`.
        assert_eq!(
            run("t=5; typeset -a t; declare -p t; i=1+1; declare -ai i; declare -p i").0,
            "declare -a t=([0]=\"5\")\ndeclare -ai i=([0]=\"1+1\")\n"
        );
        // The migration is what makes an appending literal continue *after* the
        // old value instead of overwriting it.
        assert_eq!(
            run("w=5; declare -a w+=(9); declare -p w; v=5; v+=(9); declare -p v").0,
            "declare -a w=([0]=\"5\" [1]=\"9\")\ndeclare -a v=([0]=\"5\" [1]=\"9\")\n"
        );
        // A non-appending literal still replaces it.
        assert_eq!(
            run("a=5; declare -a a=(1); declare -p a").0,
            "declare -a a=([0]=\"1\")\n"
        );
    }

    #[test]
    fn readonly_array_flags_need_a_value_to_take_effect() {
        // bash's `readonly -a`/`-A` create the array through the *assignment*, so
        // a bare name keeps whatever kind it had: `x=5; readonly -a x` still
        // reports `declare -r x="5"`, and an unset name stays a plain scalar.
        // osh applied the attribute regardless, turning the scalar into an
        // unreachable one and reporting a `-a` bash does not.
        assert_eq!(
            run("x=5; readonly -a x; declare -p x; readonly -A fresh; declare -p fresh").0,
            "declare -r x=\"5\"\ndeclare -r fresh\n"
        );
        // With a value the flag does apply, and the value lands in element 0.
        assert_eq!(
            run("readonly -a rx=7; declare -p rx; readonly -A ry=7; declare -p ry").0,
            "declare -ar rx=([0]=\"7\")\ndeclare -Ar ry=([0]=\"7\" )\n"
        );
        // A subscript-less value onto an existing array targets element 0 rather
        // than a scalar slot of the same name (the rule `name=value` follows).
        assert_eq!(
            run("z=(1 2); readonly z=5; declare -p z").0,
            "declare -ar z=([0]=\"5\" [1]=\"2\")\n"
        );
    }

    #[test]
    fn export_assigns_through_the_array_aware_store() {
        // `export name=value` is an assignment, so a name that is already an
        // array takes the value at element/key 0 — exactly where a bare
        // `name=value` and `readonly name=value` put it. osh wrote the scalar
        // slot directly, which no expansion of an array name ever reads, so the
        // value was silently lost.
        assert_eq!(
            run("declare -a arr=(1 2); export arr=9; declare -p arr").0,
            "declare -ax arr=([0]=\"9\" [1]=\"2\")\n"
        );
        // Same for an associative array, where the subscript-less value takes
        // key "0". (bash lists `[0]` first here; the key *order* of an assoc
        // listing is TD-OILS-ASSOC-ORDER, not this fix — what matters is that
        // the key exists and holds the value.)
        assert_eq!(
            run("declare -A m=([k]=v); export m=9; declare -p m").0,
            "declare -Ax m=([k]=\"v\" [0]=\"9\" )\n"
        );
        // The append form reads back through the same routing, so it extends
        // element 0's value rather than an empty scalar slot.
        assert_eq!(
            run("declare -a arr=(1 2); export arr+=9; declare -p arr").0,
            "declare -ax arr=([0]=\"19\" [1]=\"2\")\n"
        );
        // A plain name is unaffected: it still lands in the scalar slot.
        assert_eq!(
            run("export s=1; export s+=2; declare -p s").0,
            "declare -x s=\"12\"\n"
        );
    }

    #[test]
    fn export_takes_the_array_kind_flags_readonly_does() {
        // bash accepts `export -a`/`-A` (they reach the same `declare_internal`
        // that `readonly` does); osh's option table omitted them and answered
        // with an invalid-option usage error.
        assert_eq!(
            run("export -a v=5; declare -p v; export -A m=5; declare -p m").0,
            "declare -ax v=([0]=\"5\")\ndeclare -Ax m=([0]=\"5\" )\n"
        );
        // As in `readonly`, the kind is created by the *assignment*, so a bare
        // name keeps whatever it had: an unset name stays a plain scalar and an
        // existing scalar is not widened.
        assert_eq!(
            run("export -a fresh; declare -p fresh; x=5; export -A x; declare -p x").0,
            "declare -x fresh\ndeclare -x x=\"5\"\n"
        );
        // The append form sees the array the same operand's flag just created,
        // so it extends element 0 rather than starting from empty.
        assert_eq!(
            run("export -a v=1; export -a v+=2; declare -p v").0,
            "declare -ax v=([0]=\"12\")\n"
        );
        // An option letter that really is unknown still fails the same way.
        let (out, st) = run("export -Z x 2>&1");
        assert_eq!(st, 2);
        assert!(out.contains("export: -Z: invalid option"), "{out:?}");
    }

    #[test]
    fn a_kind_flag_restricts_a_listing_rather_than_widening_it() {
        // `a`/`A` are type *restrictions*, applied conjunctively, while the
        // other attribute letters union among themselves. So `declare -ax` is
        // "the indexed arrays that are exported" — osh unioned all the letters
        // together and listed every array *or* exported name instead.
        let setup = "declare -a plain=(1); declare -ax earr=(2); foo=1; export foo;\
                     declare -ai iarr=(9); declare -i n=3; declare -A aa=([k]=v);";
        assert_eq!(
            run(&format!("{setup} declare -ax")).0,
            "declare -ax earr=([0]=\"2\")\n"
        );
        assert_eq!(
            run(&format!("{setup} declare -ai")).0,
            "declare -ai iarr=([0]=\"9\")\n"
        );
        // No name is both kinds at once, so the two restrictions together admit
        // nothing — where a union would have listed every array of either kind.
        assert_eq!(run(&format!("{setup} declare -aA")).0, "");
        // Attribute letters with no restriction still union: an integer-only
        // and a readonly-only name both appear. (Asserted by containment, not
        // equality — the shell's own readonly/integer variables such as
        // `SHELLOPTS` and `UID` are in this listing too, as they are in bash's.)
        let ir = run("declare -i n=1; declare -r r=2; declare -ir").0;
        assert!(ir.contains("declare -i n=\"1\"\n"), "{ir:?}");
        assert!(ir.contains("declare -r r=\"2\"\n"), "{ir:?}");
        // `export`/`readonly` reach the same listing in bash, so they restrict
        // the same way rather than ignoring the flag.
        assert_eq!(
            run("declare -ax e=(2); foo=1; export foo; export -a").0,
            "declare -ax e=([0]=\"2\")\n"
        );
        // Containment again: `BASH_VERSINFO` is a readonly indexed array, so it
        // belongs in this listing — bash lists it here too. What matters is
        // that the readonly *scalar* `rs` does not appear.
        let ro = run("declare -ar ra=(3); readonly rs=4; readonly -a").0;
        assert!(ro.contains("declare -ar ra=([0]=\"3\")\n"), "{ro:?}");
        assert!(!ro.contains("rs"), "{ro:?}");
        assert_eq!(
            run("declare -Ax m=([k]=v); foo=1; export foo; export -A").0,
            "declare -Ax m=([k]=\"v\" )\n"
        );
    }

    #[test]
    fn a_second_local_of_a_name_redeclares_rather_than_reshadows() {
        // Only the *first* `local` of a name in a frame shadows. A second one
        // re-declares a binding that is already local, and bash leaves its value
        // and attributes alone, applying the new flags on top. osh cleared on
        // every `local`, so a re-declaration silently destroyed the value the
        // caller had just set.
        let f = |body: &str| run(&format!("f(){{ {body}; }}; f")).0;
        assert_eq!(f("local -i n=5; local n; declare -p n"), "declare -i n=\"5\"\n");
        assert_eq!(f("local -l s=AB; local s; declare -p s"), "declare -l s=\"ab\"\n");
        assert_eq!(f("local -x e=1; local e; declare -p e"), "declare -x e=\"1\"\n");
        assert_eq!(
            f("local -a a=(1 2); local a; declare -p a"),
            "declare -a a=([0]=\"1\" [1]=\"2\")\n"
        );
        assert_eq!(
            f("local -A m=([k]=v); local -A m; declare -p m"),
            "declare -A m=([k]=\"v\" )\n"
        );
        // The first `local` still shadows: the outer binding's value *and* its
        // attributes are dropped, including its array kind.
        let g = |setup: &str, body: &str| run(&format!("{setup} f(){{ {body}; }}; f")).0;
        assert_eq!(g("declare -i o=5;", "local o; declare -p o"), "declare -- o\n");
        assert_eq!(g("declare -l o=AB;", "local o; declare -p o"), "declare -- o\n");
        assert_eq!(g("declare -a o=(1);", "local o; declare -p o"), "declare -- o\n");
    }

    #[test]
    fn giving_a_local_scalar_an_array_kind_drops_its_value_but_not_its_valuedness() {
        // bash builds a local array with `make_local_array_variable`, which
        // rebinds the name as a fresh array instead of converting the variable
        // in place — so the scalar's value is lost, unlike the global widening
        // that keeps it as element 0. The name still reports as *valued*, which
        // is the difference between `declare -a x=()` and a bare `declare -a x`.
        let f = |body: &str| run(&format!("f(){{ {body}; }}; f")).0;
        assert_eq!(f("local x=5; local -a x; declare -p x"), "declare -a x=()\n");
        assert_eq!(f("local x=5; local -A x; declare -p x"), "declare -A x=()\n");
        // Other attributes on the name survive the widening.
        assert_eq!(f("local -i n=5; local -a n; declare -p n"), "declare -ai n=()\n");
        // With no value to begin with there is nothing to drop, so the name
        // stays unvalued and prints as a bare declaration.
        assert_eq!(f("local x; local -a x; declare -p x"), "declare -a x\n");
        assert_eq!(f("local -a x; declare -p x"), "declare -a x\n");
        // A *first* local widening a global scalar is unvalued too: the shadow
        // step runs first, so by then there is no local scalar to drop.
        assert_eq!(
            run("g=9; f(){ local -a g; declare -p g; }; f").0,
            "declare -a g\n"
        );
        // The global widening is unchanged — it still carries the scalar.
        assert_eq!(
            run("x=5; declare -a x; declare -p x").0,
            "declare -a x=([0]=\"5\")\n"
        );
    }

    #[test]
    fn declare_t_records_the_trace_attribute_on_a_variable() {
        // On a *variable* `-t` is inert even in bash — it only has to survive
        // into `declare -p`, `${v@a}` and a `declare -t` listing. osh parsed the
        // letter and dropped it.
        assert_eq!(run("declare -tirx v=1; declare -p v").0, "declare -irtx v=\"1\"\n");
        assert_eq!(run("declare -t v=1; declare +t v; declare -p v").0, "declare -- v=\"1\"\n");
        assert_eq!(run("declare -t q=1; echo \"${q@a}|${q@A}\"").0, "t|declare -t q='1'\n");
        // A nameless `-t` is a listing filtered by the attribute.
        assert_eq!(
            run("declare -t a=1; b=2; declare -ti c=3; declare -t").0,
            "declare -t a=\"1\"\ndeclare -it c=\"3\"\n"
        );
        // The kind and the case letter bracket the attribute letters.
        assert_eq!(run("declare -ta v=(1); declare -p v").0, "declare -at v=([0]=\"1\")\n");
        assert_eq!(run("declare -tu v=ab; declare -p v").0, "declare -tu v=\"AB\"\n");
        // bash emits the attribute letters in a fixed order (`i n r t x`), not
        // the order they were written; osh had `n` before `i`.
        assert_eq!(run("declare -ni v; declare -p v").0, "declare -in v\n");
        assert_eq!(run("declare -tinlrx v; declare -p v").0, "declare -inrtxl v\n");
        // It is a per-name attribute like the others: a `local` does not inherit
        // it, and `unset` drops it.
        assert_eq!(
            run("declare -t g=1; f(){ local g; declare -p g; }; f").0,
            "declare -- g\n"
        );
    }

    #[test]
    fn a_function_listing_reports_the_readonly_and_trace_attributes() {
        let setup = "f(){ :; }; g(){ :; }; h(){ :; }; i(){ :; }; \
                     declare -ft f; readonly -f f; readonly -f g; declare -ft h;";
        // `declare -F` renders each function's attributes as `-f` plus `r`/`t`.
        assert_eq!(
            run(&format!("{setup} declare -F")).0,
            "declare -frt f\ndeclare -fr g\ndeclare -ft h\ndeclare -f i\n"
        );
        // With no names, `-r`/`-t` filter the listing rather than marking
        // anything, and they union — as the variable listing's letters do.
        assert_eq!(run(&format!("{setup} declare -Ft")).0, "declare -frt f\ndeclare -ft h\n");
        assert_eq!(run(&format!("{setup} declare -Fr")).0, "declare -frt f\ndeclare -fr g\n");
        assert_eq!(
            run(&format!("{setup} declare -Frt")).0,
            "declare -frt f\ndeclare -fr g\ndeclare -ft h\n"
        );
        // A nameless `-f` prints the body, then the attribute line for the
        // functions that have one.
        assert_eq!(
            run("f(){ :; }; g(){ :; }; declare -ft f; declare -f").0,
            "f () \n{ \n    :\n}\ndeclare -ft f\ng () \n{ \n    :\n}\n"
        );
        // `-ft` with names is still the mutation, and an unknown name fails
        // silently (status 1, no diagnostic), as `declare -fr` does.
        let (out, code) = run("declare -ft nope");
        assert_eq!((out.as_str(), code), ("", 1));
    }

    #[test]
    fn declare_g_reaches_past_a_local_to_the_global_binding() {
        // `-g` declares the *global* variable even when a local of the same
        // name is in the way: the local is left alone and the global survives
        // the return. osh used to convert the local instead, so the
        // declaration's effects died with the frame and no global was made.
        assert_eq!(
            run("f(){ local x=5; declare -ga x; declare -p x; }; f; declare -p x").0,
            "declare -- x=\"5\"\ndeclare -a x\n"
        );
        // A value goes to the global too, and an *existing* global is widened
        // from its own value rather than the local's.
        assert_eq!(
            run("f(){ local x=5; declare -g x=9; declare -p x; }; f; declare -p x").0,
            "declare -- x=\"5\"\ndeclare -- x=\"9\"\n"
        );
        assert_eq!(
            run("x=1; f(){ local x=5; declare -ga x; }; f; declare -p x").0,
            "declare -a x=([0]=\"1\")\n"
        );
        // Attributes and appends likewise resolve against the global.
        assert_eq!(
            run("x=1; f(){ local x=5; declare -gi x; }; f; declare -p x").0,
            "declare -i x=\"1\"\n"
        );
        assert_eq!(
            run("x=ab; f(){ local x=5; declare -g x+=9; }; f; declare -p x").0,
            "declare -- x=\"ab9\"\n"
        );
        // A compound operand is bound before the builtin ever runs, so the
        // retarget has to wrap the whole command, not just the builtin.
        assert_eq!(
            run("f(){ local x=5; declare -ga x=(7 8); declare -p x; }; f; declare -p x").0,
            "declare -- x=\"5\"\ndeclare -a x=([0]=\"7\" [1]=\"8\")\n"
        );
        // From two frames deep it is still the *global*, not the enclosing
        // function's local, that is declared — and that local is untouched.
        assert_eq!(
            run("f(){ local x=5; g; declare -p x; }; \
                 g(){ local x=7; declare -g x=9; declare -p x; }; f; declare -p x")
                .0,
            "declare -- x=\"7\"\ndeclare -- x=\"5\"\ndeclare -- x=\"9\"\n"
        );
        // With no local in the way `-g` is an ordinary global declaration.
        assert_eq!(
            run("x=1; f(){ declare -ga x; }; f; declare -p x").0,
            "declare -a x=([0]=\"1\")\n"
        );
    }

    #[test]
    fn declare_c_lists_the_capcase_variables() {
        // `-c` was missing from both copies of the listing letter set, so it
        // routed to a declaration that declared nothing and printed nothing.
        // The two copies are now one helper, which is what kept them in sync.
        assert_eq!(
            run("declare -c cv=abc; declare -l lv=ABC; declare -c").0,
            "declare -c cv=\"Abc\"\n"
        );
        assert_eq!(
            run("declare -c cv=abc; declare -l lv=ABC; declare -l").0,
            "declare -l lv=\"abc\"\n"
        );
    }

    #[test]
    fn a_compound_operand_binds_before_the_declaration_builtin_runs() {
        // A compound operand is bound during the command's word-expansion pass,
        // not by the builtin — only a compound can bind a whole array, and there
        // is no way to hand one to a builtin as an argv string. So compounds bind
        // in operand order and a later one sees an earlier one's value.
        assert_eq!(
            run("declare -a x=(1 2) y=(\"${x[1]}\" \"${#x[@]}\"); declare -p y").0,
            "declare -a y=([0]=\"2\" [1]=\"2\")\n"
        );
        // A *scalar* operand, by contrast, is only expanded there and left for the
        // builtin to assign — so no compound of the same command can see it, not
        // even one written to its right. osh ran the builtin first and bound `b`
        // to the *new* `c`.
        assert_eq!(
            run("c=old; declare -a b=($c) c=2; declare -p b c").0,
            "declare -a b=([0]=\"old\")\ndeclare -a c=([0]=\"2\")\n"
        );
        assert_eq!(
            run("c=old; declare -a c=2 b=($c); declare -p b").0,
            "declare -a b=([0]=\"old\")\n"
        );
        // The kind and the value-transforming attributes are in force while the
        // literal binds, so the stored values are already evaluated and folded.
        assert_eq!(
            run("declare -ai n=(1+1 3*3); declare -al lo=(AB); declare -p n lo").0,
            "declare -ai n=([0]=\"2\" [1]=\"9\")\ndeclare -al lo=([0]=\"ab\")\n"
        );
    }

    #[test]
    fn a_failed_compound_operand_discards_the_rest_of_the_parse_unit() {
        // Binding during expansion means a compound that *fails* stops the command
        // dead, the way the array-kind conflict already did: the earlier operands
        // stay bound, the later ones never bind, the builtin never runs, and the
        // rest of the parse unit goes with it — so the `echo` never speaks and
        // `ok` is unset. osh bound `ok`, ran the builtin and reported 0.
        let (o, rc) = run(
            "readonly r=1\ndeclare -a first=(0) r=(2) ok=(3); echo never\necho \"status=$?\"\ndeclare -p first\ndeclare -p ok 2>/dev/null; echo \"ok=$?\"",
        );
        assert_eq!(o, "status=1\ndeclare -a first=([0]=\"0\")\nok=1\n");
        assert_eq!(rc, 0, "the discard ends the command, not the script");
        // Because the builtin never ran, the attributes only *it* applies were
        // never applied to the survivor either — `-x`/`-r`/`-n` are missing while
        // `-i`/`-l`, in force at bind time, are there. bash reports exactly this
        // split, and it is the observable proof of where each attribute is applied.
        assert_eq!(
            run("readonly r=1\ndeclare -ailx g=(2+3 AB) r=(1)\ndeclare -p g").0,
            "declare -ail g=([0]=\"5\" [1]=\"0\")\n"
        );
        // The *builtin* failing is milder: status 1, no discard, and the compound
        // bound before it keeps the attributes the builtin did apply.
        let (o2, _) = run("readonly s=1; declare -ax v=(1) s=2; echo \"rc=$?\"; declare -p v");
        assert_eq!(o2, "rc=1\ndeclare -ax v=([0]=\"1\")\n");
    }

    /// A word-expansion error inside a compound operand ends the command the same
    /// way a rejected operand does — and, critically, ends there: the discard must
    /// not reach the *next* command, which is what happened while
    /// `exec_declare_with_arrays` left `discard_error` set for
    /// `exec_simple_inner`'s next expansion check to find.
    #[test]
    fn a_failed_operand_expansion_discards_only_the_rest_of_the_parse_unit() {
        // Line 1's operand fails, so `g` never binds and `$?` is 1 — but line 2 and
        // everything after it still run. osh used to swallow the command right after
        // the failure (here the `echo`), reporting `status=` from a later line.
        let (o, rc) = run(
            "declare -a f=(x $((1/0))) g=(1)\necho \"status=$?\"\ndeclare -p g 2>/dev/null; echo \"g=$?\"",
        );
        assert_eq!(o, "status=1\ng=1\n");
        assert_eq!(rc, 0, "the discard ends the parse unit, not the script");
        // A survivor to the *left* of the failing operand keeps its binding, and the
        // command following on a new line is untouched.
        assert_eq!(
            run("declare -a h=(1) i=(y $((1/0))) j=(2)\ndeclare -p h\ndeclare -p j 2>/dev/null; echo \"j=$?\"").0,
            "declare -a h=([0]=\"1\")\nj=1\n"
        );
        // Same for an associative operand, whose branch takes a different path.
        let (o1, _) = run(
            "declare -A m\nm=([z]=old)\ndeclare -A m+=([a]=1 [b]=$((1/0)))\necho \"st=$?\"\ndeclare -p m",
        );
        assert_eq!(o1, "st=1\ndeclare -A m=([z]=\"old\" )\n");
        // The leak was loudest under `set -x`, where the eaten command was the
        // `set +x` meant to stop the tracing. `exec 2>&1` rather than a `{ … }`
        // group, because the discard legitimately takes out the rest of a group
        // (bash does the same — the group is the parse unit).
        let (o2, _) = run("exec 2>&1\nset -x\ndeclare -a b=(x $((1/0)))\nset +x\necho done");
        assert!(
            o2.ends_with("+ set +x\ndone\n"),
            "`set +x` must still run: {o2:?}"
        );
        // `set -u` is fatal instead, with nounset's status — and it aborts before
        // the following line rather than discarding just the parse unit.
        let (o3, rc3) = run("set -u\ndeclare -a k=($NOPE)\necho never");
        assert_eq!(o3, "");
        assert_eq!(rc3, 1, "a subshell-less script exits nounset's status");
    }

    #[test]
    fn a_failed_operand_expansion_leaves_its_name_exactly_as_it_was() {
        // A compound operand's value is computed in full before the variable is
        // touched, so an expansion failure leaves *nothing* behind — not the value,
        // not the array kind, not the value attributes, and not even the name. osh
        // used to apply the kind and the attributes on the way in, so a failed
        // operand converted a scalar to an array and created names out of nothing.
        //
        // An existing scalar keeps being a scalar with its old value.
        assert_eq!(
            run("sc=hello\ndeclare -a sc=(x $((1/0)))\ndeclare -p sc").0,
            "declare -- sc=\"hello\"\n"
        );
        // A name that did not exist stays non-existent, rather than becoming an
        // empty `declare -ail`.
        assert_eq!(
            run("declare -ail nf=(2+3 $((1/0)))\ndeclare -p nf 2>/dev/null; echo \"nf=$?\"").0,
            "nf=1\n"
        );
        // An existing *array* keeps its old elements and its old attribute set: the
        // `-l` of the failing declaration does not stick either.
        assert_eq!(
            run("declare -a ea=(AB)\ndeclare -al ea=(CD $((1/0)))\ndeclare -p ea").0,
            "declare -a ea=([0]=\"AB\")\n"
        );
        // Same for an associative operand in either of its two modes.
        assert_eq!(
            run("declare -A pm=([z]=old)\ndeclare -A pm=(k v j$((1/0)) x)\ndeclare -p pm").0,
            "declare -A pm=([z]=\"old\" )\n"
        );
        assert_eq!(
            run("declare -A sm\ndeclare -Au sm=([a]=b [c]=$((1/0)))\ndeclare -p sm").0,
            // Still *unvalued*, as a bare `declare -A sm` leaves it: the abandoned
            // literal did not even count as giving the array a value.
            "declare -A sm\n"
        );
        // A failure in the *binding* pass is the other regime: by then the variable
        // really has been written, so what bound first stays, attributes included.
        // `-i` evaluates each element as it is stored, so `2+` fails at element 1
        // with element 0 already in place.
        assert_eq!(
            run("declare -ai bp=([0]=1 [1]=2+ [2]=3) 2>/dev/null\ndeclare -p bp").0,
            "declare -ai bp=([0]=\"1\")\n"
        );
        // And a *readonly* target is a third: bash applies the kind and the value
        // attributes there, because the rejection happens at the store rather than
        // during the expansion.
        assert_eq!(
            run("readonly rs=1\ndeclare -a rs=(2) 2>/dev/null\ndeclare -p rs").0,
            "declare -ar rs=([0]=\"1\")\n"
        );
    }

    #[test]
    fn a_scalar_operand_of_an_array_declaration_gets_the_value_attributes() {
        // `declare -a name=word` binds `word` at index/key 0 — and the value
        // attributes apply to it exactly as they would to a scalar. osh used to
        // store the raw word, so `-l`/`-u`/`-c`/`-i` were silently skipped whenever
        // the array kind was also given.
        assert_eq!(
            run("declare -al a=QQ; declare -p a").0,
            "declare -al a=([0]=\"qq\")\n"
        );
        assert_eq!(
            run("declare -Au a=qq; declare -p a").0,
            "declare -Au a=([0]=\"QQ\" )\n"
        );
        assert_eq!(
            run("declare -ac a=hELLO; declare -p a").0,
            "declare -ac a=([0]=\"Hello\")\n"
        );
        assert_eq!(
            run("declare -ai a=2+3; declare -p a").0,
            "declare -ai a=([0]=\"5\")\n"
        );
        // `-i` beats the case attributes, as it does for a scalar: `Q` is an
        // (unset) variable name in arithmetic, so it evaluates to 0.
        assert_eq!(
            run("declare -ail a=Q; declare -p a").0,
            "declare -ail a=([0]=\"0\")\n"
        );
        // `+=` follows the attribute too: numeric addition under `-i`, and a
        // concatenation of the *folded* text otherwise.
        assert_eq!(
            run("declare -ai a=5; declare -ai a+=3; declare -p a").0,
            "declare -ai a=([0]=\"8\")\n"
        );
        assert_eq!(
            run("declare -al a=AB; declare -al a+=CD; declare -p a").0,
            "declare -al a=([0]=\"abcd\")\n"
        );
        assert_eq!(
            run("declare -au a=(x); declare -au a+=yy; declare -p a").0,
            "declare -au a=([0]=\"XYY\")\n"
        );
        // A bad `-i` value discards the command (as it does for a scalar), leaves
        // the array *valued but empty*, and abandons every operand after it.
        let (o, _) = run("declare -ai bad=2+ ok=1 2>/dev/null\ndeclare -p bad\ndeclare -p ok 2>/dev/null; echo \"ok=$?\"");
        assert_eq!(o, "declare -ai bad=()\nok=1\n");
        // The same for a *scalar* declaration, where the name is left
        // created-but-unset rather than valued-empty.
        let (o2, _) = run("declare -i bad=2+ ok=1 2>/dev/null\ndeclare -p bad\ndeclare -p ok 2>/dev/null; echo \"ok=$?\"");
        assert_eq!(o2, "declare -i bad\nok=1\n");
        // And for a subscripted operand.
        let (o3, _) = run("declare -ai b[0]=2+ ok=1 2>/dev/null\ndeclare -p b\ndeclare -p ok 2>/dev/null; echo \"ok=$?\"");
        assert_eq!(o3, "declare -ai b=()\nok=1\n");
    }

    #[test]
    fn assoc_compound_assignment_has_two_modes() {
        // The *first* element chooses the mode. Unsubscripted first ⇒ the whole
        // list is consumed as alternating key/value words (a bare list is not an
        // error at all), and a trailing odd word gets the empty string.
        let (o, _) = run(
            "declare -A m=(a 1 b 2 c); echo \"n=${#m[@]} a=${m[a]} b=${m[b]} c=[${m[c]}]\"",
        );
        assert_eq!(o, "n=3 a=1 b=2 c=[]\n");
        // In pair mode a later `[k]=v` is *not* interpreted — it is a literal key.
        let (o2, _) = run("declare -A p=(x 1 [y]=2); echo \"n=${#p[@]} lit=${p['[y]=2']-missing}\"");
        assert_eq!(o2, "n=2 lit=\n");
        // Subscripted first ⇒ the other mode, where a bare word is rejected by
        // name (status still 0) while the rest of the list still lands. bash
        // quotes the word for a `declare` operand and not for a bare `m=(…)`.
        let (o3, _) = run("{ declare -A k=([a]=1 loose [b]=2); } 2>&1\necho \"s=$? a=${k[a]} b=${k[b]}\"");
        assert_eq!(
            o3,
            "osh: k: 'loose': must use subscript when assigning associative array\ns=0 a=1 b=2\n"
        );
        let (o5, _) = run("declare -A k2\n{ k2=([a]=1 loose [b]=2); } 2>&1\necho \"s=$? n=${#k2[@]}\"");
        assert_eq!(
            o5,
            "osh: k2: loose: must use subscript when assigning associative array\ns=0 n=2\n"
        );
        // A plain `=` clears first; `+=` merges into what is already there.
        let (o4, _) = run(
            "declare -A c=([one]=1 [two]=2); c+=([three]=3 [one]=uno); echo \"n=${#c[@]} one=${c[one]}\"; c=([only]=x); echo \"n=${#c[@]}\"",
        );
        assert_eq!(o4, "n=3 one=uno\nn=1\n");
    }

    #[test]
    fn assoc_empty_subscript_is_rejected() {
        // An empty key has no representation in an associative array. Writing
        // one reports the full reference in *source* form and creates nothing.
        // The failed assignment discards the rest of its parse unit (bash), so
        // the check has to live on a following line.
        let (o, _) = run("declare -A m=([k]=v)\n{ m['']=x; } 2>&1\necho \"s=$? n=${#m[@]}\"");
        assert_eq!(o, "osh: m['']: bad array subscript\ns=1 n=1\n");
        // Reading the value form names the *base* and expands empty (status 0).
        let (o2, _) = run("declare -A m=([k]=v)\n{ echo \"r=[${m['']}]\"; } 2>&1\necho \"s=$?\"");
        // The diagnostic comes from expanding the word, so it precedes the
        // line `echo` then writes (bash prints the same order).
        assert_eq!(o2, "osh: m: bad array subscript\nr=[]\ns=0\n");
    }

    #[test]
    fn a_lexically_empty_subscript_is_refused_rather_than_read_as_zero() {
        // `a[]` is not index 0. bash refuses it — but only complains: a *read*
        // yields 0 and a *write* is dropped, and either way the expression keeps
        // going and the command keeps its status. osh used to quietly treat the
        // empty subscript as 0, so `(( a[]=9 ))` silently wrote element 0.
        //
        // The read complaint is printed twice, because bash validates the
        // subscript both when resolving the reference and when fetching its
        // value.
        let (o, _) = run("a=(one two)\n(( a[] )) 2>&1\necho \"rc=$?\"");
        assert_eq!(
            o,
            "osh: a[]: bad array subscript\nosh: a[]: bad array subscript\nrc=1\n"
        );
        // A store is tagged with the enclosing builtin and drops the element,
        // while the expression still carries the value it assigned.
        let (o2, _) = run("a=(one two)\n(( a[]=9 )) 2>&1\necho \"rc=$? n=${#a[@]}\"");
        assert_eq!(o2, "osh: ((: `a[]': not a valid identifier\nrc=0 n=2\n");
        let (o3, _) = run("a=(one two)\n{ x=$(( a[]=3 )); } 2>&1\necho \"rc=$? x=[$x]\"");
        assert_eq!(o3, "osh: `a[]': not a valid identifier\nrc=0 x=[3]\n");
        let (o4, _) = run("let 'a[]=5' 2>&1\necho \"rc=$?\"");
        assert_eq!(o4, "osh: let: `a[]': not a valid identifier\nrc=0\n");
        // A read-modify-write does both: it reads (twice-complained), then the
        // store is refused. `a[]+=2` is therefore worth 0+2, so the `((`
        // succeeds.
        let (o5, _) = run("a=(one two)\n(( a[]+=2 )) 2>&1\necho \"rc=$?\"");
        assert_eq!(
            o5,
            "osh: a[]: bad array subscript\nosh: a[]: bad array subscript\nosh: ((: `a[]': not a valid identifier\nrc=0\n"
        );
        // The refusal does not depend on the name: an unset name, a scalar and
        // an associative array are all refused the same way, and a nameref is
        // *not* followed — the name is blamed exactly as written.
        let (o6, _) = run("declare -A m=([k]=v)\n(( m[]=1 )) 2>&1\necho \"rc=$? n=${#m[@]}\"");
        assert_eq!(o6, "osh: ((: `m[]': not a valid identifier\nrc=0 n=1\n");
        let (o7, _) = run("declare -n r=x\nx=(7 8)\n(( r[]=1 )) 2>&1\necho \"rc=$? n=${#x[@]}\"");
        assert_eq!(o7, "osh: ((: `r[]': not a valid identifier\nrc=0 n=2\n");
        // Lazily: a short-circuited read is never reached, so never complained
        // about. And the check is purely lexical — `a[  ]` is not empty, and its
        // blanks arithmetic-evaluate to index 0 as usual.
        let (o8, _) = run("a=(one two)\n(( 1 ? 7 : a[] )) 2>&1\necho \"rc=$?\"");
        assert_eq!(o8, "rc=0\n");
        let (o9, _) = run("a=(1 2)\necho \"[${a[  ]}] [$(( a[  ]+1 ))]\"");
        assert_eq!(o9, "[1] [2]\n");
    }

    #[test]
    fn an_empty_subscript_in_a_brace_expansion_is_a_runtime_bad_substitution() {
        // `${a[]}` parses fine in bash and is only rejected when the word is
        // expanded, as a DISCARD-class "bad substitution" — so a guarded
        // occurrence is silent, and a reached one abandons its parse unit
        // without exiting the shell. osh used to make it a *parse* error, which
        // killed the whole script with status 2 before it ran a line.
        let (o, _) = run("if false; then echo \"${a[]}\"; fi\necho \"rc=$?\"\necho after");
        assert_eq!(o, "rc=0\nafter\n");
        // The subject named is the whole word with its quotes removed, as for
        // every other bad substitution.
        let (o2, _) = run("a=(one two)\n{ echo \"X${a[]}Y\"; echo unreachable; } 2>&1\necho \"rc=$?\"\necho after");
        assert_eq!(o2, "osh: X${a[]}Y: bad substitution\nrc=1\nafter\n");
        // Every brace form that can carry a subscript defers the same way.
        for form in ["${#a[]}", "${!a[]}", "${a[]:-def}", "${a[]#o}"] {
            let (o3, _) = run(&format!("a=(one two)\n{{ echo \"{form}\"; }} 2>&1\necho after"));
            assert_eq!(o3, format!("osh: {form}: bad substitution\nafter\n"));
        }
    }

    #[test]
    fn break_continue_level_clamped_to_loop_depth() {
        // `break N`/`continue N` with N larger than the nesting depth act on
        // the outermost enclosing loop and carry on — they do not keep
        // unwinding out of the script. (bash: same.) Before the clamp the
        // surplus levels escaped every loop and silently truncated the run.
        let (o, _) = run(
            "for a in 1 2; do for b in x y; do break 9; done; done; echo \"s=$?\"; echo after",
        );
        assert_eq!(o, "s=0\nafter\n");
        // `continue 9` two deep restarts the *outer* loop, so the inner loop
        // never reaches its second item and the outer body never finishes.
        let (o2, _) = run(
            "for a in 1 2; do for b in x y; do printf '%s%s ' \"$a\" \"$b\"; continue 9; done; echo \"inner-done-$a\"; done; echo \"s=$?\"",
        );
        assert_eq!(o2, "1x 2x s=0\n");
        // A clamped level must not escape into a *caller's* loop: loop depth
        // resets per function body, so `break 9` inside a function called from
        // a loop is still the outside-a-loop no-op.
        let (o3, _) = run(
            "f() { break 9; echo in-fn; }; for a in 1 2; do echo \"iter$a\"; f; done 2>/dev/null",
        );
        assert_eq!(o3, "iter1\nin-fn\niter2\nin-fn\n");
    }

    #[test]
    fn loop_status_is_breaks_own_not_the_previous_iterations() {
        // `break` is the last command executed in its iteration, so its status
        // (0) is the loop's. Before the fix the loop restored the status saved
        // at the *end of the previous iteration*, so a failure two iterations
        // back leaked out. (bash: all of these are 0.)
        assert_eq!(run("for i in 1 2 3; do (exit 4); [ $i = 3 ] && break; done; echo $?").0, "0\n");
        assert_eq!(run("for i in 1 2; do (exit 5); break; done; echo $?").0, "0\n");
        assert_eq!(run("for i in 1 2; do break; (exit 5); done; echo $?").0, "0\n");
        assert_eq!(
            run("i=0; while [ $i -lt 3 ]; do i=$((i+1)); (exit 6); [ $i = 2 ] && break; done; echo $?").0,
            "0\n"
        );
        // `continue` already fell through to the per-iteration bookkeeping, and
        // an inner `break N` must not leak either.
        assert_eq!(run("for i in 1 2; do (exit 7); continue; done; echo $?").0, "0\n");
        assert_eq!(
            run("for a in 1 2; do for b in x y; do (exit 8); break 2; done; done; echo $?").0,
            "0\n"
        );
        // A loop that ends normally still reports its last body command.
        assert_eq!(run("for i in 1 2; do (exit 5); done; echo $?").0, "5\n");
    }

    #[test]
    fn break_continue_reject_a_bad_loop_count() {
        // A count that is not a number is fatal: bash's `get_numeric_arg` calls
        // `throw_to_top_level`, which ORs 128 into `$?` and exits the shell.
        let (o, s) = run("{ for i in 1 2; do break abc; done; echo NOT-REACHED; } 2>&1");
        assert_eq!(o, "osh: break: abc: numeric argument required\n");
        assert_eq!(s, 128);
        // The OR keeps a status that already carries the 128 bit …
        assert_eq!(run("(exit 130); for i in 1; do break xyz; done 2>/dev/null").1, 130);
        // … and adds to one that does not.
        assert_eq!(run("(exit 3); for i in 1; do continue 2abc; done 2>/dev/null").1, 131);
        // Hex and overflowing literals are not numbers to bash either.
        assert_eq!(run("for i in 1; do break 0x10; done 2>/dev/null").1, 128);
        assert_eq!(run("for i in 1; do break 99999999999999999999999; done 2>/dev/null").1, 128);
        // A second operand is "too many arguments" — status 1, the rest of the
        // current top-level unit discarded — and it is diagnosed *before* the
        // range check, so `break 0 2` reports this rather than the range error.
        let (o2, s2) = run("{ for i in 1 2; do break 0 2; done; echo NOT-REACHED; } 2>&1");
        assert_eq!(o2, "osh: break: too many arguments\n");
        assert_eq!(s2, 1);
        // Only the *current* unit is discarded: the next line still runs.
        let (o3, _) = run("for i in 1 2; do continue 1 2; done 2>/dev/null\necho next=$?");
        assert_eq!(o3, "next=1\n");
        // Zero or negative leaves *every* enclosing loop, `continue` included,
        // with status 1 — bash sets `breaking` to the full loop level.
        let (o4, _) = run(
            "{ for a in 1 2; do for b in x y; do break 0; done; echo inner=$?; done; } 2>&1; echo outer=$?",
        );
        assert_eq!(o4, "osh: break: 0: loop count out of range\nouter=1\n");
        let (o5, _) = run(
            "{ for a in 1 2; do for b in x y; do continue -1; done; echo inner=$?; done; } 2>&1; echo outer=$?",
        );
        assert_eq!(o5, "osh: continue: -1: loop count out of range\nouter=1\n");
        // `--` ends option processing; the count may carry a sign and padding.
        assert_eq!(
            run("for a in 1 2; do for b in x y; do break -- 2; done; echo inner=$?; done; echo $?").0,
            "0\n"
        );
        assert_eq!(run("for i in 1 2; do break --; echo no; done; echo $?").0, "0\n");
        assert_eq!(
            run("for a in 1 2; do for b in x y; do break \" +2 \"; done; echo inner=$?; done; echo $?").0,
            "0\n"
        );
        // Outside a loop the operand is not looked at at all.
        let (o6, _) = run("{ break abc; } 2>&1; echo s=$?");
        assert_eq!(
            o6,
            "osh: break: only meaningful in a `for', `while', or `until' loop\ns=0\n"
        );
    }

    #[test]
    fn break_continue_outside_loop_warn_and_continue() {
        // Outside a loop, `break` warns to stderr, returns status 0, and does
        // NOT unwind — the following command still runs. (bash: same.)
        let (o, _) = run("echo before; break; echo after");
        assert_eq!(o, "before\nafter\n");
        let (o2, _) = run("{ break; } 2>&1; echo \"s=$?\"");
        assert_eq!(
            o2,
            "osh: break: only meaningful in a `for', `while', or `until' loop\ns=0\n"
        );
        let (o3, _) = run("{ continue; } 2>&1; echo \"s=$?\"");
        assert_eq!(
            o3,
            "osh: continue: only meaningful in a `for', `while', or `until' loop\ns=0\n"
        );
        // Inside a loop, `break` still works normally.
        assert_eq!(run("for i in 1 2 3; do echo $i; break; done; echo done").0, "1\ndone\n");
        // A `break` inside a function called from a loop must NOT break the
        // enclosing loop: bash resets loop nesting on function entry, so the
        // break is an error inside the function and the loop keeps iterating.
        let (o4, _) = run("f() { break; }; for i in 1 2 3; do echo $i; f; done 2>/dev/null");
        assert_eq!(o4, "1\n2\n3\n");
        // A `break` in a subshell inside a loop likewise does not break the
        // loop (bash resets loop nesting in the subshell).
        let (o5, _) = run("for i in 1 2; do echo $i; ( break ); done 2>/dev/null");
        assert_eq!(o5, "1\n2\n");
    }

    #[test]
    fn test_file_comparison_operators() {
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("clock")
            .as_nanos();
        let base = std::env::temp_dir();
        let a = base.join(format!("osh_ntef_{}_{nanos}_a", std::process::id()));
        let b = base.join(format!("osh_ntef_{}_{nanos}_b", std::process::id()));
        std::fs::write(&a, b"x").expect("write a");
        // Ensure b's mtime is strictly later than a's.
        std::thread::sleep(std::time::Duration::from_millis(20));
        std::fs::write(&b, b"y").expect("write b");
        let pa = a.to_string_lossy().replace('\\', "/");
        let pb = b.to_string_lossy().replace('\\', "/");

        // `[[ … ]]` form.
        assert_eq!(run(&format!("[[ {pb} -nt {pa} ]] && echo yes")).0, "yes\n");
        assert_eq!(run(&format!("[[ {pa} -ot {pb} ]] && echo yes")).0, "yes\n");
        assert_eq!(
            run(&format!("[[ {pa} -nt {pb} ]] && echo yes || echo no")).0,
            "no\n"
        );
        assert_eq!(run(&format!("[[ {pa} -ef {pa} ]] && echo yes")).0, "yes\n");
        assert_eq!(
            run(&format!("[[ {pa} -ef {pb} ]] && echo yes || echo no")).0,
            "no\n"
        );

        // `test` / `[` form.
        assert_eq!(run(&format!("[ {pb} -nt {pa} ] && echo yes")).0, "yes\n");
        assert_eq!(run(&format!("test {pa} -ef {pa} && echo yes")).0, "yes\n");

        // Existence rule: a exists, missing sibling does not → `-nt` is true.
        let missing = base.join(format!("osh_ntef_{}_{nanos}_gone", std::process::id()));
        let pm = missing.to_string_lossy().replace('\\', "/");
        assert_eq!(run(&format!("[[ {pa} -nt {pm} ]] && echo yes")).0, "yes\n");

        std::fs::remove_file(&a).ok();
        std::fs::remove_file(&b).ok();
    }

    #[test]
    fn array_literal_and_index() {
        assert_eq!(run("a=(one two three); echo ${a[0]}").0, "one\n");
        assert_eq!(run("a=(one two three); echo ${a[2]}").0, "three\n");
        // A bare reference reads element 0.
        assert_eq!(run("a=(one two three); echo $a").0, "one\n");
        // Out-of-range index expands to empty.
        assert_eq!(run("a=(one two); echo x${a[9]}y").0, "xy\n");
    }

    #[test]
    fn array_all_and_star() {
        assert_eq!(run("a=(x y z); echo ${a[@]}").0, "x y z\n");
        assert_eq!(run("a=(x y z); echo ${a[*]}").0, "x y z\n");
    }

    #[test]
    fn array_length() {
        assert_eq!(run("a=(a b c d); echo ${#a[@]}").0, "4\n");
        assert_eq!(run("a=(a b c d); echo ${#a[*]}").0, "4\n");
        // Length of a specific element.
        assert_eq!(run("a=(hi hello); echo ${#a[1]}").0, "5\n");
    }

    #[test]
    fn array_indexed_assignment() {
        assert_eq!(run("a=(x y z); a[1]=Q; echo ${a[@]}").0, "x Q z\n");
        // Assigning past the end adds one sparse element (bash: no gap-fill), so
        // the element count is 2 (indices 0 and 3), not 4.
        assert_eq!(run("a=(x); a[3]=w; echo ${#a[@]}").0, "2\n");
        assert_eq!(run("a=(x); a[3]=w; echo ${a[3]}").0, "w\n");
    }

    #[test]
    fn array_append() {
        assert_eq!(run("a=(x y); a+=(z w); echo ${a[@]}").0, "x y z w\n");
        assert_eq!(run("a=(x y); a+=(z); echo ${#a[@]}").0, "3\n");
    }

    #[test]
    fn array_negative_index() {
        // -1 is the last element, -2 the second-to-last (bash semantics).
        assert_eq!(run("a=(x y z); echo ${a[-1]}").0, "z\n");
        assert_eq!(run("a=(x y z); echo ${a[-2]}").0, "y\n");
        assert_eq!(run("a=(x y z); echo ${a[-3]}").0, "x\n");
        // Out-of-range negative → empty (bash treats it as a bad subscript).
        assert_eq!(run("a=(x y z); echo [${a[-4]}]").0, "[]\n");
        // Length of the last element via ${#a[-1]}.
        assert_eq!(run("a=(x yy zzz); echo ${#a[-1]}").0, "3\n");
        // A scalar answers to `[0]`, but it has no highest index to count back
        // from, so a negative subscript on one names nowhere at all.
        assert_eq!(run("x=hello; echo [${x[0]}]").0, "[hello]\n");
        assert_eq!(
            run("x=hello; { echo [${x[-1]}]; } 2>&1").0,
            "osh: x: bad array subscript\n[]\n"
        );
        // Negative index in an assignment target overwrites from the end.
        assert_eq!(run("a=(x y z); a[-1]=Q; echo ${a[@]}").0, "x y Q\n");
        assert_eq!(run("a=(x y z); a[-2]=Q; echo ${a[@]}").0, "x Q z\n");
        // Out-of-range negative assignment is a fatal error in command position:
        // bash aborts the script, so the trailing echo never runs (matches
        // `bash -c 'a=(x y); { a[-9]=Q; } 2>&1; echo ${a[@]}'` → error, exit 1).
        let (o, s) = run("a=(x y); { a[-9]=Q; } 2>&1; echo ${a[@]}");
        assert_eq!(o, "osh: a[-9]: bad array subscript\n");
        assert_eq!(s, 1);
    }

    #[test]
    fn a_subscript_naming_nowhere_is_reported_wherever_it_is_resolved() {
        // Reading one is not fatal: the complaint names the *base*, and the
        // reference stands for nothing, so every operator gets the answer it
        // would give an unset element.
        assert_eq!(
            run("a=(x); { echo [${a[-5]}]; } 2>&1").0,
            "osh: a: bad array subscript\n[]\n"
        );
        for op in ["-D", ":+A", "#p", "/x/y", "^^", ":0:2"] {
            let want = if op == "-D" { "[D]" } else { "[]" };
            assert_eq!(
                run(&format!("a=(x); {{ echo [${{a[-5]{op}}}]; }} 2>&1")).0,
                format!("osh: a: bad array subscript\n{want}\n"),
                "${{a[-5]{op}}}"
            );
        }
        // An empty associative key is the same fact about a different kind of
        // array, and is reported the same way.
        assert_eq!(
            run("declare -A m=([k]=v); b=; { echo [${m[$b]}]; } 2>&1").0,
            "osh: m: bad array subscript\n[]\n"
        );
        // A nameref that stands for such an element reports it on the nameref's
        // behalf, naming the array it points into.
        assert_eq!(
            run("a=(x y); declare -n r='a[-5]'; { echo [$r]; } 2>&1; echo AFTER").0,
            "osh: a: bad array subscript\n[]\nAFTER\n"
        );
        // The *length* form is the one read that is fatal, and it names the
        // subscript rather than the base.
        let (o, s) = run("a=(x); { echo [${#a[-5]}]; } 2>&1; echo AFTER");
        assert_eq!(o, "osh: -5]: bad array subscript\n");
        assert_eq!(s, 1);

        // Writing through one is refused rather than silently dropped — the
        // complaint quotes the whole reference — and the array is not brought
        // into being by a write that never happened.
        assert_eq!(
            run("a=(x y); read 'a[-5]' <<< NEW 2>&1; echo rc=$?; declare -p a").0,
            "osh: a[-5]: bad array subscript\nrc=1\ndeclare -a a=([0]=\"x\" [1]=\"y\")\n"
        );
        assert_eq!(
            run("printf -v 'a[-1]' v 2>&1; echo rc=$?; declare -p a 2>&1").0,
            "osh: a[-1]: bad array subscript\nrc=1\nosh: declare: a: not found\n"
        );
        // `${a[i]:=v}` has nowhere to put the default, so the expansion cannot
        // be completed at all: the read reports it first, then the write, and
        // the command is discarded.
        let (o, s) = run("a=(x); { echo [${a[-5]:=v}]; } 2>&1; echo AFTER");
        assert_eq!(o, "osh: a: bad array subscript\nosh: a[-5]: bad array subscript\n");
        assert_eq!(s, 1);
    }

    #[test]
    fn arith_array_subscript() {
        // Array elements are addressable inside $(( … )) and (( … )).
        assert_eq!(run("a=(10 20 30); echo $(( a[1] ))").0, "20\n");
        assert_eq!(run("a=(10 20 30); i=2; echo $(( a[i] + 1 ))").0, "31\n");
        assert_eq!(run("a=(10 20 30); echo $(( a[i+1] ))").0, "20\n"); // i unset → 0, a[1]
        // Negative subscript inside arithmetic (last element).
        assert_eq!(run("a=(10 20 30); echo $(( a[-1] ))").0, "30\n");
        // A (( … )) command: a[0] is non-zero → success (exit 0).
        assert_eq!(run("a=(5 0); (( a[0] ))").1, 0);
        assert_eq!(run("a=(5 0); (( a[1] ))").1, 1); // zero → exit 1
    }

    #[test]
    fn array_element_with_operator() {
        // `:-` use-default on a present vs. absent element.
        assert_eq!(run("a=(x y z); echo ${a[1]:-def}").0, "y\n");
        assert_eq!(run("a=(x y z); echo ${a[9]:-def}").0, "def\n");
        // Negative subscript combined with an operator.
        assert_eq!(run("a=(x y z); echo ${a[-1]:-def}").0, "z\n");
        assert_eq!(run("a=(x y z); echo ${a[-9]:-def}").0, "def\n");
        // `:+` use-alternate: element set → arg; unset → empty.
        assert_eq!(run("a=(x y); echo [${a[0]:+set}]").0, "[set]\n");
        assert_eq!(run("a=(x y); echo [${a[5]:+set}]").0, "[]\n");
        // Prefix/suffix trim on an element.
        assert_eq!(run("a=(foo.txt bar.md); echo ${a[0]%.txt}").0, "foo\n");
        assert_eq!(run("a=(abcabc); echo ${a[0]#a}").0, "bcabc\n");
        // Substring on an element.
        assert_eq!(run("a=(hello world); echo ${a[1]:0:3}").0, "wor\n");
        // Pattern replacement on an element.
        assert_eq!(run("a=(a-b-c); echo ${a[0]//-/_}").0, "a_b_c\n");
        // `:=` assign-default writes the element back.
        assert_eq!(run("a=(x); echo ${a[2]:=new}; echo ${a[2]}").0, "new\nnew\n");
        // Associative element with an operator (string key).
        assert_eq!(
            run("declare -A m; m[k]=v; echo ${m[k]:-def} ${m[nope]:-def}").0,
            "v def\n"
        );
        // The use/alternate/error operators on `[@]`/`[*]` treat the array like
        // `$@` (see `array_use_alternate_error_operators` for full coverage).
        assert_eq!(run("a=(); echo ${a[@]:-def}").0, "def\n");
        assert_eq!(run("a=(p q); echo ${a[@]:-def}").0, "p q\n");
        // …and the element-wise (bulk) operators.
        assert_eq!(run("a=(a.x b.x); echo ${a[*]#*.}").0, "x x\n");
    }

    #[test]
    fn sparse_indexed_array() {
        // A sparse literal does NOT fill the gaps: only the assigned indices
        // exist, so the element count is the number of set elements.
        assert_eq!(run("a=([5]=x); echo ${#a[@]}").0, "1\n");
        assert_eq!(run("a=([5]=x); echo ${!a[@]}").0, "5\n");
        // Multiple explicit indices keep their gaps; `${a[@]}` and `${!a[@]}`
        // iterate in ascending-index order.
        assert_eq!(run("a=([2]=a [5]=b); echo ${a[@]}").0, "a b\n");
        assert_eq!(run("a=([2]=a [5]=b); echo ${!a[@]}").0, "2 5\n");
        // A plain `${a}` reads index 0 specifically — empty when unset.
        assert_eq!(run("a=([5]=x); echo [${a}]").0, "[]\n");
        assert_eq!(run("a=([5]=x); echo [${a[0]}]").0, "[]\n");
        // Negative index counts from the highest index + 1, not the count.
        assert_eq!(run("a=([2]=a [5]=b); echo ${a[-1]}").0, "b\n");
        // `unset a[i]` removes only that index (leaves a gap, no shift down).
        assert_eq!(run("a=(x y z); unset a[1]; echo ${!a[@]}").0, "0 2\n");
        assert_eq!(run("a=(x y z); unset a[1]; echo ${a[@]}").0, "x z\n");
        // Positional elements after a keyed one resume at that index + 1.
        assert_eq!(run("a=([2]=x y); echo ${!a[@]}").0, "2 3\n");
        // A sparse `a[i]=v` past the end adds one entry, not a filled range.
        assert_eq!(run("a=([5]=x); a[10]=y; echo ${#a[@]}").0, "2\n");
    }

    #[test]
    fn array_literal_spaced_subscript() {
        // TD-OILS-ARRAYLIT-SPACED-SUBSCRIPT: a keyed array-literal subscript that
        // contains whitespace is scanned as a *single* `[ … ]=` unit (up to the
        // matching `]`), not split at the space — matching bash. A spaced-but-valid
        // arithmetic subscript evaluates normally; an invalid one is fatal with
        // bash's exact arith diagnostic; an associative key keeps its literal
        // spaces. All three verified byte-for-byte against bash 5.2.
        assert_eq!(run("a=([1 + 2]=99); declare -p a").0, "declare -a a=([3]=\"99\")\n");
        // The invalid arith subscript is fatal; route its stderr into the capture
        // via a redirected group so the diagnostic text can be asserted.
        let (o, s) = run("{ a=([3 x]=99); } 2>&1");
        assert_eq!(o, "osh: 3 x: syntax error in expression (error token is \"x\")\n");
        assert_eq!(s, 1);
        assert_eq!(
            run("declare -A m; m=([a b]=v); declare -p m").0,
            "declare -A m=([\"a b\"]=\"v\" )\n"
        );
    }

    #[test]
    fn array_quoted_all_preserves_fields() {
        // "${a[@]}" keeps element boundaries even with embedded spaces.
        let out = run(r#"a=("a b" c); for w in "${a[@]}"; do echo "[$w]"; done"#).0;
        assert_eq!(out, "[a b]\n[c]\n");
    }

    #[test]
    fn array_unquoted_all_splits() {
        // Unquoted ${a[@]} field-splits, so "a b" becomes two words.
        let out = run(r#"a=("a b" c); for w in ${a[@]}; do echo "[$w]"; done"#).0;
        assert_eq!(out, "[a]\n[b]\n[c]\n");
    }

    #[test]
    fn array_unset() {
        assert_eq!(run("a=(x y z); unset a[1]; echo ${a[@]}").0, "x z\n");
        assert_eq!(run("a=(x y z); unset a; echo ${#a[@]}").0, "0\n");
    }

    #[test]
    fn array_from_glob_and_expansion() {
        // Array elements undergo splitting/expansion.
        assert_eq!(run("s='p q'; a=($s r); echo ${#a[@]}").0, "3\n");
    }

    #[test]
    fn array_keyed_literal_indexed() {
        // `[i]=v` elements place at an explicit index; positional resume after.
        assert_eq!(run("a=([2]=x y); echo ${a[2]} ${a[3]}").0, "x y\n");
        assert_eq!(run("a=(p [5]=q); echo ${a[0]} ${a[5]}").0, "p q\n");
    }

    #[test]
    fn assoc_basic_set_and_read() {
        let src = "declare -A m; m[foo]=1; m[bar]=2; echo ${m[foo]} ${m[bar]}";
        assert_eq!(run(src).0, "1 2\n");
    }

    #[test]
    fn assoc_all_values_and_keys() {
        // Values and keys come back in insertion order.
        assert_eq!(run("declare -A m; m[a]=x; m[b]=y; echo ${m[@]}").0, "x y\n");
        assert_eq!(run("declare -A m; m[a]=x; m[b]=y; echo ${!m[@]}").0, "a b\n");
    }

    #[test]
    fn assoc_length_and_overwrite() {
        assert_eq!(run("declare -A m; m[a]=1; m[b]=2; echo ${#m[@]}").0, "2\n");
        // Re-assigning a key overwrites in place (count unchanged).
        let src = "declare -A m; m[k]=1; m[k]=2; echo ${m[k]}; echo ${#m[@]}";
        assert_eq!(run(src).0, "2\n1\n");
    }

    #[test]
    fn assoc_literal_init() {
        let src = "declare -A m; m=([x]=1 [y]=2); echo ${m[x]} ${m[y]}; echo ${#m[@]}";
        assert_eq!(run(src).0, "1 2\n2\n");
    }

    #[test]
    fn assoc_expanded_key() {
        // The subscript on assignment/read is a string key, expanded not arith'd.
        assert_eq!(run("declare -A m; k=foo; m[$k]=bar; echo ${m[foo]}").0, "bar\n");
    }

    #[test]
    fn assoc_key_with_unquoted_spaces() {
        // bash's tokenizer keeps a `name[…]=` subscript as one assignment word
        // even with unquoted interior spaces, so `h[a b]=v` stores under the
        // literal key "a b". Chained assignments on one line also work.
        assert_eq!(
            run("declare -A h; h[a b]=1 h[c d]=2; echo \"${h[a b]}${h[c d]}\"").0,
            "12\n"
        );
        assert_eq!(
            run("declare -A h; h[key with space]=v; echo \"${h[key with space]}\"").0,
            "v\n"
        );
        // Argument position still word-splits: `echo h[a b]` prints two fields.
        assert_eq!(run("echo h[a b]").0, "h[a b]\n");
    }

    #[test]
    fn assoc_literal_quoted_key() {
        // A keyed array-literal element whose subscript is *quoted* — so the
        // closing `]=` lands in a later segment than the opening `[` — must
        // still parse as a keyed element (bash: `(["k v"]=1)` stores under the
        // key `k v`). Regression: osh previously treated any quoted-key element
        // as positional and errored with "must use subscript".
        assert_eq!(
            run("declare -A h=([\"k v\"]=1); echo \"[${h[k v]}]\"").0,
            "[1]\n"
        );
        // Single-quoted key, and a quoted key containing a literal `]`.
        assert_eq!(
            run("declare -A h=(['a b']=2); echo \"[${h[a b]}]\"").0,
            "[2]\n"
        );
        assert_eq!(
            run("declare -A h=([\"x]y\"]=3); declare -p h").0,
            "declare -A h=([\"x]y\"]=\"3\" )\n"
        );
        // Mixed bare and quoted keys in one literal, plus an expansion key.
        assert_eq!(
            run("k=dk; declare -A h=([p]=1 [\"q u\"]=2 [$k]=3); echo \"${h[p]}${h[q u]}${h[dk]}\"").0,
            "123\n"
        );
    }

    #[test]
    fn assoc_read_quoted_bracket_in_subscript() {
        // TD-OILS-SUBSCRIPT-QUOTED-BRACKET: reading an associative element whose
        // key contains a literal `]` with the subscript *quoted*
        // (`${h["a]b"]}`) must not mistake the quoted `]` for the subscript
        // terminator. Previously the subscript scanner split mid-quote, leaving
        // an unbalanced quote that failed with `unexpected EOF … matching '"'`.
        // Double-quoted key with an embedded `]`.
        assert_eq!(
            run("declare -A h=([\"with]bracket\"]=1); echo \"${h[\"with]bracket\"]}\"").0,
            "1\n"
        );
        // Single-quoted key with an embedded `]`.
        assert_eq!(
            run("declare -A h=(['a]b']=2); echo \"${h['a]b']}\"").0,
            "2\n"
        );
        // A key containing a *balanced* `[...]` inside the quotes: the nested
        // brackets are skipped as quoted content, so depth tracking still finds
        // the real close.
        assert_eq!(
            run("declare -A h=([\"a[b]c\"]=3); echo \"${h[\"a[b]c\"]}\"").0,
            "3\n"
        );
        // Regression guard: a plain quoted key without `]` and an ordinary
        // indexed read still resolve correctly.
        assert_eq!(run("declare -A h=([\"k\"]=4); echo \"${h[\"k\"]}\"").0, "4\n");
        assert_eq!(run("a=(7 8 9); echo \"${a[2]}\"").0, "9\n");
    }

    #[test]
    fn assoc_key_preserves_surrounding_whitespace() {
        // bash never trims an associative subscript: `h[ x ]=v` keys on the
        // literal " x " (with surrounding spaces), on both the store and the read
        // path. A no-space read `${h[x]}` therefore does NOT match. (Regression
        // for TD-OILS-ASSOC-KEY-TRIM.)
        assert_eq!(run("declare -A h; h[ x ]=v; echo \"[${!h[@]}]\"").0, "[ x ]\n");
        assert_eq!(run("declare -A h; h[ x ]=v; echo \"[${h[ x ]}]\"").0, "[v]\n");
        assert_eq!(run("declare -A h; h[ x ]=v; echo \"[${h[x]}]\"").0, "[]\n");
        // Same for a keyed array-literal element `([ x ]=v)`.
        assert_eq!(
            run("declare -A m=([ x ]=v); echo \"[${!m[@]}]\"").0,
            "[ x ]\n"
        );
        // Indexed subscripts still arithmetic-evaluate (whitespace ignored).
        assert_eq!(run("declare -a a; a[ 1 + 2 ]=v; echo ${!a[@]}").0, "3\n");
    }

    #[test]
    fn declare_p_quotes_assoc_keys_needing_it() {
        // `declare -p` quotes an associative key when it holds a shell
        // metacharacter (so the subscript round-trips), and leaves "safe" keys
        // bare — matching bash.
        assert_eq!(
            run("declare -A m; m[x]=v; declare -p m").0,
            "declare -A m=([x]=\"v\" )\n"
        );
        assert_eq!(
            run("declare -A m; m[\"a b\"]=v; declare -p m").0,
            "declare -A m=([\"a b\"]=\"v\" )\n"
        );
        // `-`/`@`/`#` do not force quoting.
        assert_eq!(
            run("declare -A m; m[\"a-b\"]=v; declare -p m").0,
            "declare -A m=([a-b]=\"v\" )\n"
        );
    }

    #[test]
    fn assoc_scalar_assignment_targets_key_zero() {
        // A subscript-less `name=value` on an existing associative array assigns
        // to key "0" (bash: `declare -A b; b=a` yields `b[0]=a`). Same for the
        // `+=` append and the `-i` integer forms, and it coexists with other keys.
        assert_eq!(run("declare -A b; b=a; echo \"[${b[0]}]\"").0, "[a]\n");
        assert_eq!(run("declare -A b; b=x; b+=y; echo \"[${b[0]}]\"").0, "[xy]\n");
        assert_eq!(run("declare -A b; b+=y; echo \"[${b[0]}]\"").0, "[y]\n");
        assert_eq!(run("declare -Ai b; b=5; b+=3; echo \"[${b[0]}]\"").0, "[8]\n");
        assert_eq!(
            run("declare -A b=([k]=v); b=scalar; echo \"${b[0]}-${b[k]}\"").0,
            "scalar-v\n"
        );
    }

    #[test]
    fn declare_p_empty_array_distinguishes_assigned_from_declared() {
        // bash distinguishes an assigned-but-empty array (`a=()` → `=()`) from
        // one merely declared with `declare -a a` and never given a value
        // (bare `declare -a a`). osh tracks a per-name has-a-value flag.
        assert_eq!(run("a=(); declare -p a").0, "declare -a a=()\n");
        assert_eq!(run("declare -A m=(); declare -p m").0, "declare -A m=()\n");
        assert_eq!(run("declare -a a; declare -p a").0, "declare -a a\n");
        assert_eq!(run("declare -A m; declare -p m").0, "declare -A m\n");
        // An element assignment gives the array a value even after every
        // element is unset — the flag is sticky until the whole var is unset.
        assert_eq!(
            run("declare -a a; a[3]=x; unset 'a[3]'; declare -p a").0,
            "declare -a a=()\n"
        );
        assert_eq!(
            run("declare -A m; m[k]=v; unset 'm[k]'; declare -p m").0,
            "declare -A m=()\n"
        );
        // `+=` on an empty array is still an assignment.
        assert_eq!(run("a=(); a+=(); declare -p a").0, "declare -a a=()\n");
        // Combined attribute + empty literal.
        assert_eq!(run("declare -ai a=(); declare -p a").0, "declare -ai a=()\n");
        // Unsetting the whole variable clears the flag.
        assert_eq!(
            run("a=(); unset a; declare -a a; declare -p a").0,
            "declare -a a\n"
        );
    }

    #[test]
    fn read_a_creates_empty_array_on_eof() {
        // bash's `read -a arr` resets the target to empty up front, so even an
        // EOF with no data leaves a defined, empty array (and a pre-existing
        // array is replaced, not merged).
        assert_eq!(
            run("read -a arr < /dev/null; echo rc=$?; declare -p arr").0,
            "rc=1\ndeclare -a arr=()\n"
        );
        assert_eq!(
            run("arr=(old); read -a arr < /dev/null; declare -p arr").0,
            "declare -a arr=()\n"
        );
        assert_eq!(
            run("read -a arr <<< 'x y'; declare -p arr").0,
            "declare -a arr=([0]=\"x\" [1]=\"y\")\n"
        );
    }

    #[test]
    fn read_stores_through_a_subscripted_name() {
        // A `read` operand is a *name*, and bash's idea of a name includes a
        // subscripted one — so a record can go straight into an element without
        // a temporary in between.
        assert_eq!(
            run("a=(x y); read 'a[1]' <<< NEW; declare -p a").0,
            "declare -a a=([0]=\"x\" [1]=\"NEW\")\n"
        );
        // The subscript is evaluated as arithmetic on an indexed array, and
        // taken as a literal key on an associative one.
        assert_eq!(run("v=5; read 'a[v]' <<< NEW; declare -p a").0, "declare -a a=([5]=\"NEW\")\n");
        assert_eq!(
            run("a=(x y); read 'a[1+1]' <<< NEW; declare -p a").0,
            "declare -a a=([0]=\"x\" [1]=\"y\" [2]=\"NEW\")\n"
        );
        assert_eq!(
            run("a=(x y z); read 'a[-1]' <<< NEW; declare -p a").0,
            "declare -a a=([0]=\"x\" [1]=\"y\" [2]=\"NEW\")\n"
        );
        assert_eq!(
            run("declare -A m; read 'm[k v]' <<< NEW; declare -p m").0,
            "declare -A m=([\"k v\"]=\"NEW\" )\n"
        );
        // An element target is a field like any other, so it takes its own
        // field and the array's attributes still apply to what lands in it.
        assert_eq!(
            run("read 'a[1]' x <<< 'p q'; declare -p a x").0,
            "declare -a a=([1]=\"p\")\ndeclare -- x=\"q\"\n"
        );
        assert_eq!(
            run("declare -i a; read 'a[0]' <<< '3+4'; declare -p a").0,
            "declare -ai a=([0]=\"7\")\n"
        );
        // The refusal is the array's, and it names the array rather than the
        // element that was aimed at.
        assert_eq!(
            run("a=(x y); readonly a; read 'a[1]' <<< NEW 2>&1; declare -p a").0,
            "osh: a: readonly variable\ndeclare -ar a=([0]=\"x\" [1]=\"y\")\n"
        );
        // A nameref reaches the array it stands for.
        assert_eq!(
            run("declare -n r=arr; read 'r[0]' <<< NEW; declare -p arr").0,
            "declare -a arr=([0]=\"NEW\")\n"
        );
    }

    #[test]
    fn read_checks_its_first_name_before_it_reads() {
        // Only a name that could never hold anything is refused: an identifier,
        // or an identifier with a non-empty subscript, is all bash accepts.
        for bad in ["1bad", "a-b", "a[b", "a[]", ""] {
            assert_eq!(
                run(&format!("read '{bad}' <<< x 2>&1; echo rc=$?")).0,
                format!("osh: read: `{bad}': not a valid identifier\nrc=1\n"),
                "read {bad}"
            );
        }
        // The *first* name is checked before anything is read, so that refusal
        // costs the input nothing and a following read still sees all of it…
        assert_eq!(
            run("{ read 1bad ok; read r; } <<< 'p q' 2>/dev/null; echo \"r=[$r] ok=[${ok-unset}]\"").0,
            "r=[p q] ok=[unset]\n"
        );
        // …while a later one is only reached once the record has been read and
        // handed out, so the input is gone and the earlier names keep what they
        // were given.
        assert_eq!(
            run("{ read x y 1bad; read r; } <<< 'p q z' 2>/dev/null; echo \"r=[$r] x=[$x] y=[$y]\"").0,
            "r=[] x=[p] y=[q]\n"
        );
        // `-a` names an array to fill, so a subscript is not a name it takes —
        // and being an option argument rather than an operand, it is checked
        // only after the input has been consumed.
        assert_eq!(
            run("read -a 'a[1]' <<< x 2>&1; echo rc=$?").0,
            "osh: read: `a[1]': not a valid identifier\nrc=1\n"
        );
        assert_eq!(
            run("{ read -a 1bad; read r; } <<< 'p q' 2>/dev/null; echo \"r=[$r]\"").0,
            "r=[]\n"
        );
    }

    #[test]
    fn printf_checks_its_v_name_as_it_reads_it() {
        // Same pair of accepted shapes as `read`'s names, refused with printf's
        // own wording and the usage error's status 2.
        for bad in ["1bad", "a-b", "a[", "a[]", " a", ""] {
            assert_eq!(
                run(&format!("printf -v '{bad}' x 2>&1; echo rc=$?")).0,
                format!("osh: printf: `{bad}': not a valid identifier\nrc=2\n"),
                "printf -v {bad}"
            );
        }
        // The name is checked as the option is read, ahead of everything else
        // printf would complain about — the format it is missing, and the
        // argument that would not have converted.
        assert_eq!(
            run("printf -v 1bad 2>&1; echo rc=$?").0,
            "osh: printf: `1bad': not a valid identifier\nrc=2\n"
        );
        assert_eq!(
            run("printf -v 1bad '%d' abc 2>&1; echo rc=$?").0,
            "osh: printf: `1bad': not a valid identifier\nrc=2\n"
        );
        // Glued or separate, it is the same name.
        assert_eq!(
            run("printf -v1bad x 2>&1; echo rc=$?").0,
            "osh: printf: `1bad': not a valid identifier\nrc=2\n"
        );
        // An empty key reaches this check as the empty subscript it expanded
        // to, so it is refused as a name rather than as a bad subscript.
        assert_eq!(
            run("declare -A m; b=''; printf -v \"m[$b]\" x 2>&1; echo rc=$?; declare -p m").0,
            "osh: printf: `m[]': not a valid identifier\nrc=2\ndeclare -A m\n"
        );
        // The shapes that do name somewhere are untouched.
        assert_eq!(run("printf -v 'a[0]' x; declare -p a").0, "declare -a a=([0]=\"x\")\n");
        assert_eq!(
            run("declare -A m; printf -v 'm[k v]' x; declare -p m").0,
            "declare -A m=([\"k v\"]=\"x\" )\n"
        );
        assert_eq!(run("printf -v a '%s' hi; echo \"[$a]\"").0, "[hi]\n");
    }

    #[test]
    fn read_at_eof_still_empties_its_names() {
        // A `read` that finds nothing is still an assignment: bash empties every
        // name it was given before reporting the EOF, so a stale value from an
        // earlier read is never left behind to be mistaken for a fresh one.
        assert_eq!(
            run("r=stale; read r < /dev/null; echo \"rc=$? r=[$r]\"").0,
            "rc=1 r=[]\n"
        );
        // Which matters most where it is easiest to miss: the second of two
        // reads on the same source, where the first one succeeded.
        assert_eq!(
            run("r=s1; s=s2; { read r; read s; } <<< x; echo \"r=[$r] s=[$s]\"").0,
            "r=[x] s=[]\n"
        );
        // Every name, not just the first, and REPLY when there are none.
        assert_eq!(
            run("a=1 b=2; read a b < /dev/null; echo \"[$a][$b]\"").0,
            "[][]\n"
        );
        assert_eq!(
            run("REPLY=stale; read < /dev/null; echo \"[$REPLY]\"").0,
            "[]\n"
        );
        // It goes through the ordinary assignment, so the name's attributes
        // apply to the empty value and a readonly one still refuses it.
        assert_eq!(
            run("declare -i r=5; read r < /dev/null; echo \"rc=$? r=[$r]\"").0,
            "rc=1 r=[0]\n"
        );
        assert_eq!(
            run("r=stale; readonly r; read r < /dev/null 2>&1; echo \"r=[$r]\"").0,
            "osh: r: readonly variable\nr=[stale]\n"
        );
        // The record readers report the same way.
        for opt in ["-d ,", "-d ''", "-n 3", "-N 3"] {
            assert_eq!(
                run(&format!("r=stale; read {opt} r < /dev/null; echo \"rc=$? r=[$r]\"")).0,
                "rc=1 r=[]\n",
                "read {opt} at EOF"
            );
        }
    }

    #[test]
    fn read_of_zero_characters_is_satisfied_without_reading() {
        // A count of zero is the one way to come back empty and still succeed:
        // what was asked for was read in full. It is answered without touching
        // the input, so the next read still sees all of it.
        for opt in ["-n 0", "-N 0"] {
            assert_eq!(
                run(&format!("r=stale; read {opt} r <<< abc; echo \"rc=$? r=[$r]\"")).0,
                "rc=0 r=[]\n",
                "read {opt}"
            );
            assert_eq!(
                run(&format!("{{ read {opt} a; read b; }} <<< abc; echo \"[$a][$b]\"")).0,
                "[][abc]\n",
                "read {opt} consumed input"
            );
            // Even with no input at all, since none was wanted.
            assert_eq!(
                run(&format!("read {opt} r < /dev/null; echo rc=$?")).0,
                "rc=0\n",
                "read {opt} at EOF"
            );
        }
        // It is an assignment like any other, so it empties an array target and
        // is still refused by a readonly one.
        assert_eq!(
            run("a=(x y); read -n 0 -a a <<< 'p q'; echo rc=$?; declare -p a").0,
            "rc=0\ndeclare -a a=()\n"
        );
        assert_eq!(
            run("r=stale; readonly r; read -n 0 r <<< abc 2>&1; echo \"rc=$? r=[$r]\"").0,
            "osh: r: readonly variable\nrc=1 r=[stale]\n"
        );
    }

    #[test]
    fn shellopts_reflects_option_state_and_is_readonly() {
        // bash exposes the enabled `set -o` options as a readonly, colon-
        // separated, alphabetically-sorted list. A non-interactive shell's
        // default is braceexpand:hashall:interactive-comments.
        assert_eq!(
            run_script("echo \"[$SHELLOPTS]\"").0,
            "[braceexpand:hashall:interactive-comments]\n"
        );
        // Enabling an option inserts its long name in sorted position.
        assert_eq!(
            run_script("set -u; echo \"$SHELLOPTS\"").0,
            "braceexpand:hashall:interactive-comments:nounset\n"
        );
        assert_eq!(
            run_script("set -f -a -C -x; echo \"$SHELLOPTS\"").0,
            "allexport:braceexpand:hashall:interactive-comments:noclobber:noglob:xtrace\n"
        );
        // Disabling removes it again.
        assert_eq!(
            run_script("set -u; set +u; echo \"$SHELLOPTS\"").0,
            "braceexpand:hashall:interactive-comments\n"
        );
        // `declare -p` renders it readonly (not exported).
        assert_eq!(
            run_script("set -u; declare -p SHELLOPTS").0,
            "declare -r SHELLOPTS=\"braceexpand:hashall:interactive-comments:nounset\"\n"
        );
        // It cannot be assigned to.
        assert_eq!(run_script("SHELLOPTS=foo; echo after").1, 1);
    }

    #[test]
    fn shellopts_gains_the_interactive_defaults() {
        // `histexpand` and `history` default to the shell's interactivity, so an
        // interactive shell lists both. Measured:
        // `bash --norc --noprofile -i -c 'echo $SHELLOPTS'` reports
        // braceexpand:emacs:hashall:histexpand:history:interactive-comments.
        // osh omits `emacs` on purpose — it has no line editor, so claiming the
        // option would make `[[ -o emacs ]]` lie (see `shell_option_enabled`).
        assert_eq!(
            run("echo \"$SHELLOPTS\"").0,
            "braceexpand:hashall:histexpand:history:interactive-comments\n"
        );
        // `set +o` on either one overrides the interactive default…
        assert_eq!(
            run("set +H; set +o history; echo \"$SHELLOPTS\"").0,
            "braceexpand:hashall:interactive-comments\n"
        );
        // …and `set -o` overrides the script default the same way.
        assert_eq!(
            run_script("set -o history; set -H; echo \"$SHELLOPTS\"").0,
            "braceexpand:hashall:histexpand:history:interactive-comments\n"
        );
        // `[[ -o NAME ]]` agrees with the listing, both ways round.
        assert_eq!(run("[[ -o histexpand ]] && [[ -o history ]]; echo $?").0, "0\n");
        assert_eq!(run_script("[[ -o histexpand ]] || [[ -o history ]]; echo $?").0, "1\n");
    }

    #[test]
    fn bulk_attr_transform_empty_positional_is_empty() {
        // `${@@A}` / `${*@A}` with no positional parameters yields nothing (not a
        // bare `set -- `), matching bash.
        assert_eq!(run("set -- ; echo \"[${@@A}]\"").0, "[]\n");
        assert_eq!(run("set -- ; echo \"[${*@A}]\"").0, "[]\n");
        // With params it still produces the re-inputtable `set --` form.
        assert_eq!(run("set -- x y; echo \"${@@A}\"").0, "set -- 'x' 'y'\n");
    }

    #[test]
    fn assoc_unset_key() {
        let src = "declare -A m; m[a]=1; m[b]=2; unset m[a]; echo ${!m[@]}; echo ${#m[@]}";
        assert_eq!(run(src).0, "b\n1\n");
    }

    #[test]
    fn assoc_quoted_all_preserves_fields() {
        let src = r#"declare -A m; m[a]="x y"; m[b]=z; for v in "${m[@]}"; do echo "[$v]"; done"#;
        assert_eq!(run(src).0, "[x y]\n[z]\n");
    }

    #[test]
    fn assoc_bare_ref_reads_key_zero() {
        // `$m` on an associative array reads the value at key "0", not "first".
        assert_eq!(run("declare -A m; m[foo]=a; m[0]=z; echo $m").0, "z\n");
    }

    #[test]
    fn declare_assoc_oneliner() {
        // The combined `declare -A m=([k]=v)` form now works in one statement.
        let src = "declare -A m=([x]=1 [y]=2); echo ${m[x]} ${m[y]}; echo ${#m[@]}";
        assert_eq!(run(src).0, "1 2\n2\n");
    }

    #[test]
    fn declare_indexed_oneliner() {
        // `declare -a a=(x y z)` (and the flagless `declare a=(…)`) make an
        // indexed array in one statement.
        assert_eq!(run("declare -a a=(x y z); echo ${a[1]} ${#a[@]}").0, "y 3\n");
        assert_eq!(run("declare a=(p q); echo ${a[@]}").0, "p q\n");
    }

    #[test]
    fn declare_array_string_value_is_reparsed_literal() {
        // A quoted parenthesized string assigned to a declared array is a
        // compound array literal that bash re-parses and re-expands.
        assert_eq!(run("declare -a a=\"(1 2 3)\"; echo ${#a[@]} ${a[2]}").0, "3 3\n");
        // Sparse indices survive the round-trip.
        assert_eq!(
            run("declare -a a=\"([2]=x [5]=y)\"; echo ${!a[@]}").0,
            "2 5\n"
        );
        // Associative keys via a string literal.
        assert_eq!(
            run("declare -A m=\"([k1]=v1 [k2]=v2)\"; echo ${m[k1]}${m[k2]}").0,
            "v1v2\n"
        );
        // A non-parenthesized string becomes element/key 0.
        assert_eq!(run("declare -a a=\"hi\"; echo ${a[0]}").0, "hi\n");
        assert_eq!(run("declare -A m=\"str\"; echo ${m[0]}").0, "str\n");
        // Append merges another literal onto the existing elements.
        assert_eq!(
            run("declare -a a=\"(1 2)\"; declare -a a+=\"(3 4)\"; echo ${a[@]}").0,
            "1 2 3 4\n"
        );
    }

    #[test]
    fn declare_assoc_oneliner_is_associative() {
        // A `-A` one-liner must be associative (string subscripts), not indexed:
        // a non-numeric key must round-trip.
        let src = "declare -A m=([foo]=bar); echo ${m[foo]}; echo ${!m[@]}";
        assert_eq!(run(src).0, "bar\nfoo\n");
    }

    /// A unique cwd-relative temp path (no `set_current_dir`, so parallel-safe).
    fn uniq_path(tag: &str) -> String {
        // Absolute path under the temp dir (forward slashes so it feeds cleanly
        // into shell scripts). Using an absolute path makes these tests
        // independent of the process cwd, so they never race the cwd-mutating
        // tests (`cd`/`pushd`) even though they don't hold `cwd_guard`.
        let tmp = std::env::temp_dir().to_string_lossy().replace('\\', "/");
        let tmp = tmp.trim_end_matches('/');
        format!(
            "{tmp}/osh_{tag}_{}_{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .expect("clock")
                .as_nanos()
        )
    }

    #[test]
    fn compound_while_read_from_file() {
        let path = uniq_path("whileread");
        std::fs::write(&path, "alpha\nbeta\ngamma\n").expect("write");
        let (o, _) = run(&format!(
            "while read line; do echo \"got:$line\"; done < {path}"
        ));
        std::fs::remove_file(&path).ok();
        assert_eq!(o, "got:alpha\ngot:beta\ngot:gamma\n");
    }

    #[test]
    fn dev_null_read_yields_eof() {
        // Reading `/dev/null` must yield EOF (empty, rc=1), not the contents of
        // a stray host file. On Windows this is mapped to the `NUL` device.
        let (o, st) = run("read x < /dev/null; echo \"rc=$? x=[$x]\"");
        assert_eq!(o, "rc=1 x=[]\n");
        assert_eq!(st, 0);
        assert_eq!(run("cat < /dev/null; echo done").0, "done\n");
    }

    #[test]
    fn dev_null_write_discards() {
        // Writing to `/dev/null` must discard output, not create a real file.
        let (_, st) = run("echo junk > /dev/null");
        assert_eq!(st, 0);
        // A subsequent read of /dev/null still sees EOF (nothing was persisted).
        assert_eq!(run("read x < /dev/null; echo \"[$x]\"").0, "[]\n");
    }

    #[test]
    fn same_command_fd_dup_resolves() {
        // Regression: a *simple* command that opens a scratch descriptor and
        // then dups from it within the SAME command (`3>&1 2>&3`) must resolve
        // the dup rather than report "3: Bad file descriptor". The collapsed
        // RedirPlan buckets each effect into a fixed slot and loses left-to-
        // right order, so only `exec` and compound commands used to install the
        // scratch fds. The executor now materialises `extra_fds` for simple
        // builtins and externals too (via install/restore around the run),
        // mirroring the compound path. Captured through command substitution
        // (fd 1 is a pipe), so the dup aliases onto that pipe.
        // Builtin `echo`:
        assert_eq!(run("r=$(echo hi 3>&1 2>&3); echo \"[$r]\""), ("[hi]\n".into(), 0));
        // A different scratch fd number works the same way.
        assert_eq!(run("r=$(echo hi 4>&1 2>&4); echo \"[$r]\""), ("[hi]\n".into(), 0));
        // External command (`env echo`): the child inherits the resolved fds.
        assert_eq!(run("r=$(env echo hi 3>&1 2>&3); echo \"[$r]\""), ("[hi]\n".into(), 0));
    }

    #[test]
    fn ambiguous_redirect_target_must_be_one_field() {
        // A redirect target that expands to zero fields (unset/empty *unquoted*
        // expansion) or more than one (word splitting) is an "ambiguous
        // redirect": the redirect fails (status 1) and the command does not run.
        // (The diagnostic text — the word echoed *as written* — is verified
        // against bash via the CLI probe suite; the resolve-time error bypasses
        // the stdout capture used here, so these assert status + non-execution.)
        assert_eq!(run("echo hi >$undef; echo after").1, 0); // list continues
        assert_eq!(run("echo hi >$undef").1, 1);
        // Multi-word split target is ambiguous; a *quoted* multi-word target is
        // a single field and succeeds (writes the file — checked in the redirect
        // file tests). Here just the status.
        assert_eq!(run("v='a b'; echo hi >$v").1, 1);
        // Input and append forms behave the same.
        assert_eq!(run("cat <$undef").1, 1);
        assert_eq!(run("echo hi >>$undef").1, 1);
        // The command does not run when its redirect is ambiguous: a following
        // command in the list still executes (status of the list is the echo).
        assert_eq!(run("echo NOPE >$undef; echo after").0, "after\n");
        // A *quoted* empty expansion is a single (empty) field — NOT ambiguous;
        // it attempts to open "" and fails with a plain open error (still 1, but
        // via a different path). Distinguished here by the DIRSTACK-independent
        // fact that an unquoted-empty and quoted-empty both fail: assert both 1.
        assert_eq!(run("v=; echo hi >\"$v\"").1, 1);
    }

    #[test]
    fn fd_dup_bad_descriptor_is_status_one() {
        // An unopened output/input fd dup fails the redirect with status 1 and
        // does not run the command. (The diagnostic echoes the word as written —
        // `>&$n` → "$n: Bad file descriptor" — verified against bash via the CLI
        // probes; the message bypasses this harness's stdout capture.)
        assert_eq!(run("n=5; echo hi >&$n").1, 1);
        assert_eq!(run("echo hi >&7").1, 1);
        assert_eq!(run("r=8; read x <&$r").1, 1);
        // A following command still runs (the failure is scoped to the redirect).
        assert_eq!(run("echo NOPE >&7; echo after").0, "after\n");
        // A validly-opened scratch fd dup still resolves (regression guard for
        // the resolve-time validation not rejecting staged same-command fds).
        assert_eq!(run("r=$(echo ok 3>&1 2>&3)").1, 0);
    }

    #[test]
    fn read_dash_t_zero_polls_without_consuming() {
        // `read -t 0` is a non-consuming availability poll: it assigns nothing
        // and exits 0 when a read would proceed without blocking (bash returns 0
        // for a seekable/ready source — including an empty file or EOF — and
        // non-zero only when a read would block). Regression for `-t` previously
        // being parsed-and-ignored, which turned `-t 0` into a real blocking
        // read that also consumed a line.
        // A here-string source is always ready:
        assert_eq!(run("read -t 0 <<< \"x\"; echo $?"), ("0\n".into(), 0));
        // An empty here-string is still ready (bash: 0):
        assert_eq!(run("read -t 0 <<< \"\"; echo $?"), ("0\n".into(), 0));
        // /dev/null (immediate EOF) counts as ready:
        assert_eq!(run("read -t 0 </dev/null; echo $?"), ("0\n".into(), 0));
        // It must NOT consume: a following `read` still sees the first line.
        assert_eq!(run("{ read -t 0; read x; echo \"[$x]\"; } <<< \"keep\""), ("[keep]\n".into(), 0));
    }

    #[test]
    fn ulimit_reports_and_sets_limits() {
        // A single resource prints the bare value; `-n` defaults to 1024.
        assert_eq!(run("ulimit -n"), ("1024\n".into(), 0));
        // No option letter defaults to the file-size limit (`-f`), unlimited.
        assert_eq!(run("ulimit"), ("unlimited\n".into(), 0));
        // Setting a soft limit is honoured by a subsequent query.
        assert_eq!(run("ulimit -n 512; ulimit -n"), ("512\n".into(), 0));
        // `unlimited` operand round-trips.
        assert_eq!(run("ulimit -c unlimited; ulimit -c"), ("unlimited\n".into(), 0));
        // Setting without -H/-S touches both; -H then reads the hard value.
        assert_eq!(run("ulimit -n 256; ulimit -Hn"), ("256\n".into(), 0));
        // -S alone leaves the hard limit unchanged (still unlimited by default).
        assert_eq!(run("ulimit -Sn 100; ulimit -Hn"), ("unlimited\n".into(), 0));
        // Accepting a set operand returns success (common `ulimit -c 0` idiom).
        assert_eq!(run("ulimit -c 0; echo $?"), ("0\n".into(), 0));
    }

    #[test]
    fn ulimit_errors_and_multi() {
        // An unknown option letter is a usage error (exit 2), like bash.
        let (out, code) = run("ulimit -z 2>&1");
        assert_eq!(code, 2);
        assert!(out.contains("invalid option"), "got {out:?}");
        // A bad limit argument is rejected without changing state.
        let (out, code) = run("ulimit -n abc 2>&1; ulimit -n");
        assert_eq!(code, 0); // trailing `ulimit -n` succeeds
        assert!(out.contains("invalid limit argument"), "got {out:?}");
        assert!(out.trim_end().ends_with("1024"), "limit unchanged: {out:?}");
        // Multiple resource letters print one labelled line each.
        let (out, code) = run("ulimit -c -n");
        assert_eq!(code, 0);
        assert!(out.contains("core file size") && out.contains("open files"), "got {out:?}");
    }

    #[test]
    fn ulimit_dash_a_lists_all() {
        let (out, code) = run("ulimit -a");
        assert_eq!(code, 0);
        // One line per modelled resource, in bash's order.
        assert_eq!(out.lines().count(), 16);
        assert!(out.contains("open files"));
        assert!(out.contains("(-n) 1024"));
        assert!(out.starts_with("core file size"));
    }

    #[test]
    fn compound_for_loop_output_redirect() {
        let path = uniq_path("forout");
        let (_, _) = run(&format!("for x in 1 2 3; do echo n$x; done > {path}"));
        let contents = std::fs::read_to_string(&path).expect("read");
        std::fs::remove_file(&path).ok();
        assert_eq!(contents, "n1\nn2\nn3\n");
    }

    #[test]
    fn compound_output_append_redirect() {
        let path = uniq_path("append");
        run(&format!("for x in a b; do echo $x; done > {path}"));
        run(&format!("for x in c d; do echo $x; done >> {path}"));
        let contents = std::fs::read_to_string(&path).expect("read");
        std::fs::remove_file(&path).ok();
        assert_eq!(contents, "a\nb\nc\nd\n");
    }

    #[test]
    fn compound_brace_group_redirect() {
        let path = uniq_path("brace");
        run(&format!("{{ echo one; echo two; }} > {path}"));
        let contents = std::fs::read_to_string(&path).expect("read");
        std::fs::remove_file(&path).ok();
        assert_eq!(contents, "one\ntwo\n");
    }

    #[test]
    fn compound_while_read_from_heredoc() {
        let (o, _) = run("while read l; do echo [$l]; done <<EOF\nfoo\nbar\nEOF");
        assert_eq!(o, "[foo]\n[bar]\n");
    }

    #[test]
    fn compound_stderr_redirect_to_file() {
        // `2> file` on a brace group must capture the group's stderr (including
        // an inner `>&2`) to the file while stdout still reaches the outer sink.
        let path = uniq_path("stderrfile");
        let (o, _) = run(&format!(
            "{{ echo out; echo err >&2; }} 2> {path}"
        ));
        let contents = std::fs::read_to_string(&path).expect("read");
        std::fs::remove_file(&path).ok();
        assert_eq!(o, "out\n");
        assert_eq!(contents, "err\n");
    }

    #[test]
    fn compound_stderr_append_redirect() {
        let path = uniq_path("stderrappend");
        run(&format!("{{ echo a >&2; }} 2> {path}"));
        run(&format!("{{ echo b >&2; }} 2>> {path}"));
        let contents = std::fs::read_to_string(&path).expect("read");
        std::fs::remove_file(&path).ok();
        assert_eq!(contents, "a\nb\n");
    }

    #[test]
    fn compound_stderr_to_stdout_in_capture() {
        // `2>&1` inside command substitution folds the group's stderr into the
        // captured stdout.
        let (o, _) = run("x=$( { echo a; echo b >&2; } 2>&1 ); echo \"$x\"");
        assert_eq!(o, "a\nb\n");
    }

    #[test]
    fn compound_stderr_to_stdout_top_level_capture() {
        // Same merge when the outer sink is a plain capture (not a subshell).
        let (o, _) = run("{ echo a; echo b >&2; } 2>&1");
        assert_eq!(o, "a\nb\n");
    }

    #[test]
    fn pipe_ampersand_pipes_stdout_and_stderr() {
        // `cmd |& rhs` is bash shorthand for `cmd 2>&1 | rhs`: both streams reach
        // the right-hand side. The RHS reads each line and re-emits it.
        let (o, _) = run("{ echo o; echo e >&2; } |& while read l; do echo \"[$l]\"; done");
        assert_eq!(o, "[o]\n[e]\n");
    }

    #[test]
    fn pipe_ampersand_with_explicit_left_redirect() {
        // The implicit `2>&1` is applied *after* the left command's own
        // redirects, so a preceding `2>/dev/null` is overridden and stderr still
        // reaches the pipe (bash semantics).
        let (o, _) =
            run("{ echo o; echo e >&2; } 2>/dev/null |& while read l; do echo \"<$l>\"; done");
        assert_eq!(o, "<o>\n<e>\n");
    }

    #[test]
    fn redirect_dup_last_writer_wins() {
        // `2>/dev/null 2>&1` — the later `2>&1` re-points stderr onto stdout's
        // sink, overriding the earlier file target (a common `|&`-adjacent idiom
        // that the old order-free RedirPlan got wrong).
        let (o, _) = run("x=$( { echo out; echo err >&2; } 2>/dev/null 2>&1 ); echo \"$x\"");
        assert_eq!(o, "out\nerr\n");
        // Reverse order: the later `2>/dev/null` wins, so only stdout is captured.
        let (o2, _) = run("x=$( { echo out; echo err >&2; } 2>&1 2>/dev/null ); echo \"[$x]\"");
        assert_eq!(o2, "[out]\n");
    }

    #[test]
    fn compound_for_loop_stderr_redirect() {
        let path = uniq_path("forstderr");
        run(&format!(
            "for x in 1 2; do echo e$x >&2; done 2> {path}"
        ));
        let contents = std::fs::read_to_string(&path).expect("read");
        std::fs::remove_file(&path).ok();
        assert_eq!(contents, "e1\ne2\n");
    }

    #[test]
    fn compound_read_count_lines() {
        // Classic idiom: count lines via a redirected while-read loop.
        let path = uniq_path("count");
        std::fs::write(&path, "l1\nl2\nl3\nl4\n").expect("write");
        let (o, _) = run(&format!(
            "n=0; while read _; do n=$((n+1)); done < {path}; echo $n"
        ));
        std::fs::remove_file(&path).ok();
        assert_eq!(o, "4\n");
    }

    #[test]
    fn pipeline_into_while_read() {
        // Feeding a while-read loop from a pipeline must consume successive
        // lines streamed over the connecting OS pipe.
        let (o, _) = run("printf 'x\\ny\\nz\\n' | while read v; do echo \"<$v>\"; done");
        assert_eq!(o, "<x>\n<y>\n<z>\n");
    }

    #[test]
    fn threaded_pipeline_builtin_stages_stream() {
        // Two in-process stages (printf → a while-read that filters) connected
        // by a real pipe; the threaded path must carry and transform the data.
        let (o, _) = run(
            "printf 'a\\nbb\\nc\\n' | while read v; do echo \"$v$v\"; done | while read w; do echo \"[$w]\"; done",
        );
        assert_eq!(o, "[aa]\n[bbbb]\n[cc]\n");
    }

    #[test]
    fn threaded_pipeline_stage_runs_in_subshell() {
        // A pipeline stage's variable mutation must NOT leak to the parent
        // shell (each stage is a subshell — bash semantics, no lastpipe).
        let (o, _) = run("v=outer; printf 'inner\\n' | read v; echo $v");
        assert_eq!(o, "outer\n");
    }

    #[test]
    fn pipeline_classifier_routes_external_vs_builtin() {
        let mut sh = Shell::new();
        sh.funcs.insert(b"myfn".to_vec(), parse("echo hi".as_bytes()).unwrap());
        let classify = |sh: &Shell, src: &str| -> bool {
            let prog = parse(src.as_bytes()).unwrap();
            let cmds = &prog.items[0].list.first.commands;
            cmds.iter().all(|c| sh.stage_is_plain_external(c))
        };
        // All-external → real-pipe (concurrent) path.
        assert!(classify(&sh, "cat a | grep b | wc -l"));
        // A builtin stage → threaded path.
        assert!(!classify(&sh, "cat a | echo hi"));
        assert!(!classify(&sh, "printf x | cat"));
        // A per-stage redirection → threaded path.
        assert!(!classify(&sh, "cat a | grep b > out"));
        // A command word needing expansion can't be proven external → threaded.
        assert!(!classify(&sh, "$cmd a | cat"));
        // A shell function stage → threaded path.
        assert!(!classify(&sh, "cat a | myfn"));
        // A compound stage → threaded path.
        assert!(!classify(&sh, "cat a | while read x; do echo $x; done"));
    }

    // NOTE: there is deliberately no `external_producer_terminates_early` test.
    // Terminating an *unbounded external* producer when its downstream consumer
    // exits early is an OS-signal property (bash relies on SIGPIPE; the slateos
    // target delivers EPIPE), not shell logic. The Windows test host cannot
    // exercise it faithfully: `cmd`'s `echo` ignores broken-pipe write errors
    // and loops forever, so `Child::wait` never returns. The shell-side cascade
    // (a stage stopping once its write end breaks) is covered by the in-process
    // test below. See known-issues.md TD-OILS4.
    #[test]
    fn threaded_pipeline_inprocess_producer_terminates_early() {
        // An unbounded *in-process* producer (`while true; do echo`) feeding a
        // consumer that stops after one line must terminate via the pipe_broken
        // (SIGPIPE analogue) flag rather than looping forever.
        use std::sync::mpsc;
        let (tx, rx) = mpsc::channel();
        let h = std::thread::spawn(move || {
            let (o, _) = run("while true; do echo x; done | while read v; do echo got; break; done");
            let _ = tx.send(o);
        });
        let out = rx
            .recv_timeout(std::time::Duration::from_secs(20))
            .expect("in-process producer should stop on broken pipe, not hang");
        h.join().ok();
        assert_eq!(out, "got\n");
    }

    // The following exercise the real-OS-pipe path with actual external
    // processes; they use `cmd` (always present on the Windows test host).
    #[cfg(windows)]
    #[test]
    fn concurrent_pipeline_carries_data() {
        // Two `cmd` echoes feed Windows `sort`; the pipe must carry both lines.
        let (o, _) = run(r#"cmd /c "echo b&echo a" | sort"#);
        let norm = o.replace("\r\n", "\n");
        assert_eq!(norm, "a\nb\n");
    }

    #[cfg(windows)]
    #[test]
    fn pipeline_stage_stdout_redirect_composes_with_pipe() {
        // An external stage that carries its own `> file` redirect takes the
        // threaded path (it is not "plain external"); the pipe must still feed
        // its stdin while the redirect captures its stdout. Producer `cmd echo`
        // → consumer `findstr` (matches every line) → file.
        let f = std::env::temp_dir().join("osh_pipe_redir_stdout.txt");
        let _ = std::fs::remove_file(&f);
        let fp = f.to_string_lossy().replace('\\', "/");
        let script = format!(r#"cmd /c "echo hi" | findstr "h" > "{fp}""#);
        run(&script);
        let content = std::fs::read_to_string(&f).unwrap_or_default();
        let _ = std::fs::remove_file(&f);
        assert_eq!(content.replace("\r\n", "\n"), "hi\n");
    }

    #[cfg(windows)]
    #[test]
    fn pipeline_stage_stderr_redirect_composes_with_pipe() {
        // The last stage's own `2> file` must capture its stderr even though its
        // stdin is the inter-stage pipe. The consumer ignores stdin and writes
        // to its stderr, which the redirect diverts to the file.
        let f = std::env::temp_dir().join("osh_pipe_redir_stderr.txt");
        let _ = std::fs::remove_file(&f);
        let fp = f.to_string_lossy().replace('\\', "/");
        let script = format!(r#"cmd /c "echo E 1>&2" 2> "{fp}" | cmd /c "sort""#);
        run(&script);
        let content = std::fs::read_to_string(&f).unwrap_or_default();
        let _ = std::fs::remove_file(&f);
        // `echo E 1>&2` emits "E " (cmd keeps the space before the redirect),
        // so the diverted stderr is "E \r\n". The point is that the redirect
        // captured the stage's stderr while its stdout fed the downstream pipe.
        assert_eq!(content.replace("\r\n", "\n"), "E \n");
    }

    #[cfg(windows)]
    #[test]
    fn concurrent_pipeline_status_is_last_stage() {
        // `$?` reflects the last stage, not earlier ones (no pipefail).
        assert_eq!(run("cmd /c exit 0 | cmd /c exit 5").1, 5);
        assert_eq!(run("cmd /c exit 7 | cmd /c exit 0").1, 0);
    }

    #[cfg(windows)]
    #[test]
    fn pipefail_reports_rightmost_nonzero_stage() {
        // With pipefail, a middle/leftmost failure surfaces even though the last
        // stage succeeds; the rightmost non-zero stage wins.
        assert_eq!(run("set -o pipefail; cmd /c exit 7 | cmd /c exit 0").1, 7);
        assert_eq!(
            run("set -o pipefail; cmd /c exit 3 | cmd /c exit 5 | cmd /c exit 0").1,
            5
        );
        // All-success pipeline is still 0 under pipefail.
        assert_eq!(run("set -o pipefail; cmd /c exit 0 | cmd /c exit 0").1, 0);
        // `set +o pipefail` restores last-stage semantics.
        assert_eq!(
            run("set -o pipefail; set +o pipefail; cmd /c exit 7 | cmd /c exit 0").1,
            0
        );
    }

    #[cfg(windows)]
    #[test]
    fn pipestatus_array_records_every_stage() {
        // `${PIPESTATUS[@]}` holds one code per stage, in pipeline order.
        let (o, _) =
            run(r#"cmd /c exit 3 | cmd /c exit 0 | cmd /c exit 5; echo "${PIPESTATUS[@]}""#);
        assert_eq!(o, "3 0 5\n");
        // Individual subscripts are addressable.
        let (o, _) = run(r#"cmd /c exit 4 | cmd /c exit 0; echo "${PIPESTATUS[0]}""#);
        assert_eq!(o, "4\n");
    }

    #[test]
    fn pipestatus_single_command_has_one_element() {
        // A bare command still populates a one-element PIPESTATUS.
        let (o, _) = run(r#"true; echo "${PIPESTATUS[@]}""#);
        assert_eq!(o, "0\n");
        let (o, _) = run(r#"false; echo "${PIPESTATUS[@]}""#);
        assert_eq!(o, "1\n");
    }

    #[test]
    fn pipefail_buffered_path_folds_status() {
        // The buffered path (builtin stages) also honours pipefail + PIPESTATUS.
        // `false | true` — last stage true, but pipefail surfaces the failure.
        let mut sh = Shell::new();
        assert_eq!(sh.run_source("set -o pipefail; false | true".as_bytes()), 1);
        let (o, _) = run(r#"false | true; echo "${PIPESTATUS[@]}""#);
        assert_eq!(o, "1 0\n");
    }

    #[test]
    fn set_cluster_consumes_o_long_option() {
        // `set -eo pipefail` must enable BOTH errexit (`-e`) and pipefail (the
        // `-o` selector consuming the following word `pipefail`). Regression:
        // osh previously treated the clustered `o` as an ignored flag and left
        // `pipefail` to become a positional, so pipefail stayed off.
        let mut sh = Shell::new();
        assert_eq!(sh.run_source("set -eo pipefail; shopt -oq pipefail && shopt -oq errexit".as_bytes()), 0);
        // The `o` may appear anywhere in the cluster; remaining letters stay
        // flags, and successive `o`s consume successive following words.
        let mut sh = Shell::new();
        assert_eq!(sh.run_source("set -oe pipefail; shopt -oq pipefail && shopt -oq errexit".as_bytes()), 0);
        let mut sh = Shell::new();
        assert_eq!(
            sh.run_source("set -oo pipefail xtrace; shopt -oq pipefail && shopt -oq xtrace".as_bytes()),
            0
        );
        // Words left after the consumed option name become positionals.
        assert_eq!(run(r#"set -eo pipefail extra; echo "$1""#).0, "extra\n");
        // `+eo` disables both.
        let mut sh = Shell::new();
        sh.run_source("set -e -o pipefail".as_bytes());
        sh.run_source("set +eo pipefail".as_bytes());
        assert_eq!(sh.run_source("shopt -oq pipefail || shopt -oq errexit".as_bytes()), 1);
        // The end-to-end effect: errexit fires on a pipefail-surfaced failure.
        assert_eq!(run("set -eo pipefail; false | true; echo reached"), (String::new(), 1));
    }

    #[cfg(windows)]
    #[test]
    fn wait_reaps_background_job_status() {
        // A `&` command is tracked as a job and sets `$!`; `wait $!` blocks
        // until it finishes and yields its exit status.
        let mut sh = Shell::new();
        assert_eq!(sh.run_source("cmd /c exit 7 &".as_bytes()), 0);
        assert!(sh.last_bg_pid.is_some());
        assert_eq!(sh.jobs.len(), 1);
        assert_eq!(sh.run_source("wait $!".as_bytes()), 7);
        // The row outlives the `wait` that read it; the next sweep drops it.
        assert_eq!(sh.jobs.len(), 1);
        // An operand-less `wait` also blocks until the job is done, but names no
        // job and so reports 0 rather than its status (bash). It discards the
        // jobs it waited for outright.
        assert_eq!(sh.run_source("cmd /c exit 7 &".as_bytes()), 0);
        assert_eq!(sh.run_source("wait".as_bytes()), 0);
        assert!(sh.jobs.is_empty());
    }

    #[test]
    fn thread_backed_background_jobs_set_pid_and_wait() {
        // A backgrounded *builtin*, compound command, function, or pipeline is
        // not a single external process, so it runs on a background thread. It
        // must still register a job, set `$!`, and be waitable with its exit
        // status — matching bash's "run `&` in a subshell". (Pre-fix, these fell
        // back to synchronous execution and never set `$!`; see TD-OILS13.)
        for (src, want) in [
            ("true &", 0),          // builtin
            ("false &", 1),         // builtin, nonzero status
            ("{ exit 5; } &", 5),   // compound (brace group)
            ("( exit 9 ) &", 9),    // subshell
        ] {
            let mut sh = Shell::new();
            assert_eq!(sh.run_source(src.as_bytes()), 0, "backgrounding {src:?} succeeds");
            assert!(sh.last_bg_pid.is_some(), "$! set for {src:?}");
            assert_eq!(sh.jobs.len(), 1, "one job registered for {src:?}");
            // `wait $!` returns the job's exit status. Its row survives that
            // one `wait` and is dropped by the next sweep of the table.
            assert_eq!(sh.run_source("wait $!".as_bytes()), want, "wait status for {src:?}");
            assert_eq!(sh.jobs.len(), 1, "job reported but not yet swept for {src:?}");
            assert_eq!(sh.run_source("wait $!".as_bytes()), want, "status answered again for {src:?}");
            assert!(sh.jobs.is_empty(), "job swept for {src:?}");
        }

        // `$!` survives after a fast job finishes (bash keeps the last bg pid).
        let mut sh = Shell::new();
        assert_eq!(sh.run_source("true &\np=$!\nwait\n[ -n \"$p\" ] && echo saved".as_bytes()), 0);
    }

    #[test]
    fn background_spawn_shortcut_declines_what_it_cannot_carry() {
        // The direct-spawn shortcut in `exec_background` can only hand the OS a
        // program and its arguments. Everything else about the command has to
        // send it down the general path, or it would simply be dropped — bash
        // forks, so a `&` job keeps its assignments, its redirections, and the
        // expansions in its words exactly as a foreground command would.
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map_or(0, |d| d.subsec_nanos());
        let dir = std::env::temp_dir().join(format!("osh_bg_{}_{nanos}", std::process::id()));
        std::fs::create_dir_all(&dir).expect("create scratch dir");
        let cd = dir.to_string_lossy().replace('\\', "/");

        let mut sh = Shell::new();
        assert_eq!(sh.run_source(format!("cd '{cd}'").as_bytes()), 0);

        // A redirection applies to the job, rather than being dropped.
        assert_eq!(sh.run_source("printf 'redirected\\n' > bg.out & wait".as_bytes()), 0);
        assert_eq!(std::fs::read_to_string(dir.join("bg.out")).expect("bg.out"), "redirected\n");

        // An assignment prefix reaches the job's environment.
        assert_eq!(sh.run_source("V=zz sh -c 'printf v=$V' > bg.env & wait".as_bytes()), 0);
        assert_eq!(std::fs::read_to_string(dir.join("bg.env")).expect("bg.env"), "v=zz");

        // The words are expanded once. `true` is a builtin, so a shortcut that
        // expanded them to discover that and then let the general path expand
        // them again would run the substitution twice.
        assert_eq!(sh.run_source(": > bg.cnt\ntrue $(printf x >> bg.cnt; echo y) &\nwait".as_bytes()), 0);
        assert_eq!(std::fs::read_to_string(dir.join("bg.cnt")).expect("bg.cnt"), "x");

        // A name that resolves nowhere is reported by the job, not by the shell:
        // the shell's own status is 0 and the 127 belongs to the job.
        assert_eq!(sh.run_source("nosuch_cmd_bg_xyz &".as_bytes()), 0);
        assert_eq!(sh.run_source("wait $!".as_bytes()), 127);
        // …which is also why `command_not_found_handle` gets a chance to run and
        // to supply the job's status.
        assert_eq!(
            sh.run_source("command_not_found_handle() { return 9; }\nnosuch_cmd_bg_xyz &".as_bytes()),
            0
        );
        assert_eq!(sh.run_source("wait $!".as_bytes()), 9);

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn background_pipeline_loses_its_own_negation() {
        // bash inverts a pipeline's status on the way out of the executor, and
        // the asynchronous case returns before reaching that — so a `!` written
        // on the backgrounded pipeline itself is simply not applied, and `! X &`
        // comes out the opposite way round from a foreground `! X`.
        let mut sh = Shell::new();
        assert_eq!(sh.run_source("! true".as_bytes()), 1, "foreground negation still applies");
        for (src, want) in [
            ("! true &", 0),
            ("! false &", 1),
            ("! false | cat &", 0),
            // Only the outermost `!` of the whole unit is lost: inside an and-or
            // list the `&` binds to the list, so each pipeline keeps its own.
            ("! true && echo unreachable &", 1),
            ("true && ! true &", 1),
            ("true && ! false &", 0),
            // A `!` sealed inside a group or subshell is untouched.
            ("( ! true ) &", 1),
            ("{ ! true; } &", 1),
        ] {
            assert_eq!(sh.run_source(src.as_bytes()), 0, "backgrounding {src:?} succeeds");
            assert_eq!(sh.run_source("wait $!".as_bytes()), want, "job status for {src:?}");
        }
    }

    #[test]
    fn background_job_writes_to_the_sink_it_was_started_under() {
        // A job inherits fd 1 as it stood where it was started, so inside
        // `$( … )` its output belongs to the substitution — and the substitution
        // waits for it, because bash's collecting pipe has no EOF while the job
        // still holds a copy of the write end.
        assert_eq!(run("x=$(echo hi &); echo \"[$x]\"").0, "[hi]\n");
        assert_eq!(run("x=$(echo hi & wait); echo \"[$x]\"").0, "[hi]\n");
        // Its writes interleave with the substitution's own in write order…
        assert_eq!(run("x=$(printf a; printf b & wait); echo \"[$x]\"").0, "[ab]\n");
        // …and so do a compound job's.
        assert_eq!(run("x=$( { echo g1; echo g2; } & wait ); echo \"[$x]\"").0, "[g1\ng2]\n");
        assert_eq!(run("f() { echo fn; }; x=$(f &); echo \"[$x]\"").0, "[fn]\n");
        // The job's status is not the substitution's: the substitution ends when
        // the pipe closes, and never consults it.
        assert_eq!(run("x=$(false &); echo \"rc=$?\"").0, "rc=0\n");
        // A redirection in the job points its fd 1 somewhere else, so there is no
        // copy of the sink left to collect from or wait on.
        assert_eq!(run("x=$(echo s > /dev/null &); echo \"[$x]\"").0, "[]\n");
        // A pipeline stage is the same sink.
        assert_eq!(run("{ echo hi & wait; } | tr a-z A-Z").0, "HI\n");
        assert_eq!(run("{ echo hi & } | tr a-z A-Z").0, "HI\n");
    }

    #[test]
    fn background_job_without_a_redirect_reads_dev_null() {
        // fd 0 goes the other way from fd 1: a job that carries no redirection
        // of its own reads /dev/null, so it cannot race the shell for the script
        // it is being read from. `exec < file` rebinds the *shell's* fd 0, which
        // is not a redirection of the job, so the rule still applies — and the
        // shell's own read position is untouched by the job.
        let dir = std::env::temp_dir().join(format!(
            "osh_bgstdin_{}_{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map_or(0, |d| d.as_nanos())
        ));
        std::fs::create_dir_all(&dir).expect("scratch dir");
        std::fs::write(dir.join("two.txt"), "l1\nl2\n").expect("write two.txt");
        let mut sh = Shell::new();
        let cap = capture_sink();
        {
            let mut out = Out::Capture(cap.clone());
            let src = format!(
                "cd '{}'\n\
                 exec < two.txt\n\
                 cat & wait\n\
                 read a & wait; echo \"read=[${{a-unset}}]\"\n\
                 read b; echo \"parent=[$b]\"\n\
                 cat < two.txt & wait\n",
                dir.display().to_string().replace('\\', "/")
            );
            sh.run_source_out(src.as_bytes(), &mut out, 0);
        }
        let got = String::from_utf8_lossy(&take_capture(&cap)).into_owned();
        assert_eq!(got, "read=[unset]\nparent=[l1]\nl1\nl2\n");

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[cfg(windows)]
    #[test]
    fn wait_by_pid_and_job_spec() {
        // `wait PID` and `wait %n` both target a specific job. The row outlives
        // the `wait` that read it (it is the *next* sweep that drops it), and
        // creating the next job is one such sweep — so numbering restarts.
        let mut sh = Shell::new();
        sh.run_source("cmd /c exit 3 &".as_bytes());
        let pid = sh.last_bg_pid.expect("bg pid");
        assert_eq!(sh.run_source(format!("wait {pid}").as_bytes()), 3);
        assert_eq!(sh.jobs.len(), 1);

        sh.run_source("cmd /c exit 4 &".as_bytes());
        assert_eq!(sh.jobs.len(), 1, "the reported job was swept first");
        assert_eq!(sh.run_source("wait %1".as_bytes()), 4);
        assert_eq!(sh.jobs.len(), 1);
    }

    #[test]
    fn wait_bad_operand_classification() {
        // bash classifies a failed `wait` operand three ways, each with its own
        // message and status. A bare integer that is not a child → status 127.
        let (o, s) = run("wait 99999 2>&1");
        assert_eq!(o, "osh: wait: pid 99999 is not a child of this shell\n");
        assert_eq!(s, 127);
        // A `%…` job spec that does not exist → `no such job`, status 127.
        let (o2, s2) = run("wait %99 2>&1");
        assert_eq!(o2, "osh: wait: %99: no such job\n");
        assert_eq!(s2, 127);
        // Neither a pid nor a valid job spec → status *1* (not 127).
        let (o3, s3) = run("wait abc 2>&1");
        assert_eq!(o3, "osh: wait: `abc': not a pid or valid job spec\n");
        assert_eq!(s3, 1);
        // A leading-`-` token is an invalid option (status 2 + usage), never a
        // negative pid.
        let (o4, s4) = run("wait -1 2>&1");
        assert_eq!(
            o4,
            "osh: wait: -1: invalid option\n\
             wait: usage: wait [-fn] [-p var] [id ...]\n"
        );
        assert_eq!(s4, 2);
        // `-f` (wait-for-termination) is accepted as a no-op.
        assert_eq!(run("wait -f 2>&1").1, 0);
    }

    #[test]
    fn wait_options_cluster_and_p_names_a_variable() {
        // bash reads `wait`'s options with getopt, so the letters cluster and an
        // unknown one is named wherever in the cluster it appears.
        for (src, want) in [("wait -nx 2>&1", 'x'), ("wait -fx 2>&1", 'x'), ("wait -x 2>&1", 'x')] {
            let (o, s) = run(src);
            assert_eq!(
                o,
                format!(
                    "osh: wait: -{want}: invalid option\n\
                     wait: usage: wait [-fn] [-p var] [id ...]\n"
                ),
                "{src}"
            );
            assert_eq!(s, 2, "{src}");
        }
        // `-p` takes the rest of its own cluster, or the next word; missing it
        // is a usage error like any other.
        for src in ["wait -p 2>&1", "wait -np 2>&1", "wait -fnp 2>&1"] {
            let (o, s) = run(src);
            assert_eq!(
                o,
                "osh: wait: -p: option requires an argument\n\
                 wait: usage: wait [-fn] [-p var] [id ...]\n",
                "{src}"
            );
            assert_eq!(s, 2, "{src}");
        }
        // The argument has to be a name, and that is checked before waiting.
        for bad in ["1x", "", "a b"] {
            let (o, s) = run(&format!("wait -p '{bad}' 2>&1"));
            assert_eq!(o, format!("osh: wait: `{bad}': not a valid identifier\n"));
            assert_eq!(s, 1);
        }
        // A lone `-` is an operand, not an option cluster.
        let (o, s) = run("wait - 2>&1");
        assert_eq!(o, "osh: wait: `-': not a pid or valid job spec\n");
        assert_eq!(s, 1);
    }

    #[test]
    fn wait_without_operands_names_no_job() {
        // An operand-less `wait` reports no particular job's status, so bash
        // returns 0 however the jobs ended — and clears `-p VAR` rather than
        // leaving it holding a pid it is not reporting on.
        let mut sh = Shell::new();
        for src in ["( exit 3 ) &", "( exit 3 ) & ( exit 0 ) &", "false &"] {
            assert_eq!(sh.run_source(src.as_bytes()), 0);
            assert_eq!(sh.run_source("wait".as_bytes()), 0, "operand-less wait after {src:?}");
        }
        // Only a named job answers with its own status.
        sh.run_source("( exit 3 ) &".as_bytes());
        assert_eq!(sh.run_source("wait $!".as_bytes()), 3);
        // `-p VAR` is cleared up front, so a `wait` that names no job unsets it…
        // The job body sleeps so that it is *certainly* still running when the
        // `wait` arrives: an operand-less `wait` marks every job it actually
        // waited for as reported, and only spares one that had already finished
        // (see below). Without the sleep, which branch this took depended on how
        // fast the job's thread ran, and the `-n` assertion below flaked under
        // parallel test load.
        sh.run_source("VAR=stale; ( sleep 0.1; exit 3 ) &".as_bytes());
        assert_eq!(sh.run_source("wait -p VAR".as_bytes()), 0);
        assert!(!sh.vars.contains_key("VAR"), "operand-less wait leaves -p VAR unset");
        // …and so does a `-n` with nothing left to wait for.
        sh.run_source("VAR=stale".as_bytes());
        assert_eq!(sh.run_source("wait -n -p VAR 2>/dev/null".as_bytes()), 127);
        assert!(!sh.vars.contains_key("VAR"), "`wait -n` with no jobs leaves -p VAR unset");
    }

    #[test]
    fn wait_n_ignores_a_job_whose_status_was_already_reported() {
        // `-n` answers with the *next* job to finish, so a job whose death has
        // already been announced is not a candidate — even though its row can
        // still be sitting in the table unswept (bash's `J_NOTIFIED`, which a
        // `jobs`/`wait %1` may read once more before it goes).
        let mut sh = Shell::new();
        // An operand-less `wait` spares the `$!` job from being marked reported
        // when it had already finished, so the status is still `-n`-answerable…
        sh.run_source("( exit 3 ) & sleep 0.2".as_bytes());
        assert_eq!(sh.run_source("wait".as_bytes()), 0);
        assert_eq!(sh.run_source("wait -n".as_bytes()), 3, "spared job is still answerable");
        // …until a `jobs` listing announces it, after which bash denies the job
        // exists at all: 127 from a bare `-n`, and `no such job` for one named by
        // pid — while a *targeted* `wait PID` still replays the status.
        sh.run_source("( exit 5 ) & p=$!; sleep 0.2".as_bytes());
        assert_eq!(sh.run_source("wait".as_bytes()), 0);
        assert_eq!(listing(&mut sh, "jobs").lines().count(), 1);
        assert!(
            listing(&mut sh, "wait -n $p 2>&1").ends_with(": no such job\n"),
            "a pid naming a reported job is unknown to `wait -n`"
        );
        assert_eq!(sh.run_source("wait -n".as_bytes()), 127);
        assert_eq!(sh.run_source("wait $p".as_bytes()), 5, "a targeted wait still answers");
        // A reported job does not shadow a live one: `-n` waits for the live one.
        sh.run_source("( exit 7 ) & sleep 0.2".as_bytes());
        assert_eq!(sh.run_source("wait".as_bytes()), 0);
        assert_eq!(listing(&mut sh, "jobs").lines().count(), 1);
        sh.run_source("( sleep 0.1; exit 9 ) &".as_bytes());
        assert_eq!(sh.run_source("wait -n".as_bytes()), 9);
    }

    /// Run `src` and return what it wrote to stdout — for the `jobs` tests,
    /// which need several listings from one shell whose job table persists.
    #[cfg(test)]
    fn listing(sh: &mut Shell, src: &str) -> String {
        let buf = capture_sink();
        let mut out = Out::Capture(buf.clone());
        sh.run_source_out(src.as_bytes(), &mut out, 0);
        String::from_utf8_lossy(&take_capture(&buf)).into_owned()
    }

    #[test]
    fn jobs_marks_the_current_and_previous_job() {
        // The `+`/`-` markers are decided when a job is *created* and survive
        // its death, so they are not a function of what is still running: the
        // newest job is `+`, and the newest job that was still running when it
        // started is `-`.
        let mut sh = Shell::new();
        let settle = || std::thread::sleep(std::time::Duration::from_millis(700));

        // Two jobs alive at once: the newer is `+`, the older `-`.
        sh.run_source("sleep 0.4 & sleep 1 &".as_bytes());
        assert_eq!(
            listing(&mut sh, "jobs"),
            "[1]-  Running                 sleep 0.4 &\n\
             [2]+  Running                 sleep 1 &\n"
        );
        sh.run_source("wait".as_bytes());

        // The older one keeps its `-` after finishing — and loses its `&`,
        // because there is no longer anything running in the background.
        sh.run_source("sleep 0.2 & sleep 1 &".as_bytes());
        settle();
        assert_eq!(
            listing(&mut sh, "jobs"),
            "[1]-  Done                    sleep 0.2\n\
             [2]+  Running                 sleep 1 &\n"
        );
        sh.run_source("wait".as_bytes());

        // A job that had *already* finished when the next one started never
        // gets the `-` at all: with no older job running, previous falls back
        // to current, and only one marker shows.
        sh.run_source("sleep 0.2 &".as_bytes());
        settle();
        sh.run_source("sleep 1 &".as_bytes());
        assert_eq!(
            listing(&mut sh, "jobs"),
            "[1]   Done                    sleep 0.2\n\
             [2]+  Running                 sleep 1 &\n"
        );
        sh.run_source("wait".as_bytes());

        // Only ever two markers, however many jobs there are.
        sh.run_source("sleep 0.4 & sleep 1 & sleep 1 &".as_bytes());
        assert_eq!(
            listing(&mut sh, "jobs"),
            "[1]   Running                 sleep 0.4 &\n\
             [2]-  Running                 sleep 1 &\n\
             [3]+  Running                 sleep 1 &\n"
        );
        sh.run_source("wait".as_bytes());
    }

    #[test]
    fn jobs_reports_a_finished_job_once() {
        // bash forgets a finished job after listing it — but only the ones the
        // listing actually reported, so a `-r` that filtered it out leaves it
        // for the next `jobs`, as does a jobspec that named someone else.
        let mut sh = Shell::new();
        sh.run_source("sleep 0.2 &".as_bytes());
        std::thread::sleep(std::time::Duration::from_millis(700));
        assert_eq!(listing(&mut sh, "jobs -r"), "", "-r filters the finished job out");
        assert_eq!(listing(&mut sh, "jobs -s"), "", "no stopped jobs in a script shell");
        assert_eq!(listing(&mut sh, "jobs"), "[1]+  Done                    sleep 0.2\n");
        assert_eq!(listing(&mut sh, "jobs"), "", "reported once, then forgotten");
        // Numbering restarts at 1 once the table has drained, and `-l` inserts
        // the pid between the marker and the state column.
        sh.run_source("sleep 0.2 &".as_bytes());
        std::thread::sleep(std::time::Duration::from_millis(700));
        let l = listing(&mut sh, "jobs -l");
        let pid = sh.last_bg_pid.expect("bg pid");
        assert_eq!(l, format!("[1]+ {pid} Done                    sleep 0.2\n"));
        // An unresolvable jobspec is a diagnostic and a failing status.
        let (o, s) = run("jobs %9 2>&1");
        assert_eq!(o, "osh: jobs: %9: no such job\n");
        assert_eq!(s, 1);
    }

    #[test]
    fn jobs_words_exits_and_signals_apart() {
        // `Done` is only for a *clean* exit; a dirty one is spelled out, and a
        // job that was signalled is named by the signal rather than by the
        // 128+n status it happens to share with `exit 143`.
        let mut sh = Shell::new();
        for (src, want) in [
            ("( exit 0 ) &", "Done                    ( exit 0 )"),
            ("( exit 1 ) &", "Exit 1                  ( exit 1 )"),
            ("( exit 255 ) &", "Exit 255                ( exit 255 )"),
            ("( exit 143 ) &", "Exit 143                ( exit 143 )"),
        ] {
            sh.run_source(src.as_bytes());
            std::thread::sleep(std::time::Duration::from_millis(100));
            assert_eq!(listing(&mut sh, "jobs"), format!("[1]+  {want}\n"), "{src}");
        }
        for (sig, want) in [("TERM", "Terminated"), ("PIPE", "Broken pipe")] {
            sh.run_source("sleep 5 &".as_bytes());
            sh.run_source(format!("kill -{sig} %1").as_bytes());
            assert_eq!(
                listing(&mut sh, "jobs"),
                format!("[1]+  {want:<24}sleep 5\n"),
                "kill -{sig}"
            );
        }
        // `INT` and `QUIT` cannot produce such a row at all — no background job
        // is ever listed as `Interrupt` or `Quit` — because an asynchronous job
        // is handed both already ignored, so the delivery succeeds and the job
        // keeps running. `CHLD` stands for the signals whose *default* is to be
        // ignored, which the job is left to keep.
        for sig in ["INT", "QUIT", "CHLD"] {
            sh.run_source("sleep 5 &".as_bytes());
            sh.run_source(format!("kill -{sig} %1").as_bytes());
            assert_eq!(sh.last_status, 0, "kill -{sig}");
            assert_eq!(
                listing(&mut sh, "jobs"),
                "[1]+  Running                 sleep 5 &\n",
                "kill -{sig}"
            );
            sh.run_source("kill -TERM %1; disown -a".as_bytes());
        }
    }

    #[test]
    fn a_killed_job_is_announced_between_commands_and_forgotten() {
        // The corpus can only watch what the announcement *does* — the message
        // carries a pid the two shells cannot agree on — so its text is checked
        // here, where the pid is knowable.
        let mut sh = Shell::new();
        sh.run_source("sleep 5 &".as_bytes());
        let pid = sh.jobs[0].pid;
        // The news arrives *between* commands, so the group's `2>&1` has to
        // enclose one: `kill` writes the death down, and the `:` after it is the
        // boundary at which the shell says so.
        let (o, _) = run_in(&mut sh, "{ kill -HUP %1; :; } 2>&1");
        assert_eq!(o, format!("osh: {pid} {:<24}sleep 5\n", "Hangup"));
        // Announcing is reporting, and the row goes with it — unlike the one a
        // `jobs` listing leaves behind for one more sweep.
        assert!(sh.jobs.is_empty(), "the announced job is gone");
        let (o, s) = run_in(&mut sh, "wait %1 2>&1");
        assert_eq!(o, "osh: wait: %1: no such job\n");
        assert_eq!(s, 127);

        // The three signals a listing can word are the three that are never
        // announced: the job is left in the table, still owed.
        for (sig, want) in [("TERM", "Terminated"), ("PIPE", "Broken pipe")] {
            sh.run_source("sleep 5 &".as_bytes());
            let (o, _) = run_in(&mut sh, &format!("{{ kill -{sig} %1; :; }} 2>&1"));
            assert_eq!(o, "", "kill -{sig} says nothing");
            assert_eq!(listing(&mut sh, "jobs"), format!("[1]+  {want:<24}sleep 5\n"));
            sh.run_source("disown -a".as_bytes());
        }
    }

    #[test]
    fn a_command_substitution_does_not_announce_a_killed_job() {
        // bash suppresses the announcement inside `$( … )`, where it would land
        // on the parent's stderr in the middle of a value being collected; the
        // job stays in the substitution's own table instead. A `( … )` group
        // *inside* the substitution is a fresh subshell and announces again.
        let mut sh = Shell::new();
        let (o, _) = run_in(&mut sh, "x=$( sleep 5 & kill -HUP %1; jobs ); echo \"[$x]\"");
        assert_eq!(o, "[[1]+  Hangup                  sleep 5]\n");
        let (o, _) =
            run_in(&mut sh, "x=$( ( sleep 5 & kill -HUP %1; jobs ) 2>&1 ); echo \"[$x]\"");
        // The group's own `2>&1` catches the announcement, so it is captured as
        // part of the value — and the group's `jobs` then has nothing to add.
        let head = o.strip_prefix("[osh: ").expect("the group announced the death");
        assert!(head.ends_with(" Hangup                  sleep 5]\n"), "{o:?}");
    }

    #[test]
    fn disown_acts_on_each_operand_before_reading_the_next() {
        // Each operand is resolved against the table as it stands *after* the
        // previous one was acted on, so `%2 %+` disowns two jobs (dropping job 2
        // hands the `+` to job 1) and `%2 %2` fails the second time.
        let mut sh = Shell::new();
        sh.run_source("sleep 5 &".as_bytes());
        sh.run_source("sleep 6 &".as_bytes());
        assert_eq!(sh.run_source("disown %2 %+".as_bytes()), 0);
        assert!(sh.jobs.is_empty(), "both jobs should be gone");

        let mut sh = Shell::new();
        sh.run_source("sleep 5 &".as_bytes());
        sh.run_source("sleep 6 &".as_bytes());
        let (o, s) = run_in(&mut sh, "disown %2 %2 2>&1");
        assert_eq!(o, "osh: disown: %2: no such job\n");
        assert_eq!(s, 1);
        assert_eq!(sh.jobs.len(), 1, "the first operand still took effect");
        // A bad operand is reported and skipped, not fatal to the rest.
        let (o, s) = run_in(&mut sh, "disown %nosuch %1 2>&1");
        assert_eq!(o, "osh: disown: %nosuch: no such job\n");
        assert_eq!(s, 1);
        assert!(sh.jobs.is_empty());
    }

    /// Run `src` in `sh` and return its stdout and status — for tests that need
    /// a shell whose job table survives from one command to the next.
    #[cfg(test)]
    fn run_in(sh: &mut Shell, src: &str) -> (String, i32) {
        let buf = capture_sink();
        let mut out = Out::Capture(buf.clone());
        let status = sh.run_source_out(src.as_bytes(), &mut out, 0);
        (String::from_utf8_lossy(&take_capture(&buf)).into_owned(), status)
    }

    #[test]
    fn jobs_x_substitutes_a_pid_for_a_whole_word_job_spec() {
        // What `-x` is for: handing a job to something that only speaks pids.
        // The corpus cannot check the substituted value — reference bash
        // answers with a process group, which osh has no notion of — so it is
        // checked here instead.
        let mut sh = Shell::new();
        sh.run_source("sleep 5 &".as_bytes());
        sh.run_source("sleep 6 &".as_bytes());
        let pid1 = sh.jobs[0].pid.to_string();
        let pid2 = sh.jobs[1].pid.to_string();
        // Every spelling of a spec resolves; a repeat resolves again.
        let (o, s) = run_in(&mut sh, "jobs -x echo %1 %2 %+ %- %1");
        assert_eq!(o, format!("{pid1} {pid2} {pid2} {pid1} {pid1}\n"));
        assert_eq!(s, 0);
        // Only a whole word is a spec, and one naming nothing is left as it is.
        let (o, _) = run_in(&mut sh, "jobs -x echo x%1y %9 not%1");
        assert_eq!(o, "x%1y %9 not%1\n");
        // The words are not expanded again on the way through, so a substituted
        // value is never split or matched against the filesystem.
        let (o, _) = run_in(&mut sh, "jobs -x echo '*' 'a b'");
        assert_eq!(o, "* a b\n");
        sh.run_source("kill %1; kill %2".as_bytes());
    }

    #[test]
    fn job_specs_name_by_number_prefix_and_substring() {
        // Only the first character after the `%` decides what kind of spec it
        // is, so a suffix on `%+`/`%-` is ignored while `%1x` is a *name*.
        let mut sh = Shell::new();
        sh.run_source("sleep 5 &".as_bytes());
        sh.run_source("( sleep 6 ) &".as_bytes());
        for (spec, want) in [
            (b"%1".as_slice(), 0),
            (b"%2", 1),
            // `%`, `%%` and `%+` are the current job; `%-` the previous one.
            (b"%", 1),
            (b"%%", 1),
            (b"%+", 1),
            (b"%+x", 1),
            (b"%-", 0),
            (b"%-x", 0),
            // A name matches the start of the command, `%?str` anywhere in it.
            (b"%sleep", 0),
            (b"%(", 1),
            (b"%?6", 1),
        ] {
            // A `%` spec means the same thing to every builtin, so the
            // bare-number rule cannot change any of these.
            for bare in [BareNumber::Pid, BareNumber::JobId] {
                assert!(
                    matches!(sh.lookup_job(spec, bare), JobLookup::Found(i) if i == want),
                    "{}",
                    spec.as_bstr()
                );
            }
        }
        for spec in [b"%0".as_slice(), b"%1x", b"%nosuch", b"%?nosuch"] {
            assert!(
                matches!(sh.lookup_job(spec, BareNumber::JobId), JobLookup::NotFound),
                "{}",
                spec.as_bstr()
            );
        }
        // Matching two jobs is an error rather than a pick, and the error names
        // the text that was matched against — the spec minus its `%` and `?`.
        match sh.lookup_job(b"%?sleep", BareNumber::JobId) {
            JobLookup::Ambiguous(text) => assert_eq!(text, b"sleep"),
            _ => panic!("%?sleep should have matched both jobs"),
        }
        // A bare number is a pid or a job number according to which builtin is
        // asking, and never both — bash's `wait`/`kill`/`disown` read one,
        // `jobs`/`fg`/`bg` the other. So job 2's pid resolves only as a pid, and
        // the number 2 only as a job.
        let pid = sh.jobs[1].pid.to_string();
        assert!(matches!(sh.lookup_job(pid.as_bytes(), BareNumber::Pid), JobLookup::Found(1)));
        assert!(matches!(sh.lookup_job(pid.as_bytes(), BareNumber::JobId), JobLookup::NotFound));
        assert!(matches!(sh.lookup_job(b"2", BareNumber::JobId), JobLookup::Found(1)));
        assert!(matches!(sh.lookup_job(b"2", BareNumber::Pid), JobLookup::NotFound));
        sh.run_source("kill %1; kill %2".as_bytes());
    }

    /// Block until job `id` has ended *and the shell has noticed*.
    ///
    /// Tests about what a finished job does need this. A real shell hears about
    /// an exit asynchronously, so by the time a script reaches the next command
    /// the job is long since known to be over; a test that backgrounds a job and
    /// looks at it in the same breath would instead catch it still running.
    fn settle_job(sh: &mut Shell, id: usize) {
        loop {
            sh.poll_jobs();
            let Some(job) = sh.jobs.iter().find(|j| j.id == id) else {
                return;
            };
            if job.status.is_some() {
                return;
            }
            std::thread::yield_now();
        }
    }

    #[test]
    fn a_reported_job_outlives_the_command_that_reported_it() {
        // Reporting a job does not remove it; the *next* sweep of the table
        // does. The two `jobs` forms sweep at opposite ends, so a bare listing
        // leaves the job nameable for one more command while a jobspec listing
        // does not.
        let mut sh = Shell::new();
        sh.run_source("true &".as_bytes());
        settle_job(&mut sh, 1);
        let (o, _) = run_in(&mut sh, "jobs");
        assert!(o.starts_with("[1]+  Done"), "{o}");
        assert_eq!(sh.jobs.len(), 1, "a bare listing sweeps before it prints");
        let (o, _) = run_in(&mut sh, "jobs");
        assert_eq!(o, "", "the second listing swept it away first");
        assert!(sh.jobs.is_empty());

        let mut sh = Shell::new();
        sh.run_source("true &".as_bytes());
        settle_job(&mut sh, 1);
        let (o, s) = run_in(&mut sh, "jobs %1");
        assert!(o.starts_with("[1]+  Done"), "{o}");
        assert_eq!(s, 0);
        assert!(sh.jobs.is_empty(), "a jobspec listing sweeps after it prints");

        // Naming a job in `kill` puts its fate back on the books, so a listing
        // that already announced it announces it again — but only while the row
        // is still there, which is to say only within the one line.
        let mut sh = Shell::new();
        sh.run_source("true &".as_bytes());
        settle_job(&mut sh, 1);
        let (o, _) = run_in(&mut sh, "jobs; kill -0 %1; jobs");
        assert_eq!(o.lines().filter(|l| l.starts_with("[1]+  Done")).count(), 2, "{o}");
        // On the next line the row is gone, so `%1` names nothing.
        let mut sh = Shell::new();
        sh.run_source("true &".as_bytes());
        settle_job(&mut sh, 1);
        run_in(&mut sh, "jobs");
        let (o, s) = run_in(&mut sh, "kill -0 %1 2>&1");
        assert_eq!(o, "osh: kill: %1: no such job\n");
        assert_eq!(s, 1);
    }

    #[test]
    fn the_sweep_boundary_is_the_readers_unit_not_the_command() {
        // The read-parse-execute loop is where a reported dead job leaves the
        // table, so an `eval` body — which has a loop of its own — sweeps
        // between its lines, while a function body — one parsed unit — does not.
        let one = |src: &str| {
            let mut sh = Shell::new();
            sh.run_source("true &".as_bytes());
            settle_job(&mut sh, 1);
            run_in(&mut sh, src).0
        };
        assert_eq!(one("jobs >/dev/null; jobs %1 >/dev/null 2>&1; echo \"rc=$?\""), "rc=0\n");
        assert_eq!(
            one("eval 'jobs >/dev/null\njobs %1 >/dev/null 2>&1; echo \"rc=$?\"'"),
            "rc=1\n",
            "an eval body's own line boundary sweeps"
        );
        assert_eq!(
            one("g() { jobs >/dev/null\njobs %1 >/dev/null 2>&1; echo \"rc=$?\"; }; g"),
            "rc=0\n",
            "a function body is one unit, so it has no boundary inside it"
        );
        // Running out of input is not a boundary: the row survives an `eval`
        // whose last unit reported it, for the command that follows.
        assert_eq!(
            one("eval 'jobs >/dev/null'; jobs %1 >/dev/null 2>&1; echo \"rc=$?\""),
            "rc=0\n"
        );
    }

    #[test]
    fn a_swept_job_is_still_answerable_by_pid() {
        // Dropping a row hands its status to the remembered-pid table, so
        // `wait PID` keeps answering after the job itself is gone — bash's
        // `delete_job`/`bgp_add`. The `jobs` listing here is what marks the job
        // reported; the next line's sweep is what drops it.
        let mut sh = Shell::new();
        sh.run_source("( exit 5 ) & p=$!".as_bytes());
        settle_job(&mut sh, 1);
        run_in(&mut sh, "jobs");
        assert_eq!(run_in(&mut sh, "wait $p").1, 5);
        assert!(sh.jobs.is_empty(), "the row is gone; only the memory answered");
        assert_eq!(run_in(&mut sh, "wait $p").1, 5, "and it answers as often as asked");
        // A pid that was never a child is still an error, memory or no.
        let (o, s) = run_in(&mut sh, "wait 99999 2>&1");
        assert_eq!(o, "osh: wait: pid 99999 is not a child of this shell\n");
        assert_eq!(s, 127);
    }

    #[test]
    fn disowning_a_job_still_leaves_its_status_answerable_by_pid() {
        // `disown` drops the row through the same door, so bash answers a later
        // `wait PID` from the remembered table rather than calling it a
        // stranger. A finished job answers with its own status.
        let mut sh = Shell::new();
        sh.run_source("( exit 5 ) & p=$!".as_bytes());
        settle_job(&mut sh, 1);
        run_in(&mut sh, "disown %1");
        assert!(sh.jobs.is_empty());
        assert_eq!(run_in(&mut sh, "wait $p").1, 5);

        // A job disowned while still running answers 0, and answers at once:
        // the shell has let go of the child, so there is nothing left to wait
        // on and no status to have learnt.
        let mut sh = Shell::new();
        sh.run_source("( sleep 5; exit 6 ) & q=$!".as_bytes());
        run_in(&mut sh, "disown %1");
        let t = std::time::Instant::now();
        assert_eq!(run_in(&mut sh, "wait $q").1, 0);
        assert!(t.elapsed() < std::time::Duration::from_secs(3), "it did not wait");

        // `-h` keeps the row, so the job is waited on for real.
        let mut sh = Shell::new();
        sh.run_source("( exit 4 ) & r=$!".as_bytes());
        run_in(&mut sh, "disown -h %1");
        assert_eq!(sh.jobs.len(), 1);
        assert_eq!(run_in(&mut sh, "wait $r").1, 4);
    }

    #[test]
    fn waiting_on_a_job_answers_twice_before_the_row_is_gone() {
        // The sweep happens before the job is marked reported, so the row
        // outlives the `wait` that read it: a second `wait` on the same line
        // answers with the status again and is the one that drops the row.
        let mut sh = Shell::new();
        sh.run_source("( exit 7 ) &".as_bytes());
        let (o, _) = run_in(
            &mut sh,
            "wait %1; echo \"1=$?\"; wait %1; echo \"2=$?\"; wait %1 2>&1; echo \"3=$?\"",
        );
        assert_eq!(o, "1=7\n2=7\nosh: wait: %1: no such job\n3=127\n");
        assert!(sh.jobs.is_empty());

        // Across a line boundary there is no second answer: the boundary is
        // itself a sweep, so the row the first `wait` reported is already gone.
        let mut sh = Shell::new();
        sh.run_source("( exit 7 ) &".as_bytes());
        assert_eq!(run_in(&mut sh, "wait %1").1, 7);
        assert_eq!(sh.jobs.len(), 1, "the reporting line does not sweep on its way out");
        let (o, s) = run_in(&mut sh, "wait %1 2>&1");
        assert_eq!(o, "osh: wait: %1: no such job\n");
        assert_eq!(s, 127);

        // Numbering restarts once the row is gone, and not before.
        sh.run_source("sleep 5 &".as_bytes());
        assert_eq!(sh.jobs[0].id, 1);
        sh.run_source("kill %1".as_bytes());
    }

    #[test]
    fn an_operand_less_wait_spares_the_job_that_holds_the_last_bg_pid() {
        // A job that had already finished is not one the `wait` waited for, so
        // it is discarded only if some later job took `$!` away from it.
        let mut sh = Shell::new();
        sh.run_source("true &".as_bytes());
        settle_job(&mut sh, 1);
        assert_eq!(run_in(&mut sh, "wait").1, 0);
        assert_eq!(sh.jobs.len(), 1, "the last job backgrounded is spared");
        assert!(run_in(&mut sh, "jobs %1").0.starts_with("[1]+  Done"));

        // Job 2 is still running, so the `wait` really waits for it and it is
        // discarded despite holding `$!`; job 1, no longer holding it, goes too.
        let mut sh = Shell::new();
        sh.run_source("true &".as_bytes());
        settle_job(&mut sh, 1);
        sh.run_source("sleep 0.3 &".as_bytes());
        assert_eq!(run_in(&mut sh, "wait").1, 0);
        assert!(sh.jobs.is_empty(), "job 1 lost `$!` to job 2, so both went");
    }

    #[test]
    fn losing_a_marked_job_costs_both_markers() {
        // Dropping the `-` job leaves the `+` job in the table, and still
        // clears both markers: the replacement has to be a job still running,
        // and with none there is nothing to re-mark. Dropping an unmarked job
        // disturbs neither.
        // Job 1 has to still be running when job 2 arrives, or it would never
        // have been the `-` job in the first place: a new job takes both
        // markers when there is nothing running to hand the `-` to.
        let mut sh = Shell::new();
        sh.run_source("sleep 0.2 &".as_bytes());
        sh.run_source("true &".as_bytes());
        assert_eq!((sh.current_job, sh.previous_job), (Some(2), Some(1)));
        settle_job(&mut sh, 1);
        settle_job(&mut sh, 2);
        run_in(&mut sh, "jobs %1");
        assert_eq!(sh.jobs.len(), 1, "only job 1 was swept");
        assert_eq!((sh.current_job, sh.previous_job), (None, None));

        // With something still running, that running job takes both markers.
        let mut sh = Shell::new();
        sh.run_source("sleep 5 &".as_bytes());
        sh.run_source("true &".as_bytes());
        settle_job(&mut sh, 2);
        run_in(&mut sh, "jobs %2");
        assert_eq!((sh.current_job, sh.previous_job), (Some(1), Some(1)));
        sh.run_source("kill %1".as_bytes());
    }

    #[cfg(windows)]
    #[test]
    fn wait_n_returns_next_completed() {
        // `wait -n` returns as soon as one job finishes; a second `wait -n`
        // reaps the other. `-p VAR` records the returned job's pid.
        let mut sh = Shell::new();
        sh.run_source("cmd /c exit 5 &".as_bytes());
        sh.run_source("cmd /c exit 6 &".as_bytes());
        assert_eq!(sh.jobs.len(), 2);
        let first = sh.run_source("wait -n -p done_pid".as_bytes());
        assert!(first == 5 || first == 6, "unexpected status {first}");
        assert_eq!(sh.jobs.len(), 1);
        // The pid variable was set to a plausible pid.
        assert!(
            sh.vars
                .get("done_pid")
                .is_some_and(|p| as_text(p).parse::<u32>().is_ok())
        );
        let second = sh.run_source("wait -n".as_bytes());
        assert!(second == 5 || second == 6);
        assert_ne!(first, second);
        assert!(sh.jobs.is_empty());
        // `wait -n` with no jobs left returns 127.
        assert_eq!(sh.run_source("wait -n".as_bytes()), 127);
    }

    #[cfg(windows)]
    #[test]
    fn jobs_lists_background_job() {
        // `jobs` reports the tracked job with its job number and command line.
        let mut sh = Shell::new();
        sh.run_source("cmd /c exit 0 &".as_bytes());
        let buf = capture_sink();
        {
            let prog = parse("jobs".as_bytes()).expect("parse");
            let mut out = Out::Capture(buf.clone());
            sh.exec_program(&prog, &mut out, &StdinSrc::Inherit);
        }
        let buf = take_capture(&buf);
        let s = String::from_utf8_lossy(&buf);
        assert!(s.contains("[1]"), "jobs output: {s:?}");
        assert!(s.contains("cmd /c exit 0"), "jobs output: {s:?}");
        // `wait` cleans up any still-tracked job for a tidy teardown.
        sh.run_source("wait".as_bytes());
    }

    #[cfg(windows)]
    #[test]
    fn fg_echoes_command_and_waits_for_status() {
        // `fg` (no spec) foregrounds the current job: it prints the command line
        // and blocks until the job finishes, returning its exit status.
        let mut sh = Shell::new();
        sh.run_source("cmd /c exit 7 &".as_bytes());
        assert_eq!(sh.jobs.len(), 1);
        let buf = capture_sink();
        let status = {
            let prog = parse("fg".as_bytes()).expect("parse");
            let mut out = Out::Capture(buf.clone());
            sh.exec_program(&prog, &mut out, &StdinSrc::Inherit);
            sh.last_status
        };
        let buf = take_capture(&buf);
        assert_eq!(status, 7);
        let s = String::from_utf8_lossy(&buf);
        assert!(s.contains("cmd /c exit 7"), "fg output: {s:?}");
        assert!(sh.jobs.is_empty(), "fg should remove the job");
    }

    #[cfg(windows)]
    #[test]
    fn fg_by_job_spec_targets_named_job() {
        // `fg %n` targets a specific job by its job number.
        let mut sh = Shell::new();
        sh.run_source("cmd /c exit 3 &".as_bytes());
        assert_eq!(sh.run_source("fg %1".as_bytes()), 3);
        assert!(sh.jobs.is_empty());
    }

    #[test]
    fn fg_no_jobs_errors() {
        // With no jobs, `fg` reports an error and returns 1.
        let mut sh = Shell::new();
        assert_eq!(sh.run_source("fg".as_bytes()), 1);
        // A non-existent job spec is also an error.
        assert_eq!(sh.run_source("fg %9".as_bytes()), 1);
    }

    #[cfg(windows)]
    #[test]
    fn bg_reports_already_in_background() {
        // osh has no stopped jobs — every tracked job is already running in the
        // background — so `bg` on a resolvable target matches bash's "already
        // running" case: `bg: job N already in background` on stderr, exit 0.
        // (The stdout capture stays empty; the message goes to real stderr.)
        let mut sh = Shell::new();
        sh.run_source("cmd /c exit 0 &".as_bytes());
        let buf = capture_sink();
        {
            let prog = parse("bg".as_bytes()).expect("parse");
            let mut out = Out::Capture(buf.clone());
            sh.exec_program(&prog, &mut out, &StdinSrc::Inherit);
        }
        let buf = take_capture(&buf);
        assert!(buf.is_empty(), "bg writes to stderr, not stdout: {buf:?}");
        assert_eq!(sh.last_status, 0);
        sh.run_source("wait".as_bytes());
    }

    #[test]
    fn fg_bg_require_job_control() {
        // In `-c`/command mode (job control off, no `set -m`), bash refuses
        // `fg`/`bg` outright with `no job control` and returns 1 — even when a
        // background job is running. `set -m` re-enables job control.
        let (out, code) = run_cmd_mode("fg 2>&1");
        assert_eq!(code, 1);
        assert!(out.contains("fg: no job control"), "fg output: {out:?}");
        let (out, code) = run_cmd_mode("bg 2>&1");
        assert_eq!(code, 1);
        assert!(out.contains("bg: no job control"), "bg output: {out:?}");
        // With `set -m`, job control is on, so `fg` gets past the guard and
        // instead reports the empty job table.
        let (out, _) = run_cmd_mode("set -m; fg 2>&1");
        assert!(out.contains("no such job"), "fg output: {out:?}");
    }

    #[test]
    fn bg_no_jobs_errors() {
        // With no jobs, `bg` reports an error and returns 1.
        let mut sh = Shell::new();
        assert_eq!(sh.run_source("bg".as_bytes()), 1);
        assert_eq!(sh.run_source("bg %5".as_bytes()), 1);
    }

    #[cfg(windows)]
    #[test]
    fn disown_removes_job_from_table() {
        // `disown %1` drops the job so `jobs` no longer reports it.
        let mut sh = Shell::new();
        sh.run_source("cmd /c exit 0 &".as_bytes());
        assert_eq!(sh.jobs.len(), 1);
        assert_eq!(sh.run_source("disown %1".as_bytes()), 0);
        assert!(sh.jobs.is_empty(), "job should be removed after disown");
    }

    #[cfg(windows)]
    #[test]
    fn disown_all_and_running_flags() {
        let mut sh = Shell::new();
        sh.run_source("cmd /c exit 0 &".as_bytes());
        sh.run_source("cmd /c exit 0 &".as_bytes());
        assert_eq!(sh.jobs.len(), 2);
        // `disown -a` clears every tracked job.
        assert_eq!(sh.run_source("disown -a".as_bytes()), 0);
        assert!(sh.jobs.is_empty(), "disown -a should clear all jobs");
    }

    #[cfg(windows)]
    #[test]
    fn disown_h_marks_without_removing() {
        // `disown -h` keeps the job but flags it no-SIGHUP.
        let mut sh = Shell::new();
        sh.run_source("cmd /c exit 0 &".as_bytes());
        assert_eq!(sh.run_source("disown -h %1".as_bytes()), 0);
        assert_eq!(sh.jobs.len(), 1, "disown -h keeps the job in the table");
        assert!(sh.jobs[0].no_hup, "disown -h sets no_hup");
        sh.run_source("wait".as_bytes());
    }

