    #[test]
    fn enable_n_bypasses_builtin_resolution() {
        // `command -v times` finds the builtin (status 0); once `times` is
        // disabled it is no longer a builtin, so with no external of that name
        // resolution fails (status 1) — proving `enable -n` bypasses the builtin.
        assert_eq!(run("command -v times").1, 0);
        assert_eq!(run("enable -n times; command -v times").1, 1);
        // `type -t` likewise stops reporting it as a builtin.
        assert_eq!(run("type -t times").0, "builtin\n");
        assert_eq!(run("enable -n times; type -t times").1, 1);
    }

    #[test]
    fn declare_big_f_lists_functions() {
        let (o, s) = run("foo() { echo hi; }; bar() { :; }; declare -F");
        assert_eq!(s, 0);
        assert!(o.contains("declare -f foo\n"), "declare -F output: {o:?}");
        assert!(o.contains("declare -f bar\n"), "declare -F output: {o:?}");
    }

    #[test]
    fn declare_attr_filter_lists_matching_vars() {
        // `declare -A` (no names) lists only associative arrays, in
        // re-inputtable declare-prefix form, sorted by name. The always-present
        // dynamic mirrors BASH_ALIASES/BASH_CMDS sort ahead of user arrays,
        // exactly as bash lists them.
        let (o, s) = run("declare -A m=([x]=1); declare -A n=([y]=2); a=(1 2); declare -A");
        assert_eq!(s, 0);
        assert_eq!(
            o,
            "declare -A BASH_ALIASES=()\ndeclare -A BASH_CMDS=()\n\
             declare -A m=([x]=\"1\" )\ndeclare -A n=([y]=\"2\" )\n"
        );

        // `PPID` lists with the real parent pid, so it is normalised away before
        // the listings below are compared literally.
        let hide_ppid = |o: String| {
            o.lines()
                .map(|l| if l.starts_with("declare -ir PPID=") { "declare -ir PPID" } else { l })
                .collect::<Vec<&str>>()
                .join("\n")
        };

        // `declare -i` lists all integer-attributed variables. Besides the
        // user's `k`/`k2`, this includes the always-present readonly-integer
        // identity vars `EUID`/`UID` (seeded as real `declare -ir` vars) and the
        // integer dynamic specials, which have no entry in the variable tables
        // but which bash lists all the same — all ahead of the user's integers
        // in sort order, exactly as bash lists them.
        let (o2, _) = run("declare -i k=5; s=hi; declare -i k2=9; declare -i");
        assert_eq!(
            hide_ppid(o2),
            "declare -i BASHPID\ndeclare -ir EUID=\"0\"\ndeclare -i HISTCMD\n\
             declare -i OPTIND=\"1\"\ndeclare -ir PPID\ndeclare -i RANDOM\n\
             declare -i SRANDOM\ndeclare -ir UID=\"0\"\n\
             declare -i k=\"5\"\ndeclare -i k2=\"9\""
        );

        // Union semantics: `declare -il` lists variables that are integer OR
        // lowercase-attributed (bash), each shown with its full attribute set.
        // EUID/UID and the integer dynamics are included for the same reason as
        // above; the `-il` (not `-ir`) union still excludes non-integer internal
        // readonly vars like BASH_VERSINFO.
        let (o3, _) = run("declare -i ii=1; declare -l low=HELLO; plain=3; declare -il");
        assert_eq!(
            hide_ppid(o3),
            "declare -i BASHPID\ndeclare -ir EUID=\"0\"\ndeclare -i HISTCMD\n\
             declare -i OPTIND=\"1\"\ndeclare -ir PPID\ndeclare -i RANDOM\n\
             declare -i SRANDOM\ndeclare -ir UID=\"0\"\n\
             declare -i ii=\"1\"\ndeclare -l low=\"hello\""
        );

        // A declaration *with* a name operand still declares (not a listing).
        assert_eq!(run("declare -A m=([k]=v); echo ${m[k]}").0, "v\n");
    }

